TEST_F(StringTest, compare) {
    {
        string a = "first";
        string b = "first";

        EXPECT_EQ(a <=> b, std::strong_ordering::equal);
    }

    {
        string a = "first";
        EXPECT_EQ(a <=> "first", std::strong_ordering::equal);
    }

    {
        string a = "first";
        EXPECT_EQ("first" <=> a, std::strong_ordering::equal);
    }

    {
        EXPECT_EQ(tmp_func("second") <=> "first second third", std::strong_ordering::equal);
    }
}

TEST_F(StringTest, equal) {
    {
        string a = "first ";
        string b = "second";
        string c = a + b;
        EXPECT_EQ(c.equals("first second"), true);
    }

    {
        string a = "first ";
        string b = "second";
        string c = a + b;
        string d = "first second";
        EXPECT_EQ(c.equals(d), true);
    }

    {
        string a = "first ";

        a += 21;

        EXPECT_EQ(a.equals("first 21"), true);
    }
}

TEST_F(StringTest, operatorPlusDoesNotMutateLeftOperand) {
    {
        string a = "first ";
        string b = "second";
        string c = a + b;

        EXPECT_EQ(a.equals("first "), true);
        EXPECT_EQ(b.equals("second"), true);
        EXPECT_EQ(c.equals("first second"), true);
    }

    {
        string a = "first ";
        string c = a + "second";

        EXPECT_EQ(a.equals("first "), true);
        EXPECT_EQ(c.equals("first second"), true);
    }

    {
        string a = "first ";
        string b = "second";
        string c = a + b + " third";

        EXPECT_EQ(a.equals("first "), true);
        EXPECT_EQ(b.equals("second"), true);
        EXPECT_EQ(c.equals("first second third"), true);
    }

    {
        string a = "first ";
        string b = "second";
        string c = "prefix " + a + b;

        EXPECT_EQ(a.equals("first "), true);
        EXPECT_EQ(b.equals("second"), true);
        EXPECT_EQ(c.equals("prefix first second"), true);
    }
}

TEST_F(StringTest, operatorPlusInLoopDoesNotAccumulate) {
    string dir = "/tmp/project";
    string base = dir;

    for (int i = 0; i < 5; i++) {
        string candidate = dir + "/Application.cfm";
        EXPECT_EQ(candidate.equals("/tmp/project/Application.cfm"), true);
    }

    EXPECT_EQ(dir.equals(base), true);
    EXPECT_EQ(dir.equals("/tmp/project"), true);
}

TEST_F(StringTest, operatorPlusEmptyAndNullOperands) {
    {
        string a = "abc";
        string c = a + "";
        EXPECT_EQ(a.equals("abc"), true);
        EXPECT_EQ(c.equals("abc"), true);
    }

    {
        string a = "abc";
        string empty;
        string c = a + empty;
        EXPECT_EQ(a.equals("abc"), true);
        EXPECT_EQ(c.equals("abc"), true);
    }
}

TEST_F(StringTest, cfvariant) {
    {
        cfvariant variant = cfvariant::Struct;
        variant.set("ok");

        EXPECT_EQ(variant["ok"].m_type == cfvariant::NotSet, true);
    }

    {
        cfvariant variant = cfvariant::Struct;
        variant.set("ok");
        variant["ok"] = "awed";

        EXPECT_EQ(variant["ok"] == "awed", true);
    }

    {
        cfvariant variant = cfvariant::Struct;
        variant.set("coldfusion") = cfvariant::Struct;
        variant["coldfusion"].set("appserver") = "apache2";

        EXPECT_EQ(variant["coldfusion"]["appserver"] == "apache2", true);
    }

    {
        cfvariant variant = cfvariant::Struct;
        variant.setAutoCreate();
        variant["coldfusion"]["appserver"] = "apache2";

        EXPECT_EQ(variant["coldfusion"]["appserver"] == "apache2", true);
    }

    {
        cfvariant variant = cfvariant::Struct;
        variant.setAutoCreate();
        variant["coldfusion"]["appserver"] = "apache2";

        string str = "apache2";
        EXPECT_EQ(variant["coldfusion"]["appserver"] == str, true);
    }
}

TEST_F(StringTest, cfvariantToStringScalarTypes) {
    // String passthrough
    cfvariant s("hello");
    EXPECT_EQ(s.toString().equals("hello"), true);

    // Boolean renders as CF's lowercase true/false in string context when it is
    // a literal, and as YES/NO when computed (BUGS.md #7).
    cfvariant t(cfvariant::Boolean);
    t.m_bool = true;
    t.m_boolLiteral = true;
    EXPECT_EQ(t.toString().equals("true"), true);

    cfvariant f(cfvariant::Boolean);
    f.m_bool = false;
    f.m_boolLiteral = true;
    EXPECT_EQ(f.toString().equals("false"), true);

    // Computed booleans (comparisons, not, boolean-returning functions, ...)
    // stringify as YES/NO.
    cfvariant tc(cfvariant::Boolean);
    tc.m_bool = true;
    EXPECT_EQ(tc.toString().equals("YES"), true);

    cfvariant fc(cfvariant::Boolean);
    fc.m_bool = false;
    EXPECT_EQ(fc.toString().equals("NO"), true);

    // Number (int)
    cfvariant n(42);
    EXPECT_EQ(n.toString().equals("42"), true);

    cfvariant nz(0);
    EXPECT_EQ(nz.toString().equals("0"), true);

    cfvariant nn(-42);
    EXPECT_EQ(nn.toString().equals("-42"), true);

    // Float: %.12g with normalized 3-digit exponent (CF output style)
    cfvariant fl(cfvariant::Float);
    fl.m_double = 5.5;
    EXPECT_EQ(fl.toString().equals("5.5"), true);

    cfvariant fl2(cfvariant::Float);
    fl2.m_double = 1.0 / 3.0;
    EXPECT_EQ(fl2.toString().equals("0.333333333333"), true);

    cfvariant fl3(cfvariant::Float);
    fl3.m_double = std::pow(2.0, 53.0);
    EXPECT_EQ(fl3.toString().equals("9.00719925474E+015"), true);

    cfvariant fl4(cfvariant::Float);
    fl4.m_double = 1.0 / 100000.0;
    EXPECT_EQ(fl4.toString().equals("1E-005"), true);

    // Infinity/NaN render with CF's output quirks
    cfvariant inf(cfvariant::Float);
    inf.m_double = std::numeric_limits<double>::infinity();
    EXPECT_EQ(inf.toString().equals("1.#INF"), true);

    cfvariant ninf(cfvariant::Float);
    ninf.m_double = -std::numeric_limits<double>::infinity();
    EXPECT_EQ(ninf.toString().equals("-1.#INF"), true);

    cfvariant nan(cfvariant::Float);
    nan.m_double = std::numeric_limits<double>::quiet_NaN();
    // CF 2021 stringifies NaN as the single U+FFFD replacement character
    // (UTF-8 EF BF BD), not "NAN"/"NaN" (verified against CF server).
    EXPECT_EQ(nan.toString().equals("\xEF\xBF\xBD"), true);

    // DateTime still renders as {ts '...'}
    cfvariant dt(cfvariant::DateTime);
    dt.m_double = 0.0; // CF date 0 == 1899-12-30
    EXPECT_EQ(dt.toString().equals("{ts '1899-12-30 00:00:00'}"), true);
}

TEST_F(StringTest, cfvariantToStringBinaryThrows) {
    cfvariant bin(cfvariant::Binary);
    bin.m_binary->assign({std::byte('H'), std::byte('i')});
    bool caught = false;
    try {
        bin.toString();
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(StringTest, lastIndexOfDefaultPos) {
    string a = "foo.bar.baz";
    EXPECT_EQ(a.lastIndexOf('.'), 7);
    EXPECT_EQ(a.lastIndexOf('o'), 2);
    EXPECT_EQ(a.lastIndexOf('z'), 10);
    EXPECT_EQ(a.lastIndexOf('q'), -1);
    EXPECT_EQ(a.lastIndexOf(".baz"), 7);
    EXPECT_EQ(a.lastIndexOf("bar"), 4);
    EXPECT_EQ(a.lastIndexOf("nope"), -1);
    EXPECT_EQ(a.lastIndexOf(string(".baz")), 7);
    EXPECT_EQ(a.lastIndexOf(string("bar")), 4);
    EXPECT_EQ(a.lastIndexOf(string("nope")), -1);
}

TEST_F(StringTest, RemoveShiftsTailWithoutOverflow) {
    // string::remove used memmove(str+pos, str+pos+size, len-size), reading
    // `pos` bytes past the end of the buffer (heap-buffer-overflow, caught by
    // ASAN during CFKillBoard killmail parsing); the copy length must be
    // len-size-pos. Verify the visible result and that an over-length removal
    // truncates to pos.
    string s = "abcdef";
    s.remove(2, 3);            // remove "cde" -> "abf"
    EXPECT_EQ(s.equals("abf"), true) << s.constData();
    string s2 = "abcdef";
    s2.remove(4, 10);          // removal past the end truncates to pos (4)
    EXPECT_EQ(s2.equals("abcd"), true) << s2.constData();
    string s3 = "abcdef";
    s3.remove(0, 2);           // remove head -> "cdef"
    EXPECT_EQ(s3.equals("cdef"), true) << s3.constData();
    string s4 = "abcdef";
    s4.remove(1, 1);           // middle remove -> "acdef"
    EXPECT_EQ(s4.equals("acdef"), true) << s4.constData();
}

TEST_F(StringTest, lastIndexOfExplicitPos) {
    string a = "foo.bar.baz";
    EXPECT_EQ(a.lastIndexOf('.', a.length() - 1), 7);
    EXPECT_EQ(a.lastIndexOf('.', 3), 3);
    EXPECT_EQ(a.lastIndexOf('.', 2), -1);
    EXPECT_EQ(a.lastIndexOf(".baz", a.length() - 1), 7);
    EXPECT_EQ(a.lastIndexOf(".bar", 5), 3);
    EXPECT_EQ(a.lastIndexOf(".bar", 2), -1);
    EXPECT_EQ(a.lastIndexOf(string(".baz"), a.length() - 1), 7);
    EXPECT_EQ(a.lastIndexOf(string(".bar"), 5), 3);
    EXPECT_EQ(a.lastIndexOf(string(".bar"), 2), -1);
}

TEST_F(StringTest, lastIndexOfBounds) {
    string a = "abc";
    EXPECT_EQ(a.lastIndexOf('a', 100), 0);
    EXPECT_EQ(a.lastIndexOf('c', -10), 2);
    EXPECT_EQ(a.lastIndexOf("abc", 100), 0);
    EXPECT_EQ(a.lastIndexOf("bc", -10), 1);
    EXPECT_EQ(a.lastIndexOf(string("abc"), 100), 0);
    EXPECT_EQ(a.lastIndexOf(string("bc"), -10), 1);
    EXPECT_EQ(string().lastIndexOf('a'), -1);
    EXPECT_EQ(string().lastIndexOf("a"), -1);
    EXPECT_EQ(string().lastIndexOf(string("a")), -1);
}

TEST_F(StringTest, lastIndexOfEmptySubstring) {
    string a = "abc";
    EXPECT_EQ(a.lastIndexOf("", a.length()), 3);
    EXPECT_EQ(a.lastIndexOf("", 2), 2);
    EXPECT_EQ(a.lastIndexOf(string(""), a.length()), 3);
    EXPECT_EQ(a.lastIndexOf(string(""), 2), 2);
}

TEST_F(StringTest, percentDecodePlusToSpace) {
    // Form-urlencoded decoding must turn '+' into a space (and keep %XX).
    string a = "hello+world";
    EXPECT_EQ(a.percent_decode().equals("hello world"), true);
    string b = "a+b+c";
    EXPECT_EQ(b.percent_decode().equals("a b c"), true);
    string c = "hello%20world";
    EXPECT_EQ(c.percent_decode().equals("hello world"), true);
    string d = "plus+and%2Bencoded";
    EXPECT_EQ(d.percent_decode().equals("plus and+encoded"), true);
    string e = "2026.05.21+18:22";
    EXPECT_EQ(e.percent_decode().equals("2026.05.21 18:22"), true);
    string f = "none";
    EXPECT_EQ(f.percent_decode().equals("none"), true);
    string g = "";
    EXPECT_EQ(g.percent_decode().equals(""), true);
    string h = "100%25";
    EXPECT_EQ(h.percent_decode().equals("100%"), true);
    string i = "trailing%";
    EXPECT_EQ(i.percent_decode().equals("trailing%"), true);
}

class WriteOutputTest : public testing::Test {
protected:
    webstrada::string out;
    webstrada::cfvariant variables;
    cfml::VariantCleanupGuard guard;

    void SetUp() override {
        variables = webstrada::cfvariant::Struct;
    }
};

TEST_F(WriteOutputTest, StringOutput) {
    webstrada::string out;
    cfvariant result = cfml::cfevaluate(out, "WriteOutput(\"hello world\")", nullptr);
    EXPECT_EQ(out.equals("hello world"), true);
    EXPECT_EQ(result.m_type == cfvariant::Boolean, true);
    EXPECT_EQ(result.m_bool, true);
}

TEST_F(WriteOutputTest, NumberOutput) {
    webstrada::string out;
    cfvariant result = cfml::cfevaluate(out, "WriteOutput(42)", nullptr);
    EXPECT_EQ(out.equals("42"), true);
    EXPECT_EQ(result.m_bool, true);
}

TEST_F(WriteOutputTest, BooleanOutput) {
    webstrada::string out;
    cfvariant result = cfml::cfevaluate(out, "WriteOutput(true)", nullptr);
    EXPECT_EQ(out.equals("true"), true);
    EXPECT_EQ(result.m_bool, true);
}

TEST_F(WriteOutputTest, FloatVariableOutput) {
    webstrada::string out;
    cfvariant piVal(cfvariant::Float);
    piVal.m_double = 3.14;
    variables.set("PI");
    variables["PI"] = piVal;
    cfvariant result = cfml::cfevaluate(out, "WriteOutput(PI)", &variables);
    EXPECT_EQ(out.equals("3.14"), true);
    EXPECT_EQ(result.m_bool, true);
}

TEST_F(WriteOutputTest, EmptyStringOutput) {
    webstrada::string out;
    cfvariant result = cfml::cfevaluate(out, "WriteOutput(\"\")", nullptr);
    EXPECT_EQ(out.isEmpty(), true);
    EXPECT_EQ(result.m_bool, true);
}

TEST_F(WriteOutputTest, NoArgumentsThrows) {
    webstrada::string out;
    bool caught = false;
    try {
        cfml::cfevaluate(out, "WriteOutput()", nullptr);
    } catch (exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(WriteOutputTest, EscapedDoubleQuotesCollapse) {
    webstrada::string out;
    // CFML "a, b ""quoted"" x" -> a, b "quoted" x
    cfvariant result = cfml::cfevaluate(out, "WriteOutput(\"a, b \"\"quoted\"\" x\")", nullptr);
    EXPECT_EQ(out.equals("a, b \"quoted\" x"), true);
    EXPECT_EQ(result.m_bool, true);
}

TEST_F(WriteOutputTest, EscapedSingleQuotesCollapse) {
    webstrada::string out;
    // CFML 'a, b ''quoted'' x' -> a, b 'quoted' x
    cfvariant result = cfml::cfevaluate(out, "WriteOutput('a, b ''quoted'' x')", nullptr);
    EXPECT_EQ(out.equals("a, b 'quoted' x"), true);
    EXPECT_EQ(result.m_bool, true);
}

TEST_F(WriteOutputTest, EscapedQuoteLeading) {
    webstrada::string out;
    // CFML """lead" -> "lead
    cfml::cfevaluate(out, "WriteOutput(\"\"\"lead\")", nullptr);
    EXPECT_EQ(out.equals("\"lead"), true);
}

TEST_F(WriteOutputTest, EscapedQuoteTrailing) {
    webstrada::string out;
    // CFML "trail quote """ -> trail quote "
    cfml::cfevaluate(out, "WriteOutput(\"trail quote \"\"\")", nullptr);
    EXPECT_EQ(out.equals("trail quote \""), true);
}

TEST_F(WriteOutputTest, EscapedQuotePairKeepsBoth) {
    webstrada::string out;
    // CFML "two """" pairs" (4 inner quotes = 2 escaped pairs) -> two "" pairs
    cfml::cfevaluate(out, "WriteOutput(\"two \"\"\"\" pairs\")", nullptr);
    EXPECT_EQ(out.equals("two \"\" pairs"), true);
}

TEST_F(WriteOutputTest, OppositeQuotePairIsLiteral) {
    webstrada::string out;
    // '' inside double-quoted and "" inside single-quoted strings are NOT escapes.
    cfml::cfevaluate(out, "WriteOutput(\"a '' b\")", nullptr);
    EXPECT_EQ(out.equals("a '' b"), true);

    webstrada::string out2;
    cfml::cfevaluate(out2, "WriteOutput('a \"\" b')", nullptr);
    EXPECT_EQ(out2.equals("a \"\" b"), true);
}

TEST_F(WriteOutputTest, EmptyAndPlainStringsUnaffected) {
    webstrada::string out;
    cfml::cfevaluate(out, "WriteOutput(\"\")", nullptr);
    EXPECT_EQ(out.isEmpty(), true);

    webstrada::string out2;
    cfml::cfevaluate(out2, "WriteOutput(\"plain\")", nullptr);
    EXPECT_EQ(out2.equals("plain"), true);
}

class JitExpressionTest : public testing::Test {
protected:
    cfvariant variables;
    cfml::VariantCleanupGuard guard;

    void SetUp() override {
        variables = cfvariant::Struct;
    }
};

static string runJitTemplate(const string &cfml_code, cfvariant &variables) {
    char temp_path[] = "/tmp/webstrada_jit_test_XXXXXX";
    int fd = mkstemp(temp_path);
    if (fd == -1) {
        throw std::runtime_error("Failed to create temporary file");
    }
    string code = cfml_code;
    if (write(fd, code.constData(), code.length()) != (ssize_t)code.length()) {
        close(fd);
        unlink(temp_path);
        throw std::runtime_error("Failed to write to temporary file");
    }
    close(fd);

    string out;
    try {
        llvm_codegen comp;
        auto compiled = comp.compile(temp_path, getenv("DUMP_AST") != nullptr);
        unlink(temp_path);

        if (!compiled) {
            throw std::runtime_error("Failed to compile CFML template via JIT");
        }

        cfvariant cgi = cfvariant::Struct;
        cfvariant server = cfvariant::Struct;
        cfvariant cookie = cfvariant::Struct;
        cfvariant application = cfvariant::Struct;
        cfvariant session = cfvariant::Struct;
        cfvariant url = cfvariant::Struct;
        cfvariant form = cfvariant::Struct;

        cfml::VariantCleanupGuard guard;
        compiled(&out, &cgi, &server, &cookie, &application, &session, &url, &form, &variables);
    } catch (const webstrada::exit_exception &) {
        // <cfexit> at the top level halts the page like <cfabort>: the partial
        // output is preserved (the CLI catches it the same way).
    } catch (...) {
        unlink(temp_path);
        throw;
    }
    return out;
}

class WhitespaceManagementTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    // Runs CFML and returns the raw output bytes.
    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }

    void expectOutput(const string &cfml_code, const char *expected) {
        string out = run(cfml_code);
        EXPECT_EQ(out.equals(expected), true) << "CFML: " << cfml_code.constData() << " -> " << out.constData();
    }
};

TEST_F(WhitespaceManagementTest, WhitespaceBetweenTagsRemoved) {
    // A newline-only region between two non-output tags is removed entirely.
    expectOutput("A<cfset a = 1>\n<cfset b = 2>B", "AB");
    // ... and so is a region with spaces/tabs and a line break.
    expectOutput("A<cfset a = 1>  	\n<cfset b = 2>B", "AB");
    // A whitespace-only region without a line break collapses to a single space.
    expectOutput("A<cfset a = 1> <cfset b = 2>B", "A B");
    expectOutput("A<cfset a = 1>\t<cfset b = 2>B", "A B");
}

TEST_F(WhitespaceManagementTest, WhitespaceAdjacentToPlainTextPreserved) {
    // Whitespace-only text that touches plain text is emitted verbatim.
    expectOutput("A<cfset z = 1>\nB", "A\nB");
    expectOutput("A<cfoutput>X</cfoutput>\nB", "AX\nB");
    expectOutput("A<cfset z = 1>\n<!--- c --->\nB", "A\n\nB");
}

TEST_F(WhitespaceManagementTest, SpaceAfterOutputProducingTags) {
    // After <cfoutput>/<cfscript>/<cfdump> a newline-only region becomes a space.
    expectOutput("A<cfoutput>P</cfoutput>\n<cfset c = 3>B", "AP B");
    expectOutput("A<cfoutput>R</cfoutput>\n<cfoutput>S</cfoutput>B", "AR SB");
    expectOutput("A<cfscript>writeOutput(\"T\");</cfscript>\n<cfset h = 6>B", "AT B");
    // But before <cfoutput> it is removed.
    expectOutput("A<cfset d = 4>\n<cfoutput>Q</cfoutput>B", "AQB");
    // A <cfdump format="text"> writes through a buffered path (no space).
    expectOutput("<cfdump var=\"z\" format=\"text\">\n<cfset y = 1>B", "<pre>z</pre>B");
    expectOutput("<cfdump var=\"z\" format=\"text\">\n", "<pre>z</pre>");
}

TEST_F(WhitespaceManagementTest, SpaceAfterTagFollowingOutput) {
    // A newline after </cfif> becomes a space only when an output-producing tag
    // has emitted since the last collapsed/removed whitespace region.
    expectOutput("P<cfoutput>X</cfoutput>\nP<cfif true>Y</cfif>\n<cfset w = 1>Q", "PX\nPY Q");
    // Without the preceding <cfoutput> the same region is removed.
    expectOutput("P<cfif true>Y</cfif>\n<cfset w = 1>Q", "PYQ");
    // A <cfset> before the region consumes the output state, so it is removed.
    expectOutput("P<cfoutput>X</cfoutput>\n<cfset a = 1>P<cfif true>Y</cfif>\n<cfset w = 1>Q", "PX PYQ");
}

TEST_F(WhitespaceManagementTest, RuntimeSpaceDependsOnOutputTail) {
    // The space is only added when the output so far does not end in whitespace.
    expectOutput("P<cfset x = \"V\">\n<cfoutput>#x#</cfoutput>\n<cfset w = 1>Q", "PV Q");
    // A <cfoutput> value ending with a newline suppresses the space.
    expectOutput("P<cfset x = \"V#chr(10)#\">\n<cfoutput>#x#</cfoutput>\n<cfset w = 1>Q", "PV\nQ");
    // An empty output buffer suppresses the space too.
    expectOutput("<cfoutput></cfoutput>\n<cfset w = 1>Q", "Q");
}

TEST_F(WhitespaceManagementTest, LeadingAndTrailingWhitespaceRemoved) {
    expectOutput("\n<cfset y = 1>A", "A");
    expectOutput("A<cfset y = 1>\n", "A");
    expectOutput(" <cfset y = 1>A", "A");
    // ... except after an output-producing tag at the end of the template.
    expectOutput("A<cfoutput>X</cfoutput>\n", "AX ");
    expectOutput("<cfoutput>x</cfoutput><cfscript>y = 1;</cfscript>", "x");
    expectOutput("<cfoutput>x</cfoutput><cfscript>y = 1;</cfscript>\n", "x ");
}

TEST_F(WhitespaceManagementTest, CfoutputBodyTrailingWhitespaceManaged) {
    // A line break after #expr# inside <cfoutput> collapses to a space.
    expectOutput("<cfset x = \"V\"><cfoutput>#x#\n</cfoutput>", "V ");
    // Leading whitespace before the first #expr# is removed.
    expectOutput("<cfset x = \"V\"><cfoutput>   #x#</cfoutput>", "V");
    // Plain text runs inside <cfoutput> are untouched.
    expectOutput("<cfoutput>  B  </cfoutput>", "  B  ");
    expectOutput("<cfoutput>\nZ\n</cfoutput>", "\nZ\n");
}

TEST_F(WhitespaceManagementTest, CommentsAreTransparent) {
    expectOutput("A<cfset a = 1>\n<!--- c --->\n<cfset b = 2>B", "AB");
    expectOutput("A<cfoutput>P</cfoutput>\n<!--- c --->\n<cfset b = 2>B", "AP B");
    expectOutput("A<cfset a = 1>\n<!--- c --->\nB", "A\n\nB");
}

// ---- <cfsilent> (suppresses the body's output) ----

class SilentTagTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    // Runs CFML and returns the raw output bytes.
    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }

    void expectOutput(const string &cfml_code, const char *expected) {
        string out = run(cfml_code);
        EXPECT_EQ(out.equals(expected), true) << "CFML: " << cfml_code.constData() << " -> " << out.constData();
    }
};

TEST_F(SilentTagTest, SuppressesCfoutput) {
    expectOutput("<cfsilent><cfoutput>X</cfoutput></cfsilent>", "");
    expectOutput("<cfoutput>A</cfoutput><cfsilent><cfoutput>X</cfoutput></cfsilent><cfoutput>B</cfoutput>", "AB");
}

TEST_F(SilentTagTest, SuppressesSharpExpressions) {
    expectOutput("<cfset v = 9><cfsilent><cfoutput>#v#</cfoutput></cfsilent><cfoutput>#v#</cfoutput>", "9");
}

TEST_F(SilentTagTest, SuppressesPlainText) {
    expectOutput("<cfsilent>PLAINTEXT</cfsilent><cfoutput>|A</cfoutput>", "|A");
    expectOutput("<cfsilent>line1\nline2\nline3</cfsilent><cfoutput>|A</cfoutput>", "|A");
}

TEST_F(SilentTagTest, SuppressesWriteOutputInCfscript) {
    expectOutput("<cfsilent><cfscript>writeOutput(\"HID\");</cfscript></cfsilent><cfoutput>|A</cfoutput>", "|A");
}

TEST_F(SilentTagTest, VariableSetInsideIsVisibleOutside) {
    expectOutput("<cfsilent><cfset q = 5></cfsilent><cfoutput>#q#</cfoutput>", "5");
}

TEST_F(SilentTagTest, NestedSilent) {
    expectOutput("<cfsilent><cfsilent><cfoutput>X</cfoutput></cfsilent><cfoutput>Y</cfoutput></cfsilent><cfoutput>|A</cfoutput>", "|A");
    // A self-closing nested <cfsilent/> must not swallow the rest of the outer body.
    expectOutput("<cfsilent><cfsilent/><cfoutput>Y</cfoutput></cfsilent><cfoutput>|A</cfoutput>", "|A");
}

TEST_F(SilentTagTest, SelfClosingHasNoBody) {
    expectOutput("<cfsilent/><cfoutput>|A</cfoutput>", "|A");
    expectOutput("<cfoutput>A</cfoutput><cfsilent/><cfoutput>B</cfoutput>", "AB");
}

TEST_F(SilentTagTest, SuppressesCfdump) {
    expectOutput("<cfset s = {a:1}><cfsilent><cfdump var=\"#s#\"></cfsilent><cfoutput>|A</cfoutput>", "|A");
}

TEST_F(SilentTagTest, InsideLoop) {
    expectOutput("<cfloop from=\"1\" to=\"3\" index=\"i\"><cfsilent><cfoutput>#i#</cfoutput></cfsilent><cfoutput>#i#</cfoutput></cfloop>", "123");
}

TEST_F(SilentTagTest, OuterWhitespaceManagementUnaffected) {
    // cfsilent participates in whitespace management as a plain tag.
    expectOutput("A<cfoutput>P</cfoutput>\n<cfsilent><cfoutput>X</cfoutput></cfsilent>\n<cfoutput>B</cfoutput>", "AP B");
    // Whitespace adjacent to plain text after </cfsilent> is kept verbatim (CF).
    expectOutput("<cfset a=1>\n<cfsilent>X</cfsilent>\nB", "\nB");
}

TEST_F(SilentTagTest, ExceptionPropagatesOut) {
    // An exception raised in the body is not swallowed; it propagates to an
    // enclosing cftry or out of the template.
    expectOutput("<cftry><cfsilent><cfthrow message=\"boom\"></cfsilent><cfcatch><cfoutput>CAUGHT_#cfcatch.message#</cfoutput></cfcatch></cftry>", "CAUGHT_boom");
    bool threw = false;
    try {
        run("<cfsilent><cfthrow message=\"boom\"></cfsilent>");
    } catch (const webstrada::exception &) {
        threw = true;
    }
    EXPECT_EQ(threw, true);
}

TEST_F(SilentTagTest, UnterminatedSilentRunsToEnd) {
    // An unterminated <cfsilent> treats the rest of the template as its body
    // (matching CF), so the trailing output is suppressed.
    expectOutput("<cfoutput>A|</cfoutput><cfsilent><cfoutput>X</cfoutput>", "A|");
}

TEST_F(SilentTagTest, AttributesRejectedAtCompileTime) {
    bool threw = false;
    try {
        run("<cfsilent foo=\"bar\"></cfsilent>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("Attribute validation error for the cfsilent tag."), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(SilentTagTest, WriteOutputInsideSilentInsideCatch) {
    expectOutput("<cftry><cfthrow message=\"x\"><cfcatch><cfsilent><cfoutput>HID</cfoutput></cfsilent><cfoutput>C#cfcatch.message#</cfoutput></cfcatch></cftry>", "Cx");
}

TEST_F(SilentTagTest, TagNamesAreCaseInsensitive) {
    // CFML tag names are case-insensitive (matching Adobe CF): <CFSILENT> is
    // dispatched the same as <cfsilent>, and so are all other tags.
    expectOutput("<CFSILENT><CFOUTPUT>X</CFOUTPUT></CFSILENT><CFOUTPUT>|A</CFOUTPUT>", "|A");
    expectOutput("<CfsIlEnT><cfoUtPuT>X</cfoUtPuT></CFSILENT><CFOUTPUT>|A</CFOUTPUT>", "|A");
    expectOutput("<CFSILENT><CFSET q = 5></CFSILENT><CFOUTPUT>#q#</CFOUTPUT>", "5");
    expectOutput("<CFSET v = 40><CFOUTPUT>#v + 2#</CFOUTPUT>", "42");
    expectOutput("<CFIF v EQ 40><CFOUTPUT>|IF</CFOUTPUT><CFELSE><CFOUTPUT>|ELSE</CFOUTPUT></CFIF>", "|IF");
    expectOutput("<CFLOOP from=\"1\" to=\"3\" index=\"i\"><CFOUTPUT>#i#</CFOUTPUT></CFLOOP>", "123");
    expectOutput("<CFSWITCH expression=\"2\"><CFCASE value=\"2\"><CFOUTPUT>T</CFOUTPUT></CFCASE><CFDEFAULTCASE><CFOUTPUT>D</CFOUTPUT></CFDEFAULTCASE></CFSWITCH>", "T");
    expectOutput("<CFTRY><CFTHROW message=\"m\"><CFCATCH><CFOUTPUT>#cfcatch.message#</CFOUTPUT></CFCATCH></CFTRY>", "m");
    // A cfdump with an uppercase tag still dispatches (and with format="text"
    // does not arm the whitespace flag).
    expectOutput("<CFSET s = {a:1}><CFDUMP var=\"#s#\" format=\"text\"><CFOUTPUT>|A</CFOUTPUT>", "<pre>struct\r\n\r\nA: 1\r\n</pre>|A");
}

// ---- <cfxml> (captures body output and assigns the parsed XML document) ----

class CfXmlTagTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }

    // Runs CFML then evaluates `expr` against the request's variables.
    string eval(const string &expr) {
        string out;
        cfvariant result = cfml::cfevaluate(out, expr.constData(), &variables);
        return result.toString().constData() ? result.toString().constData() : "";
    }

    void expectOutput(const string &cfml_code, const char *expected) {
        string out = run(cfml_code);
        EXPECT_EQ(out.equals(expected), true) << "CFML: " << cfml_code.constData() << " -> " << out.constData();
    }
};

TEST_F(CfXmlTagTest, AssignsXmlDocument) {
    expectOutput("<cfxml variable=\"d\"><root><child id=\"1\">text</child></root></cfxml>", "");
    EXPECT_EQ(eval("IsXmlDoc(d)").equals("YES"), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlName").equals("root"), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlChildren[1].XmlName").equals("child"), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlChildren[1].XmlText").equals("text"), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlChildren[1].XmlAttributes.id").equals("1"), true);
}

TEST_F(CfXmlTagTest, DoesNotEmitBody) {
    expectOutput("<cfoutput>A</cfoutput><cfxml variable=\"d\"><root>x</root></cfxml><cfoutput>B</cfoutput>", "AB");
}

TEST_F(CfXmlTagTest, DynamicVariableName) {
    expectOutput("<cfset n = \"dyn\"><cfxml variable=\"#n#\"><root><a>1</a></root></cfxml>", "");
    EXPECT_EQ(eval("IsXmlDoc(dyn)").equals("YES"), true);
}

TEST_F(CfXmlTagTest, DottedAndScopedVariableName) {
    expectOutput("<cfset holder = structNew()><cfxml variable=\"holder.mydoc\"><r>1</r></cfxml>", "");
    EXPECT_EQ(eval("IsXmlDoc(holder.mydoc)").equals("YES"), true);
    expectOutput("<cfset vn = \"scoped\"><cfxml variable=\"variables.#vn#\"><s>2</s></cfxml>", "");
    EXPECT_EQ(eval("IsXmlDoc(scoped)").equals("YES"), true);
}

TEST_F(CfXmlTagTest, CasesensitivePreservesCase) {
    expectOutput("<cfxml variable=\"cs\" casesensitive=\"true\"><RooT><CHILD>v</CHILD></RooT></cfxml>", "");
    EXPECT_EQ(eval("cs.XmlRoot.XmlName").equals("RooT"), true);
    EXPECT_EQ(eval("cs.XmlRoot.XmlChildren[1].XmlName").equals("CHILD"), true);
    // Case-insensitive doc uppercases the root key (matching CF's default).
    expectOutput("<cfxml variable=\"ci\"><RooT><CHILD>v</CHILD></RooT></cfxml>", "");
    EXPECT_EQ(eval("ci.ROOT.XmlName").equals("RooT"), true);
}

TEST_F(CfXmlTagTest, BodySharpNotInterpolated) {
    // A bare #...# in the <cfxml> body is literal text (CF does not interpolate
    // it unless the expression sits inside a <cfoutput>).
    expectOutput("<cfset v = 42><cfxml variable=\"d\"><root><a>#v#</a></root></cfxml>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlChildren[1].XmlText").equals("#v#"), true);
    expectOutput("<cfset v = 42><cfxml variable=\"d\"><root><a><cfoutput>#v#</cfoutput></a></root></cfxml>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlChildren[1].XmlText").equals("42"), true);
}

TEST_F(CfXmlTagTest, CfsetInBodyRuns) {
    // <cfset> inside the body executes (shared scope), but produces no XML text.
    expectOutput("<cfxml variable=\"d\"><root><a><cfset x = 7></a></root></cfxml>", "");
    EXPECT_EQ(eval("x").equals("7"), true);
}

TEST_F(CfXmlTagTest, XmlTextConcatenatesDirectTextOnly) {
    // XmlText of an element concatenates only its direct text children, not the
    // text of nested elements (matching CF; verified on the RDS host).
    expectOutput("<cfxml variable=\"d\"><root>pre<a>1</a>mid</root></cfxml>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlText").equals("premid"), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlChildren[1].XmlText").equals("1"), true);
}

TEST_F(CfXmlTagTest, XmlValueOfElementIsEmpty) {
    expectOutput("<cfxml variable=\"d\"><root><a>1</a></root></cfxml>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlValue").equals(""), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlChildren[1].XmlValue").equals(""), true);
}

TEST_F(CfXmlTagTest, NodeNamesForSpecialTypes) {
    expectOutput("<cfxml variable=\"d\"><root>pre<a>1</a><!--c--></root></cfxml>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlNodes[1].XmlName").equals("#text"), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlNodes[1].XmlValue").equals("pre"), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlNodes[3].XmlName").equals("#comment"), true);
}

TEST_F(CfXmlTagTest, SameNameChildrenSingleVsArray) {
    // A single occurrence resolves to the element itself; multiple ones to an
    // XmlNodeArray that IsArray() rejects but len()/ArrayLen()/indexing accept.
    expectOutput("<cfxml variable=\"s\"><root><Child>x</Child></root></cfxml>", "");
    EXPECT_EQ(eval("IsArray(s.XmlRoot.CHILD)").equals("NO"), true);
    EXPECT_EQ(eval("s.XmlRoot.CHILD.XmlText").equals("x"), true);
    expectOutput("<cfxml variable=\"m\"><root><Child>1</Child><Child>2</Child></root></cfxml>", "");
    EXPECT_EQ(eval("IsArray(m.XmlRoot.CHILD)").equals("NO"), true);
    EXPECT_EQ(eval("ArrayLen(m.XmlRoot.CHILD)").equals("2"), true);
    EXPECT_EQ(eval("m.XmlRoot.CHILD[2].XmlText").equals("2"), true);
}

TEST_F(CfXmlTagTest, XmlChildrenIsARealArray) {
    expectOutput("<cfxml variable=\"d\"><root><a>1</a><a>2</a></root></cfxml>", "");
    EXPECT_EQ(eval("IsArray(d.XmlRoot.XmlChildren)").equals("YES"), true);
    EXPECT_EQ(eval("ArrayLen(d.XmlRoot.XmlChildren)").equals("2"), true);
}

TEST_F(CfXmlTagTest, WhitespaceInBodyTrimmed) {
    expectOutput("<cfxml variable=\"d\">\n<root>\n  <a>1</a>\n</root>\n</cfxml>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlName").equals("root"), true);
    EXPECT_EQ(eval("d.XmlRoot.XmlChildren[1].XmlText").equals("1"), true);
}

TEST_F(CfXmlTagTest, NestedCfxml) {
    expectOutput("<cfxml variable=\"outer\"><o><cfxml variable=\"inner\"><i>n</i></cfxml><b>#inner.XmlRoot.XmlName#</b></o></cfxml>", "");
    EXPECT_EQ(eval("IsXmlDoc(inner)").equals("YES"), true);
    EXPECT_EQ(eval("inner.XmlRoot.XmlName").equals("i"), true);
}

TEST_F(CfXmlTagTest, EmptyAndMalformedBodyThrow) {
    bool threw = false;
    try {
        run("<cfxml variable=\"d\"></cfxml>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("An error occurred while Parsing an XML document."), true);
    }
    EXPECT_EQ(threw, true);

    threw = false;
    try {
        run("<cfxml variable=\"d\"><root><a></root></cfxml>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("An error occurred while Parsing an XML document."), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(CfXmlTagTest, MissingVariableCompileError) {
    bool threw = false;
    try {
        run("<cfxml><root>no var</root></cfxml>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("cfxml"), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(CfXmlTagTest, UnknownAttributeCompileError) {
    bool threw = false;
    try {
        run("<cfxml variable=\"d\" bogus=\"1\"><root/></cfxml>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("Attribute validation error for the cfxml tag."), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(CfXmlTagTest, TagNamesAreCaseInsensitive) {
    expectOutput("<CFXML variable=\"d\"><root><a>1</a></root></CFXML>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlName").equals("root"), true);
    expectOutput("<CfXml variable=\"d\"><root/></CfXml>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlName").equals("root"), true);
    expectOutput("<CfXMl variable=\"d\"><root/></CfXMl>", "");
    EXPECT_EQ(eval("d.XmlRoot.XmlName").equals("root"), true);
}

TEST_F(CfXmlTagTest, ArrayAppendOnNodeListUnsupported) {
    expectOutput("<cfxml variable=\"m\"><root><Child>1</Child><Child>2</Child></root></cfxml>", "");
    bool threw = false;
    try {
        run("<cfxml variable=\"m\"><root><Child>1</Child><Child>2</Child></root></cfxml><cfoutput>#arrayAppend(m.XmlRoot.CHILD, \"3\")#</cfoutput>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("The ArrayAppend ColdFusion function is not supported on this object."), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(CfXmlTagTest, XmlParseErrorMessageMatchesCf) {
    // XmlParse() must report the same parse-failure message as <cfxml> — CF 2025
    // throws `An error occurred while Parsing an XML document.` (type Expression,
    // catchable) for both, while XmlParse previously reported its own wording
    // "XmlParse: Failed to parse XML markup". Verified on the RDS host.
    bool threw = false;
    try {
        run("<cfscript>XmlParse('<invalid>');</cfscript>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("An error occurred while Parsing an XML document."), true);
    }
    EXPECT_EQ(threw, true);
}

// ---- <cfquery> ----

class CfQueryTest : public testing::Test {
protected:
    cfvariant variables;
    std::string dsnDir;
    std::string savedDsnDir;
    std::string savedScopeDbPath;

    void SetUp() override {
        variables = cfvariant::Struct;
        // Route the per-DSN SQLite files to a fresh temp dir (the default is
        // "next to the executable", which would pollute the repo's bin/).
        char dir[] = "/tmp/webstrada_query_test_XXXXXX";
        char *d = mkdtemp(dir);
        EXPECT_NE(d, nullptr);
        dsnDir = d;
        savedDsnDir = webstrada::config::dsnDbDir;
        savedScopeDbPath = webstrada::config::scopeDbPath;
        webstrada::config::dsnDbDir = dsnDir;
    }

    void TearDown() override {
        webstrada::config::dsnDbDir = savedDsnDir;
        webstrada::config::scopeDbPath = savedScopeDbPath;
        // Remove the DSN database (plus its WAL/SHM sidecars).
        unlink((dsnDir + "/DNS_test.sqlite").c_str());
        unlink((dsnDir + "/DNS_test.sqlite-wal").c_str());
        unlink((dsnDir + "/DNS_test.sqlite-shm").c_str());
        rmdir(dsnDir.c_str());
    }

    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }

    string eval(const string &expr) {
        string out;
        cfvariant result = cfml::cfevaluate(out, expr.constData(), &variables);
        return result.toString().constData() ? result.toString().constData() : "";
    }

    void expectOutput(const string &cfml_code, const char *expected) {
        string out = run(cfml_code);
        EXPECT_EQ(out.equals(expected), true) << "CFML: " << cfml_code.constData() << " -> " << out.constData();
    }

    // Fresh tables for an isolated test run (the DSN file may persist between
    // runs of the same binary, so the tables are recreated defensively).
    string setupSql(const string &tableName) {
        return "<cfquery datasource=\"test\">DROP TABLE IF EXISTS " + tableName + "</cfquery>\n"
               "<cfquery datasource=\"test\">CREATE TABLE " + tableName +
               " (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, age INTEGER)</cfquery>\n"
               "<cfquery datasource=\"test\">INSERT INTO " + tableName +
               " (name, age) VALUES ('alice', 30)</cfquery>\n"
               "<cfquery datasource=\"test\">INSERT INTO " + tableName +
               " (name, age) VALUES ('bob', 25)</cfquery>\n";
    }
};

TEST_F(CfQueryTest, BasicSelectStoresQuery) {
    string cfml = setupSql("q_basic");
    cfml += "<cfquery name=\"q\" datasource=\"test\">SELECT id, name, age FROM q_basic ORDER BY id</cfquery>\n";
    cfml += "<cfoutput>#q.recordcount#|#q.columnlist#|#q.name#|#q.age#</cfoutput>";
    expectOutput(cfml, "2|AGE,ID,NAME|alice|30");
}

TEST_F(CfQueryTest, EmitsNoOutputFromBody) {
    expectOutput(setupSql("q_noout") + "<cfoutput>X</cfoutput><cfquery datasource=\"test\">SELECT * FROM q_noout</cfquery><cfoutput>Y</cfoutput>", "XY");
}

TEST_F(CfQueryTest, SqlInterpolationInBody) {
    string cfml = setupSql("q_interp");
    cfml += "<cfset minAge = 26>\n";
    cfml += "<cfquery name=\"q\" datasource=\"test\">SELECT name FROM q_interp WHERE age > #minAge#</cfquery>\n";
    cfml += "<cfoutput>#q.recordcount#:#q.name#</cfoutput>";
    // Only bob (25) is excluded; alice (30) is not > 26.
    expectOutput(cfml, "1:alice");
}

TEST_F(CfQueryTest, ResultStructKeys) {
    string cfml = setupSql("q_result");
    cfml += "<cfquery name=\"q\" datasource=\"test\" result=\"r\">SELECT id, name FROM q_result ORDER BY id</cfquery>\n";
    cfml += "<cfoutput>#r.RECORDCOUNT#|#r.CACHED#|#r.COLUMNLIST#|#StructKeyExists(r, 'SQL')#|#StructKeyExists(r, 'EXECUTIONTIME')#</cfoutput>";
    expectOutput(cfml, "2|false|ID,NAME|YES|YES");
    EXPECT_EQ(eval("r.SQL").contains("SELECT id, name FROM q_result"), true);
}

TEST_F(CfQueryTest, ResultSqlReflectsInterpolatedBody) {
    string cfml = setupSql("q_sql");
    cfml += "<cfset v = 7>\n";
    cfml += "<cfquery name=\"q\" datasource=\"test\" result=\"r\">SELECT name FROM q_sql WHERE id = #v#</cfquery>\n";
    cfml += "<cfoutput>#r.SQL#</cfoutput>";
    string out = run(cfml);
    EXPECT_EQ(out.contains("WHERE id = 7"), true);
    EXPECT_EQ(out.contains("WHERE id = #v#"), false);
}

TEST_F(CfQueryTest, InsertSetsAffectedRowsAndGeneratedKey) {
    string cfml = setupSql("q_ins");
    cfml += "<cfquery name=\"q\" datasource=\"test\" result=\"r\">INSERT INTO q_ins (name, age) VALUES ('carol', 40)</cfquery>\n";
    // CF leaves `name` UNDEFINED for a non-result-set statement (setAttribute
    // with a null result) — IsDefined is NO — and reports the affected rows
    // plus the auto-increment id only in the result struct.
    cfml += "<cfoutput>#IsDefined('q')#|#r.RECORDCOUNT#|#r.GENERATEDKEY#|#StructKeyExists(r, 'COLUMNLIST')#</cfoutput>";
    // Two prior inserts consumed ids 1 and 2; this third one gets id 3.
    expectOutput(cfml, "NO|1|3|NO");
}

TEST_F(CfQueryTest, MaxrowsLimitsRows) {
    string cfml = setupSql("q_max");
    cfml += "<cfquery name=\"q\" datasource=\"test\" maxrows=\"1\">SELECT id, name FROM q_max ORDER BY id</cfquery>\n";
    cfml += "<cfoutput>#q.recordcount#:#q.id#</cfoutput>";
    expectOutput(cfml, "1:1");
}

TEST_F(CfQueryTest, EmptyResultSetStillReportsColumns) {
    string cfml = setupSql("q_empty");
    cfml += "<cfquery name=\"q\" datasource=\"test\">SELECT id, name FROM q_empty WHERE age > 1000</cfquery>\n";
    cfml += "<cfoutput>#q.recordcount#|#q.columnlist#</cfoutput>";
    expectOutput(cfml, "0|ID,NAME");
}

TEST_F(CfQueryTest, NonSelectStatementNoResult) {
    string cfml = "<cfquery datasource=\"test\">DROP TABLE IF EXISTS q_ddl</cfquery>\n";
    cfml += "<cfquery name=\"q\" datasource=\"test\">CREATE TABLE q_ddl (a TEXT)</cfquery>\n";
    cfml += "<cfoutput>#IsDefined('q')#</cfoutput>";
    expectOutput(cfml, "NO");
}

TEST_F(CfQueryTest, WithoutNameStillExecutes) {
    string cfml = setupSql("q_noname");
    cfml += "<cfquery datasource=\"test\">SELECT * FROM q_noname</cfquery>\n";
    cfml += "<cfoutput>OK</cfoutput>";
    expectOutput(cfml, "OK");
}

TEST_F(CfQueryTest, CaseInsensitiveTagAndAttributes) {
    string cfml = setupSql("q_case");
    cfml += "<CFQUERY Name=\"q\" DataSource=\"test\" Result=\"r\">SELECT id FROM q_case</CFQUERY>\n";
    cfml += "<cfoutput>#q.recordcount#|#r.RECORDCOUNT#</cfoutput>";
    expectOutput(cfml, "2|2");
}

TEST_F(CfQueryTest, EscapedHashInBody) {
    string cfml = setupSql("q_hash");
    // A literal # in the SQL text (## escape) is passed through.
    cfml += "<cfquery name=\"q\" datasource=\"test\">SELECT '#x' AS lit</cfquery>\n";
    cfml += "<cfoutput>#q.lit#</cfoutput>";
    // '#' followed by a space: the "##" escape emits a literal '#' only when
    // the text is a bare # ; here a single '#' in "x#x" is literal text.
    expectOutput(cfml, "#x");
}

TEST_F(CfQueryTest, NoDatasourceThrows) {
    bool threw = false;
    try {
        run("<cfquery name=\"q\">SELECT 1</cfquery>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).contains("no data source"), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(CfQueryTest, UnknownAttributeCompileError) {
    bool threw = false;
    try {
        run("<cfquery name=\"q\" datasource=\"test\" bogus=\"1\">SELECT 1</cfquery>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("Attribute validation error for the cfquery tag."), true);
        EXPECT_EQ(string(e.m_detail).contains("does not have an attribute called"), true);
    }
    EXPECT_EQ(threw, true);
}

