TEST_F(CfQueryTest, MultipleStatementsExecute) {
    // CF hands the whole body to Statement.execute(); batch-capable drivers run
    // every statement and only the FIRST result is surfaced (Executive.getRowSet
    // returns after the first result set / reports the first update count).
    // Verified against CF 2025 on the RDS host.
    string cfml = "<cfquery datasource=\"test\">DROP TABLE IF EXISTS q_multi</cfquery>\n";
    cfml += "<cfquery name=\"q\" datasource=\"test\" result=\"r\">SELECT 1 AS a; SELECT 2 AS b</cfquery>\n";
    cfml += "<cfoutput>#q.recordcount#|#q.columnlist#|#r.RECORDCOUNT#</cfoutput>";
    expectOutput(cfml, "1|A|1");
    // A first non-result statement leaves `name` undefined; RECORDCOUNT is the
    // first statement's update count.
    cfml = "<cfquery datasource=\"test\">DROP TABLE IF EXISTS q_multi2</cfquery>\n";
    cfml += "<cfquery datasource=\"test\">CREATE TABLE q_multi2 (id INTEGER)</cfquery>\n";
    cfml += "<cfquery name=\"q2\" datasource=\"test\" result=\"r2\">INSERT INTO q_multi2 (id) VALUES (9); SELECT 5 AS five</cfquery>\n";
    cfml += "<cfoutput>#IsDefined('q2')#|#r2.RECORDCOUNT#</cfoutput>";
    expectOutput(cfml, "NO|1");
    // All statements execute: both INSERTs after the SELECT still land.
    cfml = "<cfquery datasource=\"test\">DROP TABLE IF EXISTS q_multi3</cfquery>\n";
    cfml += "<cfquery datasource=\"test\">CREATE TABLE q_multi3 (id INTEGER)</cfquery>\n";
    cfml += "<cfquery name=\"ins\" datasource=\"test\" result=\"insr\">INSERT INTO q_multi3 VALUES (1); INSERT INTO q_multi3 VALUES (2)</cfquery>\n";
    cfml += "<cfquery name=\"cnt\" datasource=\"test\">SELECT COUNT(*) AS n FROM q_multi3</cfquery>\n";
    cfml += "<cfoutput>#insr.RECORDCOUNT#|#cnt.n#</cfoutput>";
    cfml += "<cfquery datasource=\"test\">DROP TABLE IF EXISTS q_multi3</cfquery>";
    expectOutput(cfml, "1|2");
}

