    // #...# interpolation in the middle keeps the surrounding spaces exactly.
    string cfml2 = "<cfset x = 4>\n<cfquery name=\"q\" datasource=\"test\" result=\"r\">SELECT  #x#  AS four</cfquery>\n";
    cfml2 += "<cfoutput>[#r.SQL#]</cfoutput>";
