    string cfml2 = "<cfquery name=\"q\" datasource=\"test\" result=\"r\"><cfoutput>SELECT 1 AS one</cfoutput></cfquery>\n";
    cfml2 += "<cfoutput>[#r.SQL#]</cfoutput>";
