TEST_F(MySqlDbTest, DecimalPreservesScaleLikeBigDecimal) {
    // A DECIMAL column stringifies with its original scale (CF stores it as a
    // java.math.BigDecimal: "12.50", not "12.5") while staying numeric for
    // arithmetic. Verified against CF 2025 on the RDS host.
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_my_decimal", -1);
    c->execute("CREATE TABLE dl_my_decimal (id INT PRIMARY KEY, price DECIMAL(10,2))", -1);
    c->execute("INSERT INTO dl_my_decimal VALUES (1, 12.50)", -1);
    delete c;

    db::DBResult r = run("SELECT price FROM dl_my_decimal WHERE id = 1");
    ASSERT_EQ(r.rowCount, 1);
    ASSERT_EQ(r.columns.size(), 1u);
    const cfvariant &cell = r.columns[0].values[0];
    EXPECT_EQ(const_cast<cfvariant&>(cell).toString().equals("12.50"), true) << const_cast<cfvariant&>(cell).toString().constData();
    EXPECT_EQ(cell.m_type, cfvariant::Float);
    EXPECT_DOUBLE_EQ(cell.m_double, 12.5);

    // Roundtrip through a JIT <cfquery> renders the scaled value and does
    // arithmetic on the underlying double.
    cfvariant variables = cfvariant::Struct;
    string out = runJitTemplate(
        "<cfquery name=\"q\" datasource=\"mysqltest\">SELECT price FROM dl_my_decimal WHERE id = 1</cfquery>\n"
        "<cfoutput>#q.price#|#q.price + 1#|#q.price * 2#|#q.price / 2#</cfoutput>", variables);
    EXPECT_EQ(out.equals("12.50|13.5|25|6.25"), true) << out.constData();
}

TEST_F(MySqlDbTest, DecimalZeroScaleTrailingZeroPreserved) {
    // A DECIMAL(10,2) storing 0.00 keeps both trailing zeros (BigDecimal "0.00").
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_my_decimal0", -1);
    c->execute("CREATE TABLE dl_my_decimal0 (id INT PRIMARY KEY, price DECIMAL(10,2))", -1);
    c->execute("INSERT INTO dl_my_decimal0 VALUES (1, 0.00)", -1);
    delete c;
    db::DBResult r = run("SELECT price FROM dl_my_decimal0 WHERE id = 1");
    ASSERT_EQ(r.rowCount, 1);
    EXPECT_EQ(const_cast<cfvariant&>(r.columns[0].values[0]).toString().equals("0.00"), true)
        << const_cast<cfvariant&>(r.columns[0].values[0]).toString().constData();
}

