// <cfstoredproc> / <cfprocparam> / <cfprocresult> against the live server: OUT
// parameters, the result struct, and result-set binding (MySQL procedures
// return result sets from SELECT statements in their bodies).

TEST_F(MySqlDbTest, StoredProcOutParamsAndResultStruct) {
    db::DBConnection *c = conn();
    c->execute("DROP PROCEDURE IF EXISTS dl_my_sp1", -1);
    c->execute("CREATE PROCEDURE dl_my_sp1(IN a INT, IN b INT, OUT s INT) "
               "BEGIN SET s = a + b; END", -1);
    delete c;
    cfvariant variables = cfvariant::Struct;
    string out = runJitTemplate(
        "<cfstoredproc procedure=\"dl_my_sp1\" datasource=\"mysqltest\" result=\"r\">\n"
        "<cfprocparam type=\"in\" cfsqltype=\"CF_SQL_INTEGER\" value=\"2\">\n"
        "<cfprocparam type=\"in\" cfsqltype=\"CF_SQL_INTEGER\" value=\"3\">\n"
        "<cfprocparam type=\"out\" cfsqltype=\"CF_SQL_INTEGER\" variable=\"s\">\n"
        "</cfstoredproc>\n"
        "<cfoutput>#s#|#StructKeyExists(r,'EXECUTIONTIME')#|#StructKeyExists(r,'STATUSCODE')#|#r.CACHED#</cfoutput>", variables);
    EXPECT_EQ(out.equals("5|YES|NO|false"), true) << out.constData();
}

TEST_F(MySqlDbTest, StoredProcResultSetBinding) {
    db::DBConnection *c = conn();
    c->execute("DROP PROCEDURE IF EXISTS dl_my_spr", -1);
    c->execute("CREATE PROCEDURE dl_my_spr(IN n INT) "
               "BEGIN DROP TEMPORARY TABLE IF EXISTS dl_my_tmp; "
               "CREATE TEMPORARY TABLE dl_my_tmp (id INT, nm VARCHAR(20)); "
               "SET @i = 1; WHILE @i <= n DO "
               "INSERT INTO dl_my_tmp VALUES (@i, CONCAT('name', @i)); SET @i = @i + 1; END WHILE; "
               "SELECT * FROM dl_my_tmp ORDER BY id; END", -1);
    delete c;
    cfvariant variables = cfvariant::Struct;
    string out = runJitTemplate(
        "<cfstoredproc procedure=\"dl_my_spr\" datasource=\"mysqltest\">\n"
        "<cfprocparam type=\"in\" cfsqltype=\"CF_SQL_INTEGER\" value=\"3\">\n"
        "<cfprocresult name=\"q\" resultset=\"1\">\n"
        "</cfstoredproc>\n"
        "<cfoutput>#q.recordcount#|#q.id#|#q.nm#</cfoutput>", variables);
    EXPECT_EQ(out.equals("3|1|name1"), true) << out.constData();
}

TEST_F(MySqlDbTest, StoredProcMultipleResultSets) {
    db::DBConnection *c = conn();
    c->execute("DROP PROCEDURE IF EXISTS dl_my_spm", -1);
    c->execute("CREATE PROCEDURE dl_my_spm() "
               "BEGIN SELECT 1 AS a, 2 AS b; SELECT 'x' AS c; END", -1);
    delete c;
    cfvariant variables = cfvariant::Struct;
    string out = runJitTemplate(
        "<cfstoredproc procedure=\"dl_my_spm\" datasource=\"mysqltest\">\n"
        "<cfprocresult name=\"rs1\" resultset=\"1\">\n"
        "<cfprocresult name=\"rs2\" resultset=\"2\">\n"
        "</cfstoredproc>\n"
        "<cfoutput>#rs1.recordcount#|#rs1.a#|#rs1.b#|#rs2.recordcount#|#rs2.c#</cfoutput>", variables);
    EXPECT_EQ(out.equals("1|1|2|1|x"), true) << out.constData();
}

// ---- PostgreSQL backend (webstrada::db) ----
//
// Requires a reachable PostgreSQL server configured via the WSDATASOURCE_*
// environment variables (see config::loadDatasourcesFromEnv). The tests skip
// when no server is configured or reachable.

namespace {
bool postgresConfigured()
{
    for (auto &kv : webstrada::config::datasources) {
        std::string k = kv.first;
        for (auto &c : k) c = static_cast<char>(toupper((unsigned char)c));
        if (k == "PGTEST" && (kv.second.backend == "postgres" ||
                              kv.second.backend == "postgresql" ||
                              kv.second.backend == "pg")) return true;
    }
    return false;
}

bool postgresReachable()
{
    if (!postgresConfigured()) return false;
    try {
        db::DBConnection *c = db::openConnection("pgtest", 2000);
        delete c;
        return true;
    } catch (...) {
        return false;
    }
}
} // namespace

class PostgresDbTest : public testing::Test {
protected:
    void SetUp() override {
        if (!postgresReachable()) {
            GTEST_SKIP() << "no PostgreSQL server configured (WSDATASOURCE_PGTEST_*)";
        }
    }

    db::DBConnection *conn() { return db::openConnection("pgtest", 5000); }

    db::DBResult run(const std::string &sql) {
        db::DBConnection *c = conn();
        db::DBResult r = c->execute(sql, -1);
        delete c;
        return r;
    }
};

TEST_F(PostgresDbTest, SelectReturnsColumnsAndRows) {
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_pg_a", -1);
    c->execute("CREATE TABLE dl_pg_a (id INT PRIMARY KEY, name TEXT, age INT)", -1);
    c->execute("INSERT INTO dl_pg_a VALUES (1, 'alice', 30)", -1);
    c->execute("INSERT INTO dl_pg_a VALUES (2, 'bob', 25)", -1);
    db::DBResult r = c->execute("SELECT id, name, age FROM dl_pg_a ORDER BY id", -1);
    delete c;
    ASSERT_EQ(r.columns.size(), 3u);
    EXPECT_EQ(r.rowCount, 2);
    EXPECT_EQ(r.columns[0].values[0].m_int, 1);
    EXPECT_EQ(r.columns[1].values[1].toString().equals("bob"), true);
}

TEST_F(PostgresDbTest, DataPersistsAcrossConnections) {
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_pg_persist", -1);
    c->execute("CREATE TABLE dl_pg_persist (id INT PRIMARY KEY, name TEXT)", -1);
    c->execute("INSERT INTO dl_pg_persist VALUES (1, 'x')", -1);
    delete c;

    db::DBResult r = run("SELECT name FROM dl_pg_persist");
    ASSERT_EQ(r.rowCount, 1);
    EXPECT_EQ(r.columns[0].values[0].toString().equals("x"), true);
}

TEST_F(PostgresDbTest, TransactionCommitPersistsRollbackUndoes) {
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_pg_tx", -1);
    c->execute("CREATE TABLE dl_pg_tx (id INT PRIMARY KEY, name TEXT)", -1);
    delete c;

    db::DBConnection *c1 = conn();
    c1->begin();
    c1->execute("INSERT INTO dl_pg_tx VALUES (1, 'kept')", -1);
    c1->commit();
    delete c1;

    db::DBConnection *c2 = conn();
    c2->begin();
    c2->execute("INSERT INTO dl_pg_tx VALUES (2, 'gone')", -1);
    c2->rollback();
    delete c2;

    db::DBResult r = run("SELECT name FROM dl_pg_tx ORDER BY id");
    EXPECT_EQ(r.rowCount, 1);
    EXPECT_EQ(r.columns[0].values[0].toString().equals("kept"), true);
}

TEST_F(PostgresDbTest, SavepointRollsBackInnerWork) {
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_pg_sp", -1);
    c->execute("CREATE TABLE dl_pg_sp (id INT PRIMARY KEY)", -1);
    c->begin();
    c->execute("INSERT INTO dl_pg_sp VALUES (1)", -1);
    c->setSavepoint("sp1");
    c->execute("INSERT INTO dl_pg_sp VALUES (2)", -1);
    c->rollbackTo("sp1");
    c->execute("INSERT INTO dl_pg_sp VALUES (3)", -1);
    c->commit();
    delete c;

    db::DBResult r = run("SELECT id FROM dl_pg_sp ORDER BY id");
    ASSERT_EQ(r.rowCount, 2);
    EXPECT_EQ(r.columns[0].values[0].m_int, 1);
    EXPECT_EQ(r.columns[0].values[1].m_int, 3);
}

TEST_F(PostgresDbTest, InsertReportsAffectedRowsWithoutGeneratedKey) {
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_pg_ins", -1);
    c->execute("CREATE TABLE dl_pg_ins (id SERIAL PRIMARY KEY, name TEXT)", -1);
    db::DBResult r = c->execute("INSERT INTO dl_pg_ins (name) VALUES ('a')", -1);
    delete c;
    // Modern PostgreSQL tables carry no implicit OIDs, so a plain INSERT has no
    // generated key (matching pgjdbc's getGeneratedKeys without RETURNING).
    EXPECT_EQ(r.rowCount, 1);
    EXPECT_FALSE(r.hasGeneratedKey);
}

TEST_F(PostgresDbTest, InsertReturningSurfacesResultSet) {
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_pg_ret", -1);
    c->execute("CREATE TABLE dl_pg_ret (id SERIAL PRIMARY KEY, name TEXT)", -1);
    db::DBResult r = c->execute("INSERT INTO dl_pg_ret (name) VALUES ('b') RETURNING id", -1);
    delete c;
    ASSERT_EQ(r.columns.size(), 1u);
    EXPECT_EQ(r.columns[0].name, "id");
    EXPECT_EQ(r.rowCount, 1);
    EXPECT_EQ(r.columns[0].values[0].m_int, 1);
}

TEST_F(PostgresDbTest, MultiStatementSurfacesFirstResult) {
    db::DBResult r = run("SELECT 1 AS a; SELECT 2 AS b");
    ASSERT_EQ(r.columns.size(), 1u);
    EXPECT_EQ(r.columns[0].name, "a");
    EXPECT_EQ(r.rowCount, 1);
}

TEST_F(PostgresDbTest, TypeMappings) {
    db::DBConnection *c = conn();
    db::DBResult r = c->execute(
        "SELECT true AS b, 9223372036854775807::bigint AS big, 3.5::numeric AS num, "
        "'\\xdeadbeef'::bytea AS bytes, NULL AS n", -1);
    delete c;
    ASSERT_EQ(r.rowCount, 1);
    ASSERT_EQ(r.columns.size(), 5u);
    EXPECT_EQ(r.columns[0].values[0].m_type, cfvariant::Number);
    EXPECT_EQ(r.columns[0].values[0].m_int, 1);
    EXPECT_EQ(r.columns[1].values[0].m_type, cfvariant::Long);
    EXPECT_EQ(r.columns[1].values[0].m_long, 9223372036854775807LL);
    EXPECT_EQ(r.columns[2].values[0].m_type, cfvariant::Float);
    EXPECT_EQ(r.columns[3].values[0].m_type, cfvariant::Binary);
    EXPECT_EQ(r.columns[3].values[0].m_binary->size(), 4u);
    EXPECT_EQ(r.columns[4].values[0].m_type, cfvariant::Null);
}

TEST_F(PostgresDbTest, TableColumnsIntrospectsSchema) {
    db::DBConnection *c = conn();
    c->execute("DROP TABLE IF EXISTS dl_pg_cols", -1);
    c->execute("CREATE TABLE dl_pg_cols (id INT PRIMARY KEY, name TEXT)", -1);
    std::vector<db::DBConnection::ColumnMeta> cols = c->tableColumns("dl_pg_cols");
    delete c;
    ASSERT_EQ(cols.size(), 2u);
    EXPECT_EQ(cols[0].name, "id");
    EXPECT_TRUE(cols[0].isPk);
    EXPECT_EQ(cols[1].name, "name");
    EXPECT_FALSE(cols[1].isPk);
}

