TEST_F(CfLoopQueryTest, GroupCaseSensitive) {
    string cfml = "<cfquery datasource=\"test\">DROP TABLE IF EXISTS lq_gcs</cfquery>\n";
    cfml += "<cfquery datasource=\"test\">CREATE TABLE lq_gcs (id INTEGER PRIMARY KEY AUTOINCREMENT, grp TEXT)</cfquery>\n";
    cfml += "<cfquery datasource=\"test\">INSERT INTO lq_gcs (grp) VALUES ('G1')</cfquery>\n";
    cfml += "<cfquery datasource=\"test\">INSERT INTO lq_gcs (grp) VALUES ('g1')</cfquery>\n";
    cfml += "<cfquery name=\"q\" datasource=\"test\">SELECT id, grp FROM lq_gcs ORDER BY id</cfquery>";
    // Default: case-insensitive grouping -> G1 and g1 are one group.
    cfml += "D<cfloop query=\"q\" group=\"grp\"><cfoutput>#q.id#;</cfoutput></cfloop>";
    // groupcasesensitive="true": case-sensitive -> every row is its own group.
    cfml += "|CS<cfloop query=\"q\" group=\"grp\" groupcasesensitive=\"true\"><cfoutput>#q.id#;</cfoutput></cfloop>";
    expectOutput(cfml, "D1;|CS1;2;");
}

TEST_F(CfLoopQueryTest, BreakAndContinue) {
    string cfml = setupQuery("lq_ctrl");
    cfml += "B<cfloop query=\"q\"><cfoutput>#q.id#;</cfoutput><cfif q.id EQ 2><cfbreak></cfif></cfloop>";
    cfml += "|C<cfloop query=\"q\"><cfif q.id EQ 2><cfcontinue></cfif><cfoutput>#q.id#;</cfoutput></cfloop>";
    expectOutput(cfml, "\nB1;2;|C1;3;4;");
}

TEST_F(CfLoopQueryTest, DynamicQueryName) {
    string cfml = setupQuery("lq_dyn");
    cfml += "<cfset qn = \"q\">";
    cfml += "<cfloop query=\"#qn#\"><cfoutput>#q.id#;</cfoutput></cfloop>";
    expectOutput(cfml, "1;2;3;4;");
}

TEST_F(CfLoopQueryTest, QueryNewBackedLoop) {
    string cfml = "<cfset q = QueryNew(\"id,name\")>\n";
    cfml += "<cfset QueryAddRow(q, 2)>\n";
    cfml += "<cfset QuerySetCell(q, \"id\", 10, 1)><cfset QuerySetCell(q, \"name\", \"ten\", 1)>\n";
    cfml += "<cfset QuerySetCell(q, \"id\", 20, 2)><cfset QuerySetCell(q, \"name\", \"twenty\", 2)>\n";
    cfml += "<cfloop query=\"q\"><cfoutput>#q.id#:#q.name#;</cfoutput></cfloop>";
    expectOutput(cfml, "10:ten;20:twenty;");
}

