// ---- <cfinclude> ----

// Loads a compiled template from a TemplateCache cache (the `opaque`
// pointer); used as the <cfinclude> loader in the tests below.
static cfml::include_template_fn test_include_loader(const char *path, void *opaque)
{
    TemplateCache *cache = static_cast<TemplateCache*>(opaque);
    if (!cache) return nullptr;
    struct stat st;
    if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) {
        return nullptr;
    }
    template_fn fn = cache->get(webstrada::string(path));
    auto *target = fn.target<cfml::include_template_fn>();
    return target ? *target : nullptr;
}

// Loads a compiled ColdFusion component from a TemplateCache cache (the
// `opaque` pointer); used as the <cfobject>/CreateObject component loader.
static webstrada::ComponentInfo *test_component_loader(const char *path, void *opaque)
{
    TemplateCache *cache = static_cast<TemplateCache*>(opaque);
    if (!cache) return nullptr;
    struct stat st;
    if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) {
        return nullptr;
    }
    return cache->get_component(webstrada::string(path));
}

class CfincludeTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    // Creates a throwaway directory holding the given files
    // (name -> content; parent directories are created as needed) and returns
    // its path. The caller must remove it with removeTempDir.
    static std::string makeTempDir(const std::vector<std::pair<const char*, const char*>> &files)
    {
        char tmpl[] = "/tmp/webstrada_cfinclude_test_XXXXXX";
        char *dir = mkdtemp(tmpl);
        if (!dir) throw std::runtime_error("mkdtemp failed");
        std::string base(dir);
        for (const auto &f : files) {
            std::filesystem::path p(std::string(base + "/" + f.first));
            std::filesystem::create_directories(p.parent_path());
            std::ofstream ofs(p, std::ios::binary);
            ofs.write(f.second, static_cast<std::streamsize>(strlen(f.second)));
        }
        return base;
    }

    static void removeTempDir(const std::string &dir)
    {
        std::filesystem::remove_all(dir);
    }

    // Compiles and runs `mainName` inside `dir` and returns its output. A
    // TemplateCache cache doubles as the <cfinclude> loader so included
    // templates are compiled on demand, exactly like the worker/CLI.
    string runFile(const std::string &dir, const char *mainName)
    {
        std::string mainPath = dir + "/" + mainName;
        TemplateCache templates;
        template_fn compiled = templates.get(webstrada::string(mainPath.c_str()));
        if (!compiled) throw std::runtime_error("Failed to compile main template");

        cfvariant cgi = cfvariant::Struct, server = cfvariant::Struct, cookie = cfvariant::Struct;
        cfvariant application = cfvariant::Struct, session = cfvariant::Struct;
        cfvariant url = cfvariant::Struct, form = cfvariant::Struct;
        string out;

        cfml::VariantCleanupGuard guard;
        cfml::IncludeRuntime rt;
        rt.currentPath = mainPath;
        rt.webRoot = dir;
        rt.loader = &test_include_loader;
        rt.loaderOpaque = &templates;
        cfml::include_begin(&rt);
        try {
            compiled(&out, &cgi, &server, &cookie, &application, &session, &url, &form, &variables);
        } catch (...) {
            cfml::include_end();
            throw;
        }
        cfml::include_end();
        return out;
    }
};

TEST_F(CfincludeTest, BasicRelativeInclude) {
    auto dir = makeTempDir({
        {"main.cfm", "<cfoutput>A|</cfoutput><cfinclude template=\"inc.cfm\"><cfoutput>|B</cfoutput>"},
        {"inc.cfm", "<cfoutput>INC</cfoutput>"},
    });
    EXPECT_EQ(runFile(dir, "main.cfm").equals("A|INC|B"), true);
    removeTempDir(dir);
}

TEST_F(CfincludeTest, IncludeSharesVariablesScope) {
    auto dir = makeTempDir({
        {"main.cfm", "<cfset x = 5><cfinclude template=\"inc.cfm\"><cfoutput>|#x#|</cfoutput>"},
        {"inc.cfm", "<cfset x = 42><cfoutput>[#x#]</cfoutput>"},
    });
    EXPECT_EQ(runFile(dir, "main.cfm").equals("[42]|42|"), true);
    removeTempDir(dir);
}

