// ---- <cfinvoke> / <cfinvokeargument> ----

TEST_F(ComponentTest, CfinvokeargumentChildren) {
    // <cfinvoke> with <cfinvokeargument> children passes named arguments.
    string out = runCfc({
        {"calc.cfc",
         "component {\n"
         "  function greet(who=\"world\") { return \"hi \" & who; }\n"
         "  function add(a=0, b=0) { return a + b; }\n"
         "  function two(name, value) { return name & \"=\" & value; }\n"
         "}\n"},
        {"main.cfm",
         "<cfoutput>START|</cfoutput>\n"
         "<cfinvoke component=\"calc\" method=\"add\" returnvariable=\"r1\">\n"
         "  <cfinvokeargument name=\"a\" value=\"3\">\n"
         "  <cfinvokeargument name=\"b\" value=\"4\">\n"
         "</cfinvoke>\n"
         "<cfoutput>#r1#|</cfoutput>\n"
         "<cfinvoke component=\"calc\" method=\"two\" returnvariable=\"r2\">\n"
         "  <cfinvokeargument name=\"name\" value=\"x\">\n"
         "  <cfinvokeargument name=\"value\" value=\"#1+1#\">\n"
         "</cfinvoke>\n"
         "<cfoutput>#r2#</cfoutput>"},
    }, "main.cfm");
    EXPECT_EQ(out.equals("START| 7| x=2"), true) << out.constData();
}

TEST_F(ComponentTest, CfinvokeargumentMergesArgumentCollection) {
    // <cfinvokeargument> children override argumentcollection entries with the
    // same name; named args reorder against the parameter names.
    string out = runCfc({
        {"calc.cfc",
         "component {\n"
         "  function add(a=0, b=0) { return a + b; }\n"
         "  function two(name, value) { return name & \"=\" & value; }\n"
         "}\n"},
        {"main.cfm",
         "<cfoutput>START|</cfoutput>\n"
         "<cfinvoke component=\"calc\" method=\"two\" returnvariable=\"r1\" argumentcollection=\"#{name:'coll', value:'arg'}#\">\n"
         "  <cfinvokeargument name=\"value\" value=\"child\">\n"
         "</cfinvoke>\n"
         "<cfoutput>#r1#|</cfoutput>\n"
         "<cfinvoke component=\"calc\" method=\"add\" returnvariable=\"r2\" argumentcollection=\"#{b:5, a:7}#\">\n"
         "</cfinvoke>\n"
         "<cfoutput>#r2#|</cfoutput>\n"
         "<cfinvoke component=\"calc\" method=\"add\" returnvariable=\"r3\" argumentcollection=\"#{x:5, a:7}#\">\n"
         "</cfinvoke>\n"
         "<cfoutput>#r3#</cfoutput>"},
    }, "main.cfm");
    EXPECT_EQ(out.equals("START| coll=child| 12| 7"), true) << out.constData();
}

TEST_F(ComponentTest, CfinvokeInvokesUdfWithoutComponent) {
    // With no `component` attribute, <cfinvoke> invokes a UDF by name (CF's
    // InvokeTag `_invokeUDF` path).
    string out = runCfc({
        {"main.cfm",
         "<cffunction name=\"udf_add\" output=\"false\">\n"
         "  <cfargument name=\"a\" type=\"numeric\" required=\"true\">\n"
         "  <cfargument name=\"b\" type=\"numeric\" required=\"true\">\n"
         "  <cfreturn arguments.a + arguments.b>\n"
         "</cffunction>\n"
         "<cfoutput>START|</cfoutput>\n"
         "<cfinvoke method=\"udf_add\" returnvariable=\"r1\">\n"
         "  <cfinvokeargument name=\"a\" value=\"20\">\n"
         "  <cfinvokeargument name=\"b\" value=\"22\">\n"
         "</cfinvoke>\n"
         "<cfoutput>#r1#|</cfoutput>\n"
         "<cfinvoke method=\"udf_add\" returnvariable=\"r2\" argumentcollection=\"#{a:5, b:6}#\">\n"
         "</cfinvoke>\n"
         "<cfoutput>#r2#</cfoutput>"},
    }, "main.cfm");
    EXPECT_EQ(out.equals("START| 42| 11"), true) << out.constData();
}

TEST_F(ComponentTest, CfinvokeUnclosedTagInvokesImmediately) {
    // An unterminated <cfinvoke> behaves like a self-closing one: the invoke
    // runs at the tag and the rest of the template continues (verified on CF).
    string out = runCfc({
        {"calc.cfc",
         "component { function add(a=0, b=0) { return a + b; } }\n"},
        {"main.cfm",
         "<cfoutput>START|</cfoutput>\n"
         "<cfinvoke component=\"calc\" method=\"add\" returnvariable=\"r1\" argumentcollection=\"#{a:3,b:4}#\">\n"
         "<cfoutput>#r1#|DONE</cfoutput>"},
    }, "main.cfm");
    EXPECT_EQ(out.equals("START| 7|DONE"), true) << out.constData();
}

