// ---- <cfinterface> ----

TEST_F(ComponentTest, InterfaceBasicImplements) {
    string out = runCfc({
        {"animal_iface.cfc",
         "<cfinterface displayname=\"Animal\" hint=\"animals\">\n"
         "  <cffunction name=\"getSound\" returntype=\"string\" output=\"false\">\n"
         "    <cfargument name=\"volume\" type=\"numeric\" required=\"false\" default=\"5\">\n"
         "  </cffunction>\n"
         "  <cffunction name=\"getLegs\" returntype=\"numeric\" output=\"false\">\n"
         "  </cffunction>\n"
         "</cfinterface>\n"},
        {"dog.cfc",
         "<cfcomponent implements=\"animal_iface\">\n"
         "  <cffunction name=\"getSound\" returntype=\"string\" output=\"false\">\n"
         "    <cfargument name=\"volume\" type=\"numeric\" required=\"false\" default=\"5\">\n"
         "    <cfreturn \"Woof\" & arguments.volume>\n"
         "  </cffunction>\n"
         "  <cffunction name=\"getLegs\" returntype=\"numeric\" output=\"false\"><cfreturn 4></cffunction>\n"
         "</cfcomponent>\n"},
        {"main.cfm",
         "<cfset d = CreateObject(\"component\", \"dog\")>\n"
         "<cfoutput>#d.getSound(3)#|#d.getLegs()#|#IsInstanceOf(d, \"animal_iface\")#|#IsInstanceOf(d, \"dog\")#</cfoutput>"},
    }, "main.cfm");
    EXPECT_EQ(out.equals("Woof3|4|YES|YES"), true) << out.constData();
}

