    expectOutput("<cfset d=CreateDate(2020,5,15)><cfoutput>#DateFormat(d, \"full\")#|#DateFormat(d, \"short\")#|#DateFormat(d, \"medium\")#|#DateFormat(d, \"long\")#</cfoutput>", "Friday, May 15, 2020|5/15/20|May 15, 2020|May 15, 2020");
