TEST_F(JitExpressionTest, AbsCornerCases) {
    // 1. Positive and negative integers
    runJitTemplate("<cfset x = Abs(42)>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["x"].m_int, 42);

    runJitTemplate("<cfset x = Abs(-42)>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["x"].m_int, 42);

    // 2. Floats
    runJitTemplate("<cfset x = Abs(-3.14)>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_EQ(variables["x"].m_double, 3.14);

    runJitTemplate("<cfset x = Abs(0.0)>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_EQ(variables["x"].m_double, 0.0);

    // 3. String numeric conversion
    runJitTemplate("<cfset x = Abs(\"-42\")>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_EQ(variables["x"].m_double, 42.0);

    // 4. Boolean conversion
    runJitTemplate("<cfset x = Abs(true)>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_EQ(variables["x"].m_double, 1.0);

    runJitTemplate("<cfset x = Abs(false)>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_EQ(variables["x"].m_double, 0.0);
}

