TEST_F(JitExpressionTest, MathDirectCalls) {
    // 1. Trig functions
    runJitTemplate("<cfset x = Cos(0.0)>", variables);
    EXPECT_EQ(variables["x"].m_double, 1.0);

    runJitTemplate("<cfset x = Sin(0.0)>", variables);
    EXPECT_EQ(variables["x"].m_double, 0.0);

    runJitTemplate("<cfset x = Tan(0.0)>", variables);
    EXPECT_EQ(variables["x"].m_double, 0.0);

    runJitTemplate("<cfset x = Atan(0.0)>", variables);
    EXPECT_EQ(variables["x"].m_double, 0.0);

    runJitTemplate("<cfset x = Atn(0.0)>", variables);
    EXPECT_EQ(variables["x"].m_double, 0.0);

    // 2. Log & Exp
    runJitTemplate("<cfset x = Exp(0.0)>", variables);
    EXPECT_EQ(variables["x"].m_double, 1.0);

    // 3. Ceiling/Floor/Round
    runJitTemplate("<cfset x = Ceiling(4.2)>", variables);
    EXPECT_EQ(variables["x"].m_int, 5);

    runJitTemplate("<cfset x = Floor(4.8)>", variables);
    EXPECT_EQ(variables["x"].m_int, 4);

    runJitTemplate("<cfset x = Round(4.5)>", variables);
    EXPECT_EQ(variables["x"].m_int, 5);

    runJitTemplate("<cfset x = Round(4.4)>", variables);
    EXPECT_EQ(variables["x"].m_int, 4);

    // 4. Max & Min & Sgn
    runJitTemplate("<cfset x = Max(10, 20)>", variables);
    EXPECT_EQ(variables["x"].m_int, 20);

    runJitTemplate("<cfset x = Min(10, 20)>", variables);
    EXPECT_EQ(variables["x"].m_int, 10);

    runJitTemplate("<cfset x = Sgn(-5.5)>", variables);
    EXPECT_EQ(variables["x"].m_int, -1);

    // 5. Increment/Decrement
    runJitTemplate("<cfset x = IncrementValue(41)>", variables);
    EXPECT_EQ(variables["x"].m_int, 42);

    runJitTemplate("<cfset x = DecrementValue(43)>", variables);
    EXPECT_EQ(variables["x"].m_int, 42);

    // 6. Pi & Random
    runJitTemplate("<cfset x = Pi()>", variables);
    EXPECT_TRUE(variables["x"].m_double > 3.14 && variables["x"].m_double < 3.15);
}

TEST_F(JitExpressionTest, RandRange) {
    // randRange(number1, number2): random integer in [min, max] inclusive,
    // with the bounds swapped when number1 > number2 (CF behavior).
    for (int i = 0; i < 50; i++) {
        runJitTemplate("<cfset x = RandRange(5, 7)>", variables);
        EXPECT_TRUE(variables["x"].m_int >= 5 && variables["x"].m_int <= 7)
            << "RandRange(5,7) out of range: " << variables["x"].m_int;
    }
    for (int i = 0; i < 50; i++) {
        runJitTemplate("<cfset x = RandRange(7, 5)>", variables);
        EXPECT_TRUE(variables["x"].m_int >= 5 && variables["x"].m_int <= 7)
            << "RandRange(7,5) out of range: " << variables["x"].m_int;
    }
    // Negative bounds.
    for (int i = 0; i < 50; i++) {
        runJitTemplate("<cfset x = RandRange(-3, 3)>", variables);
        EXPECT_TRUE(variables["x"].m_int >= -3 && variables["x"].m_int <= 3)
            << "RandRange(-3,3) out of range: " << variables["x"].m_int;
    }
    // Equal bounds always return that value.
    runJitTemplate("<cfset x = RandRange(100, 100)>", variables);
    EXPECT_EQ(variables["x"].m_int, 100);
    runJitTemplate("<cfset x = RandRange(7, 7)>", variables);
    EXPECT_EQ(variables["x"].m_int, 7);
    // Explicit algorithm argument is accepted (SHA1PRNG etc.).
    for (int i = 0; i < 20; i++) {
        runJitTemplate("<cfset x = RandRange(1, 2, \"SHA1PRNG\")>", variables);
        EXPECT_TRUE(variables["x"].m_int >= 1 && variables["x"].m_int <= 2);
    }
}

TEST_F(JitExpressionTest, RandRangeInterpreterPath) {
    // randRange through the #...# interpreter path (cfoutputexpr / evaluateExpr).
    string out = runJitTemplate("<cfoutput>#RandRange(5,7)#</cfoutput>", variables);
    int v = atoi(out.constData());
    EXPECT_TRUE(v >= 5 && v <= 7) << "interpreter RandRange out of range: " << v;
    out = runJitTemplate("<cfoutput>#RandRange(5,3)#</cfoutput>", variables);
    v = atoi(out.constData());
    EXPECT_TRUE(v >= 3 && v <= 5) << "interpreter RandRange(5,3) out of range: " << v;
}

// Runs fn on a freshly spawned thread (so the thread_local RNG cache is unset)
// and returns whether it threw an exception.
static bool throwsOnFreshThread(const std::function<void()> &fn) {
    std::atomic<bool> threw{false};
    std::thread t([&] {
        try { fn(); } catch (...) { threw = true; }
    });
    t.join();
    return threw.load();
}

TEST_F(JitExpressionTest, RandRangeErrors) {
    // Too few / too many arguments.
    EXPECT_THROW(runJitTemplate("<cfset x = RandRange(5)>", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cfset x = RandRange(1, 2, 3, 4)>", variables), webstrada::exception);
    // Rand/Randomize arity errors too.
    EXPECT_THROW(runJitTemplate("<cfset d = Rand(1, 2)>", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cfset z = Randomize(42, \"SHA1PRNG\", 3)>", variables), webstrada::exception);
    // CF validates the RandRange algorithm only on the *first* call of a thread
    // (its SecureRandom generator is cached per-thread in a never-cleared
    // ThreadLocal); later calls silently ignore a bad name.
    cfvariant n1(1), n2(2), bogus("bogus");
    EXPECT_TRUE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_randrange(&n1, &n2, &bogus);
        delete r;
    }));
    // After a valid call populates the cache, the same bogus call is accepted.
    runJitTemplate("<cfset x = RandRange(1, 2, \"SHA1PRNG\")>", variables);
    EXPECT_NO_THROW(runJitTemplate("<cfset x = RandRange(1, 2, \"bogus\")>", variables));
}

TEST_F(JitExpressionTest, RandRangeAlgorithmCaching) {
    cfvariant n1(1), n2(2), bogus("bogus"), sh1("SHA1PRNG");
    // The empty algorithm name is rejected by SecureRandom.getInstance on a
    // fresh thread (CF: "The  algorithm is not supported ..."), as is a
    // whitespace-padded name (JCA names are not trimmed).
    cfvariant empty("");
    EXPECT_TRUE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_randrange(&n1, &n2, &empty);
        delete r;
    }));
    cfvariant spaces("  SHA1PRNG  ");
    EXPECT_TRUE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_randrange(&n1, &n2, &spaces);
        delete r;
    }));
    // JCA algorithm matching is case-insensitive: lowercase works.
    cfvariant lower("sha1prng");
    EXPECT_FALSE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_randrange(&n1, &n2, &lower);
        delete r;
    }));
    // Every known CF 2025 name is accepted on a fresh thread.
    const char *valid[] = {"SHA1PRNG", "NativePRNG", "NativePRNGNonBlocking",
                           "NativePRNGBlocking", "DRBG", "Windows-PRNG"};
    for (const char *a : valid) {
        cfvariant algo(a);
        EXPECT_FALSE(throwsOnFreshThread([&] {
            cfvariant *r = cfml::cf_randrange(&n1, &n2, &algo);
            delete r;
        })) << "algorithm: " << a;
    }
    // Once any call has populated the cache, empty/spaces/bogus are all
    // silently ignored (the generator is never re-validated on this thread).
    EXPECT_FALSE(throwsOnFreshThread([&] {
        cfvariant *r0 = cfml::cf_randrange(&n1, &n2, &sh1);
        delete r0;
        cfvariant *r1 = cfml::cf_randrange(&n1, &n2, &bogus);
        delete r1;
        cfvariant *r2 = cfml::cf_randrange(&n1, &n2, &empty);
        delete r2;
        cfvariant *r3 = cfml::cf_randrange(&n1, &n2, &spaces);
        delete r3;
    }));
}

TEST_F(JitExpressionTest, RandRandomizeAlgorithmCaching) {
    cfvariant seed(42), bogus("bogus"), sh1("SHA1PRNG");
    // Randomize always validates the algorithm (its 2-arg generator path calls
    // SecureRandom.getInstance and reseeds every time, never consulting the
    // cache) — on a fresh thread AND on a thread whose cache is already warm.
    EXPECT_TRUE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_randomize(&seed, &bogus);
        delete r;
    }));
    EXPECT_THROW(runJitTemplate("<cfset z = Randomize(42, \"bogus\")>", variables), webstrada::exception);
    // Rand validates only on the first call of a thread, like RandRange.
    EXPECT_TRUE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_rand(&bogus);
        delete r;
    }));
    // A successful Randomize overwrites the per-thread cache, so a subsequent
    // bogus Rand/RandRange on the same thread is silently accepted.
    EXPECT_FALSE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_randomize(&seed, &sh1);
        delete r;
        cfvariant *r2 = cfml::cf_rand(&bogus);
        delete r2;
    }));
    EXPECT_FALSE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_randomize(&seed, nullptr);
        delete r;
        cfvariant n1(1), n2(2);
        cfvariant *r2 = cfml::cf_randrange(&n1, &n2, &bogus);
        delete r2;
    }));
    // Rand() (default algorithm) also populates the cache.
    EXPECT_FALSE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_rand(nullptr);
        delete r;
        cfvariant *r2 = cfml::cf_rand(&bogus);
        delete r2;
    }));
    // Valid algorithm names work on every path.
    EXPECT_FALSE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_rand(&sh1);
        delete r;
    }));
    EXPECT_FALSE(throwsOnFreshThread([&] {
        cfvariant *r = cfml::cf_randomize(&seed, &sh1);
        delete r;
    }));
    // JIT path: Rand("SHA1PRNG") and Randomize(42, "SHA1PRNG") work.
    EXPECT_NO_THROW(runJitTemplate("<cfset d = Rand(\"SHA1PRNG\")>", variables));
    EXPECT_NO_THROW(runJitTemplate("<cfset z = Randomize(42, \"SHA1PRNG\")>", variables));
}

TEST_F(JitExpressionTest, RandomizeReturnValue) {
    // CF's Randomize returns the next value of the freshly reseeded generator
    // (CFPage.Randomize -> random.nextDouble()): a numeric in [0,1) that is
    // deterministic for a given seed. It does NOT return a boolean.
    runJitTemplate("<cfset z = Randomize(42)>", variables);
    EXPECT_EQ(variables["z"].m_type, cfvariant::Float);
    EXPECT_TRUE(variables["z"].m_double >= 0.0 && variables["z"].m_double < 1.0);
    double first = variables["z"].m_double;
    runJitTemplate("<cfset z = Randomize(42)>", variables);
    EXPECT_DOUBLE_EQ(variables["z"].m_double, first) << "same seed must give the same value";
    // IsNumeric is YES on the return value (CF verified).
    runJitTemplate("<cfset n = IsNumeric(Randomize(7))>", variables);
    EXPECT_EQ(variables["n"].m_type, cfvariant::Boolean);
    EXPECT_EQ(variables["n"].m_bool, true);
    // It renders as a number, not "YES".
    string out = runJitTemplate("<cfoutput>#Randomize(42)#</cfoutput>", variables);
    EXPECT_NE(out.indexOf("YES"), 0) << "renders numeric, not boolean: " << out.constData();
    // Direct C call: Float in [0,1).
    cfvariant seed(42), sh1("SHA1PRNG");
    cfvariant *r = cfml::cf_randomize(&seed, &sh1);
    ASSERT_TRUE(r != nullptr);
    EXPECT_EQ(r->m_type, cfvariant::Float);
    EXPECT_TRUE(r->m_double >= 0.0 && r->m_double < 1.0);
    delete r;
    // The seeded sequence continues deterministically: Randomize(42);Rand()
    // twice in a row yields the same pair.
    {
        cfvariant *a = cfml::cf_randomize(&seed, &sh1);
        delete a;
        cfvariant *b = cfml::cf_rand(nullptr);
        double p1 = b->m_double;
        delete b;
        cfvariant *c = cfml::cf_randomize(&seed, &sh1);
        delete c;
        cfvariant *d = cfml::cf_rand(nullptr);
        double p2 = d->m_double;
        delete d;
        EXPECT_DOUBLE_EQ(p1, p2) << "seeded Rand() sequence must be reproducible";
    }
}

TEST_F(JitExpressionTest, GetHttpRequestData) {
    // The CLI has an empty CGI scope and no request body, so headers/method/
    // protocol are empty and content is an empty string.
    runJitTemplate("<cfset d = GetHttpRequestData()>", variables);
    EXPECT_EQ(variables["d"].m_type, cfvariant::Struct);
    EXPECT_EQ(variables["d"].has("headers"), true);
    EXPECT_EQ(variables["d"].has("protocol"), true);
    EXPECT_EQ(variables["d"].has("method"), true);
    EXPECT_EQ(variables["d"].has("content"), true);
    EXPECT_EQ(variables["d"]["headers"].m_type, cfvariant::Struct);
    EXPECT_EQ(variables["d"]["method"].m_type, cfvariant::String);
    EXPECT_EQ(variables["d"]["protocol"].m_type, cfvariant::String);
    EXPECT_EQ(variables["d"]["content"].m_type, cfvariant::String);
    EXPECT_TRUE(variables["d"]["content"].toString().isEmpty());

    // includeBody=false omits the content key.
    runJitTemplate("<cfset d2 = GetHttpRequestData(false)>", variables);
    EXPECT_EQ(variables["d2"].has("headers"), true);
    EXPECT_EQ(variables["d2"].has("protocol"), true);
    EXPECT_EQ(variables["d2"].has("method"), true);
    EXPECT_EQ(variables["d2"].has("content"), false);

    // The #...# interpreter path.
    runJitTemplate("<cfoutput>#GetHttpRequestData(true).method#|#StructKeyExists(GetHttpRequestData(false), 'content')#</cfoutput>", variables);
}

TEST_F(JitExpressionTest, DirectCallsRefactored) {
    // 1. Len, Left, Right, Mid, Trim
    runJitTemplate("<cfset x = Len('hello')>", variables);
    EXPECT_EQ(variables["x"].m_int, 5);

    runJitTemplate("<cfset x = Left('abcdef', 3)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("abc"), true);

    runJitTemplate("<cfset x = Right('abcdef', 3)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("def"), true);

    runJitTemplate("<cfset x = Mid('abcdef', 2, 3)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("bcd"), true);

    runJitTemplate("<cfset x = Trim('  hello  ')>", variables);
    EXPECT_EQ(variables["x"].toString().equals("hello"), true);

    // 2. LCase, UCase, Reverse, RepeatString
    runJitTemplate("<cfset x = LCase('ABC')>", variables);
    EXPECT_EQ(variables["x"].toString().equals("abc"), true);

    runJitTemplate("<cfset x = UCase('abc')>", variables);
    EXPECT_EQ(variables["x"].toString().equals("ABC"), true);

    runJitTemplate("<cfset x = Reverse('abc')>", variables);
    EXPECT_EQ(variables["x"].toString().equals("cba"), true);

    runJitTemplate("<cfset x = RepeatString('ab', 3)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("ababab"), true);

    // 3. Find, FindNoCase, Compare, CompareNoCase
    runJitTemplate("<cfset x = Find('bc', 'abcdef')>", variables);
    EXPECT_EQ(variables["x"].m_int, 2);

    runJitTemplate("<cfset x = FindNoCase('BC', 'abcdef')>", variables);
    EXPECT_EQ(variables["x"].m_int, 2);

    runJitTemplate("<cfset x = Compare('abc', 'abc')>", variables);
    EXPECT_EQ(variables["x"].m_int, 0);

    runJitTemplate("<cfset x = CompareNoCase('ABC', 'abc')>", variables);
    EXPECT_EQ(variables["x"].m_int, 0);

    // 4. DateTime Extractors
    runJitTemplate("<cfset x = Year(CreateDate(2026, 5, 31))>", variables);
    EXPECT_EQ(variables["x"].m_int, 2026);

    runJitTemplate("<cfset x = Month(CreateDate(2026, 5, 31))>", variables);
    EXPECT_EQ(variables["x"].m_int, 5);

    runJitTemplate("<cfset x = Day(CreateDate(2026, 5, 31))>", variables);
    EXPECT_EQ(variables["x"].m_int, 31);
}


TEST_F(JitExpressionTest, ScriptTag) {
    // 1. Simple variables and assignments
    string cfml1 = "<cfscript>x = 10; y = x + 5;</cfscript>";
    runJitTemplate(cfml1, variables);
    EXPECT_EQ(variables["x"].m_int, 10);
    EXPECT_EQ(variables["y"].m_int, 15);

    // 2. Var declarations keyword var: allowed inside a function body, where
    // they are function-local; rejected at top level (CF: "The local variable
    // a cannot be declared outside of a function.").
    string cfml2 =
        "<cfscript>"
        "function f() {"
        "    var a = 100; var b = a * 2;"
        "    return b;"
        "}"
        "function g() {"
        "    var a = 7;"
        "    return a;"
        "}"
        "</cfscript>"
        "<cfset r = f()><cfset r2 = g()>";
    runJitTemplate(cfml2, variables);
    EXPECT_EQ(variables["r"].m_int, 200);
    EXPECT_EQ(variables["r2"].m_int, 7);
    // `var` at template top level is a CF compile-time error.
    EXPECT_THROW(runJitTemplate("<cfscript>var a = 1;</cfscript>", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cfset var a = 1>", variables), webstrada::exception);

    // 3. Structures and function calls
    string cfml3 = 
        "<cfscript>"
        "    s = StructNew();"
        "    StructInsert(s, \"name\", \"Alex\");"
        "    s.age = 30;"
        "</cfscript>";
    runJitTemplate(cfml3, variables);
    EXPECT_EQ(variables["s"]["name"].toString().equals("Alex"), true);
    EXPECT_EQ(variables["s"]["age"].m_int, 30);

    // 4. If-else conditional branching inside script blocks
    string cfml4 =
        "<cfscript>"
        "    val = 15;"
        "    if (val GT 20) {"
        "        res = \"greater\";"
        "    } else if (val GT 10) {"
        "        res = \"middle\";"
        "    } else {"
        "        res = \"lesser\";"
        "    }"
        "</cfscript>";
    runJitTemplate(cfml4, variables);
    EXPECT_EQ(variables["res"].toString().equals("middle"), true);
}

TEST_F(JitExpressionTest, ScriptIfElseExecutesOnlyOneBranch) {
    // Regression coverage for BUGS.md #1 ("JIT-compiled if/else executes both
    // branches"): only the taken branch may run, both in script and tag form.
    string cfml =
        "<cfscript>"
        "    if (true) { x = 1; } else { x = 2; }"
        "    if (false) { y = 3; } else { y = 4; }"
        "</cfscript>";
    runJitTemplate(cfml, variables);
    EXPECT_EQ(variables["x"].m_int, 1);
    EXPECT_EQ(variables["y"].m_int, 4);

    // Tag-based variant with cfset in each branch.
    runJitTemplate("<cfif true><cfset a = 10><cfelse><cfset a = 20></cfif>", variables);
    EXPECT_EQ(variables["a"].m_int, 10);
    runJitTemplate("<cfif false><cfset b = 30><cfelse><cfset b = 40></cfif>", variables);
    EXPECT_EQ(variables["b"].m_int, 40);
}

TEST_F(JitExpressionTest, ScriptIfElseOutputOnlyTakenBranch) {
    string cfml1 =
        "<cfscript>"
        "    if (true) { writeOutput(\"T\"); } else { writeOutput(\"F\"); }"
        "    if (false) { writeOutput(\"U\"); } else { writeOutput(\"V\"); }"
        "</cfscript>";
    EXPECT_EQ(runJitTemplate(cfml1, variables).equals("TV"), true);

    string cfml2 =
        "<cfscript>"
        "    if (false) { writeOutput(\"A\"); } else if (true) { writeOutput(\"B\"); } else { writeOutput(\"C\"); }"
        "</cfscript>";
    EXPECT_EQ(runJitTemplate(cfml2, variables).equals("B"), true);

    string cfml3 =
        "<cfscript>"
        "    if (false) { writeOutput(\"X\"); } else if (false) { writeOutput(\"Y\"); } else if (true) { writeOutput(\"Z\"); }"
        "</cfscript>";
    EXPECT_EQ(runJitTemplate(cfml3, variables).equals("Z"), true);
}

TEST_F(JitExpressionTest, ScriptNestedIfElse) {
    string cfml =
        "<cfscript>"
        "    x = 5;"
        "    if (x GT 3) {"
        "        if (x GT 4) { writeOutput(\"N\"); } else { writeOutput(\"M\"); }"
        "    } else { writeOutput(\"O\"); }"
        "    if (true) {"
        "        if (false) { writeOutput(\"P\"); } else { writeOutput(\"Q\"); }"
        "    } else { writeOutput(\"R\"); }"
        "</cfscript>";
    EXPECT_EQ(runJitTemplate(cfml, variables).equals("NQ"), true);
}

TEST_F(JitExpressionTest, ScriptIfCompoundConditions) {
    string cfml =
        "<cfscript>"
        "    x = 5;"
        "    if (x GT 1 AND x LT 10) { writeOutput(\"A\"); } else { writeOutput(\"B\"); }"
        "    if (x GT 1 OR x GT 100) { writeOutput(\"C\"); } else { writeOutput(\"D\"); }"
        "    if (NOT (x GT 10)) { writeOutput(\"E\"); } else { writeOutput(\"F\"); }"
        "    if (x EQ 5) { writeOutput(\"G\"); } else { writeOutput(\"H\"); }"
        "</cfscript>";
    EXPECT_EQ(runJitTemplate(cfml, variables).equals("ACEG"), true);
}

TEST_F(JitExpressionTest, ScriptIfWithoutElseContinues) {
    string cfml =
        "<cfscript>"
        "    if (true) { writeOutput(\"A\"); }"
        "    if (false) { writeOutput(\"B\"); }"
        "    writeOutput(\"C\");"
        "    if (true) { } else { writeOutput(\"D\"); }"
        "    writeOutput(\"E\");"
        "</cfscript>";
    EXPECT_EQ(runJitTemplate(cfml, variables).equals("ACE"), true);
}

TEST_F(JitExpressionTest, ScriptIfSingleLineStatements) {
    // Single-line if/else with statement bodies (no braces).
    EXPECT_EQ(runJitTemplate("<cfscript>if (true) writeOutput(\"A\");</cfscript>", variables).equals("A"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>if (false) writeOutput(\"B\"); writeOutput(\"C\");</cfscript>", variables).equals("C"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>if (false) writeOutput(\"D\"); else writeOutput(\"E\");</cfscript>", variables).equals("E"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>if (true) writeOutput(\"F\"); else writeOutput(\"G\");</cfscript>", variables).equals("F"), true);
}

TEST_F(JitExpressionTest, ScriptIfSingleLineElseIfChain) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (false) writeOutput(\"A\"); else if (true) writeOutput(\"B\"); else writeOutput(\"C\");</cfscript>",
        variables).equals("B"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (false) writeOutput(\"A\"); else if (false) writeOutput(\"B\"); else if (true) writeOutput(\"C\"); else writeOutput(\"D\");</cfscript>",
        variables).equals("C"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (false) writeOutput(\"A\"); else if (false) writeOutput(\"B\"); else writeOutput(\"C\");</cfscript>",
        variables).equals("C"), true);
}

TEST_F(JitExpressionTest, ScriptIfMixedBlockAndSingleStatement) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (true) { writeOutput(\"A\"); } else writeOutput(\"B\");</cfscript>",
        variables).equals("A"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (false) writeOutput(\"C\"); else { writeOutput(\"D\"); }</cfscript>",
        variables).equals("D"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (true) writeOutput(\"E\"); else { writeOutput(\"F\"); }</cfscript>",
        variables).equals("E"), true);
}

TEST_F(JitExpressionTest, ScriptIfNestedSingleLineDanglingElse) {
    // The dangling-else rule: an else binds to the nearest unmatched if.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (true) if (true) writeOutput(\"A\"); else writeOutput(\"B\"); else writeOutput(\"C\");</cfscript>",
        variables).equals("A"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (true) if (false) writeOutput(\"D\"); else writeOutput(\"E\"); else writeOutput(\"F\");</cfscript>",
        variables).equals("E"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (false) if (true) writeOutput(\"G\"); else writeOutput(\"H\"); else writeOutput(\"I\");</cfscript>",
        variables).equals("I"), true);
}

TEST_F(JitExpressionTest, ScriptIfSingleLineAssignments) {
    string cfml =
        "<cfscript>"
        "    v = 15;"
        "    if (v GT 20) r = \"gt\"; else if (v GT 10) r = \"mid\"; else r = \"lt\";"
        "    if (v LT 20) s = \"small\"; else s = \"big\";"
        "</cfscript>";
    runJitTemplate(cfml, variables);
    EXPECT_EQ(variables["r"].toString().equals("mid"), true);
    EXPECT_EQ(variables["s"].toString().equals("small"), true);
}

TEST_F(JitExpressionTest, ScriptIfEmptySingleLineBodies) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (true); writeOutput(\"A\");</cfscript>",
        variables).equals("A"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (false); else writeOutput(\"B\");</cfscript>",
        variables).equals("B"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>if (true) { } else writeOutput(\"C\"); writeOutput(\"D\");</cfscript>",
        variables).equals("D"), true);
}

TEST_F(JitExpressionTest, ScriptRejectsSingleWordElseIf) {
    // `elseif` is not an Adobe ColdFusion script keyword (CF 2021 rejects the
    // template); only `else if` is valid. The engine must throw instead of
    // silently running the trailing statement.
    auto expectThrows = [&](const char *cfml) {
        bool caught = false;
        try {
            runJitTemplate(cfml, variables);
        } catch (const webstrada::exception &) {
            caught = true;
        }
        EXPECT_EQ(caught, true) << "CFML: " << cfml;
    };
    expectThrows("<cfscript>if (false) writeOutput(\"A\"); elseif (true) writeOutput(\"B\");</cfscript>");
    expectThrows("<cfscript>if (false) { writeOutput(\"A\"); } elseif (true) { writeOutput(\"B\"); }</cfscript>");
    expectThrows("<cfscript>elseif (true) writeOutput(\"B\");</cfscript>");
}

TEST_F(JitExpressionTest, ScriptTryCatchBasic) {
    // `catch (any e)` intercepts a runtime error; the success path is skipped.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { x = 1/0; writeOutput(\"UNREACHABLE\"); } catch (any e) { writeOutput(\"caught\"); }</cfscript>",
        variables).equals("caught"), true);
    // No exception: catch body is skipped.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { writeOutput(\"ok\"); } catch (any e) { writeOutput(\"err\"); }</cfscript>",
        variables).equals("ok"), true);
}

TEST_F(JitExpressionTest, ScriptTryCatchBindsExceptionStruct) {
    // The catch variable exposes CF's exception struct fields.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { x = 1/0; } catch (any e) { writeOutput(e.type & \":\" & e.message); }</cfscript>",
        variables).equals("Expression:Division by zero."), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { y = undefinedVar; } catch (any e) { writeOutput(e.type); }</cfscript>",
        variables).equals("Expression"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { z = 1/0; } catch (any e) { caughtName = e.type; } writeOutput(caughtName);</cfscript>",
        variables).equals("Expression"), true);
}

TEST_F(JitExpressionTest, AbortInsideCftryIsNotCaught) {
    // <cfabort> inside a <cftry> is uncatchable: it aborts the request (no
    // catch clause runs, nothing after the try runs). Was BUGS.md "an abort
    // inside a <cftry> is re-raised as a catchable Request error".
    bool aborted = false;
    try {
        runJitTemplate(
            "<cfoutput>BEFORE|</cfoutput>"
            "<cftry><cfabort><cfcatch type=\"any\"><cfoutput>CAUGHT</cfoutput></cfcatch></cftry>"
            "<cfoutput>AFTER</cfoutput>",
            variables);
    } catch (const webstrada::abort_exception &) {
        aborted = true;
    }
    EXPECT_EQ(aborted, true);
}

TEST_F(JitExpressionTest, AbortInsideCftryRunsFinally) {
    // The <cffinally> runs on the abort, then the abort still propagates.
    bool aborted = false;
    try {
        runJitTemplate(
            "<cfoutput>B|</cfoutput>"
            "<cftry><cfabort><cffinally><cfoutput>FIN</cfoutput></cffinally></cftry>"
            "<cfoutput>A</cfoutput>",
            variables);
    } catch (const webstrada::abort_exception &) {
        aborted = true;
    }
    EXPECT_EQ(aborted, true);
}

TEST_F(JitExpressionTest, AbortInsideCftryNestedNotCaught) {
    // Nested try/catch around the abort: neither the inner nor outer catch
    // intercepts the abort (CF halts the request).
    bool aborted = false;
    try {
        runJitTemplate(
            "NEST:<cftry><cftry><cfabort>"
            "<cfcatch type=\"any\"><cfoutput>INNER</cfoutput></cfcatch></cftry>"
            "<cfcatch type=\"any\"><cfoutput>OUTER</cfoutput></cfcatch></cftry>"
            "<cfoutput>AFTER</cfoutput>",
            variables);
    } catch (const webstrada::abort_exception &) {
        aborted = true;
    }
    EXPECT_EQ(aborted, true);
}

TEST_F(JitExpressionTest, ScriptAbortIsUncatchable) {
    // A bare `abort;` in cfscript aborts (uncatchable), matching CF; a `try`
    // around it cannot intercept it. Previously `abort;` resolved as an
    // undefined variable and was caught by `catch (any)`.
    bool aborted = false;
    try {
        runJitTemplate(
            "<cfscript>writeOutput(\"X|\"); try { abort; } catch (any e) { writeOutput(\"CAUGHT\"); }</cfscript>"
            "<cfoutput>|AFTER</cfoutput>",
            variables);
    } catch (const webstrada::abort_exception &) {
        aborted = true;
    }
    EXPECT_EQ(aborted, true);
}

TEST_F(JitExpressionTest, TagCfExitAbortsPage) {
    // <cfexit> aborts the page (uncatchable); output written before it is
    // preserved and nothing after runs (verified on CF 2025).
    EXPECT_EQ(runJitTemplate("<cfoutput>BEFORE|</cfoutput><cfexit><cfoutput>AFTER</cfoutput>", variables).equals("BEFORE|"), true);
    // Without <cfoutput>, the surrounding whitespace is still emitted.
    EXPECT_EQ(runJitTemplate("A<cfexit>B", variables).equals("A"), true);
}

TEST_F(JitExpressionTest, CfExitExittagAndExittemplateAbortPage) {
    // Both explicit methods abort the page; the method value is
    // case-insensitive (EXITTAG / exittemplate / ExitTag).
    EXPECT_EQ(runJitTemplate("<cfexit method=\"exittag\">B", variables).equals(""), true);
    EXPECT_EQ(runJitTemplate("A<cfexit method=\"exittemplate\">B", variables).equals("A"), true);
    EXPECT_EQ(runJitTemplate("A<cfexit method=\"EXITTAG\">B", variables).equals("A"), true);
    EXPECT_EQ(runJitTemplate("A<cfexit method=\"ExitTag\">B", variables).equals("A"), true);
}

TEST_F(JitExpressionTest, CfExitLoopThrowsCatchableApplicationError) {
    // method="loop" outside a custom tag is a runtime, catchable error with
    // CF's exact message (custom tags are not implemented in this engine).
    EXPECT_EQ(runJitTemplate(
        "<cftry>A<cfexit method=\"loop\">X"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.type#:#cfcatch.message#</cfoutput></cfcatch></cftry>B",
        variables).equals("AApplication:Invalid use of the cfexit tag.B"), true);
}

TEST_F(JitExpressionTest, CfExitStaticInvalidMethodIsCompileError) {
    // A statically invalid method literal is a compile-time error that cannot
    // be caught (verified on CF: no prior output appears on the error page).
    bool threw = false;
    try {
        runJitTemplate("A<cfexit method=\"foo\">B", variables);
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals(
            "Attribute validation error for CFEXIT. The value of the METHOD attribute, which is currently foo, must be one of the values: EXITTAG,LOOP,EXITTEMPLATE."), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(JitExpressionTest, CfExitUnknownAttributeIsCompileError) {
    bool threw = false;
    try {
        runJitTemplate("<cfexit foo=\"bar\">B", variables);
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals(
            "Attribute validation error for tag CFEXIT. It does not allow the attribute(s) FOO. The valid attribute(s) are METHOD."), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(JitExpressionTest, CfExitDynamicInvalidMethodIsCatchable) {
    // A dynamically evaluated method dispatches at runtime; an invalid value
    // is a catchable Template error (verified on CF p33).
    EXPECT_EQ(runJitTemplate(
        "<cfset x = \"foo\">"
        "<cftry><cfexit method=\"#x#\">X"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.type#:#cfcatch.message#</cfoutput></cfcatch></cftry>B",
        variables).equals("Template:Attribute validation error for CFEXIT.B"), true);
}

TEST_F(JitExpressionTest, CfExitDynamicLoopIsCatchable) {
    EXPECT_EQ(runJitTemplate(
        "<cfset x = \"loop\">"
        "<cftry><cfexit method=\"#x#\">X"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.type#</cfoutput></cfcatch></cftry>B",
        variables).equals("ApplicationB"), true);
}

TEST_F(JitExpressionTest, CfExitInsideFunctionReturnsUndefined) {
    // Inside a <cffunction> body <cfexit> behaves like a bare <cfreturn>:
    // returns undefined and skips the rest of the body (verified on CF).
    EXPECT_EQ(runJitTemplate(
        "<cffunction name=\"f\" output=\"yes\"><cfoutput>IN</cfoutput><cfexit><cfoutput>UNREACH</cfoutput></cffunction>"
        "<cfoutput>#f() EQ \"\"#|</cfoutput>B",
        variables).equals("INYES|B"), true);
}

TEST_F(JitExpressionTest, CfExitInsideFunctionLoopStillCatchableError) {
    // Even inside a function body, method="loop" is still the catchable error
    // (verified on CF p32/p35), not a return.
    EXPECT_EQ(runJitTemplate(
        "<cffunction name=\"f\" output=\"yes\"><cftry><cfexit method=\"loop\"><cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry></cffunction>"
        "<cfoutput>#f()#|</cfoutput>",
        variables).equals("Invalid use of the cfexit tag.|"), true);
}

TEST_F(JitExpressionTest, CfExitThroughCftryIsUncatchable) {
    // Like <cfabort>, <cfexit> cannot be intercepted by cftry at page level.
    EXPECT_EQ(runJitTemplate(
        "<cfoutput>BEFORE|</cfoutput>"
        "<cftry><cfexit><cfcatch type=\"any\"><cfoutput>CAUGHT</cfoutput></cfcatch></cftry>"
        "<cfoutput>AFTER</cfoutput>",
        variables).equals("BEFORE|"), true);
}

TEST_F(JitExpressionTest, CfExitInsideCfloopHaltsPage) {
    // <cfexit> inside a cfloop aborts the page entirely (verified on CF p29).
    EXPECT_EQ(runJitTemplate(
        "<cfoutput><cfloop index=\"i\" from=\"1\" to=\"3\">#i#<cfexit></cfloop></cfoutput>B",
        variables).equals("1"), true);
}

TEST_F(JitExpressionTest, ScriptExitAbortsPage) {
    // A bare `exit;` in cfscript aborts (uncatchable); try/catch cannot
    // intercept it.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>writeOutput(\"S|\"); try { exit; } catch (any e) { writeOutput(\"CAUGHT\"); }</cfscript>"
        "<cfoutput>|AFTER</cfoutput>",
        variables).equals("S|"), true);
}

TEST_F(JitExpressionTest, CfExitEmptyStaticMethodRendersQuotedEmpty) {
    // CF renders an empty static method value as '' in the runtime message
    // (verified on the RDS host): "The value of the METHOD attribute, which is
    // currently '', must be one of the values: ...".
    bool threw = false;
    try {
        runJitTemplate("<cfexit method=\"\">B", variables);
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals(
            "Attribute validation error for CFEXIT. The value of the METHOD attribute, which is currently '', must be one of the values: EXITTAG,LOOP,EXITTEMPLATE."), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(JitExpressionTest, CfExitDynamicEmptyMethodRendersQuotedEmpty) {
    // The runtime (dynamically evaluated) path quotes an empty value the same
    // way as the static one.
    EXPECT_EQ(runJitTemplate(
        "<cfset x = \"\">"
        "<cftry><cfexit method=\"#x#\">X"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.detail#</cfoutput></cfcatch></cftry>B",
        variables).equals("The value of the METHOD attribute, which is currently '', must be one of the values: EXITTAG,LOOP,EXITTEMPLATE.B"), true);
}

TEST_F(JitExpressionTest, CftryWithoutCatchOrFinallyIsCompileError) {
    // CF rejects a <cftry> with neither <cfcatch> nor <cffinally> at compile
    // time: "Context validation error in CFTRY block. A CFTRY must contain at
    // least one CFCATCH clause or CFFINALLY clause." (verified on the RDS
    // host, CF 2025 — the page 500s).
    bool threw = false;
    try {
        runJitTemplate("<cfoutput>PRE</cfoutput><cftry><cfset x = 1></cftry><cfoutput>POST</cfoutput>", variables);
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals(
            "Context validation error in CFTRY block. A CFTRY must contain at least one CFCATCH clause or CFFINALLY clause."), true);
    }
    EXPECT_EQ(threw, true);
}

TEST_F(JitExpressionTest, CftryWithoutCatchButWithFinallyCompiles) {
    // <cffinally> alone satisfies the requirement.
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfset q = 5><cffinally><cfoutput>FIN</cfoutput></cffinally></cftry>B",
        variables).equals("FINB"), true);
}

TEST_F(JitExpressionTest, ScriptTryWithoutCatchOrFinallyIsCompileError) {
    // CF rejects a script `try { }` with neither catch nor finally at compile
    // time too: "Context validation error in ''TRY block." (verified on the
    // RDS host — the page 500s; the script form names the block '').
    bool threw = false;
    try {
        runJitTemplate("<cfscript>try { writeOutput(\"a\"); }</cfscript>", variables);
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("Context validation error in ''TRY block."), true);
    }
    EXPECT_EQ(threw, true);
    // A catch or finally alone satisfies the requirement.
    EXPECT_EQ(runJitTemplate("<cfscript>try { throw \"x\"; } catch (any e) { writeOutput(\"C\"); }</cfscript>OK", variables).equals("COK"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>try { a = 1; } finally { writeOutput(\"F\"); }</cfscript>OK", variables).equals("FOK"), true);
}

TEST_F(JitExpressionTest, ScriptExitInsideFunctionReturnsUndefined) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>function f() { writeOutput(\"IN\"); exit; writeOutput(\"UNREACH\"); } f(); writeOutput(\"AFTER\");</cfscript>B",
        variables).equals("INAFTERB"), true);
}

TEST_F(JitExpressionTest, ScriptExitInsideNestedFunctionReturnsInnermostOnly) {
    // `exit;` in a nested closure returns from the innermost function only;
    // the outer one continues (verified on CF p41).
    EXPECT_EQ(runJitTemplate(
        "<cfscript>function outer() { function inner() { exit; writeOutput(\"INNER_AFTER\"); } inner(); writeOutput(\"OUTER_AFTER\"); } outer(); writeOutput(\"PAGE_END\");</cfscript>B",
        variables).equals("OUTER_AFTERPAGE_ENDB"), true);
}

TEST_F(JitExpressionTest, ScriptExitIsKeywordNotVariable) {
    // There is no `exit("exittag")` or `exit loop;` script form (verified on
    // CF: "Variable EXIT is undefined" / "Variable LOOP is undefined"). They
    // compile but fail at runtime as undefined variables.
    bool threw = false;
    try {
        runJitTemplate("<cfscript>exit(\"exittag\");</cfscript>B", variables);
    } catch (const webstrada::exception &) {
        threw = true;
    }
    EXPECT_EQ(threw, true);
    threw = false;
    try {
        runJitTemplate("<cfscript>exit loop;</cfscript>B", variables);
    } catch (const webstrada::exception &) {
        threw = true;
    }
    EXPECT_EQ(threw, true);
}

TEST_F(JitExpressionTest, ScriptTryCatchTypeMatchingOrder) {
    // First matching clause wins; a non-matching specific type falls through.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { y = undefinedVar; } catch (expression e) { writeOutput(\"expr\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("expr"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { z = 5/0; } catch (application e) { writeOutput(\"app\"); } catch (expression e) { writeOutput(\"expr\"); }</cfscript>",
        variables).equals("expr"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { m = undefinedVar; } catch (application e) { writeOutput(\"app\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("any"), true);
}

TEST_F(JitExpressionTest, CatchClosestClassAncestorWinsRegardlessOfOrder) {
    // CF matches the CLOSEST exception-class ancestor across ALL clauses
    // (findThrowableTarget), so catch(expression) beats an earlier catch(any)
    // for a built-in runtime error (division by zero -> ExpressionException,
    // an ExpressionException is-a RuntimeException). Was BUGS.md "cfcatch type
    // matching is exact-name only".
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { x = 1/0; } catch (any e) { writeOutput(\"any\"); } catch (expression e) { writeOutput(\"expr\"); }</cfscript>",
        variables).equals("expr"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { x = 1/0; } catch (application e) { writeOutput(\"app\"); } catch (any e) { writeOutput(\"any\"); } catch (expression e) { writeOutput(\"expr\"); }</cfscript>",
        variables).equals("expr"), true);
    // A real Expression error is NOT an ApplicationException, so it does not
    // match catch(application) (CF: ExpressionException is not an ApplicationException).
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { x = 1/0; } catch (application e) { writeOutput(\"app\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("any"), true);
}

TEST_F(JitExpressionTest, CustomThrowMatchesExactNameOverAny) {
    // A custom throw(type="myType") matches catch(myType) even when catch(any)
    // precedes it (CF's findCustomTarget exact-name match wins over any), and
    // does NOT match catch(expression)/catch(application).
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"myType\", message=\"b\"); } catch (any e) { writeOutput(\"any\"); } catch (myType e) { writeOutput(\"myType\"); }</cfscript>",
        variables).equals("myType"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"myType\", message=\"b\"); } catch (expression e) { writeOutput(\"expr\"); } catch (application e) { writeOutput(\"app\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("any"), true);
}

TEST_F(JitExpressionTest, ReservedTypeThrowNormalizesToApplication) {
    // throw(type="database") is replaced by an ApplicationException (CF rejects
    // reserved type names), reporting type "Application"; catch(database) does
    // NOT match but catch(application)/catch(expression)/catch(any) do.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"database\", message=\"b\"); } catch (any e) { writeOutput(\"#e.type#\"); }</cfscript>",
        variables).equals("Application"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"database\", message=\"b\"); } catch (database e) { writeOutput(\"db\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("any"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"database\", message=\"b\"); } catch (application e) { writeOutput(\"app\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("app"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"database\", message=\"b\"); } catch (expression e) { writeOutput(\"expr\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("expr"), true);
}

TEST_F(JitExpressionTest, CustomDottedTypePrefixMatching) {
    // CF's findCustomTarget dotted-prefix matching: throw(type="my.custom.type")
    // matches catch(my.custom) (diff 1) and catch(my) (diff 2), the closest
    // dotted-prefix wins.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"my.custom.type\", message=\"b\"); } catch (my.custom e) { writeOutput(\"mc\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("mc"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"my.custom.type\", message=\"b\"); } catch (my e) { writeOutput(\"m\"); } catch (any e) { writeOutput(\"any\"); }</cfscript>",
        variables).equals("m"), true);
}

TEST_F(JitExpressionTest, CustomThrowRethrowKeepsExactNameMatching) {
    // A custom throw rethrown via `rethrow` keeps its custom-ness (cfcatch is
    // marked m_isCustomException), so the outer catch(myType) still matches.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { try { throw(type=\"myType\", message=\"b\"); } catch (any e) { rethrow; } } catch (myType e) { writeOutput(\"myType\"); }</cfscript>",
        variables).equals("myType"), true);
}

TEST_F(JitExpressionTest, ScriptTryFinallyRunsOnSuccessAndCatch) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { writeOutput(\"T\"); } finally { writeOutput(\"F\"); }</cfscript>",
        variables).equals("TF"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { x = 1/0; } catch (any e) { writeOutput(\"C\"); } finally { writeOutput(\"F\"); }</cfscript>",
        variables).equals("CF"), true);
    // Variables assigned in finally are visible afterwards.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { } finally { finVar = 42; } writeOutput(finVar);</cfscript>",
        variables).equals("42"), true);
}

TEST_F(JitExpressionTest, ScriptTryFinallyRethrowsUnmatched) {
    // An uncaught exception runs finally then keeps unwinding to an outer try.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { try { x = 1/0; } finally { writeOutput(\"F\"); } } catch (any e) { writeOutput(\"C\" & e.type); }</cfscript>",
        variables).equals("FCExpression"), true);
    // Deeply nested finally chain all run before the outer catch.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { try { try { z = 1/0; } finally { writeOutput(\"A\"); } } finally { writeOutput(\"B\"); } } catch (any e) { writeOutput(\"C\"); }</cfscript>",
        variables).equals("ABC"), true);
    // An exception raised inside finally replaces the original one.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { try { a = 1/0; } finally { b = undefinedVar2; } } catch (any e) { writeOutput(e.message); }</cfscript>",
        variables).equals("Variable UNDEFINEDVAR2 is undefined."), true);
}

TEST_F(JitExpressionTest, ScriptTryCatchInLoop) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>k = 0; while (k < 3) { k++; try { if (k == 2) { l = 1/0; } writeOutput(\"T\" & k); } catch (any e) { writeOutput(\"C\" & k); } finally { writeOutput(\"F\" & k); } }</cfscript>",
        variables).equals("T1F1C2F2T3F3"), true);
}

TEST_F(JitExpressionTest, ScriptTryUncaughtStillPropagates) {
    // Without a matching catch the exception unwinds out of the template.
    bool caught = false;
    try {
        runJitTemplate("<cfscript>try { x = 1/0; } catch (application e) { writeOutput(\"not this\"); }</cfscript>", variables);
    } catch (const webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(JitExpressionTest, ScriptThrowBasic) {
    // `throw "msg"` raises an Application exception whose message is the value.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw \"hello\"; } catch (application e) { writeOutput(e.type & \":\" & e.message); }</cfscript>",
        variables).equals("Application:hello"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>m = \"abc\"; try { throw m; } catch (any e) { writeOutput(e.message); }</cfscript>",
        variables).equals("abc"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw (5+3); } catch (any e) { writeOutput(e.message); }</cfscript>",
        variables).equals("8"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw ucase(\"xyz\"); } catch (any e) { writeOutput(e.message); }</cfscript>",
        variables).equals("XYZ"), true);
}

TEST_F(JitExpressionTest, ScriptThrowBareAndEmpty) {
    // `throw;` and `throw()` both raise Application with an empty message.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw; } catch (any e) { writeOutput(e.type & \"[\" & e.message & \"]\"); }</cfscript>",
        variables).equals("Application[]"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(); } catch (any e) { writeOutput(e.type & \"[\" & e.message & \"]\"); }</cfscript>",
        variables).equals("Application[]"), true);
}

TEST_F(JitExpressionTest, ScriptThrowNamedAttributes) {
    // Named attributes populate type/message/detail/errorcode/extendedinfo and
    // the custom type participates in catch matching.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"myType\", message=\"named\"); } catch (myType e) { writeOutput(e.type & \":\" & e.message); }</cfscript>",
        variables).equals("myType:named"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"My.Custom.Type\", message=\"x\", detail=\"d\", errorcode=\"7\", extendedinfo=\"ei\"); }"
        "catch (my.custom.type e) { writeOutput(e.type & \":\" & e.message & \":\" & e.detail & \":\" & e.errorcode & \":\" & e.extendedinfo); }</cfscript>",
        variables).equals("My.Custom.Type:x:d:7:ei"), true);
    // A custom type does not match a differently-named catch.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { throw(type=\"t1\", message=\"nomatch\"); } catch (t2 e) { writeOutput(\"wrong\"); } catch (any e) { writeOutput(e.type & \":\" & e.message); }</cfscript>",
        variables).equals("t1:nomatch"), true);
}

TEST_F(JitExpressionTest, ScriptThrowUncaughtPropagates) {
    // An uncaught throw unwinds out of the template carrying its message.
    bool caught = false;
    try {
        runJitTemplate("<cfscript>throw \"escape\";</cfscript>", variables);
    } catch (const webstrada::exception &ex) {
        caught = true;
        EXPECT_EQ(ex.m_message.equals("escape"), true);
    }
    EXPECT_EQ(caught, true);
}

TEST_F(JitExpressionTest, ScriptRethrow) {
    // `rethrow;` inside a catch re-raises the caught exception to the next
    // enclosing catch, skipping the remainder of the inner try.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { try { throw \"original\"; } catch (application e) { writeOutput(\"inner:\" & e.message & \";\"); rethrow; }"
        " writeOutput(\"UNREACHABLE\"); } catch (any e) { writeOutput(\"outer:\" & e.message); }</cfscript>",
        variables).equals("inner:original;outer:original"), true);
    // `rethrow` targets the innermost enclosing catch.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { try { throw \"orig\"; } catch (application inner) { try { throw \"second\"; }"
        " catch (application innermost) { rethrow; } writeOutput(\"UNREACHABLE\"); } } catch (any e) { writeOutput(e.message); }</cfscript>",
        variables).equals("second"), true);
}

TEST_F(JitExpressionTest, ScriptRethrowOutsideCatchRejected) {
    // CF rejects `rethrow;` outside a catch at compile time.
    bool rejected = false;
    try {
        runJitTemplate("<cfscript>rethrow;</cfscript>", variables);
    } catch (const webstrada::exception &) {
        rejected = true;
    }
    EXPECT_EQ(rejected, true);
}

TEST_F(JitExpressionTest, ScriptThrowFinallyRunsBeforePropagation) {
    // A `finally` block runs before a thrown exception propagates.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>try { try { throw \"boom\"; } finally { writeOutput(\"F;\"); } } catch (any e) { writeOutput(\"C:\" & e.message); }</cfscript>",
        variables).equals("F;C:boom"), true);
}

TEST_F(JitExpressionTest, ScriptThrowInLoop) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>for (i = 1; i <= 3; i++) { try { if (i == 2) throw \"boom\"; writeOutput(i & \";\"); }"
        " catch (any e) { writeOutput(\"caught:\" & e.message & \";\"); } }</cfscript>",
        variables).equals("1;caught:boom;3;"), true);
}

TEST_F(JitExpressionTest, ScriptThrowComplexMessage) {
    // throw of a complex object (struct/array/query) reports CF's Expression
    // error "Complex object types cannot be converted to simple values." with
    // CF's standard detail (was BUGS.md #7).
    string out = runJitTemplate(
        "<cfscript>s = {a:1}; try { throw s; } catch (any e) { writeOutput(e.type & \"|\" & e.message); }</cfscript>",
        variables);
    EXPECT_EQ(out.equals("Expression|Complex object types cannot be converted to simple values."), true);
    out = runJitTemplate(
        "<cfscript>a = [1,2,3]; try { throw a; } catch (any e) { writeOutput(e.type & \"|\" & e.message); }</cfscript>",
        variables);
    EXPECT_EQ(out.equals("Expression|Complex object types cannot be converted to simple values."), true);
}

TEST_F(JitExpressionTest, TagTryCatch) {
    // <cftry>/<cfcatch> catches a runtime error and exposes cfcatch.*.
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfset x = 1/0><cfcatch type=\"any\"><cfoutput>#cfcatch.type#:#cfcatch.message#</cfoutput></cfcatch></cftry>",
        variables).equals("Expression:Division by zero."), true);
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfset y = undefinedVarTag1><cfcatch><cfoutput>#cfcatch.type#</cfoutput></cfcatch></cftry>",
        variables).equals("Expression"), true);
}

TEST_F(JitExpressionTest, TagThrowAttributes) {
    // <cfthrow> with named attributes; custom type participates in matching.
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfthrow type=\"myType\" message=\"boom\" detail=\"d\" errorcode=\"7\" extendedinfo=\"ei\">"
        "<cfcatch type=\"myType\"><cfoutput>#cfcatch.type#:#cfcatch.message#:#cfcatch.detail#:#cfcatch.errorcode#:#cfcatch.extendedinfo#</cfoutput></cfcatch></cftry>",
        variables).equals("myType:boom:d:7:ei"), true);
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfthrow message=\"nomsg\"><cfcatch type=\"t2\"><cfoutput>WRONG</cfoutput></cfcatch>"
        "<cfcatch type=\"application\"><cfoutput>#cfcatch.type#:#cfcatch.message#</cfoutput></cfcatch></cftry>",
        variables).equals("Application:nomsg"), true);
}

TEST_F(JitExpressionTest, TagThrowInterpolatedMessage) {
    // Attribute values interpolate #expr# (message="at#i#" -> "at2").
    EXPECT_EQ(runJitTemplate(
        "<cfset m = \"dyn\"><cftry><cfthrow type=\"t1\" message=\"#m#\">"
        "<cfcatch type=\"t1\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>",
        variables).equals("dyn"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfloop from=\"1\" to=\"2\" index=\"i\"><cftry><cfif i eq 2><cfthrow message=\"at#i#\"></cfif>"
        "<cfoutput>#i#;</cfoutput><cfcatch type=\"any\"><cfoutput>caught:#cfcatch.message#;</cfoutput></cfcatch></cftry></cfloop>",
        variables).equals("1;caught:at2;"), true);
}

TEST_F(JitExpressionTest, TagTryFinally) {
    // <cffinally> runs on success and on the caught path.
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfoutput>OK</cfoutput><cffinally><cfoutput>;FIN</cfoutput></cffinally></cftry>",
        variables).equals("OK;FIN"), true);
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfset x = 1/0><cfcatch type=\"any\"><cfoutput>C</cfoutput></cfcatch>"
        "<cffinally><cfoutput>;F</cfoutput></cffinally></cftry>",
        variables).equals("C;F"), true);
}

TEST_F(JitExpressionTest, TagRethrow) {
    // <cfrethrow> inside <cfcatch> re-raises to the next enclosing cftry.
    EXPECT_EQ(runJitTemplate(
        "<cftry><cftry><cfthrow message=\"original\"><cfcatch type=\"any\"><cfoutput>inner:#cfcatch.message#;</cfoutput>"
        "<cfrethrow></cfcatch></cftry><cfcatch type=\"any\"><cfoutput>outer:#cfcatch.message#</cfoutput></cfcatch></cftry>",
        variables).equals("inner:original;outer:original"), true);
}

TEST_F(JitExpressionTest, TagFinallyExceptionReplacesOriginal) {
    // An exception raised inside <cffinally> replaces the caught one.
    EXPECT_EQ(runJitTemplate(
        "<cftry><cftry><cfthrow message=\"original\"><cfcatch type=\"any\"><cfoutput>caught;</cfoutput></cfcatch>"
        "<cffinally><cfset z = 1/0></cffinally></cftry><cfcatch type=\"any\"><cfoutput>outer:#cfcatch.message#</cfoutput></cfcatch></cftry>",
        variables).equals("caught;outer:Division by zero."), true);
}

TEST_F(JitExpressionTest, TagRethrowAndCatchOutsideRejected) {
    // <cfrethrow> outside a catch and <cfcatch> outside a cftry are rejected.
    bool rej1 = false;
    try {
        runJitTemplate("<cfrethrow>", variables);
    } catch (const webstrada::exception &) {
        rej1 = true;
    }
    EXPECT_EQ(rej1, true);
    bool rej2 = false;
    try {
        runJitTemplate("<cfcatch type=\"any\"><cfoutput>x</cfoutput></cfcatch>", variables);
    } catch (const webstrada::exception &) {
        rej2 = true;
    }
    EXPECT_EQ(rej2, true);
}

TEST_F(JitExpressionTest, TagThrowUncaughtPropagates) {
    // An uncaught <cfthrow> unwinds out of the template with its message.
    bool caught = false;
    try {
        runJitTemplate("<cfthrow message=\"escape\">", variables);
    } catch (const webstrada::exception &ex) {
        caught = true;
        EXPECT_EQ(ex.m_message.equals("escape"), true);
    }
    EXPECT_EQ(caught, true);
}

TEST_F(JitExpressionTest, ScriptIfInsideLoop) {
    // The four leading spaces before <cfscript> form a whitespace-only region
    // between two tags (no line break). It would collapse to a single space,
    // but the runtime space check suppresses it because the output buffer is
    // still empty on the first iteration, matching CF 2021 (verified against
    // the server in tests/cfm/cfloop_text_body_test.cfm).
    string cfml =
        "<cfloop from=\"1\" to=\"3\" index=\"i\">"
        "    <cfscript>if (i EQ 2) { writeOutput(\"two\"); } else { writeOutput(\"other\"); }</cfscript>"
        "</cfloop>";
    EXPECT_EQ(runJitTemplate(cfml, variables).equals("other two other"), true);
}

TEST_F(JitExpressionTest, ScriptSwitchBasic) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>x=2; switch (x) { case 1: writeOutput(\"ONE\"); break; case 2: writeOutput(\"TWO\"); break; default: writeOutput(\"D\"); }</cfscript>",
        variables).equals("TWO"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>x=5; switch (x) { case 1: writeOutput(\"ONE\"); break; default: writeOutput(\"D\"); }</cfscript>",
        variables).equals("D"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>x=9; switch (x) { case 1: writeOutput(\"A\"); break; } writeOutput(\"NODEF\");</cfscript>",
        variables).equals("NODEF"), true);
}

TEST_F(JitExpressionTest, ScriptSwitchFallThrough) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>x=1; switch (x) { case 1: writeOutput(\"F1\"); case 2: writeOutput(\"F2\"); default: writeOutput(\"FD\"); }</cfscript>",
        variables).equals("F1F2FD"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>x=2; switch (x) { case 1: writeOutput(\"F1\"); case 2: writeOutput(\"F2\"); default: writeOutput(\"FD\"); }</cfscript>",
        variables).equals("F2FD"), true);
}

TEST_F(JitExpressionTest, ScriptSwitchMultipleAndExprCases) {
    // Stacked case labels and case-insensitive string matching.
    EXPECT_EQ(runJitTemplate(
        "<cfscript>z=3; switch (z) { case 1: case 2: writeOutput(\"LOW\"); break; case 3: writeOutput(\"HIGH\"); break; }</cfscript>",
        variables).equals("HIGH"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>y=\"text\"; switch (y) { case \"other\": writeOutput(\"O\"); break; case \"TEXT\": writeOutput(\"T\"); break; }</cfscript>",
        variables).equals("T"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>x=2; switch (x) { case x - 1: writeOutput(\"E1\"); break; case 2: writeOutput(\"E2\"); break; }</cfscript>",
        variables).equals("E2"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>switch (\"b\") { case \"a\": writeOutput(\"A\"); break; case \"b\": case \"c\": writeOutput(\"BC\"); break; default: writeOutput(\"D\"); }</cfscript>",
        variables).equals("BC"), true);
}

TEST_F(JitExpressionTest, ScriptForClassic) {
    EXPECT_EQ(runJitTemplate("<cfscript>for (i = 1; i <= 5; i++) writeOutput(i);</cfscript>", variables).equals("12345"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>for (i = 5; i >= 1; i--) writeOutput(i);</cfscript>", variables).equals("54321"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>for (i = 1; i <= 10; i += 2) writeOutput(i);</cfscript>", variables).equals("13579"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>for (i = 10; i >= 1; i = i - 3) writeOutput(i);</cfscript>", variables).equals("10741"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>for (i = 1; i < 3; i++) { } writeOutput(\"E\");</cfscript>", variables).equals("E"), true);
}

TEST_F(JitExpressionTest, ScriptForIn) {
    EXPECT_EQ(runJitTemplate("<cfscript>arr=[10,20]; for (item in arr) writeOutput(item);</cfscript>", variables).equals("1020"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>st={a:1,b:2}; for (k in st) writeOutput(k);</cfscript>", variables).equals("AB"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>for (x in \"a,b,c\") writeOutput(\"[\" & x & \"]\");</cfscript>", variables).equals("[a][b][c]"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>for (x in \"hello\") writeOutput(\"[\" & x & \"]\");</cfscript>", variables).equals("[hello]"), true);
}

TEST_F(JitExpressionTest, ScriptWhileAndDoWhile) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>i=0; while (i < 3) { writeOutput(i); i++; }</cfscript>",
        variables).equals("012"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>do { writeOutput(\"DO\"); } while (false);</cfscript>",
        variables).equals("DO"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>k=0; do { k++; if (k == 2) continue; writeOutput(k); } while (k < 4);</cfscript>",
        variables).equals("134"), true);
}

TEST_F(JitExpressionTest, ScriptBreakContinue) {
    EXPECT_EQ(runJitTemplate(
        "<cfscript>for (i = 1; i <= 5; i++) { if (i == 2) continue; if (i == 4) break; writeOutput(i); }</cfscript>",
        variables).equals("13"), true);
    EXPECT_EQ(runJitTemplate(
        "<cfscript>for (i = 1; i <= 3; i++) { for (j = 1; j <= 3; j++) { if (j == 2) break; writeOutput(i * 10 + j); } }</cfscript>",
        variables).equals("112131"), true);
}

TEST_F(JitExpressionTest, ScriptIncrementDecrement) {
    EXPECT_EQ(runJitTemplate("<cfscript>i=1; i++; writeOutput(i);</cfscript>", variables).equals("2"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>j=5; j--; writeOutput(j);</cfscript>", variables).equals("4"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>k=1; writeOutput(k++); writeOutput(k);</cfscript>", variables).equals("12"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>m=1; writeOutput(++m);</cfscript>", variables).equals("2"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>n=1; n+=2; n+=3; writeOutput(n);</cfscript>", variables).equals("6"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>n=6; n-=1; writeOutput(n);</cfscript>", variables).equals("5"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>q=\"ab\"; q&=\"cd\"; writeOutput(q);</cfscript>", variables).equals("abcd"), true);
}

TEST_F(JitExpressionTest, ScriptStructLiteralKeyCasing) {
    // CF uppercases unquoted struct-literal keys ({a:1} → "A") but preserves
    // quoted keys ({"aB":1} → "aB") — verified against CF 2021.
    EXPECT_EQ(runJitTemplate("<cfscript>writeOutput(SerializeJSON({a:1}));</cfscript>", variables).equals("{\"A\":1}"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>writeOutput(SerializeJSON({\"aB\":1}));</cfscript>", variables).equals("{\"aB\":1}"), true);
    EXPECT_EQ(runJitTemplate("<cfscript>s=StructNew(); StructInsert(s,\"foo\",1); writeOutput(SerializeJSON(s));</cfscript>", variables).equals("{\"foo\":1}"), true);
}

TEST_F(JitExpressionTest, CfloopListArrayCollectionCondition) {
    EXPECT_EQ(runJitTemplate("<cfloop list=\"a,b,c\" index=\"it\"><cfoutput>#it#</cfoutput></cfloop>", variables).equals("abc"), true);
    EXPECT_EQ(runJitTemplate("<cfloop list=\"a-b-c\" delimiters=\"-\" index=\"it\"><cfoutput>#it#</cfoutput></cfloop>", variables).equals("abc"), true);
    EXPECT_EQ(runJitTemplate("<cfset arr=[7,8,9]><cfloop array=\"#arr#\" index=\"it\"><cfoutput>#it#</cfoutput></cfloop>", variables).equals("789"), true);
    EXPECT_EQ(runJitTemplate("<cfset st={x:1,y:2}><cfloop collection=\"#st#\" item=\"k\"><cfoutput>#k#</cfoutput></cfloop>", variables).equals("XY"), true);
    EXPECT_EQ(runJitTemplate("<cfset i=0><cfloop condition=\"i LT 3\"><cfset i=i+1><cfoutput>#i#</cfoutput></cfloop>", variables).equals("123"), true);
}

TEST_F(JitExpressionTest, CfdumpArray) {
    string cfml =
        "<cfset arr = ArrayNew(1)>"
        "<cfset ArrayAppend(arr, \"first element\")>"
        "<cfset ArrayAppend(arr, 999)>"
        "<cfdump var=\"#arr#\">";
    string out = runJitTemplate(cfml, variables);
    EXPECT_EQ(out.contains("class=\"cfdump_array\""), true);
    EXPECT_EQ(out.contains("first element"), true);
    EXPECT_EQ(out.contains("999"), true);
}

TEST_F(JitExpressionTest, IndexAssignment) {
    // 1. Basic array index assignment
    string cfml1 = 
        "<cfscript>"
        "    arr = ArrayNew(1);"
        "    arr[1] = 42;"
        "    arr[2] = \"hello\";"
        "    val1 = arr[1];"
        "    val2 = arr[2];"
        "</cfscript>";
    runJitTemplate(cfml1, variables);
    EXPECT_EQ(variables["val1"].m_int, 42);
    EXPECT_EQ(variables["val2"].toString().equals("hello"), true);

    // 2. Dynamic growth of array index assignment
    string cfml2 = 
        "<cfscript>"
        "    arr = ArrayNew(1);"
        "    arr[5] = 99;"
        "    myLen = ArrayLen(arr);"
        "    val5 = arr[5];"
        "</cfscript>";
    runJitTemplate(cfml2, variables);
    EXPECT_EQ(variables["myLen"].m_int, 5);
    EXPECT_EQ(variables["val5"].m_int, 99);

    // 3. Nested array index assignments
    string cfml3 = 
        "<cfscript>"
        "    arr = ArrayNew(1);"
        "    arr[1] = ArrayNew(1);"
        "    arr[1][2] = 200;"
        "    val = arr[1][2];"
        "</cfscript>";
    runJitTemplate(cfml3, variables);
    EXPECT_EQ(variables["val"].m_int, 200);

    // 4. Dot member structures and nested array assignments
    string cfml4 = 
        "<cfscript>"
        "    s = StructNew();"
        "    s.data = ArrayNew(1);"
        "    s.data[1] = 77;"
        "    val = s.data[1];"
        "</cfscript>";
    runJitTemplate(cfml4, variables);
    EXPECT_EQ(variables["val"].m_int, 77);

    // 5. Array containing structure member assignment
    string cfml5 = 
        "<cfscript>"
        "    arr = ArrayNew(1);"
        "    arr[1] = StructNew();"
        "    arr[1].key = \"value\";"
        "    val = arr[1].key;"
        "</cfscript>";
    runJitTemplate(cfml5, variables);
    EXPECT_EQ(variables["val"].toString().equals("value"), true);

    // 6. Indexing bounds check (out of bounds throws)
    string cfml6 = 
        "<cfscript>"
        "    arr = ArrayNew(1);"
        "    arr[0] = 100;"
        "</cfscript>";
    bool caught = false;
    try {
        runJitTemplate(cfml6, variables);
    } catch (...) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

// Regression coverage for BUGS.md #5: cfscript string literals interpolate
// #var#/#expr# (previously the SharpExpression was stripped from the literal).
class ScriptStringInterpTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }
};

TEST_F(ScriptStringInterpTest, BasicVariable) {
    variables.set("X");
    variables["X"] = cfvariant(5);
    string out = runJitTemplate("<cfscript>writeOutput(\"val=#x#|\");</cfscript>", variables);
    EXPECT_EQ(out.equals("val=5|"), true);
}

TEST_F(ScriptStringInterpTest, MultipleAndPositioned) {
    variables.set("X");
    variables["X"] = cfvariant(5);
    variables.set("Y");
    variables["Y"] = cfvariant("world");
    string out = runJitTemplate("<cfscript>writeOutput(\"#x#-#y#|start #x#|end #x#|#x# and #y# done\");</cfscript>", variables);
    EXPECT_EQ(out.equals("5-world|start 5|end 5|5 and world done"), true);
}

TEST_F(ScriptStringInterpTest, EscapedHash) {
    variables.set("X");
    variables["X"] = cfvariant(5);
    string out = runJitTemplate("<cfscript>writeOutput(\"a ## b #x#|##\");</cfscript>", variables);
    EXPECT_EQ(out.equals("a # b 5|#"), true);
}

TEST_F(ScriptStringInterpTest, EscapedQuotesInsideLiteral) {
    string out = runJitTemplate("<cfscript>writeOutput(\"esc \"\"q\"\"|a ''b''\");</cfscript>", variables);
    EXPECT_EQ(out.equals("esc \"q\"|a ''b''"), true);
}

TEST_F(ScriptStringInterpTest, SingleQuotedLiteral) {
    variables.set("X");
    variables["X"] = cfvariant(5);
    string out = runJitTemplate("<cfscript>writeOutput('single #x#|');</cfscript>", variables);
    EXPECT_EQ(out.equals("single 5|"), true);
}

TEST_F(ScriptStringInterpTest, FunctionCall) {
    string out = runJitTemplate("<cfscript>writeOutput(\"len=#Len(\"hello\")#|\");</cfscript>", variables);
    EXPECT_EQ(out.equals("len=5|"), true);
}

TEST_F(ScriptStringInterpTest, ParenthesizedAndArithmetic) {
    variables.set("X");
    variables["X"] = cfvariant(5);
    string out = runJitTemplate("<cfscript>writeOutput(\"#(x)#|#x + 1#|#x * 2#\");</cfscript>", variables);
    EXPECT_EQ(out.equals("5|6|10"), true);
}

TEST_F(ScriptStringInterpTest, ConcatAndBoolLiteral) {
    variables.set("X");
    variables["X"] = cfvariant(5);
    variables.set("Y");
    variables["Y"] = cfvariant("world");
    string out = runJitTemplate("<cfscript>writeOutput(\"#x & y#|#true#|#false#\");</cfscript>", variables);
    EXPECT_EQ(out.equals("5world|true|false"), true);
}

TEST_F(ScriptStringInterpTest, FloatLiteral) {
    string out = runJitTemplate("<cfscript>writeOutput(\"#8.0#|#8.10#\");</cfscript>", variables);
    EXPECT_EQ(out.equals("8.0|8.10"), true);
}

TEST_F(ScriptStringInterpTest, ArrayAndStruct) {
    string out = runJitTemplate(
        "<cfscript>"
        "arr = ArrayNew(1); ArrayAppend(arr, 10); ArrayAppend(arr, 20);"
        "s = StructNew(); s.name = \"boris\";"
        "writeOutput(\"#arr[2]#|#s.name#\");"
        "</cfscript>", variables);
    EXPECT_EQ(out.equals("20|boris"), true);
}

TEST_F(ScriptStringInterpTest, CfsetsPathInterpolates) {
    // The tag-based <cfset> path shares CompileExprAST's LiteralString case,
    // so string interpolation must work there too.
    variables.set("X");
    variables["X"] = cfvariant(5);
    string out = runJitTemplate("<cfset x = 5><cfset s = \"val=#x#\"><cfoutput>#s#</cfoutput>", variables);
    EXPECT_EQ(out.equals("val=5"), true);
}

TEST_F(ScriptStringInterpTest, EmptyStringNoCrash) {
    variables.set("X");
    variables["X"] = cfvariant(5);
    string out = runJitTemplate("<cfscript>writeOutput(\"empty=||only=#x#\");</cfscript>", variables);
    EXPECT_EQ(out.equals("empty=||only=5"), true);
}

// Regression coverage for BUGS.md #4: variables named inf/nan/infinity must not
// be misparsed as C99 numeric literals (strtod accepts them) in #...# template
// expressions, which go through evaluateExpr().
class InfNanVarTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }
};

TEST_F(InfNanVarTest, InfVariable) {
    // inf = 2^1024 overflows to Infinity; #inf# must render the variable's
    // value (1.#INF), not the literal text "inf".
    string out = runJitTemplate("<cfset inf = 2^1024><cfoutput>#inf#</cfoutput>", variables);
    EXPECT_EQ(out.equals("1.#INF"), true);
}

TEST_F(InfNanVarTest, NanVariable) {
    string out = runJitTemplate("<cfset nan = 5><cfoutput>#nan#</cfoutput>", variables);
    EXPECT_EQ(out.equals("5"), true);
}

TEST_F(InfNanVarTest, InfinityVariable) {
    string out = runJitTemplate("<cfset infinity = 2><cfoutput>#infinity#</cfoutput>", variables);
    EXPECT_EQ(out.equals("2"), true);
}

TEST_F(InfNanVarTest, CaseInsensitiveLookup) {
    string out = runJitTemplate("<cfset inf = 7><cfset nan = 8><cfoutput>#INF#|#Inf#|#NaN#|#NAN#</cfoutput>", variables);
    EXPECT_EQ(out.equals("7|7|8|8"), true);
}

TEST_F(InfNanVarTest, InterpolationInsideString) {
    string out = runJitTemplate(
        "<cfset inf = 2^1024><cfset nan = 5><cfset infinity = 2><cfset s = \"v=#inf#,#nan#,#infinity#\">"
        "<cfoutput>#s#</cfoutput>", variables);
    EXPECT_EQ(out.equals("v=1.#INF,5,2"), true);
}

TEST_F(InfNanVarTest, NumericLiteralsStillWork) {
    // The numeric-literal branch must keep accepting CFML forms. A leading '-'
    // makes the literal computed (-2.5E+1 renders -25, matching CF).
    string out = runJitTemplate("<cfoutput>#1.5#|#-3#|#1e3#|#1E-2#|#.5#|#8.#|#+7#|#-2.5E+1#</cfoutput>", variables);
    EXPECT_EQ(out.equals("1.5|-3|1e3|1E-2|.5|8.|7|-25"), true);
}

TEST_F(InfNanVarTest, InfxStillUndefinedLiteral) {
    // A name that merely starts with inf is not treated as a numeric literal —
    // it is an ordinary undefined variable, which now throws (BUGS.md #4)
    // exactly like any other unknown #...# name.
    bool caught = false;
    try {
        runJitTemplate("<cfoutput>#infx#</cfoutput>", variables);
    } catch (const webstrada::exception &ex) {
        caught = true;
        EXPECT_EQ(string(ex.what()).equals("Variable INFX is undefined."), true);
    }
    EXPECT_EQ(caught, true);

    caught = false;
    try {
        runJitTemplate("<cfoutput>#nanp#</cfoutput>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);
}

// Regression coverage for BUGS.md #4: an undefined variable referenced in
// #...# output (or any expression) must throw instead of rendering its literal
// text. This must hold for every cfexpression variant: a bare name, operator
// operands, array-index bases, dotted struct members, function-call arguments,
// parenthesized expressions, string interpolation and scope-qualified names.
class UndefinedVarOutputTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    // Runs the given #...# expression through the interpreter output path and
    // returns the thrown message, or the empty string when nothing was thrown.
    webstrada::string outputExprMsg(const char *expr) {
        webstrada::string out;
        try {
            cfml::cfoutputexpr(out, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, &variables, expr);
        } catch (const webstrada::exception &ex) {
            return string(ex.what());
        }
        return "";
    }

    // Runs the full JIT-compiled template and returns the thrown message, or
    // the empty string when nothing was thrown.
    webstrada::string runMsg(const string &cfml_code) {
        try {
            runJitTemplate(cfml_code, variables);
        } catch (const webstrada::exception &ex) {
            return string(ex.what());
        }
        return "";
    }
};

TEST_F(JitExpressionTest, GetApplicationMetadataEmptyWithoutCfApplication) {
    // With no <cfapplication> active, GetApplicationMetadata() returns an EMPTY
    // struct like CF (was BUGS.md #3: previously the 8 modeled keys were always
    // returned).
    string out = runJitTemplate(
        "<cfset m = GetApplicationMetadata()>"
        "<cfoutput>#structCount(m)#|#structKeyList(m)#</cfoutput>",
        variables);
    EXPECT_EQ(out.equals("0|"), true);
}

TEST_F(JitExpressionTest, TernaryOperatorCfscript) {
    // cfscript ternary `cond ? then : else` (previously BUGS.md #7: parsed but
    // never lowered). Verified against CF 2025 on the RDS host.
    variables.set("X");
    variables["X"] = cfvariant(5);
    runJitTemplate(
        "<cfset a = (1 ? \"T\" : \"F\")>"
        "<cfset b = (0 ? \"A\" : \"B\")>"
        "<cfset c = (X EQ 5 ? \"yes\" : \"no\")>"
        "<cfset d = (\"x\" ? \"truthy\" : \"falsy\")>"
        "<cfset e = (\"no\" ? \"T\" : \"F\")>"
        "<cfset f = (\"0\" ? \"T\" : \"F\")>"
        "<cfset g = (\"\" ? \"empty-t\" : \"empty-f\")>",
        variables
    );
    EXPECT_EQ(variables["A"].toString().equals("T"), true);
    EXPECT_EQ(variables["B"].toString().equals("B"), true);
    EXPECT_EQ(variables["C"].toString().equals("yes"), true);
    EXPECT_EQ(variables["D"].toString().equals("truthy"), true);
    EXPECT_EQ(variables["E"].toString().equals("F"), true);
    EXPECT_EQ(variables["F"].toString().equals("F"), true);
    EXPECT_EQ(variables["G"].toString().equals("empty-t"), true);
}

TEST_F(JitExpressionTest, TernaryOperatorCfoutputInterpreter) {
    // The same ternary inside <cfoutput>#...# (interpreter sharp parser).
    runJitTemplate(
        "<cfoutput>#(1 ? \"T\" : \"F\")#|#(0 ? \"A\" : \"B\")#|#(\"x\" ? \"C\" : \"D\")#|#(\"\" ? \"E\" : \"F\")#</cfoutput>",
        variables
    );
    string out;
    // runJitTemplate returns the rendered output; re-run to capture it.
    out = runJitTemplate(
        "<cfoutput>#(1 ? \"T\" : \"F\")#|#(0 ? \"A\" : \"B\")#|#(\"x\" ? \"C\" : \"D\")#|#(\"\" ? \"E\" : \"F\")#</cfoutput>",
        variables
    );
    EXPECT_EQ(out.equals("T|B|C|E"), true);
}

TEST_F(JitExpressionTest, TernaryNestedAndPrecedence) {
    // Nested ternary is right-associative; comparisons bind tighter than ?:.
    variables.set("X");
    variables["X"] = cfvariant(1);
    runJitTemplate(
        "<cfset a = (X EQ 1 ? \"one\" : X EQ 2 ? \"two\" : \"other\")>"
        "<cfset b = (2 + 3 EQ 5 ? \"arith\" : \"nope\")>"
        "<cfset c = (X GT 5 ? \"big\" : \"small\")>"
        "<cfset d = (true ? \"t\" : \"f\")>"
        "<cfset e = (false ? \"t\" : \"f\")>",
        variables
    );
    EXPECT_EQ(variables["A"].toString().equals("one"), true);
    EXPECT_EQ(variables["B"].toString().equals("arith"), true);
    EXPECT_EQ(variables["C"].toString().equals("small"), true);
    EXPECT_EQ(variables["D"].toString().equals("t"), true);
    EXPECT_EQ(variables["E"].toString().equals("f"), true);
}

TEST_F(JitExpressionTest, TernaryAsFunctionArgument) {
    runJitTemplate(
        "<cfset a = Len(1 ? \"abc\" : \"x\")>"
        "<cfset c = (1 ? \"T\" : \"F\") & (0 ? \"X\" : \"Y\")>",
        variables
    );
    EXPECT_EQ(variables["A"].toString().equals("3"), true);
    EXPECT_EQ(variables["C"].toString().equals("TY"), true);
}

TEST_F(JitExpressionTest, TernaryAssignsResult) {
    // The ternary evaluates exactly one branch (no side effects in the other).
    variables.set("COUNT");
    variables["COUNT"] = cfvariant(0);
    runJitTemplate(
        "<cfset COUNT = COUNT + 1>"
        "<cfset a = (COUNT EQ 1 ? \"first\" : \"later\")>"
        "<cfset b = (COUNT EQ 2 ? \"second\" : \"not-second\")>",
        variables
    );
    EXPECT_EQ(variables["A"].toString().equals("first"), true);
    EXPECT_EQ(variables["B"].toString().equals("not-second"), true);
}

TEST_F(JitExpressionTest, AndOrShortCircuitJit) {
    // CF short-circuits AND/OR: the right operand is not evaluated when the
    // left side decides the result. `lastIndex EQ 0 OR arr[lastIndex]...` with
    // lastIndex=0 must never touch arr[0] (was MangoBlog's Queue.cfc:30
    // "element at position 0 ... cannot be found"). Verified against CF 2025
    // in tests/cfm/or_shortcircuit_test.cfm.
    string out = runJitTemplate(
        "<cfset elements = arraynew(1) />"
        "<cfset lastIndex = arraylen(elements) />"
        "<cfif lastIndex EQ 0 OR elements[lastIndex].priority GTE 5>"
        "<cfset arrayappend(elements, \"END\") />"
        "</cfif>"
        "<cfoutput>#arraylen(elements)#|</cfoutput>"
        "<cfset r = lastIndex GT 0 AND elements[lastIndex].priority GTE 5 />"
        "<cfoutput>#r#</cfoutput>",
        variables
    );
    EXPECT_EQ(out.equals("1|NO"), true);
}

TEST_F(JitExpressionTest, AndOrShortCircuitInterpreter) {
    // The cfoutput #...# interpreter path short-circuits AND/OR identically.
    string out = runJitTemplate(
        "<cfset elements = arraynew(1) />"
        "<cfset lastIndex = arraylen(elements) />"
        "<cfoutput>#(lastIndex EQ 0 OR elements[lastIndex].priority GTE 5)#|</cfoutput>"
        "<cfoutput>#(lastIndex GT 0 AND elements[lastIndex].priority GTE 5)#|</cfoutput>"
        "<cfset a = false />"
        "<cfoutput>#(a AND (undefinedVar EQ 1))#|</cfoutput>"
        "<cfoutput>#(true OR [1,2,3][5])#|</cfoutput>"
        "<cfoutput>#(false AND \"x\" & \"y\")#|</cfoutput>"
        "<cfoutput>#(true OR 1 GT 2)#|</cfoutput>"
        "<cfoutput>#(a OR \"fallback\")#</cfoutput>",
        variables
    );
    EXPECT_EQ(out.equals("YES|NO|false|true|false|true|fallback"), true);
}

TEST_F(JitExpressionTest, AndOrResults) {
    // The result values of AND/OR match CF (verified against CF 2025 in
    // tests/cfm/andor_results_test.cfm): AND/OR return one of their operands.
    string out = runJitTemplate(
        "<cfset r1 = true AND false />"
        "<cfset r2 = false OR true />"
        "<cfset r3 = 0 AND true />"
        "<cfset r4 = 2.5 AND true />"
        "<cfset r5 = false OR 5 />"
        "<cfset r6 = 0 OR false />"
        "<cfset r7 = true OR \"x\" />"
        "<cfset r8 = (5 GT 3) OR true />"
        "<cfset r9 = 1 AND 2 />"
        "<cfset r10 = 1 OR 2 />"
        "<cfset r11 = 0 AND 0 />"
        "<cfset r12 = 0 OR 0 />"
        "<cfoutput>#r1#|#r2#|#r3#|#r4#|#r5#|#r6#|#r7#|#r8#|#r9#|#r10#|#r11#|#r12#</cfoutput>",
        variables
    );
    EXPECT_EQ(out.equals("false|true|0|true|5|false|true|YES|2|1|0|0"), true);
}

TEST_F(JitExpressionTest, AndOrShortCircuitNoSideEffect) {
    // A function call on the skipped side never runs (CF: `false AND fn()` and
    // `true OR fn()` both skip fn). Counter a global to prove it.
    variables.set("CALLS");
    variables["CALLS"] = cfvariant(0);
    runJitTemplate(
        "<cfscript>function bump() { CALLS = CALLS + 1; return true; }</cfscript>"
        "<cfset a = false AND bump() />"
        "<cfset b = true OR bump() />"
        "<cfset c = true AND bump() />"
        "<cfset d = false OR bump() />",
        variables
    );
    EXPECT_EQ(variables["CALLS"].toString().equals("2"), true);
}

TEST_F(UndefinedVarOutputTest, BareVariableThrows) {
    EXPECT_EQ(outputExprMsg("undefinedVar").equals("Variable UNDEFINEDVAR is undefined."), true);
    // JIT-compiled path (cfoutputexpr) throws identically.
    EXPECT_EQ(runMsg("<cfoutput>#undefinedVar#</cfoutput>").equals("Variable UNDEFINEDVAR is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, OperatorOperandThrows) {
    EXPECT_EQ(outputExprMsg("undefinedVar + 1").equals("Variable UNDEFINEDVAR is undefined."), true);
    EXPECT_EQ(outputExprMsg("1 + undefinedVar").equals("Variable UNDEFINEDVAR is undefined."), true);
    EXPECT_EQ(outputExprMsg("undefinedVar EQ 5").equals("Variable UNDEFINEDVAR is undefined."), true);
    EXPECT_EQ(runMsg("<cfoutput>#undefinedVar * 2#</cfoutput>").equals("Variable UNDEFINEDVAR is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, ArrayIndexBaseThrows) {
    EXPECT_EQ(outputExprMsg("undefinedArr[1]").equals("Variable UNDEFINEDARR is undefined."), true);
    EXPECT_EQ(outputExprMsg("undefinedArr[1][2]").equals("Variable UNDEFINEDARR is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, DottedMemberBaseThrows) {
    // CF reports a single-dot access on an undefined base as the element
    // message, but a multi-dot access as the variable message (verified on the
    // RDS host; was BUGS.md "chain-base lookups").
    EXPECT_EQ(outputExprMsg("undefinedStruct.key").equals("Element KEY is undefined in UNDEFINEDSTRUCT."), true);
    EXPECT_EQ(runMsg("<cfoutput>#undefinedStruct.a.b#</cfoutput>").equals("Variable UNDEFINEDSTRUCT is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, ChainBaseMessagesJitAndInterpreter) {
    // The chain-base message rules hold in the JIT condition path (<cfif>,
    // <cfset>, cfscript if, <cfloop condition>) and the cfoutput interpreter
    // path: bracket access on an undefined base -> "Variable X is undefined.";
    // single-dot access -> "Element KEY is undefined in BASE."; multi-dot
    // access -> "Variable BASE is undefined.".
    EXPECT_EQ(runMsg("<cfif victim[1] eq 1>x</cfif>").equals("Variable VICTIM is undefined."), true);
    EXPECT_EQ(runMsg("<cfif undefinedStruct.key eq 1>x</cfif>").equals("Element KEY is undefined in UNDEFINEDSTRUCT."), true);
    EXPECT_EQ(runMsg("<cfset r = undefinedStruct.key>").equals("Element KEY is undefined in UNDEFINEDSTRUCT."), true);
    EXPECT_EQ(runMsg("<cfset r2 = victim[1]>").equals("Variable VICTIM is undefined."), true);
    EXPECT_EQ(runMsg("<cfset r3 = undefinedStruct.a.b>").equals("Variable UNDEFINEDSTRUCT is undefined."), true);
    EXPECT_EQ(runMsg("<cfscript>if (victim[1] eq 1) {}</cfscript>").equals("Variable VICTIM is undefined."), true);
    EXPECT_EQ(runMsg("<cfloop condition=\"undefinedStruct.key eq 1\"><cfbreak></cfloop>").equals("Element KEY is undefined in UNDEFINEDSTRUCT."), true);
}

TEST_F(UndefinedVarOutputTest, ArrayOutOfBoundsMessage) {
    // CF reports "The element at position N of dimension 1, of array variable
    // &quot;NAME,&quot; cannot be found." for a direct variable index past the
    // end (was BUGS.md "Array index out-of-bounds error message"); a chained
    // index on an array object uses the array-object form.
    EXPECT_EQ(runMsg("<cfset killArray = []><cfset x = killArray[1]>")
                     .equals("The element at position 1 of dimension 1, of array variable &quot;KILLARRAY,&quot; cannot be found."), true);
    EXPECT_EQ(runMsg("<cfset arr = [1,2,3]><cfset x = arr[5]>")
                     .equals("The element at position 5 of dimension 1, of array variable &quot;ARR,&quot; cannot be found."), true);
    EXPECT_EQ(runMsg("<cfset arr = [1,2,3]><cfset x = arr[0]>")
                     .equals("The element at position 0 of dimension 1, of array variable &quot;ARR,&quot; cannot be found."), true);
    // Chained index on an array object: array-object form.
    EXPECT_EQ(runMsg("<cfset arr2 = [[1],[2]]><cfset x = arr2[3][1]>")
                     .equals("The element at position 3, of dimension 1, of an array object used as part of an expression, cannot be found."), true);
    // Interpreter cfoutput path reports the named variable form.
    runJitTemplate("<cfset arr = [1,2,3]>", variables);
    EXPECT_EQ(outputExprMsg("arr[9]").equals("The element at position 9 of dimension 1, of array variable &quot;ARR,&quot; cannot be found."), true);
}

TEST_F(UndefinedVarOutputTest, FunctionCallArgumentThrows) {
    EXPECT_EQ(outputExprMsg("Len(undefinedVar)").equals("Variable UNDEFINEDVAR is undefined."), true);
    EXPECT_EQ(outputExprMsg("Max(1, undefinedVar)").equals("Variable UNDEFINEDVAR is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, ParenthesizedExpressionThrows) {
    EXPECT_EQ(outputExprMsg("(undefinedVar)").equals("Variable UNDEFINEDVAR is undefined."), true);
    EXPECT_EQ(outputExprMsg("((undefinedVar + 1))").equals("Variable UNDEFINEDVAR is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, StringInterpolationThrows) {
    EXPECT_EQ(outputExprMsg("\"x #undefinedVar# y\"").equals("Variable UNDEFINEDVAR is undefined."), true);
    EXPECT_EQ(runMsg("<cfoutput>#\"a #undefinedVar# b\"#</cfoutput>").equals("Variable UNDEFINEDVAR is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, ScopeQualifiedNameThrows) {
    // CF reports a scope-qualified missing member as "Element X is undefined in
    // SESSION." (member uppercased, scope uppercased) — previously the engine
    // reported "Variable UNDEFINEDVAR is undefined." / "Variable VARIABLES.X is
    // undefined." Verified against CF 2025 on the RDS host.
    EXPECT_EQ(outputExprMsg("variables.undefinedVar").equals("Element UNDEFINEDVAR is undefined in VARIABLES."), true);
    // JIT-compiled path throws the same scope-aware message.
    EXPECT_EQ(runMsg("<cfoutput>#variables.undefinedVar#</cfoutput>").equals("Element UNDEFINEDVAR is undefined in VARIABLES."), true);
    EXPECT_EQ(runMsg("<cfoutput>#url.undefinedVar#</cfoutput>").equals("Element UNDEFINEDVAR is undefined in URL."), true);
    EXPECT_EQ(runMsg("<cfoutput>#session.x#</cfoutput>").equals("Element X is undefined in SESSION."), true);
    EXPECT_EQ(runMsg("<cfoutput>#application.y#</cfoutput>").equals("Element Y is undefined in APPLICATION."), true);
    EXPECT_EQ(runMsg("<cfoutput>#server.nope#</cfoutput>").equals("Element NOPE is undefined in SERVER."), true);
    EXPECT_EQ(runMsg("<cfoutput>#form.nope#</cfoutput>").equals("Element NOPE is undefined in FORM."), true);
    // Nested missing member: the whole tail is uppercased and dot-joined.
    EXPECT_EQ(runMsg("<cfoutput>#session.sa.missing#</cfoutput>").equals("Element SA.MISSING is undefined in SESSION."), true);
}

TEST_F(UndefinedVarOutputTest, MissingMemberOnExistingStructThrows) {
    variables.set("ST");
    cfvariant st = cfvariant::Struct;
    st.set("A") = cfvariant(1);
    variables["ST"] = st;

    EXPECT_EQ(outputExprMsg("st.undefinedKey").equals("Element 'UNDEFINEDKEY' is undefined"), true);
    EXPECT_EQ(outputExprMsg("st.a.missing").equals("Element 'MISSING' is undefined"), true);
    EXPECT_EQ(runMsg("<cfoutput>#st.undefinedKey#</cfoutput>").equals("Element 'UNDEFINEDKEY' is undefined"), true);
}

TEST_F(UndefinedVarOutputTest, NullResolvesAsUndefinedVariable) {
    // #null# is not a CFML literal; CF 2021 throws "Variable NULL is undefined.".
    EXPECT_EQ(outputExprMsg("null").equals("Variable NULL is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, UnrecognizedWordThrowsLikeCf) {
    // CF 2021 rejects these templates; the generic unknown-expression path now
    // throws instead of rendering the raw text.
    EXPECT_EQ(outputExprMsg("5 FOO 4").equals("Variable 5 FOO 4 is undefined."), true);
    EXPECT_EQ(outputExprMsg("5 NOTEQUAL 4").equals("Variable 5 NOTEQUAL 4 is undefined."), true);
}

TEST_F(UndefinedVarOutputTest, DefinedVariablesStillRender) {
    variables.set("X");
    variables["X"] = cfvariant(5);
    variables.set("ARR");
    cfvariant arr(cfvariant::Array);
    arr.insert(cfvariant(10));
    variables["ARR"] = arr;
    variables.set("ST");
    cfvariant st = cfvariant::Struct;
    st.set("KEY") = cfvariant(7);
    variables["ST"] = st;

    webstrada::string out;
    cfml::cfoutputexpr(out, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, &variables, "x");
    EXPECT_EQ(out.equals("5"), true);
    out.clear();
    cfml::cfoutputexpr(out, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, &variables, "arr[1]");
    EXPECT_EQ(out.equals("10"), true);
    out.clear();
    cfml::cfoutputexpr(out, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, &variables, "st.key");
    EXPECT_EQ(out.equals("7"), true);
    out.clear();
    cfml::cfoutputexpr(out, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, &variables, "variables.x");
    EXPECT_EQ(out.equals("5"), true);

    string jitOut = runJitTemplate(
        "<cfoutput>#x#|#arr[1]#|#st.key#|#variables.x#|#x + 1#|#\"v=#x#\"#</cfoutput>", variables);
    EXPECT_EQ(jitOut.equals("5|10|7|5|6|v=5"), true);
}

TEST_F(UndefinedVarOutputTest, PartialOutputBeforeThrowIsNotRendered) {
    // CF aborts the render at the undefined reference; nothing after it is
    // emitted (verified against CF 2021: "A" then server-error).
    bool caught = false;
    try {
        runJitTemplate("<cfoutput>A#undefinedVar#B</cfoutput>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);
}

TEST_F(UndefinedVarOutputTest, CfsetUndefinedVariableThrows) {
    // <cfset x = undefinedVar> must throw too, never render the raw text.
    // (The JIT compiles the RHS through cfvariant_get_var, which already threw;
    // the interpreter evaluateExpr path used by #...# now matches.)
    EXPECT_EQ(runMsg("<cfset x = undefinedVar>").isEmpty(), false);
    EXPECT_EQ(runMsg("<cfset st = {a:1}><cfset x = st.undefinedKey>").isEmpty(), false);
    // And the interpreter path used by cfml::cfset.
    cfvariant scope = cfvariant::Struct;
    try {
        cfml::cfset(&scope, "x", "undefinedVar");
    } catch (const webstrada::exception &ex) {
        EXPECT_EQ(string(ex.what()).equals("Variable UNDEFINEDVAR is undefined."), true);
        return;
    }
    EXPECT_TRUE(false) << "cfset with an undefined variable must throw";
}

// cfevalbool()'s numeric check must only accept CFML's numeric grammar
// (digits, optional '.', optional exponent, optional sign), never C99 forms
// like inf/infinity/nan — those must resolve as variables (previously
// BUGS.md #5). The public API may be called with null scopes, which must not
// crash the variable lookup.
class CfevalboolTest : public testing::Test {
protected:
    const cfvariant *n = nullptr;

    int eval(const char *expr, cfvariant *variables = nullptr) {
        return cfml::cfevalbool(expr, n, n, n, n, n, n, n, variables);
    }
};

TEST_F(CfevalboolTest, InfNanInfinityResolveAsVariables) {
    // With no variables defined, inf/nan/infinity are undefined variables, so
    // they must be falsy — previously strtod turned them into non-zero
    // literals (Infinity/NaN) and eval returned true.
    EXPECT_EQ(eval("inf"), 0);
    EXPECT_EQ(eval("nan"), 0);
    EXPECT_EQ(eval("infinity"), 0);

    cfvariant variables = cfvariant::Struct;
    variables.set("inf") = cfvariant(7);
    variables.set("nan") = cfvariant(0);
    variables.set("infinity") = cfvariant(9);
    EXPECT_EQ(eval("inf", &variables), 1);
    EXPECT_EQ(eval("nan", &variables), 0);
    EXPECT_EQ(eval("infinity", &variables), 1);
    // Case-insensitive lookup.
    EXPECT_EQ(eval("INF", &variables), 1);
    // A name merely starting with inf is not a literal.
    EXPECT_EQ(eval("infx", &variables), 0);
}

TEST_F(CfevalboolTest, NumericLiteralsStillWork) {
    EXPECT_EQ(eval("1"), 1);
    EXPECT_EQ(eval("0"), 0);
    EXPECT_EQ(eval("2.5"), 1);
    EXPECT_EQ(eval("-3"), 1);
    EXPECT_EQ(eval("1e3"), 1);
    EXPECT_EQ(eval(".5"), 1);
    EXPECT_EQ(eval("8."), 1);
    EXPECT_EQ(eval("+7"), 1);
}

TEST_F(CfevalboolTest, OperatorPathResolvesInfAsVariable) {
    cfvariant variables = cfvariant::Struct;
    variables.set("inf") = cfvariant(7);
    variables.set("nan") = cfvariant(0);
    EXPECT_EQ(eval("inf EQ 7", &variables), 1);
    EXPECT_EQ(eval("inf GT 1", &variables), 1);
    EXPECT_EQ(eval("inf EQ 8", &variables), 0);
    EXPECT_EQ(eval("nan EQ 0", &variables), 1);
    EXPECT_EQ(eval("2 GT 1"), 1);
}

TEST_F(CfevalboolTest, NullScopesDoNotCrash) {
    // The public API may be invoked with null scope pointers; an undefined
    // variable must evaluate falsy instead of dereferencing a null scope.
    EXPECT_EQ(eval("undefinedVarX"), 0);
    EXPECT_EQ(eval("someVar GT 1"), 0);
}

class WorkerTest : public testing::Test {
protected:
    void SetUp() override {}
    void TearDown() override {}

    void callWriteException(worker &w, const webstrada::exception &ex) {
        w.writeException(ex);
    }

    // Run the requested template through the worker's run_template path (the
    // same code path the daemon uses) and return the output buffer.
    static string runWorkerTemplate(worker &w, const webstrada::string &pathname, const webstrada::string &web_root) {
        cfml::VariantCleanupGuard guard;
        w.run_template(pathname, web_root);
        return w.out();
    }

    // Wrap the private Application.cfm search so gtest-generated test classes
    // (which are not WorkerTest and therefore not friends) can call it.
    static string callFindApplicationCfm(worker &w, const webstrada::string &template_path, const webstrada::string &web_root) {
        return w.find_application_cfm(template_path, web_root);
    }

    // Full request simulation: resets the response state, disables the scope
    // slots, binds the SQLite store, runs the template and persists the scopes
    // back — mirroring process_request's scope handling. Returns the output.
    static string runWorkerRequest(worker &w, const webstrada::string &pathname, const webstrada::string &web_root) {
        w.m_application.setDisabled();
        w.m_session.setDisabled();
        cfml::VariantCleanupGuard guard;
        cfml::response_begin();
        cfml::scope_begin(&w.m_scopeStore, &w.m_application, &w.m_session);
        w.m_out.clear();
        w.run_template(pathname, web_root);
        cfml::scope_end();
        return w.out();
    }

    // Like runWorkerRequest but swallows <cflocation>'s abort_exception (the
    // request harness catches it too), so a redirecting template can be run.
    static string runWorkerRequestRedirect(worker &w, const webstrada::string &pathname, const webstrada::string &web_root) {
        w.m_application.setDisabled();
        w.m_session.setDisabled();
        cfml::VariantCleanupGuard guard;
        cfml::response_begin();
        cfml::scope_begin(&w.m_scopeStore, &w.m_application, &w.m_session);
        w.m_out.clear();
        try {
            w.run_template(pathname, web_root);
        } catch (const webstrada::abort_exception &) {
        }
        cfml::scope_end();
        return w.out();
    }

    // Value of a queued Set-Cookie body for `name` ("" when absent).
    static string cookieValue(const char *name) {
        auto &r = cfml::response();
        std::string prefix = std::string(name) + "=";
        for (const auto &c : r.cookies) {
            if (c.compare(0, prefix.size(), prefix) == 0) {
                size_t semi = c.find(';', prefix.size());
                return webstrada::string(c.substr(prefix.size(), semi - prefix.size()).c_str());
            }
        }
        return "";
    }

    // Point the worker's scope store at a fresh temp database and return its
    // path (the caller removes the file at the end of the test).
    static std::string makeTempScopeDb() {
        char db[] = "/tmp/webstrada_scope_test_XXXXXX";
        int fd = mkstemp(db);
        EXPECT_NE(fd, -1);
        close(fd);
        unlink(db); // sqlite3_open re-creates it
        return db;
    }

    static void removeScopeDb(const std::string &path) {
        unlink(path.c_str());
        unlink((path + "-wal").c_str());
        unlink((path + "-shm").c_str());
    }

    // True when the worker's scope store still holds a live row for the app
    // (optionally a specific session id). Used to assert ApplicationStop.
    static bool storeHasRow(worker &w, const char *appName, const char *sessionId = nullptr) {
        std::string data;
        int64_t now = (int64_t)std::time(nullptr);
        if (sessionId) return w.m_scopeStore.loadSession(appName, sessionId, now, data);
        return w.m_scopeStore.loadApplication(appName, now, data);
    }

    // Runs the requested template through run_template with a proper <cfinclude>
    // context (template + component loader from the worker's cache), so
    // Application.cfc / CreateObject work. Returns the output buffer.
    static string runWorkerRequestWithContext(worker &w, const webstrada::string &pathname,
                                              const webstrada::string &web_root) {
        w.m_application.setDisabled();
        w.m_session.setDisabled();
        cfml::VariantCleanupGuard guard;
        cfml::response_begin();
        cfml::scope_begin(&w.m_scopeStore, &w.m_application, &w.m_session);
        w.m_out.clear();
        cfml::IncludeRuntime rt;
        rt.currentPath = std::string(pathname.constData());
        rt.webRoot = std::string(web_root.constData());
        rt.loader = &test_include_loader;
        rt.loaderOpaque = &w.m_templates;
        rt.componentLoader = &test_component_loader;
        rt.componentLoaderOpaque = &w.m_templates;
        cfml::include_begin(&rt);
        try {
            w.run_template(pathname, web_root);
        } catch (...) {
            cfml::include_end();
            cfml::scope_end();
            throw;
        }
        cfml::include_end();
        cfml::scope_end();
        return w.out();
    }
};

TEST_F(WorkerTest, WriteExceptionNoExtraRows) {
    worker w;
    webstrada::exception ex("Test message", "Test detail");
    callWriteException(w, ex);
    
    string out = w.out();
    EXPECT_EQ(out.contains("Browser"), false);
    EXPECT_EQ(out.contains("Remote Address"), false);
    EXPECT_EQ(out.contains("Referrer"), false);
    EXPECT_EQ(out.contains("Test message"), true);
    EXPECT_EQ(out.contains("Test detail"), true);
}

TEST_F(WorkerTest, WriteExceptionAllExtraRows) {
    worker w;
    w.cgi().set("HTTP_USER_AGENT") = "MyTestBrowser";
    w.cgi().set("HTTP_HOST") = "MyTestHost";
    w.cgi().set("HTTP_REFERER") = "MyTestReferrer";
    
    webstrada::exception ex("Test message", "Test detail");
    callWriteException(w, ex);
    
    string out = w.out();
    EXPECT_EQ(out.contains("Browser"), true);
    EXPECT_EQ(out.contains("MyTestBrowser"), true);
    EXPECT_EQ(out.contains("Remote Address"), true);
    EXPECT_EQ(out.contains("MyTestHost"), true);
    EXPECT_EQ(out.contains("Referrer"), true);
    EXPECT_EQ(out.contains("MyTestReferrer"), true);
    EXPECT_EQ(out.contains("Test message"), true);
    EXPECT_EQ(out.contains("Test detail"), true);
}

TEST_F(WorkerTest, WriteExceptionShowsLocationAndStack) {
    // The exception HTML block carries the captured call stack: the "The error
    // occurred in <template>: line N." location line and a CFML Call Stack table
    // (innermost frame first).
    worker w;
    webstrada::exception ex("Test message", "Test detail");
    ex.m_stackTrace.push_back({"/srv/web/outer.cfm", 3, ""});
    ex.m_stackTrace.push_back({"/srv/web/inner.cfm", 5, "DOWORK"});
    callWriteException(w, ex);

    string out = w.out();
    EXPECT_EQ(out.contains("Test message"), true);
    EXPECT_EQ(out.contains("The error occurred in /srv/web/inner.cfm: line 5."), true);
    EXPECT_EQ(out.contains("CFML Call Stack"), true);
    EXPECT_EQ(out.contains("/srv/web/inner.cfm"), true);
    EXPECT_EQ(out.contains("DOWORK"), true);
    EXPECT_EQ(out.contains("/srv/web/outer.cfm"), true);
}

TEST_F(WorkerTest, WriteExceptionWithoutStackHasNoLocation) {
    // An exception that never unwound through a JIT landing pad has no captured
    // stack, so the error page omits the location/stack sections.
    worker w;
    webstrada::exception ex("Test message", "Test detail");
    callWriteException(w, ex);

    string out = w.out();
    EXPECT_EQ(out.contains("The error occurred in"), false);
    EXPECT_EQ(out.contains("CFML Call Stack"), false);
}

TEST_F(WorkerTest, WriteExceptionPartialExtraRows) {
    {
        worker w;
        w.cgi().set("HTTP_USER_AGENT") = "MyTestBrowser";
        webstrada::exception ex("Test message", "Test detail");
        callWriteException(w, ex);
        
        string out = w.out();
        EXPECT_EQ(out.contains("Browser"), true);
        EXPECT_EQ(out.contains("MyTestBrowser"), true);
        EXPECT_EQ(out.contains("Remote Address"), false);
        EXPECT_EQ(out.contains("Referrer"), false);
    }
    {
        worker w;
        w.cgi().set("HTTP_HOST") = "MyTestHost";
        webstrada::exception ex("Test message", "Test detail");
        callWriteException(w, ex);
        
        string out = w.out();
        EXPECT_EQ(out.contains("Browser"), false);
        EXPECT_EQ(out.contains("Remote Address"), true);
        EXPECT_EQ(out.contains("MyTestHost"), true);
        EXPECT_EQ(out.contains("Referrer"), false);
    }
    {
        worker w;
        w.cgi().set("HTTP_REFERER") = "MyTestReferrer";
        webstrada::exception ex("Test message", "Test detail");
        callWriteException(w, ex);
        
        string out = w.out();
        EXPECT_EQ(out.contains("Browser"), false);
        EXPECT_EQ(out.contains("Remote Address"), false);
        EXPECT_EQ(out.contains("Referrer"), true);
        EXPECT_EQ(out.contains("MyTestReferrer"), true);
    }
}

// ---- Application.cfm ----

// Create a temp directory tree and return its path. `files` is a list of
// "relative/path" -> contents pairs. The returned directory is created under
// /tmp and left for the process lifetime (tests don't need cleanup).
static std::string makeAppCfmTree(const std::vector<std::pair<std::string, std::string>> &files)
{
    char tmpl[] = "/tmp/webstrada_appcfm_test_XXXXXX";
    char *dir = mkdtemp(tmpl);
    EXPECT_NE(dir, nullptr);
    std::string root = dir;

    for (const auto &[rel, content] : files) {
        std::string full = root + "/" + rel;
        std::filesystem::path p(full);
        if (p.has_parent_path()) {
            std::filesystem::create_directories(p.parent_path());
        }
        std::ofstream out(full, std::ios::binary);
        out << content;
        out.close();
    }
    return root;
}

TEST_F(WorkerTest, ApplicationCfmFoundInSameDir) {
    std::string root = makeAppCfmTree({
        {"Application.cfm", "<cfset appVar = \"FROM_APP\">"},
        {"page.cfm", "<cfoutput>page|#appVar#</cfoutput>"},
    });
    worker w;
    string page = (root + "/page.cfm").c_str();
    string out = runWorkerTemplate(w, page, root.c_str());
    EXPECT_EQ(out.equals("page|FROM_APP"), true);
}

TEST_F(WorkerTest, ApplicationCfmOutputIsPrepended) {
    // App ends with </cfoutput> and NO trailing whitespace -> no space before page.
    std::string root = makeAppCfmTree({
        {"Application.cfm", "<cfset appVar = \"FROM_APP\">\n<cfoutput>APP_OUT|</cfoutput>"},
        {"page.cfm", "<cfoutput>PAGE|#appVar#</cfoutput>"},
    });
    worker w;
    string page = (root + "/page.cfm").c_str();
    string out = runWorkerTemplate(w, page, root.c_str());
    EXPECT_EQ(out.equals("APP_OUT|PAGE|FROM_APP"), true);
}

TEST_F(WorkerTest, ApplicationCfmSearchedInParentDir) {
    std::string root = makeAppCfmTree({
        {"Application.cfm", "<cfset appVar = \"FROM_PARENT\">"},
        {"sub/page.cfm", "<cfoutput>sub|#appVar#</cfoutput>"},
    });
    worker w;
    string page = (root + "/sub/page.cfm").c_str();
    string out = runWorkerTemplate(w, page, root.c_str());
    EXPECT_EQ(out.equals("sub|FROM_PARENT"), true);
}

TEST_F(WorkerTest, ApplicationCfmExitStopsPreludeOnly) {
    // <cfexit> in Application.cfm exits the prelude only; the requested page
    // still runs, and the prelude's output is preserved (verified on CF).
    std::string root = makeAppCfmTree({
        {"Application.cfm", "<cfoutput>PRE|</cfoutput><cfexit><cfoutput>PRE_AFTER</cfoutput>"},
        {"page.cfm", "<cfoutput>PAGE</cfoutput>"},
    });
    worker w;
    string page = (root + "/page.cfm").c_str();
    string out = runWorkerTemplate(w, page, root.c_str());
    EXPECT_EQ(out.equals("PRE|PAGE"), true);
}

TEST_F(WorkerTest, ApplicationCfmExitLoopInPreludeIsCatchableInside) {
    // method="loop" in the prelude is catchable from a cftry inside the
    // prelude itself, and the prelude continues (verified on CF).
    std::string root = makeAppCfmTree({
        {"Application.cfm", "<cftry><cfexit method=\"loop\"><cfcatch type=\"any\"><cfoutput>CAUGHT#cfcatch.message#</cfoutput></cfcatch></cftry>"},
        {"page.cfm", "<cfoutput>PAGE</cfoutput>"},
    });
    worker w;
    string page = (root + "/page.cfm").c_str();
    string out = runWorkerTemplate(w, page, root.c_str());
    EXPECT_EQ(out.equals("CAUGHTInvalid use of the cfexit tag.PAGE"), true);
}

TEST_F(WorkerTest, PageLevelExitPropagatesFromRunTemplate) {
    // A top-level <cfexit> on the requested page is not swallowed by the
    // prelude boundary; it propagates out of run_template (process_request
    // catches it and returns the partial output).
    std::string root = makeAppCfmTree({
        {"Application.cfm", "<cfoutput>PRE|</cfoutput>"},
        {"page.cfm", "<cfoutput>PAGE|</cfoutput><cfexit>"},
    });
    worker w;
    string page = (root + "/page.cfm").c_str();
    string out;
    bool exited = false;
    try {
        out = runWorkerTemplate(w, page, root.c_str());
    } catch (const webstrada::exit_exception &) {
        exited = true;
    }
    EXPECT_EQ(exited, true);
}

