// ---- Application.cfc lifecycle (tag-form CFC, run with a component loader) ----

TEST_F(WorkerTest, ApplicationCfcLifecycleOrder) {
    // onApplicationStart / onSessionStart / onRequestStart / onRequest /
    // onRequestEnd run in ColdFusion's order around the page.
    std::string root = makeAppCfmTree({
        {"Application.cfc",
         "<cfcomponent>\n"
         "  <cfset this.name = \"CfcApp1\">\n"
         "  <cfset this.sessionManagement = true>\n"
         "  <cffunction name=\"onApplicationStart\" returntype=\"boolean\">\n"
         "    <cfset application.started = \"AS\">\n"
         "    <cfreturn true>\n"
         "  </cffunction>\n"
         "  <cffunction name=\"onSessionStart\">\n"
         "    <cfset session.ss = \"SS\">\n"
         "  </cffunction>\n"
         "  <cffunction name=\"onRequestStart\" returntype=\"boolean\">\n"
         "    <cfargument name=\"targetPage\">\n"
         "    <cfset request.rhs = \"RS\">\n"
         "    <cfreturn true>\n"
         "  </cffunction>\n"
         "  <cffunction name=\"onRequest\">\n"
         "    <cfargument name=\"targetPage\">\n"
         "    <cfoutput>BEFORE;</cfoutput>\n"
         "    <cfinclude template=\"#arguments.targetPage#\">\n"
         "    <cfoutput>;AFTER</cfoutput>\n"
         "  </cffunction>\n"
         "  <cffunction name=\"onRequestEnd\">\n"
         "    <cfoutput>;END:#request.rhs#</cfoutput>\n"
         "  </cffunction>\n"
         "</cfcomponent>"},
        {"page.cfm", "<cfoutput>PAGE:#application.started#:#session.ss#:#request.rhs#</cfoutput>"},
    });
    worker w;
    string page = (root + "/page.cfm").c_str();
    string out = runWorkerRequestWithContext(w, page, root.c_str());
    size_t pB = out.indexOf("BEFORE;");
    size_t pP = out.indexOf("PAGE:AS:SS:RS");
    size_t pA = out.indexOf(";AFTER");
    size_t pE = out.indexOf(";END:RS");
    EXPECT_EQ(pB != SIZE_MAX && pP != SIZE_MAX && pA != SIZE_MAX && pE != SIZE_MAX, true) << out.constData();
    EXPECT_EQ(pB < pP && pP < pA && pA < pE, true) << out.constData();
}

