// ---- APPLICATION / SESSION scopes (SQLite-backed) ----

class ScopeStoreTest : public testing::Test {
protected:
    void SetUp() override {
        char db[] = "/tmp/webstrada_scopestore_XXXXXX";
        int fd = mkstemp(db);
        EXPECT_NE(fd, -1);
        close(fd);
        unlink(db); // sqlite3_open re-creates it
        m_dbPath = db;
        EXPECT_EQ(m_store.open(m_dbPath), true) << m_store.lastError();
    }
    void TearDown() override {
        m_store.close();
        unlink(m_dbPath.c_str());
        unlink((m_dbPath + "-wal").c_str());
        unlink((m_dbPath + "-shm").c_str());
    }

    ScopeStore m_store;
    std::string m_dbPath;
};

TEST_F(ScopeStoreTest, MissingRowsAreMisses) {
    std::string data;
    EXPECT_EQ(m_store.loadApplication("app", 1000000, data), false);
    EXPECT_EQ(m_store.loadSession("app", "1:t", 1000000, data), false);
}

TEST_F(ScopeStoreTest, StoreAndLoadRoundTrip) {
    std::string data;
    int64_t now = 1000000;
    m_store.storeApplication("app", "{\"a\":1}", now + 1000, now);
    EXPECT_EQ(m_store.loadApplication("app", now + 500, data), true);
    EXPECT_EQ(data, "{\"a\":1}");

    int64_t start = 0;
    m_store.storeSession("app", "1:t", "{\"c\":3}", now + 1000, now, now);
    EXPECT_EQ(m_store.loadSession("app", "1:t", now + 500, data, &start), true);
    EXPECT_EQ(data, "{\"c\":3}");
    EXPECT_EQ(start, now);

    // A second save keeps the original creation time (startTime=0 means keep).
    m_store.storeSession("app", "1:t", "{\"c\":9}", now + 2000, now + 100);
    EXPECT_EQ(m_store.loadSession("app", "1:t", now + 500, data, &start), true);
    EXPECT_EQ(data, "{\"c\":9}");
    EXPECT_EQ(start, now);
}

TEST_F(ScopeStoreTest, ExpiredRowsAreMissesAndPurged) {
    std::string data;
    int64_t now = 1000000;
    m_store.storeApplication("app", "{\"b\":2}", now + 100, now);
    // Within the window: hit.
    EXPECT_EQ(m_store.loadApplication("app", now + 50, data), true);
    // Past the expiry: miss, and the row is lazily deleted.
    EXPECT_EQ(m_store.loadApplication("app", now + 200, data), false);
    EXPECT_EQ(m_store.loadApplication("app", now + 300, data), false);

    m_store.storeApplication("never", "{\"x\":1}", 0, now); // expires_at 0 = never
    EXPECT_EQ(m_store.loadApplication("never", now + 100000, data), true);

    m_store.storeApplication("other", "{\"z\":9}", now + 50, now);
    EXPECT_EQ(m_store.purgeExpired(now + 60), true);
    EXPECT_EQ(m_store.loadApplication("other", now + 61, data), false);
}

TEST_F(ScopeStoreTest, RotateSessionRenamesRow) {
    std::string data;
    int64_t now = 1000000;
    m_store.storeSession("app", "1:t", "{\"c\":3}", now + 1000, now, now);
    EXPECT_EQ(m_store.rotateSession("app", "1:t", "2:u"), true);
    EXPECT_EQ(m_store.loadSession("app", "1:t", now + 500, data), false);
    EXPECT_EQ(m_store.loadSession("app", "2:u", now + 500, data), true);
}

TEST_F(ScopeStoreTest, RemoveApplicationRemovesSessions) {
    std::string data;
    int64_t now = 1000000;
    m_store.storeApplication("app", "{\"a\":1}", now + 1000, now);
    m_store.storeSession("app", "2:u", "{}", now + 1000, now);
    EXPECT_EQ(m_store.removeApplication("app"), true);
    EXPECT_EQ(m_store.loadApplication("app", now + 500, data), false);
    EXPECT_EQ(m_store.loadSession("app", "2:u", now + 500, data), false);
}

TEST_F(ScopeStoreTest, GlobalCfidCounter) {
    int64_t a = 0, b = 0;
    EXPECT_EQ(m_store.nextCfid(a), true);
    EXPECT_EQ(m_store.nextCfid(b), true);
    EXPECT_EQ(a + 1, b);
}

TEST_F(WorkerTest, ScopeApplicationPersistsAcrossRequests) {
    std::string db = makeTempScopeDb();
    webstrada::config::scopeDbPath = db;

    std::string root = makeAppCfmTree({
        {"index.cfm",
         "<cfapplication name=\"appx\"><cfif not StructKeyExists(application, \"c\")><cfset application.c = 0></cfif><cfset application.c = application.c + 1><cfoutput>#application.c#</cfoutput>"},
    });
    string page = (root + "/index.cfm").c_str();

    {
        worker w;
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("1"), true);
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("2"), true);
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("3"), true);
    }

    webstrada::config::scopeDbPath = "";
    removeScopeDb(db);
}

TEST_F(WorkerTest, ScopeApplicationDataPersistsAcrossWorkerInstances) {
    // The store lives in SQLite, so a brand-new worker (same db file) sees the
    // same application data — this is the cross-worker sharing property.
    std::string db = makeTempScopeDb();
    webstrada::config::scopeDbPath = db;

    std::string root = makeAppCfmTree({
        {"index.cfm",
         "<cfapplication name=\"appx\"><cfif not StructKeyExists(application, \"c\")><cfset application.c = 100></cfif><cfoutput>#application.c#</cfoutput>"},
    });
    string page = (root + "/index.cfm").c_str();

    {
        worker w1;
        EXPECT_EQ(runWorkerRequest(w1, page, root.c_str()).equals("100"), true);
    }
    {
        worker w2;
        EXPECT_EQ(runWorkerRequest(w2, page, root.c_str()).equals("100"), true);
    }

    webstrada::config::scopeDbPath = "";
    removeScopeDb(db);
}

TEST_F(WorkerTest, ScopeSessionPersistsWithCookies) {
    std::string db = makeTempScopeDb();
    webstrada::config::scopeDbPath = db;

    std::string root = makeAppCfmTree({
        {"index.cfm",
         "<cfapplication name=\"sessx\" sessionmanagement=\"true\"><cfif not StructKeyExists(session, \"c\")><cfset session.c = 0></cfif><cfset session.c = session.c + 1><cfoutput>#session.c#</cfoutput>"},
    });
    string page = (root + "/index.cfm").c_str();

    {
        worker w;
        // Request 1: no cookies -> a fresh session is minted with cookies.
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("1"), true);
        string cfid = cookieValue("CFID");
        string token = cookieValue("CFTOKEN");
        EXPECT_EQ(cfid.isEmpty(), false);
        EXPECT_EQ(token.isEmpty(), false);

        // Feeding the cookies back resumes the same session (no new cookies).
        w.cookie().set("CFID") = cfid;
        w.cookie().set("CFTOKEN") = token;
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("2"), true);
        EXPECT_EQ(cfml::response().cookies.size(), (size_t)0);
    }

    webstrada::config::scopeDbPath = "";
    removeScopeDb(db);
}

TEST_F(WorkerTest, ScopeSessionRotatePreservesData) {
    std::string db = makeTempScopeDb();
    webstrada::config::scopeDbPath = db;

    std::string root = makeAppCfmTree({
        {"index.cfm",
         "<cfapplication name=\"rot\" sessionmanagement=\"true\"><cfif not StructKeyExists(session, \"c\")><cfset session.c = 0></cfif><cfset session.c = session.c + 1><cfif StructKeyExists(url, \"rotate\")><cfset SessionRotate()></cfif><cfoutput>#session.c#</cfoutput>"},
    });
    string page = (root + "/index.cfm").c_str();

    {
        worker w;
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("1"), true);
        string cfid1 = cookieValue("CFID");
        string token1 = cookieValue("CFTOKEN");

        w.cookie().set("CFID") = cfid1;
        w.cookie().set("CFTOKEN") = token1;
        w.url().set("ROTATE") = "1";
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("2"), true);
        string cfid2 = cookieValue("CFID");
        string token2 = cookieValue("CFTOKEN");
        EXPECT_EQ(cfid1.equals(cfid2), false);      // new ids after rotate
        EXPECT_EQ(token1.equals(token2), false);

        // The rotated session is reachable with the new cookies.
        w.cookie().set("CFID") = cfid2;
        w.cookie().set("CFTOKEN") = token2;
        w.url().set("ROTATE") = "";
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("3"), true);
    }

    webstrada::config::scopeDbPath = "";
    removeScopeDb(db);
}

TEST_F(WorkerTest, CfLocationAddTokenAppendsFreshSessionTokens) {
    std::string db = makeTempScopeDb();
    webstrada::config::scopeDbPath = db;

    std::string root = makeAppCfmTree({
        {"redirect.cfm",
         "<cfapplication name=\"locx\" sessionmanagement=\"true\"><cflocation url=\"http://example.com/t\">"},
        {"redirectq.cfm",
         "<cfapplication name=\"locx\" sessionmanagement=\"true\"><cflocation url=\"http://example.com/t?x=1\">"},
        {"redirectnotok.cfm",
         "<cfapplication name=\"locx\" sessionmanagement=\"true\"><cflocation url=\"http://example.com/t\" addtoken=\"false\">"},
    });
    string page = (root + "/redirect.cfm").c_str();
    string pageQ = (root + "/redirectq.cfm").c_str();
    string pageNoTok = (root + "/redirectnotok.cfm").c_str();

    {
        worker w;
        // Fresh request, no cookies: a session is minted; addtoken (default
        // true) appends the CFID/CFTOKEN to the redirect URL.
        runWorkerRequestRedirect(w, page, root.c_str());
        auto &r = cfml::response();
        EXPECT_EQ(r.statusCode, 302);
        std::string loc;
        for (const auto &h : r.headers) {
            if (webstrada::string(h.first.c_str()).compareCaseInsensitive("location") == 0) loc = h.second;
        }
        webstrada::string cfid = cookieValue("CFID");
        EXPECT_EQ(cfid.isEmpty(), false);
        EXPECT_EQ(loc.find(std::string("?CFID=") + cfid.constData()) != std::string::npos, true);
        EXPECT_EQ(loc.find("&CFTOKEN=") != std::string::npos, true);

        // A URL that already has a query string gets '&' separators.
        runWorkerRequestRedirect(w, pageQ, root.c_str());
        std::string locQ;
        for (const auto &h : cfml::response().headers) {
            if (webstrada::string(h.first.c_str()).compareCaseInsensitive("location") == 0) locQ = h.second;
        }
        EXPECT_EQ(locQ.find("?x=1&CFID=") != std::string::npos, true);

        // addtoken="false" appends nothing.
        runWorkerRequestRedirect(w, pageNoTok, root.c_str());
        std::string locNo;
        for (const auto &h : cfml::response().headers) {
            if (webstrada::string(h.first.c_str()).compareCaseInsensitive("location") == 0) locNo = h.second;
        }
        EXPECT_EQ(locNo, "http://example.com/t");
    }

    webstrada::config::scopeDbPath = "";
    removeScopeDb(db);
}

TEST_F(WorkerTest, ScopeApplicationStopClearsAppAndSessions) {    std::string db = makeTempScopeDb();
    webstrada::config::scopeDbPath = db;

    std::string root = makeAppCfmTree({
        {"index.cfm",
         "<cfapplication name=\"stopapp\" sessionmanagement=\"true\"><cfset application.x = 1><cfset session.y = 2><cfoutput>#StructKeyExists(application, \"x\")#:#StructKeyExists(session, \"y\")#</cfoutput>"},
        {"stop.cfm",
         "<cfapplication name=\"stopapp\" sessionmanagement=\"true\"><cfset ApplicationStop()><cfoutput>stopped</cfoutput>"},
    });
    string page = (root + "/index.cfm").c_str();
    string stop = (root + "/stop.cfm").c_str();

    {
        worker w;
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("YES:YES"), true);
        string cfid = cookieValue("CFID");
        string token = cookieValue("CFTOKEN");

        // ApplicationStop deletes the application and all of its sessions.
        w.cookie().set("CFID") = cfid;
        w.cookie().set("CFTOKEN") = token;
        EXPECT_EQ(runWorkerRequest(w, stop, root.c_str()).equals("stopped"), true);
        std::string sessionKey = std::string(cfid.constData()) + ":" + token.constData();
        EXPECT_EQ(storeHasRow(w, "stopapp"), false);
        EXPECT_EQ(storeHasRow(w, "stopapp", sessionKey.c_str()), false);

        // A fresh request starts a brand-new application and session (new
        // cookies are minted because the old session row is gone).
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("YES:YES"), true);
        EXPECT_EQ(cfml::response().cookies.size(), (size_t)2);
    }

    webstrada::config::scopeDbPath = "";
    removeScopeDb(db);
}

TEST_F(WorkerTest, ScopeUrlSessionFormatAppendsNewIds) {
    std::string db = makeTempScopeDb();
    webstrada::config::scopeDbPath = db;

    std::string root = makeAppCfmTree({
        {"index.cfm",
         "<cfapplication name=\"usf\" sessionmanagement=\"true\"><cfoutput>#urlSessionFormat(\"page.cfm\")#|#urlSessionFormat(\"page.cfm?a=1\")#</cfoutput>"},
    });
    string page = (root + "/index.cfm").c_str();

    {
        worker w;
        // A fresh session was minted in this request -> ids appended.
        string out1 = runWorkerRequest(w, page, root.c_str());
        string cfid = cookieValue("CFID");
        string token = cookieValue("CFTOKEN");
        string expectA = string("page.cfm?CFID=") + cfid + "&CFTOKEN=" + token;
        string expectB = string("page.cfm?a=1&CFID=") + cfid + "&CFTOKEN=" + token;
        EXPECT_EQ(out1.equals(expectA + "|" + expectB), true);

        // A request that arrived with a valid session appends nothing.
        w.cookie().set("CFID") = cfid;
        w.cookie().set("CFTOKEN") = token;
        EXPECT_EQ(runWorkerRequest(w, page, root.c_str()).equals("page.cfm|page.cfm?a=1"), true);
    }

    webstrada::config::scopeDbPath = "";
    removeScopeDb(db);
}

TEST_F(WorkerTest, ScopeDisabledThrowsLikeCF) {
    // Without <cfapplication>, application/session scopes stay disabled and a
    // member access throws "Variable ... is undefined." (CF: "Element X is
    // undefined in SESSION/APPLICATION." — message text is a known divergence).
    std::string db = makeTempScopeDb();
    webstrada::config::scopeDbPath = db;

    std::string root = makeAppCfmTree({
        {"index.cfm", "<cfoutput>#session.x#</cfoutput>"},
    });
    string page = (root + "/index.cfm").c_str();

    {
        worker w;
        bool caught = false;
        try {
            runWorkerRequest(w, page, root.c_str());
        } catch (const webstrada::exception &) {
            caught = true;
        }
        EXPECT_EQ(caught, true);
    }

    webstrada::config::scopeDbPath = "";
    removeScopeDb(db);
}

TEST_F(WorkerTest, CfQueryRunsThroughWorker) {
    // The daemon path (worker::run_template) shares the compiled-template
    // machinery with the CLI; verify cfquery executes there too.
    char dsnDir[] = "/tmp/webstrada_query_worker_XXXXXX";
    char *d = mkdtemp(dsnDir);
    ASSERT_NE(d, nullptr);
    std::string savedDsn = webstrada::config::dsnDbDir;
    webstrada::config::dsnDbDir = d;

    std::string root = makeAppCfmTree({
        {"q.cfm", "<cfquery name=\"q\" datasource=\"test\">SELECT 7 AS seven</cfquery>"
                  "<cfoutput>#q.seven#</cfoutput>"},
    });
    {
        worker w;
        string page = (root + "/q.cfm").c_str();
        string out = runWorkerTemplate(w, page, root.c_str());
        EXPECT_EQ(out.equals("7"), true);
    }
    webstrada::config::dsnDbDir = savedDsn;
    unlink((std::string(d) + "/DNS_test.sqlite").c_str());
    unlink((std::string(d) + "/DNS_test.sqlite-wal").c_str());
    unlink((std::string(d) + "/DNS_test.sqlite-shm").c_str());
    rmdir(d);
}

