TEST_F(JitExpressionTest, DateTimeFunctions) {
    webstrada::string out;
    cfvariant result = cfml::cfevaluate(out, "CreateDateTime(2026, 5, 31, 14, 30, 45)", nullptr);
    EXPECT_EQ(result.m_type, cfvariant::DateTime);
    EXPECT_EQ(result.toString().equals("{ts '2026-05-31 14:30:45'}"), true);

    out.clear();
    result = cfml::cfevaluate(out, "CreateDate(2026, 5, 31)", nullptr);
    EXPECT_EQ(result.m_type, cfvariant::DateTime);
    EXPECT_EQ(result.toString().equals("{ts '2026-05-31 00:00:00'}"), true);

    out.clear();
    result = cfml::cfevaluate(out, "CreateTime(14, 30, 45)", nullptr);
    EXPECT_EQ(result.m_type, cfvariant::DateTime);
    EXPECT_EQ(result.toString().equals("{ts '1899-12-30 14:30:45'}"), true);

    out.clear();
    result = cfml::cfevaluate(out, "DateFormat(CreateDate(2026, 5, 31), 'yyyy-mm-dd')", nullptr);
    EXPECT_EQ(result.toString().equals("2026-05-31"), true);

    out.clear();
    result = cfml::cfevaluate(out, "TimeFormat(CreateTime(14, 30, 45), 'HH:mm:ss')", nullptr);
    EXPECT_EQ(result.toString().equals("14:30:45"), true);

    out.clear();
    result = cfml::cfevaluate(out, "DateTimeFormat(CreateDateTime(2026, 5, 31, 14, 30, 45), 'yyyy-mm-dd HH:nn:ss')", nullptr);
    EXPECT_EQ(result.toString().equals("2026-05-31 14:30:45"), true);

    out.clear();
    result = cfml::cfevaluate(out, "IsDate(CreateDate(2026, 5, 31))", nullptr);
    EXPECT_EQ(result.m_bool, true);

    out.clear();
    result = cfml::cfevaluate(out, "IsDate('2026-05-31 14:30:45')", nullptr);
    EXPECT_EQ(result.m_bool, true);

    out.clear();
    result = cfml::cfevaluate(out, "IsDate('hello')", nullptr);
    EXPECT_EQ(result.m_bool, false);

    out.clear();
    result = cfml::cfevaluate(out, "Year(CreateDate(2026, 5, 31))", nullptr);
    EXPECT_EQ(result.m_int, 2026);

    out.clear();
    result = cfml::cfevaluate(out, "Month(CreateDate(2026, 5, 31))", nullptr);
    EXPECT_EQ(result.m_int, 5);

    out.clear();
    result = cfml::cfevaluate(out, "Day(CreateDate(2026, 5, 31))", nullptr);
    EXPECT_EQ(result.m_int, 31);
}

TEST_F(JitExpressionTest, DisplayFormatFunctions) {
    webstrada::string out;
    cfvariant result = cfml::cfevaluate(out, "DecimalFormat(123456.789)", nullptr);
    EXPECT_EQ(result.toString().equals("123,456.79"), true);

    out.clear();
    result = cfml::cfevaluate(out, "DecimalFormat(-1234.5)", nullptr);
    EXPECT_EQ(result.toString().equals("-1,234.50"), true);

    out.clear();
    result = cfml::cfevaluate(out, "DollarFormat(123456.789)", nullptr);
    EXPECT_EQ(result.toString().equals("$123,456.79"), true);

    out.clear();
    result = cfml::cfevaluate(out, "DollarFormat(-1234.5)", nullptr);
    EXPECT_EQ(result.toString().equals("($1,234.50)"), true);

    out.clear();
    result = cfml::cfevaluate(out, "YesNoFormat(true)", nullptr);
    EXPECT_EQ(result.toString().equals("Yes"), true);

    out.clear();
    result = cfml::cfevaluate(out, "YesNoFormat(0)", nullptr);
    EXPECT_EQ(result.toString().equals("No"), true);

    out.clear();
    result = cfml::cfevaluate(out, "YesNoFormat('yes')", nullptr);
    EXPECT_EQ(result.toString().equals("Yes"), true);

    out.clear();
    result = cfml::cfevaluate(out, "ParagraphFormat('Hello')", nullptr);
    EXPECT_EQ(result.toString().equals("Hello <P>"), true);
}

TEST_F(JitExpressionTest, ArrayMapNamedCallback) {
    // ArrayMap with a named builtin callback ("Abs"), the non-closure form
    // used by tests/cfm/array2.cfm for the WebStrada engine.
    string cfml =
        "<cfset arr = ArrayNew(1)>"
        "<cfset ArrayAppend(arr, -10.5)>"
        "<cfset ArrayAppend(arr, 20.7)>"
        "<cfset ArrayAppend(arr, -30.0)>"
        "<cfset mapped = ArrayMap(arr, \"Abs\")>"
        "<cfoutput>#ArrayToList(mapped)#</cfoutput>";
    string out = runJitTemplate(cfml, variables);
    EXPECT_EQ(out.equals("10.5,20.7,30"), true);

    // The source array is not mutated by ArrayMap.
    EXPECT_EQ(variables["arr"].m_array->size(), (size_t)3);
    EXPECT_EQ(variables["arr"].m_array->at(0).m_type, cfvariant::Float);
    EXPECT_EQ(variables["mapped"].m_array->size(), (size_t)3);

    // Empty array maps to an empty array without calling the callback.
    string cfml2 =
        "<cfset e = ArrayNew(1)>"
        "<cfset me = ArrayMap(e, \"Abs\")>"
        "<cfoutput>#ArrayLen(me)#</cfoutput>";
    out = runJitTemplate(cfml2, variables);
    EXPECT_EQ(out.equals("0"), true);

    // A non-array first argument must throw.
    string cfml3 = "<cfset x = 5><cfset r = ArrayMap(x, \"Abs\")>";
    bool threw = false;
    try {
        runJitTemplate(cfml3, variables);
    } catch (...) {
        threw = true;
    }
    EXPECT_EQ(threw, true);

    // A missing/empty callback name must throw (only when actually invoked, so
    // the source array must be non-empty).
    string cfml4 = "<cfset arr = ArrayNew(1)><cfset ArrayAppend(arr, 1)><cfset r = ArrayMap(arr, \"\")>";
    threw = false;
    try {
        runJitTemplate(cfml4, variables);
    } catch (...) {
        threw = true;
    }
    EXPECT_EQ(threw, true);
}

TEST_F(JitExpressionTest, XmlFunctions) {
    webstrada::string out;
    cfvariant result;

    // Test IsXml with strings and parses
    result = cfml::cfevaluate(out, "IsXml('<root><child id=\"1\">text</child></root>')", nullptr);
    EXPECT_EQ(result.m_bool, true);

    result = cfml::cfevaluate(out, "IsXml('not xml')", nullptr);
    EXPECT_EQ(result.m_bool, false);

    // Test XmlParse
    cfvariant xmlObj = cfml::cfevaluate(out, "XmlParse('<root><child id=\"1\">text</child></root>')", nullptr);
    EXPECT_EQ(xmlObj.m_type, cfvariant::Xml);
    
    // Check elements
    variables.set("myXml") = xmlObj;
    result = cfml::cfevaluate(out, "IsXmlDoc(myXml)", &variables);
    EXPECT_EQ(result.m_bool, true);

    result = cfml::cfevaluate(out, "IsXmlRoot(myXml.XmlRoot)", &variables);
    EXPECT_EQ(result.m_bool, true);

    // Check DOM property access
    result = cfml::cfevaluate(out, "myXml.XmlRoot.XmlName", &variables);
    EXPECT_EQ(result.toString().equals("root"), true);

    // Test XmlFormat
    result = cfml::cfevaluate(out, "XmlFormat('<hello & world>')", nullptr);
    EXPECT_EQ(result.toString().equals("&lt;hello &amp; world&gt;"), true);

    // Test XmlNew
    result = cfml::cfevaluate(out, "XmlNew()", nullptr);
    EXPECT_EQ(result.m_type, cfvariant::Xml);

    // Test XmlElemNew
    variables.set("newDoc") = result;
    result = cfml::cfevaluate(out, "XmlElemNew(newDoc, 'myNewElement')", &variables);
    EXPECT_EQ(result.m_type, cfvariant::Xml);
    EXPECT_EQ(result.m_struct->at("XMLNAME").toString().equals("myNewElement"), true);

    // Test XmlGetNodeType (CF reports DOM node-type names)
    variables.set("newElem") = result;
    result = cfml::cfevaluate(out, "XmlGetNodeType(newElem)", &variables);
    EXPECT_EQ(result.toString().equals("ELEMENT_NODE"), true);

    result = cfml::cfevaluate(out, "XmlGetNodeType(newDoc)", &variables);
    EXPECT_EQ(result.toString().equals("DOCUMENT_NODE"), true);

    // Test XmlSearch
    result = cfml::cfevaluate(out, "XmlSearch(myXml, '/root/child')", &variables);
    EXPECT_EQ(result.m_type, cfvariant::Array);
    EXPECT_EQ(result.m_array->size() >= 1, true);

    // Test SerializeXML and DeserializeXML
    result = cfml::cfevaluate(out, "SerializeXML(myXml)", &variables);
    EXPECT_EQ(result.m_type, cfvariant::String);
    EXPECT_EQ(result.toString().contains("<root>"), true);

    variables.set("xmlStr") = result;
    cfvariant deserialized = cfml::cfevaluate(out, "DeserializeXML(xmlStr)", &variables);
    EXPECT_EQ(deserialized.m_type, cfvariant::Xml);

    // Test XmlTransform
    std::string xsl = "<?xml version=\"1.0\"?>\n"
                      "<xsl:stylesheet version=\"1.0\" xmlns:xsl=\"http://www.w3.org/1999/XSL/Transform\">\n"
                      "  <xsl:template match=\"/\">\n"
                      "    <html><body><h2>My Title</h2></body></html>\n"
                      "  </xsl:template>\n"
                      "</xsl:stylesheet>";
    variables.set("xslCode") = cfvariant(xsl.c_str());
    result = cfml::cfevaluate(out, "XmlTransform(myXml, xslCode)", &variables);
    EXPECT_EQ(result.toString().contains("My Title"), true);

    // Test XmlValidate: without a schema CF 2021 reports status NO (not
    // validated), so the engine returns false instead of true.
    result = cfml::cfevaluate(out, "XmlValidate(myXml)", &variables);
    EXPECT_EQ(result.m_type, cfvariant::Struct);
    EXPECT_EQ(result.m_struct->at("STATUS").m_bool, false);
}

TEST_F(JitExpressionTest, JsonSerializeJSON) {
    // 1. String serialization
    runJitTemplate("<cfset x = SerializeJSON(\"hello\")>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::String, true);
    EXPECT_EQ(variables["x"].toString().equals("\"hello\""), true);

    // 2. Number serialization
    runJitTemplate("<cfset x = SerializeJSON(42)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("42"), true);

    runJitTemplate("<cfset x = SerializeJSON(-7)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("-7"), true);

    // 3. Boolean serialization
    runJitTemplate("<cfset x = SerializeJSON(true)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("true"), true);

    runJitTemplate("<cfset x = SerializeJSON(false)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("false"), true);

    // 4. Array serialization
    runJitTemplate("<cfset a = ArrayNew(1)><cfset ArrayAppend(a, 1)><cfset ArrayAppend(a, \"two\")><cfset ArrayAppend(a, true)><cfset x = SerializeJSON(a)>",
                   variables);
    EXPECT_EQ(variables["x"].toString().contains("1"), true);
    EXPECT_EQ(variables["x"].toString().contains("\"two\""), true);
    EXPECT_EQ(variables["x"].toString().contains("true"), true);

    // 5. Struct serialization (keys keep the casing they were inserted with)
    runJitTemplate("<cfset s = StructNew()><cfset StructInsert(s, \"name\", \"test\")><cfset StructInsert(s, \"value\", 42)><cfset x = SerializeJSON(s)>",
                   variables);
    EXPECT_EQ(variables["x"].toString().contains("\"name\""), true);
    EXPECT_EQ(variables["x"].toString().contains("\"test\""), true);
    EXPECT_EQ(variables["x"].toString().contains("\"value\""), true);
    EXPECT_EQ(variables["x"].toString().contains("42"), true);

    // 6. Empty array
    runJitTemplate("<cfset a = ArrayNew(1)><cfset x = SerializeJSON(a)>", variables);
    EXPECT_EQ(variables["x"].toString().equals("[]"), true);
}

TEST_F(JitExpressionTest, JsonDeserializeJSON) {
    // 1. Simple struct
    runJitTemplate("<cfset d = DeserializeJSON('{\"name\":\"test\",\"count\":42}')>", variables);
    EXPECT_EQ(variables["d"].m_type == cfvariant::Struct, true);
    EXPECT_EQ(variables["d"].m_struct->at("NAME").toString().equals("test"), true);
    EXPECT_EQ(variables["d"].m_struct->at("COUNT").m_int, 42);

    // 2. Array deserialization
    runJitTemplate("<cfset d = DeserializeJSON('[1,2,3]')>", variables);
    EXPECT_EQ(variables["d"].m_type == cfvariant::Array, true);
    EXPECT_EQ(variables["d"].m_array->size(), (size_t)3);
    EXPECT_EQ(variables["d"].m_array->at(0).m_int, 1);
    EXPECT_EQ(variables["d"].m_array->at(1).m_int, 2);
    EXPECT_EQ(variables["d"].m_array->at(2).m_int, 3);

    // 3. Nested struct/array
    runJitTemplate("<cfset d = DeserializeJSON('{\"items\":[{\"id\":1},{\"id\":2}]}')>", variables);
    EXPECT_EQ(variables["d"].m_type == cfvariant::Struct, true);
    auto &items = variables["d"].m_struct->at("ITEMS");
    EXPECT_EQ(items.m_type == cfvariant::Array, true);
    EXPECT_EQ(items.m_array->size(), (size_t)2);
    EXPECT_EQ(items.m_array->at(0).m_struct->at("ID").m_int, 1);
    EXPECT_EQ(items.m_array->at(1).m_struct->at("ID").m_int, 2);

    // 4. String deserialization
    runJitTemplate("<cfset d = DeserializeJSON('\"hello\"')>", variables);
    EXPECT_EQ(variables["d"].m_type == cfvariant::String, true);
    EXPECT_EQ(variables["d"].toString().equals("hello"), true);

    // 5. Number deserialization
    runJitTemplate("<cfset d = DeserializeJSON('42')>", variables);
    EXPECT_EQ(variables["d"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["d"].m_int, 42);

    // 6. Boolean deserialization
    runJitTemplate("<cfset d = DeserializeJSON('true')>", variables);
    EXPECT_EQ(variables["d"].m_type == cfvariant::Boolean, true);
    EXPECT_EQ(variables["d"].m_bool, true);

    // 7. Float deserialization
    runJitTemplate("<cfset d = DeserializeJSON('3.14')>", variables);
    EXPECT_EQ(variables["d"].m_type == cfvariant::Float, true);
    EXPECT_TRUE(variables["d"].m_double > 3.13 && variables["d"].m_double < 3.15);

    // 8. Invalid JSON throws
    bool caught = false;
    try {
        runJitTemplate("<cfset d = DeserializeJSON('{invalid}')>", variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

