TEST_F(JitExpressionTest, JsonSerializeDeserializeGeneric) {
    // Serialize generic with "json" type
    runJitTemplate("<cfset x = Serialize(\"hello\", \"json\")>", variables);
    EXPECT_EQ(variables["x"].toString().equals("\"hello\""), true);

    runJitTemplate("<cfset x = Serialize(42, \"json\")>", variables);
    EXPECT_EQ(variables["x"].toString().equals("42"), true);

    runJitTemplate("<cfset x = Serialize(true, \"json\")>", variables);
    EXPECT_EQ(variables["x"].toString().equals("true"), true);

    // Deserialize generic with "json" type
    runJitTemplate("<cfset d = Deserialize('\"world\"', \"json\")>", variables);
    EXPECT_EQ(variables["d"].toString().equals("world"), true);

    runJitTemplate("<cfset d = Deserialize('99', \"json\")>", variables);
    EXPECT_EQ(variables["d"].m_int, 99);

    runJitTemplate("<cfset d = Deserialize('[7,8,9]', \"json\")>", variables);
    EXPECT_EQ(variables["d"].m_type == cfvariant::Array, true);
    EXPECT_EQ(variables["d"].m_array->at(0).m_int, 7);
    EXPECT_EQ(variables["d"].m_array->at(1).m_int, 8);
    EXPECT_EQ(variables["d"].m_array->at(2).m_int, 9);

    // Unsupported type throws
    bool caught = false;
    try {
        runJitTemplate("<cfset x = Serialize(42, \"xml\")>", variables);
    } catch (webstrada::exception &e) {
        EXPECT_EQ(string(e.what()).contains("not yet supported"), true);
        caught = true;
    }
    EXPECT_EQ(caught, true);

    caught = false;
    try {
        runJitTemplate("<cfset x = Serialize(42, \"unknown\")>", variables);
    } catch (webstrada::exception &e) {
        EXPECT_EQ(string(e.what()).contains("Unsupported"), true);
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

