TEST_F(JitExpressionTest, ParseDateTimeIsoT) {
    // ParseDateTime accepts the ISO-8601 'T' separator (was BUGS.md: the time
    // part was silently dropped). Expected components come from the host tz.
    runJitTemplate("<cfset t1 = ParseDateTime(\"2020-05-15T10:30:00\")>"
                   "<cfset t2 = ParseDateTime(\"2020-05-15T10:30:00Z\")>"
                   "<cfset t3 = ParseDateTime(\"2020-05-15T10:30:00-05:00\")>"
                   "<cfset t4 = ParseDateTime(\"2020-05-15T00:30:00+05:00\")>"
                   "<cfset t5 = ParseDateTime(\"2020-05-15 10:30:00Z\")>", variables);
    // No offset: wall clock kept as-is.
    EXPECT_EQ(cfml::cf_hour(&variables["T1"])->m_int, 10);
    EXPECT_EQ(cfml::cf_minute(&variables["T1"])->m_int, 30);
    // Z: 10:30 UTC localized.
    {
        int ly, lmo, ld, lh, lmi, ls;
        localComponentsForUtc(2020, 5, 15, 10, 30, 0, &ly, &lmo, &ld, &lh, &lmi, &ls);
        EXPECT_EQ(cfml::cf_hour(&variables["T2"])->m_int, lh);
        EXPECT_EQ(cfml::cf_minute(&variables["T2"])->m_int, lmi);
    }
    // -05:00: 15:30 UTC localized.
    {
        int ly, lmo, ld, lh, lmi, ls;
        localComponentsForUtc(2020, 5, 15, 15, 30, 0, &ly, &lmo, &ld, &lh, &lmi, &ls);
        EXPECT_EQ(cfml::cf_hour(&variables["T3"])->m_int, lh);
        EXPECT_EQ(cfml::cf_minute(&variables["T3"])->m_int, lmi);
    }
    // +05:00 across midnight: 2020-05-14 19:30 UTC localized.
    {
        int ly, lmo, ld, lh, lmi, ls;
        localComponentsForUtc(2020, 5, 14, 19, 30, 0, &ly, &lmo, &ld, &lh, &lmi, &ls);
        EXPECT_EQ(cfml::cf_year(&variables["T4"])->m_int, ly);
        EXPECT_EQ(cfml::cf_month(&variables["T4"])->m_int, lmo);
        EXPECT_EQ(cfml::cf_day(&variables["T4"])->m_int, ld);
        EXPECT_EQ(cfml::cf_hour(&variables["T4"])->m_int, lh);
        EXPECT_EQ(cfml::cf_minute(&variables["T4"])->m_int, lmi);
    }
    // Space separator + Z also localizes.
    {
        int ly, lmo, ld, lh, lmi, ls;
        localComponentsForUtc(2020, 5, 15, 10, 30, 0, &ly, &lmo, &ld, &lh, &lmi, &ls);
        EXPECT_EQ(cfml::cf_hour(&variables["T5"])->m_int, lh);
        EXPECT_EQ(cfml::cf_minute(&variables["T5"])->m_int, lmi);
    }
    // IsDate agrees on ISO T datetimes (trailing-garbage inputs are a separate
    // documented divergence).
    runJitTemplate("<cfset id1 = IsDate(\"2020-05-15T10:30:00Z\")>"
                   "<cfset id2 = IsDate(\"2020-05-15T10:30:00\")>"
                   "<cfset id3 = IsDate(\"2020-05-15\")>"
                   "<cfset id4 = IsDate(\"2020-12-05\")>", variables);
    EXPECT_EQ(variables["ID1"].m_bool, true);
    EXPECT_EQ(variables["ID2"].m_bool, true);
    EXPECT_EQ(variables["ID3"].m_bool, true);
    EXPECT_EQ(variables["ID4"].m_bool, true);
}

TEST_F(JitExpressionTest, GetHttpTimeStringAppliesLocalOffset) {
    // CF interprets the CF date as server-local wall clock and renders GMT:
    // CreateDate(2026,6,1) on a UTC+2 host -> "Sun, 31 May 2026 22:00:00 GMT".
    // The expected string is derived from the test host's own timezone so the
    // assertion holds regardless of the machine it runs on.
    std::string expMidnight = gmtStringForLocal(2026, 6, 1, 0, 0, 0);
    runJitTemplate("<cfset hts = GetHttpTimeString(CreateDate(2026, 6, 1))>", variables);
    EXPECT_EQ(variables["HTS"].toString().equals(expMidnight.c_str()), true);

    std::string expNoon = gmtStringForLocal(2026, 6, 1, 12, 30, 45);
    runJitTemplate("<cfset hts2 = GetHttpTimeString(CreateDateTime(2026, 6, 1, 12, 30, 45))>", variables);
    EXPECT_EQ(variables["HTS2"].toString().equals(expNoon.c_str()), true);
}

TEST_F(JitExpressionTest, DateTimeOdbcDeprecated) {
    // CreateODBCDate and CreateODBCTime are implemented (Tier 1) and render
    // CF's ODBC {d 'yyyy-mm-dd'} / {t 'hh:nn:ss'} forms; CreateODBCDateTime is
    // a DateTime wrapping the input, rendering as {ts 'yyyy-mm-dd hh:nn:ss'}.
    runJitTemplate("<cfset odbc_d = CreateODBCDate(CreateDate(2026, 6, 1))>", variables);
    EXPECT_EQ(variables["ODBC_D"].m_type, cfvariant::DateTime);
    EXPECT_EQ(variables["ODBC_D"].toString().equals("{d '2026-06-01'}"), true);

    runJitTemplate("<cfset odbc_t = CreateODBCTime(CreateTime(6, 1, 0))>", variables);
    EXPECT_EQ(variables["ODBC_T"].m_type, cfvariant::DateTime);
    EXPECT_EQ(variables["ODBC_T"].toString().equals("{t '06:01:00'}"), true);

    runJitTemplate("<cfset odbc_dt = CreateODBCDateTime(CreateDate(2026, 6, 1))>"
                   "<cfset odbc_dt_str = CreateODBCDateTime(\"2026-06-01 14:30:45\")>"
                   "<cfset odbc_dt_same = CreateODBCDateTime(CreateDateTime(2026, 6, 1, 0, 0, 0))>"
                   "<cfset odbc_dt_eq = (CreateODBCDateTime(CreateDate(2026, 6, 1)) EQ CreateDate(2026, 6, 1))>"
                   "<cfset odbc_dt_year = Year(CreateODBCDateTime(\"2026-06-01 14:30:45\"))>"
                   "<cfset odbc_dt_isdate = IsDate(CreateODBCDateTime(\"2026-06-01 14:30:45\"))>",
                   variables);
    EXPECT_EQ(variables["ODBC_DT"].m_type, cfvariant::DateTime);
    EXPECT_EQ(variables["ODBC_DT"].toString().equals("{ts '2026-06-01 00:00:00'}"), true);
    EXPECT_EQ(variables["ODBC_DT_STR"].toString().equals("{ts '2026-06-01 14:30:45'}"), true);
    EXPECT_EQ(variables["ODBC_DT_SAME"].m_type, cfvariant::DateTime);
    EXPECT_EQ(variables["ODBC_DT_EQ"].m_type, cfvariant::Boolean);
    EXPECT_EQ(variables["ODBC_DT_EQ"].m_bool, true);
    EXPECT_EQ(variables["ODBC_DT_YEAR"].m_type, cfvariant::Number);
    EXPECT_EQ(variables["ODBC_DT_YEAR"].m_int, 2026);
    EXPECT_EQ(variables["ODBC_DT_ISDATE"].m_bool, true);
}

TEST_F(JitExpressionTest, CreateOdbcDateTimeInvalidMessage) {
    // CF's two invalid-date messages (was BUGS.md #34): a non-date string ->
    // "The value X cannot be converted to a date."; a date-shaped string with an
    // out-of-range component -> "X is an invalid date or time string."
    auto msg = [&](const char *arg) -> string {
        string code = "<cftry><cfset x = CreateODBCDateTime(\"";
        code += arg;
        code += "\")><cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>";
        return runJitTemplate(code, variables);
    };
    EXPECT_EQ(msg("bad-date").equals("The value bad-date cannot be converted to a date."), true);
    EXPECT_EQ(msg("2026.13.05 10:20").equals("2026.13.05 10:20 is an invalid date or time string."), true);
    EXPECT_EQ(msg("2026-13-05").equals("2026-13-05 is an invalid date or time string."), true);
    EXPECT_EQ(msg("2026.05.32").equals("2026.05.32 is an invalid date or time string."), true);
    EXPECT_EQ(msg("2026.05.21 25:00").equals("2026.05.21 25:00 is an invalid date or time string."), true);
}

TEST_F(JitExpressionTest, DateDotSeparatedFormats) {
    // Dot-separated dates like the CFKillBoard killmail date (2026.05.21 18:22).
    // CF accepts YYYY.MM.DD, MM.DD.YYYY and DD.MM.YYYY (MM.DD.YYYY preferred),
    // with HH:MM or HH:MM:SS times. Verified against CF 2025 on the RDS host.
    runJitTemplate("<cfset a = CreateODBCDateTime(\"2026.05.21 18:22\")>"
                   "<cfset b = CreateODBCDateTime(\"2026.05.21\")>"
                   "<cfset c = CreateODBCDateTime(\"21.05.2026 18:22\")>"
                   "<cfset d = CreateODBCDateTime(\"05.21.2026 18:22\")>"
                   "<cfset e = CreateODBCDateTime(\"05.06.2026 10:20\")>"
                   "<cfset f = CreateODBCDateTime(\"13.05.2026 10:20\")>"
                   "<cfset g = CreateODBCDateTime(\"2026.05.21 18:22:45\")>"
                   "<cfset h1 = IsDate(\"2026.05.21 18:22\")>"
                   "<cfset h2 = IsDate(\"13.13.2026 10:20\")>"
                   "<cfset h3 = IsDate(\"2026.13.05 10:20\")>",
                   variables);
    EXPECT_EQ(variables["A"].toString().equals("{ts '2026-05-21 18:22:00'}"), true);
    EXPECT_EQ(variables["B"].toString().equals("{ts '2026-05-21 00:00:00'}"), true);
    EXPECT_EQ(variables["C"].toString().equals("{ts '2026-05-21 18:22:00'}"), true);
    EXPECT_EQ(variables["D"].toString().equals("{ts '2026-05-21 18:22:00'}"), true);
    EXPECT_EQ(variables["E"].toString().equals("{ts '2026-05-06 10:20:00'}"), true);
    EXPECT_EQ(variables["F"].toString().equals("{ts '2026-05-13 10:20:00'}"), true);
    EXPECT_EQ(variables["G"].toString().equals("{ts '2026-05-21 18:22:45'}"), true);
    EXPECT_EQ(variables["H1"].m_bool, true);
    EXPECT_EQ(variables["H2"].m_bool, false);
    EXPECT_EQ(variables["H3"].m_bool, false);
}

TEST_F(JitExpressionTest, CfVariantTypeCheckers) {
    variables.set("null_var") = cfvariant(cfvariant::Null);
    runJitTemplate(
        "<cfset s = StructNew()>"
        "<cfset chk_struct_s = IsStruct(s)>"
        "<cfset chk_struct_num = IsStruct(42)>"
        "<cfset chk_bool_t = IsBoolean(true)>"
        "<cfset chk_bool_y = IsBoolean(\"yes\")>"
        "<cfset chk_bool_num = IsBoolean(1)>"
        "<cfset chk_bool_str = IsBoolean(\"hello\")>"
        "<cfset chk_num_42 = IsNumeric(42)>"
        "<cfset chk_num_float = IsNumeric(3.14)>"
        "<cfset chk_num_str = IsNumeric(\"12.34\")>"
        "<cfset chk_num_abc = IsNumeric(\"abc\")>"
        "<cfset chk_ls_is_num = LSIsNumeric(100)>"
        "<cfset chk_simple_42 = IsSimpleValue(42)>"
        "<cfset chk_simple_s = IsSimpleValue(s)>"
        "<cfset chk_obj_s = IsObject(s)>"
        "<cfset chk_obj_42 = IsObject(42)>"
        "<cfset chk_null_empty = IsNull(null_var)>"
        "<cfset chk_binary_str = IsBinary(\"bin\")>"
        "<cfset chk_closure_str = IsClosure(\"func\")>"
        "<cfset chk_cust_str = IsCustomFunction(\"func\")>"
        "<cfset chk_image_str = IsImage(\"img\")>"
        "<cfset chk_file_str = IsFileObject(\"file\")>"
        "<cfset chk_query_str = IsQuery(\"query\")>",
        variables
    );

    EXPECT_EQ(variables["CHK_STRUCT_S"].m_bool, true);
    EXPECT_EQ(variables["CHK_STRUCT_NUM"].m_bool, false);
    EXPECT_EQ(variables["CHK_BOOL_T"].m_bool, true);
    EXPECT_EQ(variables["CHK_BOOL_Y"].m_bool, true);
    EXPECT_EQ(variables["CHK_BOOL_NUM"].m_bool, true);
    EXPECT_EQ(variables["CHK_BOOL_STR"].m_bool, false);
    EXPECT_EQ(variables["CHK_NUM_42"].m_bool, true);
    EXPECT_EQ(variables["CHK_NUM_FLOAT"].m_bool, true);
    EXPECT_EQ(variables["CHK_NUM_STR"].m_bool, true);
    EXPECT_EQ(variables["CHK_NUM_ABC"].m_bool, false);
    EXPECT_EQ(variables["CHK_LS_IS_NUM"].m_bool, true);
    EXPECT_EQ(variables["CHK_SIMPLE_42"].m_bool, true);
    EXPECT_EQ(variables["CHK_SIMPLE_S"].m_bool, false);
    EXPECT_EQ(variables["CHK_OBJ_S"].m_bool, false);
    EXPECT_EQ(variables["CHK_OBJ_42"].m_bool, false);
    EXPECT_EQ(variables["CHK_NULL_EMPTY"].m_bool, true);
    EXPECT_EQ(variables["CHK_BINARY_STR"].m_bool, false);
    EXPECT_EQ(variables["CHK_CLOSURE_STR"].m_bool, false);
    EXPECT_EQ(variables["CHK_CUST_STR"].m_bool, false);
    EXPECT_EQ(variables["CHK_IMAGE_STR"].m_bool, false);
    EXPECT_EQ(variables["CHK_FILE_STR"].m_bool, false);
    EXPECT_EQ(variables["CHK_QUERY_STR"].m_bool, false);

    bool caught = false;
    try {
        runJitTemplate("<cfset file_eof = FileIsEOF(\"file\")>", variables);
    } catch (...) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

