TEST_F(JitExpressionTest, IsDefinedInsideUdf) {
    // Inside a UDF, IsDefined sees the function-local scope, the arguments
    // scope and the captured parent variables scope (verified against CF 2025).
    runJitTemplate(
        "<cfscript>"
        "x = 5;"
        "function probe(a) {"
        "  local.lv = 42;"
        "  var r = '';"
        "  r &= IsDefined('arguments.a');"
        "  r &= IsDefined('a');"
        "  r &= IsDefined('arguments.b');"
        "  r &= IsDefined('local.lv');"
        "  r &= IsDefined('local');"
        "  r &= IsDefined('lv');"
        "  r &= IsDefined('arguments');"
        "  r &= IsDefined('probe');"
        "  r &= IsDefined('x');"
        "  r &= IsDefined('local.nope');"
        "  return r;"
        "}"
        "chk_udf = probe('hello');"
        "</cfscript>",
        variables
    );
    EXPECT_EQ(variables["CHK_UDF"].m_str->equals("YESYESNOYESYESYESYESYESYESNO"), true);
}


TEST_F(JitExpressionTest, BinaryDecodeHex) {
    // Basic hex decode: 48656C6C6F -> "Hello"
    runJitTemplate("<cfset x = BinaryDecode(\"48656C6C6F\", \"hex\")>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Binary, true);
    ASSERT_TRUE(variables["x"].m_binary != nullptr);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)'H');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[1]), (unsigned char)'e');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[2]), (unsigned char)'l');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[3]), (unsigned char)'l');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[4]), (unsigned char)'o');

    // Lowercase hex digits and embedded whitespace/newlines are tolerated
    runJitTemplate("<cfset x = BinaryDecode(\"48 65\n6C 6C 6F\", \"hex\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)'H');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[4]), (unsigned char)'o');

    // Encoding argument is case-insensitive
    runJitTemplate("<cfset x = BinaryDecode(\"48656C6C6F\", \"HEX\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);

    // Empty hex string decodes to an empty binary object
    runJitTemplate("<cfset x = BinaryDecode(\"\", \"hex\")>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Binary, true);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)0);

    // Odd number of hex characters must throw
    bool caught = false;
    try {
        runJitTemplate("<cfset x = BinaryDecode(\"ABC\", \"hex\")>", variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);

    // Invalid hex character must throw
    caught = false;
    try {
        runJitTemplate("<cfset x = BinaryDecode(\"4G\", \"hex\")>", variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(JitExpressionTest, BinaryDecodeBase64) {
    // SGVsbG8= is base64 for "Hello"
    runJitTemplate("<cfset x = BinaryDecode(\"SGVsbG8=\", \"base64\")>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Binary, true);
    ASSERT_TRUE(variables["x"].m_binary != nullptr);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)'H');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[1]), (unsigned char)'e');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[2]), (unsigned char)'l');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[3]), (unsigned char)'l');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[4]), (unsigned char)'o');

    // Missing trailing padding is tolerated
    runJitTemplate("<cfset x = BinaryDecode(\"SGVsbG8\", \"base64\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);

    // Empty base64 string decodes to an empty binary object
    runJitTemplate("<cfset x = BinaryDecode(\"\", \"base64\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)0);

    // TWFu is base64 for "Man" (verifies a full 4-char group)
    runJitTemplate("<cfset x = BinaryDecode(\"TWFu\", \"base64\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)3);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)'M');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[1]), (unsigned char)'a');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[2]), (unsigned char)'n');

    // Invalid base64 characters must throw
    bool caught = false;
    try {
        runJitTemplate("<cfset x = BinaryDecode(\"!!!!\", \"base64\")>", variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);

    // A single leftover character is an invalid base64 length
    caught = false;
    try {
        runJitTemplate("<cfset x = BinaryDecode(\"S\", \"base64\")>", variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);

    // URL-safe characters are not valid in standard base64
    caught = false;
    try {
        runJitTemplate("<cfset x = BinaryDecode(\"SGVsbG8-\", \"base64\")>", variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(JitExpressionTest, BinaryDecodeBase64URL) {
    // SGVsbG8 is unpadded URL-safe base64 for "Hello" (same as standard here)
    runJitTemplate("<cfset x = BinaryDecode(\"SGVsbG8\", \"base64URL\")>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Binary, true);
    ASSERT_TRUE(variables["x"].m_binary != nullptr);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)'H');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[4]), (unsigned char)'o');

    // _ is the URL-safe replacement for / : byte 0xFE is /g== in base64,
    // _g== in base64URL
    runJitTemplate("<cfset x = BinaryDecode(\"_g==\", \"base64URL\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)1);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)0xFE);

    // Unpadded URL-safe input
    runJitTemplate("<cfset x = BinaryDecode(\"_g\", \"base64URL\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)1);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)0xFE);

    // - is the URL-safe replacement for + : byte 0xFB is /w== in base64,
    // -w== in base64URL
    runJitTemplate("<cfset x = BinaryDecode(\"-w\", \"base64URL\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)1);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)0xFB);

    // Standard base64 input is also accepted in base64URL mode
    runJitTemplate("<cfset x = BinaryDecode(\"SGVsbG8=\", \"base64URL\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);
}

TEST_F(JitExpressionTest, BinaryDecodeUU) {
    // uuencode of "Hello" (5 bytes) is "%2&5L;&\`" followed by a
    // zero-length (backtick) line. Test the single data line first.
    runJitTemplate("<cfset x = BinaryDecode(\"%2&5L;&\\`\", \"UU\")>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Binary, true);
    ASSERT_TRUE(variables["x"].m_binary != nullptr);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)'H');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[1]), (unsigned char)'e');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[2]), (unsigned char)'l');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[3]), (unsigned char)'l');
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[4]), (unsigned char)'o');

    // Full uuencode with data line, zero-length terminator line and "end"
    // marker, using Chr(10) for line breaks
    string cfml =
        "<cfset x = BinaryDecode(\"%2&5L;&\\`\" & Chr(10) & \"`\" & Chr(10) & \"end\" & Chr(10), \"UU\")>";
    runJitTemplate(cfml, variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);
    EXPECT_EQ(std::to_integer<unsigned char>((*variables["x"].m_binary)[0]), (unsigned char)'H');

    // "begin 644 file.txt" header lines are skipped
    cfml =
        "<cfset x = BinaryDecode(\"begin 644 hello.txt\" & Chr(10) & \"%2&5L;&\\`\" & Chr(10) & \"`\" & Chr(10), \"UU\")>";
    runJitTemplate(cfml, variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);

    // Encoding argument is case-insensitive
    runJitTemplate("<cfset x = BinaryDecode(\"%2&5L;&\\`\", \"uu\")>", variables);
    EXPECT_EQ(variables["x"].m_binary->size(), (size_t)5);
}

