TEST_F(JitExpressionTest, BinaryDecodeInterpreterPath) {
    // Verify the interpreter (evaluateExpr) dispatch as well
    webstrada::string out;
    cfvariant result = cfml::cfevaluate(out, "BinaryDecode(\"48656C6C6F\", \"hex\")", nullptr);
    EXPECT_EQ(result.m_type == cfvariant::Binary, true);
    ASSERT_TRUE(result.m_binary != nullptr);
    EXPECT_EQ(result.m_binary->size(), (size_t)5);
    EXPECT_EQ(std::to_integer<unsigned char>((*result.m_binary)[0]), (unsigned char)'H');

    out.clear();
    result = cfml::cfevaluate(out, "BinaryDecode(\"SGVsbG8=\", \"base64\")", nullptr);
    EXPECT_EQ(result.m_binary->size(), (size_t)5);
    EXPECT_EQ(std::to_integer<unsigned char>((*result.m_binary)[4]), (unsigned char)'o');

    // Interpreter path must reject wrong argument count
    bool caught = false;
    try {
        cfml::cfevaluate(out, "BinaryDecode(\"48656C6C6F\")", nullptr);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(JitExpressionTest, ChainedMemberAccessInterpreterPath) {
    // evaluateExpr must preserve trailing '.key' / '[idx]' segments after
    // array-index access (was BUGS.md #1, fixed): D.ITEMS[1].ID evaluates fully.
    cfvariant d(cfvariant::Struct);

    cfvariant item1(cfvariant::Struct);
    item1.m_struct->insert_or_assign("ID", cfvariant(1));
    cfvariant tags(cfvariant::Array);
    tags.insert(cfvariant("a"));
    tags.insert(cfvariant("b"));
    item1.m_struct->insert_or_assign("TAGS", tags);

    cfvariant item2(cfvariant::Struct);
    item2.m_struct->insert_or_assign("ID", cfvariant(2));

    cfvariant items(cfvariant::Array);
    items.insert(item1);
    items.insert(item2);
    d.m_struct->insert_or_assign("ITEMS", items);

    variables.set("D");
    variables["D"] = d;

    webstrada::string out;

    // Chained dot access after array index: d.ITEMS[1].ID
    cfvariant result = cfml::cfevaluate(out, "D.ITEMS[1].ID", &variables);
    EXPECT_EQ(result.m_type == cfvariant::Number, true);
    EXPECT_EQ(result.m_int, 1);

    out.clear();
    result = cfml::cfevaluate(out, "D.ITEMS[2].ID", &variables);
    EXPECT_EQ(result.m_int, 2);

    // Struct key access via brackets, then further chain
    out.clear();
    result = cfml::cfevaluate(out, "D[\"ITEMS\"][1].ID", &variables);
    EXPECT_EQ(result.m_int, 1);

    // Struct member holding an array, then index
    out.clear();
    result = cfml::cfevaluate(out, "D.ITEMS[1].TAGS[2]", &variables);
    EXPECT_EQ(result.m_type == cfvariant::String, true);
    EXPECT_EQ(result.toString().equals("b"), true);

    // Array of arrays
    cfvariant outer(cfvariant::Array);
    cfvariant inner(cfvariant::Array);
    inner.insert(cfvariant("deep"));
    outer.insert(inner);
    variables.set("OUTER");
    variables["OUTER"] = outer;

    out.clear();
    result = cfml::cfevaluate(out, "OUTER[1][1]", &variables);
    EXPECT_EQ(result.toString().equals("deep"), true);

    // Function-call result followed by member access
    out.clear();
    result = cfml::cfevaluate(out, "DeserializeJSON('{\"a\":{\"b\":42}}').a.b", nullptr);
    EXPECT_EQ(result.m_type == cfvariant::Number, true);
    EXPECT_EQ(result.m_int, 42);

    // Function-call result with array chain
    out.clear();
    result = cfml::cfevaluate(out, "DeserializeJSON('{\"arr\":[{\"x\":[10,20]}]}').arr[1].x[2]", nullptr);
    EXPECT_EQ(result.m_int, 20);

    // Array index out of bounds must throw
    bool caught = false;
    try {
        cfml::cfevaluate(out, "D.ITEMS[9].ID", &variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);

    // Undefined struct member must throw
    caught = false;
    try {
        cfml::cfevaluate(out, "D.ITEMS[1].NOPE", &variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);

    // Member access on a non-struct value must throw
    caught = false;
    try {
        cfml::cfevaluate(out, "D.ITEMS[1].ID.NOPE", &variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

// ==========================================
// FileUpload / FileUploadAll tests
// ==========================================

static void registerUpload(const char *field, const char *filename, const char *content, const char *contentType) {
    std::vector<webstrada::UploadedFile> files;
    webstrada::UploadedFile f;
    f.fieldName = field;
    f.filename = filename;
    if (content) {
        for (const char *p = content; *p; p++) {
            f.content.push_back(std::byte(*p));
        }
    }
    f.contentType = contentType ? contentType : "";
    files.push_back(std::move(f));
    webstrada::UploadRegistry::instance().setFiles(std::move(files));
}

static void clearUploads() {
    webstrada::UploadRegistry::instance().setFiles({});
}

TEST_F(JitExpressionTest, FileUploadBasic) {
    registerUpload("file1", "photo.png", "PNGDATA", "image/png");
    std::filesystem::path base = std::filesystem::temp_directory_path() / "webstrada_upload_test1";
    std::filesystem::remove_all(base);
    std::filesystem::create_directories(base);

    string cfml =
        "<cfset dest = GetTempDirectory() & \"webstrada_upload_test1\">"
        "<cfset up = FileUpload(dest, \"file1\")>";
    runJitTemplate(cfml, variables);

    ASSERT_EQ(variables["up"].m_type, cfvariant::Struct);
    EXPECT_EQ(variables["up"]["SERVERFILE"] == "photo.png", true);
    EXPECT_EQ(variables["up"]["CLIENTFILE"] == "photo.png", true);
    EXPECT_EQ(variables["up"]["CLIENTFILENAME"] == "photo", true);
    EXPECT_EQ(variables["up"]["CLIENTFILEEXT"] == "png", true);
    EXPECT_EQ(variables["up"]["CONTENTTYPE"] == "image", true);
    EXPECT_EQ(variables["up"]["CONTENTSUBTYPE"] == "png", true);
    EXPECT_EQ(variables["up"]["FILESIZE"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["up"]["FILESIZE"].m_int, 7);
    EXPECT_EQ(variables["up"]["FILEWASSAVED"].m_bool, true);
    EXPECT_EQ(variables["up"]["FILEEXISTED"].m_bool, false);
    EXPECT_EQ(variables["up"]["FILEWASAPPENDED"].m_bool, false);
    EXPECT_EQ(variables["up"]["FILEWASOVERWRITTEN"].m_bool, false);
    EXPECT_EQ(variables["up"]["FILEWASRENAMED"].m_bool, false);
    EXPECT_EQ(variables["up"]["ATTEMPTEDSERVERFILE"] == "photo.png", true);
    EXPECT_EQ(variables["up"]["TIMECREATED"].m_type == cfvariant::DateTime, true);
    EXPECT_EQ(variables["up"]["SERVERDIRECTORY"] == base.string().c_str(), true);

    // The uploaded content must be written to disk at dest/serverfile.
    std::string writtenPath = base.string() + "/photo.png";
    EXPECT_EQ(std::filesystem::exists(writtenPath), true);
    std::ifstream ifs(writtenPath, std::ios::binary);
    std::stringstream ss;
    ss << ifs.rdbuf();
    EXPECT_EQ(ss.str(), "PNGDATA");

    std::filesystem::remove_all(base);
    clearUploads();
}

TEST_F(JitExpressionTest, FileUploadCaseInsensitiveFieldAndRelativeDest) {
    // Field name lookup is case-insensitive; destination is relative to GetTempDirectory().
    registerUpload("file1", "data.txt", "hello", "text/plain");
    std::filesystem::path base = std::filesystem::temp_directory_path() / "webstrada_upload_test2";
    std::filesystem::remove_all(base);
    std::filesystem::create_directories(base);

    string cfml =
        "<cfset up = FileUpload(\"webstrada_upload_test2\", \"FILE1\")>";
    runJitTemplate(cfml, variables);

    EXPECT_EQ(variables["up"]["SERVERFILE"] == "data.txt", true);
    EXPECT_EQ(std::filesystem::exists(base.string() + "/data.txt"), true);

    std::filesystem::remove_all(base);
    clearUploads();
}

TEST_F(JitExpressionTest, FileUploadOnConflictModes) {
    registerUpload("file1", "photo.png", "PNGDATA", "image/png");
    std::filesystem::path base = std::filesystem::temp_directory_path() / "webstrada_upload_test3";
    std::filesystem::remove_all(base);
    std::filesystem::create_directories(base);

    // First upload succeeds.
    runJitTemplate("<cfset up = FileUpload(\"webstrada_upload_test3\", \"file1\")>", variables);
    EXPECT_EQ(variables["up"]["FILEEXISTED"].m_bool, false);

    // Default onConflict="error" must throw when the file already exists.
    bool caught = false;
    try {
        runJitTemplate("<cfset up = FileUpload(\"webstrada_upload_test3\", \"file1\")>", variables);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);

    // onConflict="skip": nothing is written, FILEWASSAVED is false.
    runJitTemplate("<cfset up = FileUpload(\"webstrada_upload_test3\", \"file1\", \"\", \"skip\")>", variables);
    EXPECT_EQ(variables["up"]["FILEWASSAVED"].m_bool, false);
    EXPECT_EQ(variables["up"]["FILEEXISTED"].m_bool, true);
    EXPECT_EQ(variables["up"]["SERVERFILE"] == "photo.png", true);

    // onConflict="overwrite": file is replaced.
    runJitTemplate("<cfset up = FileUpload(\"webstrada_upload_test3\", \"file1\", \"\", \"overwrite\")>", variables);
    EXPECT_EQ(variables["up"]["FILEWASOVERWRITTEN"].m_bool, true);
    EXPECT_EQ(variables["up"]["FILEWASSAVED"].m_bool, true);
    EXPECT_EQ(variables["up"]["FILEEXISTED"].m_bool, true);
    EXPECT_EQ(variables["up"]["SERVERFILE"] == "photo.png", true);

    // onConflict="makeunique": saved as photo1.png, FILEWASRENAMED is true.
    runJitTemplate("<cfset up = FileUpload(\"webstrada_upload_test3\", \"file1\", \"\", \"makeunique\")>", variables);
    EXPECT_EQ(variables["up"]["SERVERFILE"] == "photo1.png", true);
    EXPECT_EQ(variables["up"]["FILEWASRENAMED"].m_bool, true);
    EXPECT_EQ(variables["up"]["FILEWASSAVED"].m_bool, true);
    EXPECT_EQ(std::filesystem::exists(base.string() + "/photo1.png"), true);
    EXPECT_EQ(std::filesystem::exists(base.string() + "/photo.png"), true);

    std::filesystem::remove_all(base);
    clearUploads();
}

