TEST_F(JitExpressionTest, EncryptDecryptAESVectors) {
    const char *key = "0123456789ABCDEF0123456789ABCDEF"; // base64-decodes to 24 bytes -> AES-192

    // Encrypt with Base64 encoding
    runJitTemplate("<cfset e = Encrypt(\"Hello World\", \"0123456789ABCDEF0123456789ABCDEF\", \"AES\", \"Base64\")>", variables);
    EXPECT_EQ(variables["e"].toString().equals("K8Unc06LCP/mcn4D+04kxQ=="), true);

    // Hex encoding is uppercase
    runJitTemplate("<cfset e = Encrypt(\"Hello World\", \"0123456789ABCDEF0123456789ABCDEF\", \"AES\", \"Hex\")>", variables);
    EXPECT_EQ(variables["e"].toString().equals("2BC527734E8B08FFE6727E03FB4E24C5"), true);

    // Decrypt round-trips with each encoding
    runJitTemplate("<cfset d = Decrypt(\"K8Unc06LCP/mcn4D+04kxQ==\", \"0123456789ABCDEF0123456789ABCDEF\", \"AES\", \"Base64\")>", variables);
    EXPECT_EQ(variables["d"].toString().equals("Hello World"), true);

    runJitTemplate("<cfset d = Decrypt(\"2BC527734E8B08FFE6727E03FB4E24C5\", \"0123456789ABCDEF0123456789ABCDEF\", \"AES\", \"Hex\")>", variables);
    EXPECT_EQ(variables["d"].toString().equals("Hello World"), true);

    // Algorithm names are case-insensitive
    runJitTemplate("<cfset e = Encrypt(\"Hello\", \"0123456789ABCDEF0123456789ABCDEF\", \"aes\", \"Base64\")>", variables);
    EXPECT_EQ(variables["e"].toString().equals("Bt+es+O3cst8nrz8bbspMQ=="), true);

    // AES with an explicit IV (CBC)
    runJitTemplate("<cfset e = Encrypt(\"Hello World\", \"0123456789ABCDEF0123456789ABCDEF\", \"AES/CBC/PKCS5Padding\", \"Base64\", BinaryDecode(RepeatString(\"00\",16),\"Hex\"))>", variables);
    EXPECT_EQ(variables["e"].toString().equals("K8Unc06LCP/mcn4D+04kxQ=="), true);

    runJitTemplate("<cfset d = Decrypt(\"K8Unc06LCP/mcn4D+04kxQ==\", \"0123456789ABCDEF0123456789ABCDEF\", \"AES/CBC/PKCS5Padding\", \"Base64\", BinaryDecode(RepeatString(\"00\",16),\"Hex\"))>", variables);
    EXPECT_EQ(variables["d"].toString().equals("Hello World"), true);
}

TEST_F(JitExpressionTest, EncryptDecryptOtherAlgorithms) {
    // DES: base64 key "93Wn5ftSokM=" decodes to 8 bytes
    runJitTemplate("<cfset e = Encrypt(\"Hello World\", \"93Wn5ftSokM=\", \"DES\", \"Base64\")>", variables);
    EXPECT_EQ(variables["e"].toString().equals("6F46dfYVsa0WCReGQle7vA=="), true);

    // DESEDE: 24-byte key
    runJitTemplate("<cfset e = Encrypt(\"Hello World\", \"0123456789ABCDEF0123456789ABCDEF\", \"DESEDE\", \"Base64\")>", variables);
    EXPECT_EQ(variables["e"].toString().equals("ytY0kobY8KlIa6Sc7XpZyg=="), true);

    // BLOWFISH: 16-byte key
    runJitTemplate("<cfset e = Encrypt(\"Hello World\", \"khJoMdQKRgOsHJEuRRY1Ng==\", \"BLOWFISH\", \"Base64\")>", variables);
    EXPECT_EQ(variables["e"].toString().equals("EohGc8oUBC3DkD2yQmF6nQ=="), true);

    // Decrypt round-trips for each
    runJitTemplate("<cfset d = Decrypt(\"6F46dfYVsa0WCReGQle7vA==\", \"93Wn5ftSokM=\", \"DES\", \"Base64\")>", variables);
    EXPECT_EQ(variables["d"].toString().equals("Hello World"), true);

    runJitTemplate("<cfset d = Decrypt(\"ytY0kobY8KlIa6Sc7XpZyg==\", \"0123456789ABCDEF0123456789ABCDEF\", \"DESEDE\", \"Base64\")>", variables);
    EXPECT_EQ(variables["d"].toString().equals("Hello World"), true);

    runJitTemplate("<cfset d = Decrypt(\"EohGc8oUBC3DkD2yQmF6nQ==\", \"khJoMdQKRgOsHJEuRRY1Ng==\", \"BLOWFISH\", \"Base64\")>", variables);
    EXPECT_EQ(variables["d"].toString().equals("Hello World"), true);
}

