TEST_F(WriteDumpTest, UdfHtmlArgumentsAndMetadata) {
    cfml::VariantCleanupGuard guard;
    cfvariant st = cfvariant::Struct;
    st.set("ADDTWO") = makeUdfValue("addTwo", false,
                                    {testParam("a"), testParam("b", "numeric", "10")}, "numeric");
    cfvariant *r = cfml::cf_writedump(&st, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr);
    ASSERT_TRUE(r != nullptr);
    webstrada::string body = bodyAfterStyle(*r->m_str);
    EXPECT_EQ(body.contains("<th class=\"udf\" colspan=\"2\">function addTwo</b></th>"), true);
    // Argument row: name, always-Optional, declared type, default value.
    EXPECT_EQ(body.contains("<td>a</td>\r\n\t\t\t\t\t\t<td>Optional</td>\r\n\t\t\t\t\t\t<td>Any</td>\r\n\t\t\t\t\t\t<td>&nbsp;</td>"), true);
    EXPECT_EQ(body.contains("<td>b</td>\r\n\t\t\t\t\t\t<td>Optional</td>\r\n\t\t\t\t\t\t<td>numeric</td>\r\n\t\t\t\t\t\t<td>10 </td>"), true);
    EXPECT_EQ(body.contains("<i>ReturnType:</i></td>\r\n\t\t\t\t<td>numeric<br></td>"), true);
}

TEST_F(WriteDumpTest, UdfLeadingSpaceOnlyFirstDump) {
    cfml::VariantCleanupGuard guard;
    cfvariant st = cfvariant::Struct;
    st.set("U") = makeUdfValue("addOne", false, {testParam("x")});

    // First dump on the page: the UDF cell has a leading space before the table.
    cfvariant *r1 = cfml::cf_writedump(&st, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr);
    ASSERT_TRUE(r1 != nullptr);
    EXPECT_EQ(bodyAfterStyle(*r1->m_str).contains("<td>\r\n\t\t\t\t\t \r\n\t\t<table class=\"cfdump_udf\""), true);

    // Second dump: no leading space.
    cfvariant *r2 = cfml::cf_writedump(&st, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr);
    ASSERT_TRUE(r2 != nullptr);
    EXPECT_EQ(r2->m_str->contains("<td>\r\n\t\t\t\t\t\r\n\t\t<table class=\"cfdump_udf\""), true);
}

TEST_F(WriteDumpTest, UdfNestedDepthGetsLeadingSpace) {
    cfml::VariantCleanupGuard guard;
    // A UDF nested two levels deep gets the leading space even in a later dump
    // (CF quirk: first UDF at each nesting depth >= 2 carries the space).
    cfvariant outer = cfvariant::Struct;
    cfvariant inner = cfvariant::Struct;
    inner.set("V") = makeUdfValue("addOne", false, {testParam("x")});
    outer.set("W") = inner;

    cfvariant *r1 = cfml::cf_writedump(&outer, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr);
    ASSERT_TRUE(r1 != nullptr);
    EXPECT_EQ(bodyAfterStyle(*r1->m_str).contains("<td>\r\n\t\t\t\t\t \r\n\t\t<table class=\"cfdump_udf\""), true);

    // The same depth already seen on the page: no leading space.
    cfvariant *r2 = cfml::cf_writedump(&outer, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr);
    ASSERT_TRUE(r2 != nullptr);
    EXPECT_EQ(r2->m_str->contains("<td>\r\n\t\t\t\t\t\r\n\t\t<table class=\"cfdump_udf\""), true);
}

