TEST_F(WriteDumpTest, UdfJitEndToEnd) {
    cfml::VariantCleanupGuard guard;
    webstrada::string out = runJitTemplate(
        "<cfscript>function addOne(x) { return x + 1; }</cfscript><cfdump var=\"#variables#\">", variables);
    // The ADDONE cell now holds a real UDF table instead of an empty cell.
    EXPECT_EQ(out.contains("<td class=\"struct\">ADDONE</td>"), true);
    EXPECT_EQ(out.contains("<table class=\"cfdump_udf\" width=\"100%\">"), true);
    EXPECT_EQ(out.contains("<th class=\"udf\" colspan=\"2\">function addOne</b></th>"), true);
    EXPECT_EQ(out.contains("<td>x</td>\r\n\t\t\t\t\t\t<td>Optional</td>\r\n\t\t\t\t\t\t<td>Any</td>"), true);
    // The function still works after being dumped.
    EXPECT_EQ(runJitTemplate("<cfscript>function addOne(x) { return x + 1; }</cfscript><cfoutput>#addOne(41)#</cfoutput>", variables).equals("42"), true);
}

TEST(UdfMetaTest, SerializeDeserializeRoundTrip) {
    UdfMetaInfo meta;
    meta.params.push_back(testParam("x"));
    meta.params.push_back(testParam("b", "numeric", "10"));
    meta.params.push_back(testParam("s", "string", "hello"));
    meta.returnType = "numeric";
    meta.access = "public";
    std::string blob = webstrada::udf_meta_serialize(meta);
    UdfMetaInfo out;
    webstrada::udf_meta_deserialize(blob.data(), out);
    EXPECT_EQ(out.params.size(), (size_t)3);
    EXPECT_EQ(out.params[0].name.equals("x"), true);
    EXPECT_EQ(out.params[0].type.isEmpty(), true);
    EXPECT_EQ(out.params[1].name.equals("b"), true);
    EXPECT_EQ(out.params[1].type.equals("numeric"), true);
    EXPECT_EQ(out.params[1].defaultValue.equals("10"), true);
    EXPECT_EQ(out.params[2].defaultValue.equals("hello"), true);
    EXPECT_EQ(out.returnType.equals("numeric"), true);
    EXPECT_EQ(out.access.equals("public"), true);
}

TEST(UdfMetaTest, DeserializeNullIsEmpty) {
    UdfMetaInfo out;
    webstrada::udf_meta_deserialize(nullptr, out);
    EXPECT_EQ(out.params.empty(), true);
    EXPECT_EQ(out.returnType.isEmpty(), true);
}

TEST(UdfTypeCoerceTest, ComponentAcceptedAsStruct) {
    cfml::VariantCleanupGuard guard;
    cfvariant comp(cfvariant::Component);
    cfvariant *argRes = cfml::cf_udf_coerce_arg(&comp, "struct", "myArg", "myFunc");
    ASSERT_TRUE(argRes != nullptr);
    EXPECT_EQ(argRes->m_type, cfvariant::Component);

    cfvariant *retRes = cfml::cf_udf_coerce_return(&comp, "struct", "myFunc");
    ASSERT_TRUE(retRes != nullptr);
    EXPECT_EQ(retRes->m_type, cfvariant::Component);
}

TEST(WriteLogTest, WritesCsvRowAndHeader) {
    char tmpl[] = "/tmp/WebStrada_log_test_XXXXXX";
    char *dir = mkdtemp(tmpl);
    ASSERT_TRUE(dir != nullptr);
    setenv("WEBSTRADA_LOG_DIR", dir, 1);

    {
        cfml::VariantCleanupGuard guard;
        cfvariant text("hello world");
        cfvariant *r = cfml::cf_writelog(&text, nullptr, nullptr, nullptr, nullptr);
        ASSERT_TRUE(r != nullptr);
        EXPECT_EQ(r->m_str->isEmpty(), true);
    }

    std::string path = std::string(dir) + "/application.log";
    std::ifstream f(path);
    std::stringstream ss;
    ss << f.rdbuf();
    std::string content = ss.str();

    // Header is written once for a new file, then one data row.
    EXPECT_EQ(content.find("\"Severity\",\"ThreadID\",\"Date\",\"Time\",\"Application\",\"Message\"") != std::string::npos, true);
    EXPECT_EQ(content.find("\"Information\",\"http-nio-WebStrada-exec-1\",\"") != std::string::npos, true);
    EXPECT_EQ(content.find("\",\"\",\"hello world\"") != std::string::npos, true);
    // Two lines total (header + row).
    size_t lines = 0;
    for (char c : content) if (c == '\n') lines++;
    EXPECT_EQ(lines, (size_t)2);

    unsetenv("WEBSTRADA_LOG_DIR");
    std::filesystem::remove_all(dir);
}

TEST(WriteLogTest, SeverityTypesAndQuoting) {
    char tmpl[] = "/tmp/WebStrada_log_test_XXXXXX";
    char *dir = mkdtemp(tmpl);
    ASSERT_TRUE(dir != nullptr);
    setenv("WEBSTRADA_LOG_DIR", dir, 1);

    {
        cfml::VariantCleanupGuard guard;
        cfvariant text("warn msg");
        cfvariant type("warning");
        cfml::cf_writelog(&text, &type, nullptr, nullptr, nullptr);

        type = cfvariant("error");
        cfml::cf_writelog(&text, &type, nullptr, nullptr, nullptr);

        type = cfvariant("fatal");
        cfml::cf_writelog(&text, &type, nullptr, nullptr, nullptr);

        // Unknown type falls back to Information (verified against CF 2021).
        type = cfvariant("bogus");
        cfml::cf_writelog(&text, &type, nullptr, nullptr, nullptr);

        // Quotes inside the message are doubled; commas are kept literal.
        cfvariant quoted("a, b \"quoted\" x");
        cfml::cf_writelog(&quoted, nullptr, nullptr, nullptr, nullptr);
    }

    std::string path = std::string(dir) + "/application.log";
    std::ifstream f(path);
    std::stringstream ss;
    ss << f.rdbuf();
    std::string content = ss.str();

    EXPECT_EQ(content.find("\"Warning\",") != std::string::npos, true);
    EXPECT_EQ(content.find("\"Error\",") != std::string::npos, true);
    EXPECT_EQ(content.find("\"Fatal\",") != std::string::npos, true);
    EXPECT_EQ(content.find("\"Information\",\"http-nio-WebStrada-exec-1\",\"") != std::string::npos, true);
    EXPECT_EQ(content.find("a, b \"\"quoted\"\" x") != std::string::npos, true);

    unsetenv("WEBSTRADA_LOG_DIR");
    std::filesystem::remove_all(dir);
}

TEST(WriteLogTest, FileAndLogAttributes) {
    char tmpl[] = "/tmp/WebStrada_log_test_XXXXXX";
    char *dir = mkdtemp(tmpl);
    ASSERT_TRUE(dir != nullptr);
    setenv("WEBSTRADA_LOG_DIR", dir, 1);

    {
        cfml::VariantCleanupGuard guard;
        cfvariant text("custom file msg");
        cfvariant file("myfile");
        cfml::cf_writelog(&text, nullptr, nullptr, &file, nullptr);

        // log="scheduler" when no file is given → scheduler.log
        cfvariant logName("scheduler");
        cfml::cf_writelog(&text, nullptr, nullptr, nullptr, &logName);

        // file wins over log.
        cfvariant logName2("ignored");
        cfml::cf_writelog(&text, nullptr, nullptr, &file, &logName2);
    }

    EXPECT_EQ(std::filesystem::exists(std::string(dir) + "/myfile.log"), true);
    EXPECT_EQ(std::filesystem::exists(std::string(dir) + "/scheduler.log"), true);
    EXPECT_EQ(std::filesystem::exists(std::string(dir) + "/ignored.log"), false);

    // myfile.log has a header + 2 rows.
    std::ifstream f(std::string(dir) + "/myfile.log");
    std::stringstream ss;
    ss << f.rdbuf();
    std::string content = ss.str();
    size_t lines = 0;
    for (char c : content) if (c == '\n') lines++;
    EXPECT_EQ(lines, (size_t)3);

    unsetenv("WEBSTRADA_LOG_DIR");
    std::filesystem::remove_all(dir);
}

TEST(WriteLogTest, MissingTextThrows) {
    char tmpl[] = "/tmp/WebStrada_log_test_XXXXXX";
    char *dir = mkdtemp(tmpl);
    ASSERT_TRUE(dir != nullptr);
    setenv("WEBSTRADA_LOG_DIR", dir, 1);

    bool caught = false;
    try {
        cfml::cf_writelog(nullptr, nullptr, nullptr, nullptr, nullptr);
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);

    unsetenv("WEBSTRADA_LOG_DIR");
    std::filesystem::remove_all(dir);
}

// ---------------------------------------------------------------------------
// Logging/Debug: <cflog> / <cftimer> / <cftrace>
// ---------------------------------------------------------------------------

// Redirects the log directory to a fresh temp dir for the duration of a test.
struct LogDirScope {
    char path[128];
    LogDirScope() {
        char tmpl[] = "/tmp/WebStrada_logdirtest_XXXXXX";
        char *d = mkdtemp(tmpl);
        path[0] = '\0';
        if (d) {
            std::snprintf(path, sizeof(path), "%s", d);
            setenv("WEBSTRADA_LOG_DIR", path, 1);
        }
    }
    ~LogDirScope() {
        unsetenv("WEBSTRADA_LOG_DIR");
        if (path[0]) std::filesystem::remove_all(path);
    }
    std::string readFile(const char *name) {
        std::ifstream f(std::string(path) + "/" + name);
        std::stringstream ss;
        ss << f.rdbuf();
        return ss.str();
    }
};

TEST_F(JitExpressionTest, CflogTagRendersNothing) {
    LogDirScope logdir;
    {
        cfml::VariantCleanupGuard guard;
        // cflog renders nothing regardless of attributes.
        EXPECT_EQ(runJitTemplate("A<cflog text=\"hi\">B", variables).equals("AB"), true);
        EXPECT_EQ(runJitTemplate("A<cflog text=\"hi\" type=\"warning\">B", variables).equals("AB"), true);
        EXPECT_EQ(runJitTemplate("A<cflog text=\"\" />B", variables).equals("AB"), true);
        // Unterminated <cflog> is self-closing (verified on CF 2025).
        EXPECT_EQ(runJitTemplate("A<cflog text=\"t1\">B<cflog text=\"t2\">C", variables).equals("ABC"), true);
    }
    std::string content = logdir.readFile("application.log");
    // Header + one row per log write (hello, warning, empty text, t1, t2).
    size_t lines = 0;
    for (char c : content) if (c == '\n') lines++;
    EXPECT_EQ(lines, (size_t)6);
}

TEST_F(JitExpressionTest, CflogTagSkipsBody) {
    LogDirScope logdir;
    {
        cfml::VariantCleanupGuard guard;
        // The body is SKIPped like CF's LogTag (no side effects), but still
        // compiled (a bad tag inside it is a compile-time error). Verified
        // byte-for-byte against CF 2025.
        EXPECT_EQ(runJitTemplate("A<cflog text=\"x\">BODY</cflog>B", variables).equals("AB"), true);
        EXPECT_EQ(runJitTemplate("<cflog text=\"x\"><cfset z=42></cflog><cfoutput>#IsDefined(\"z\")#</cfoutput>", variables).equals("NO"), true);
        EXPECT_THROW(runJitTemplate("<cflog text=\"x\"><cfbadtag></cflog>", variables), webstrada::exception);
    }
}

TEST_F(JitExpressionTest, CflogTagCompileErrors) {
    // CF 2025: compile-time errors (the whole page fails, nothing renders).
    EXPECT_THROW(runJitTemplate("<cflog type=\"warning\">", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cflog>", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cflog text=\"x\" bogus=\"1\">", variables), webstrada::exception);
}

TEST_F(JitExpressionTest, CflogLogAttributeRouting) {
    LogDirScope logdir;
    {
        cfml::VariantCleanupGuard guard;
        // file writes <file>.log; log="scheduler" (case-insensitive) writes
        // scheduler.log; any other log value writes application.log (verified
        // on CF 2025: log="foo" lands in application.log, not foo.log).
        runJitTemplate("<cflog text=\"f\"><cflog text=\"s\" log=\"scheduler\"><cflog text=\"sc\" log=\"SCHEDULER\"><cflog text=\"a\" log=\"application\"><cflog text=\"foo\" log=\"foo\"><cflog text=\"c\" file=\"WebStrada_test\">", variables);
    }
    EXPECT_EQ(std::filesystem::exists(std::string(logdir.path) + "/WebStrada_test.log"), true);
    EXPECT_EQ(std::filesystem::exists(std::string(logdir.path) + "/scheduler.log"), true);
    EXPECT_EQ(std::filesystem::exists(std::string(logdir.path) + "/foo.log"), false);
    EXPECT_EQ(std::filesystem::exists(std::string(logdir.path) + "/application.log"), true);
    std::string applog = logdir.readFile("application.log");
    EXPECT_EQ(applog.find("\"foo\"") != std::string::npos, true);
    EXPECT_EQ(applog.find("\"a\"") != std::string::npos, true);
}

TEST_F(JitExpressionTest, CflogApplicationColumn) {
    LogDirScope logdir;
    {
        cfml::VariantCleanupGuard guard;
        // With an active <cfapplication> the Application column carries the
        // uppercased name (CF's LogTag.getApplicationName); application="false"
        // leaves it empty; no active application → empty (verified on CF 2025).
        auto &sc = cfml::scope_context();
        sc.appName = "myTestApp";
        sc.applicationEnabled = true;

        cfvariant applog("applog");
        cfml::cf_writelog(&applog, nullptr, nullptr, nullptr, nullptr);
        cfvariant noappcol("noappcol");
        cfvariant falseApp("false");
        cfml::cf_writelog(&noappcol, nullptr, &falseApp, nullptr, nullptr);

        sc.appName = "";
        sc.applicationEnabled = false;

        cfvariant noapp("noapp");
        cfml::cf_writelog(&noapp, nullptr, nullptr, nullptr, nullptr);
    }
    std::string content = logdir.readFile("application.log");
    EXPECT_EQ(content.find("\"MYTESTAPP\",\"applog\"") != std::string::npos, true);
    EXPECT_EQ(content.find(",\"\",\"noappcol\"") != std::string::npos, true);
    EXPECT_EQ(content.find(",\"\",\"noapp\"") != std::string::npos, true);
}

TEST_F(JitExpressionTest, CftimerEvaluatesBodyNoTiming) {
    // With debugging disabled (the engine's state, matching CF-with-debug-off)
    // the body always evaluates and no timing is displayed.
    EXPECT_EQ(runJitTemplate("A<cftimer type=\"inline\" label=\"L1\">BODY1</cftimer>B<cftimer type=\"comment\" label=\"L2\">BODY2</cftimer>C<cftimer type=\"debug\">BODY3</cftimer>D<cftimer label=\"L4\">BODY4</cftimer>E<cftimer type=\"outline\">BODY5</cftimer>F", variables).equals("ABODY1BBODY2CBODY3DBODY4EBODY5F"), true);
    EXPECT_EQ(runJitTemplate("A<cftimer type=\"INLINE\" label=\"L6\">BODY6</cftimer>B", variables).equals("ABODY6B"), true);
    EXPECT_EQ(runJitTemplate("A<cftimer type=\"inline\" label=\"L7\"/>B", variables).equals("AB"), true);
    // Nested timers evaluate their bodies.
    EXPECT_EQ(runJitTemplate("A<cftimer type=\"inline\">X<cftimer type=\"inline\">Y</cftimer>Z</cftimer>B", variables).equals("AXYZB"), true);
}

TEST_F(JitExpressionTest, CftimerInvalidTypeCatchable) {
    // Both a static literal and a dynamic value throw CF's catchable Template
    // error (verified on CF 2025: caught by <cfcatch>, type Template).
    string out = runJitTemplate(
        "<cftry><cftimer type=\"bogus\">B</cftimer><cfoutput>NOTCAUGHT</cfoutput>"
        "<cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("Template|Attribute validation error for CFTIMER.|The value of the TYPE attribute, which is currently bogus, must be one of the values: DEBUG,OUTLINE,INLINE,COMMENT."), true);

    out = runJitTemplate(
        "<cfset x=\"bogus\"><cftry><cftimer type=\"#x#\">B</cftimer><cfoutput>NOTCAUGHT</cfoutput>"
        "<cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("Template|Attribute validation error for CFTIMER.|The value of the TYPE attribute, which is currently bogus, must be one of the values: DEBUG,OUTLINE,INLINE,COMMENT."), true);

    // An empty type renders '' in the message.
    out = runJitTemplate(
        "<cftry><cftimer type=\"\">B</cftimer><cfoutput>NOTCAUGHT</cfoutput>"
        "<cfcatch><cfoutput>#cfcatch.detail#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("The value of the TYPE attribute, which is currently '', must be one of the values: DEBUG,OUTLINE,INLINE,COMMENT."), true);
}

TEST_F(JitExpressionTest, CftimerCompileErrors) {
    // Unknown attributes and an unterminated <cftimer> are compile-time errors.
    EXPECT_THROW(runJitTemplate("<cftimer type=\"inline\" bogus=\"1\">B</cftimer>", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cftimer type=\"inline\">B", variables), webstrada::exception);
}

TEST_F(JitExpressionTest, CftraceTagIsNoOpBodyEvaluated) {
    // Debugging disabled → <cftrace> renders nothing, abort doesn't fire, the
    // body is still evaluated (all verified on CF 2025).
    EXPECT_EQ(runJitTemplate("A<cftrace text=\"hello\">B<cftrace>C<cftrace abort=\"true\">D", variables).equals("ABCD"), true);
    EXPECT_EQ(runJitTemplate("A<cftrace text=\"x\">BODY</cftrace>B", variables).equals("ABODYB"), true);
    EXPECT_EQ(runJitTemplate("A<cftrace text=\"x\" inline=\"true\">B", variables).equals("AB"), true);
    EXPECT_EQ(runJitTemplate("A<cftrace type=\"bogus\">B", variables).equals("AB"), true);
    // Attribute expressions are still evaluated (CF's setters run even with
    // debugging off), so an undefined variable throws.
    EXPECT_THROW(runJitTemplate("<cftrace text=\"#zz_undefined_zz#\">", variables), webstrada::exception);
    // The `var` attribute name is tokenized as a Keyword, but its value is
    // still evaluated (was BUGS.md "<cftrace var=...> attribute value is not
    // evaluated"); an undefined variable in it throws like text does.
    EXPECT_THROW(runJitTemplate("<cftrace var=\"#zz_undefined_zz#\">", variables), webstrada::exception);
    // A defined var value is a no-op.
    EXPECT_EQ(runJitTemplate("<cfset vv = 42><cftrace var=\"#vv#\" text=\"t\">B", variables).equals("B"), true);
}

TEST_F(JitExpressionTest, CftraceCompileError) {
    EXPECT_THROW(runJitTemplate("<cftrace text=\"x\" bogus=\"1\">", variables), webstrada::exception);
}

TEST_F(JitExpressionTest, CftimerBodyEvaluatesCfml) {
    // The body runs real CFML (side effects happen, #expr# renders), like CF.
    string out = runJitTemplate(
        "<cfset y=7><cftimer type=\"inline\" label=\"L\"><cfoutput>#y#</cfoutput><cfset zz=9></cftimer><cfoutput>[#zz#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("7[9]"), true);
}

TEST_F(JitExpressionTest, CftraceTagBodySideEffectsRun) {
    // The cftrace body is evaluated (side effects happen), like CF.
    string out = runJitTemplate(
        "<cftrace text=\"x\"><cfset zz2=5></cftrace><cfoutput>[#zz2#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[5]"), true);
}

TEST_F(JitExpressionTest, TraceFunctionNamedArgValidation) {
    // CF rejects an unknown trace() attribute at compile time
    // ("Attribute validation error for TRACE tag in cfscript."); this engine
    // surfaces the same message at runtime (documented divergence).
    string out = runJitTemplate(
        "<cftry><cfscript>r=trace(bogus=\"x\");</cfscript><cfoutput>NOTCAUGHT</cfoutput>"
        "<cfcatch><cfoutput>#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("Attribute validation error for TRACE tag in cfscript.|It does not allow the attribute(s) BOGUS. The valid attribute(s) are ABORT,CATEGORY,INLINE,TEXT,TYPE,VAR."), true);
    // Valid names are still a no-op.
    EXPECT_EQ(runJitTemplate("<cfscript>trace();trace(text=\"x\", inline=true);trace(abort=true);</cfscript><cfoutput>Z</cfoutput>", variables).equals("Z"), true);
}

TEST_F(JitExpressionTest, WriteLogNamedAndPositionalArgs) {
    LogDirScope logdir;
    {
        cfml::VariantCleanupGuard guard;
        // Named and positional argument forms bind (text, type, application,
        // file, log) by name/position (the WriteLog JIT path; was BUGS.md
        // "WriteLog in a cfset segfaults the CLI" — the named-arg form produced
        // a null LLVM operand that crashed MCJIT's constant hoisting).
        runJitTemplate("<cfset WriteLog(text=\"named\")><cfset WriteLog(\"pos\", \"warning\")><cfset WriteLog(text=\"app\", application=false)>", variables);
    }
    std::string content = logdir.readFile("application.log");
    EXPECT_EQ(content.find("\"Information\",\"http-nio-WebStrada-exec-1\",\"") != std::string::npos, true);
    EXPECT_EQ(content.find("\"named\"") != std::string::npos, true);
    EXPECT_EQ(content.find("\"Warning\",\"http-nio-WebStrada-exec-1\",\"") != std::string::npos, true);
    EXPECT_EQ(content.find("\"pos\"") != std::string::npos, true);
    EXPECT_EQ(content.find("\"app\"") != std::string::npos, true);
}


TEST_F(JitExpressionTest, PowBasics) {
    runJitTemplate("<cfset x = 2^3>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 8.0);

    runJitTemplate("<cfset x = 2^0>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 1.0);

    runJitTemplate("<cfset x = 2^1>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 2.0);

    runJitTemplate("<cfset x = 0^0>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 1.0);

    runJitTemplate("<cfset x = 0^5>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 0.0);

    runJitTemplate("<cfset x = 1^1000>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 1.0);
}

TEST_F(JitExpressionTest, PowLargeAndFractional) {
    runJitTemplate("<cfset x = 2^53>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 9007199254740992.0);

    runJitTemplate("<cfset x = 2^100>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 1.2676506002282294e30);

    runJitTemplate("<cfset x = 2^0.5>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 1.4142135623730951);

    runJitTemplate("<cfset x = 16^0.5>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 4.0);

    runJitTemplate("<cfset x = 2.5^2>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 6.25);
}

TEST_F(JitExpressionTest, PowNegativeExponent) {
    runJitTemplate("<cfset x = 2^-3>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 0.125);

    runJitTemplate("<cfset x = 2^(-1)>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 0.5);

    runJitTemplate("<cfset x = 10^-2>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 0.01);

    runJitTemplate("<cfset x = 4^(-0.5)>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 0.5);
}

TEST_F(JitExpressionTest, PowUnaryMinusBindsTighter) {
    // CF: -2^2 == (-2)^2 == 4, and -2^3 == (-2)^3 == -8 (verified on CF 2021).
    runJitTemplate("<cfset x = -2^2>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 4.0);

    runJitTemplate("<cfset x = -3^2>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 9.0);

    runJitTemplate("<cfset x = -2^3>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, -8.0);

    runJitTemplate("<cfset x = (-2)^3>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, -8.0);
}

TEST_F(JitExpressionTest, PowLeftAssociative) {
    // CF is left-associative: 2^3^2 == (2^3)^2 == 64 (verified on CF 2021).
    runJitTemplate("<cfset x = 2^3^2>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 64.0);

    runJitTemplate("<cfset x = 3^2^2>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 81.0);

    runJitTemplate("<cfset x = 2^2^3>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 64.0);

    // Parens still force right-associativity.
    runJitTemplate("<cfset x = 2^(3^2)>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 512.0);
}

TEST_F(JitExpressionTest, PowPrecedence) {
    runJitTemplate("<cfset x = 2^3*2>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 16.0);

    runJitTemplate("<cfset x = 2*3^2>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 18.0);

    runJitTemplate("<cfset x = 2^3+1>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 9.0);
}

TEST_F(JitExpressionTest, PowStringAndFloatOperands) {
    runJitTemplate("<cfset x = \"2\"^\"3\">", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 8.0);

    runJitTemplate("<cfset x = 2.0^3>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 8.0);

    runJitTemplate("<cfset x = 2^3.0>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 8.0);
}

TEST_F(JitExpressionTest, PowVariablesAndFunctions) {
    string cfml =
        "<cfset a = 3>"
        "<cfset b = 4>"
        "<cfset c = a^b>"
        "<cfset d = Abs(2^3)>"
        "<cfset e = 27^(1/3)>";
    runJitTemplate(cfml, variables);
    EXPECT_DOUBLE_EQ(variables["c"].m_double, 81.0);
    EXPECT_EQ(variables["d"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["d"].m_double, 8.0);
    EXPECT_DOUBLE_EQ(variables["e"].m_double, 3.0);
}

TEST_F(JitExpressionTest, PowInfinityAndNaN) {
    runJitTemplate("<cfset x = 2^1024>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, std::numeric_limits<double>::infinity());

    runJitTemplate("<cfset x = -2^1025>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, -std::numeric_limits<double>::infinity());

    runJitTemplate("<cfset x = 0^-1>", variables);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, std::numeric_limits<double>::infinity());

    runJitTemplate("<cfset x = (-2)^0.5>", variables);
    EXPECT_EQ(std::isnan(variables["x"].m_double), true);
}

TEST_F(JitExpressionTest, PowInConditions) {
    string cfml =
        "<cfif 2^3 EQ 8>YES<cfelse>NO</cfif>"
        "<cfif 2^3 EQ 9>B<cfelse>A</cfif>"
        "<cfif 2^0.5 GT 1>G<cfelse>L</cfif>"
        "<cfif -2^2 EQ 4>U<cfelse>D</cfif>"
        "<cfif 2^3^2 EQ 64>Q<cfelse>R</cfif>";
    string out = runJitTemplate(cfml, variables);
    EXPECT_EQ(out.equals("YESAGUQ"), true);
}

TEST_F(JitExpressionTest, PowTemplateOutput) {
    string out = runJitTemplate("<cfoutput>#2^3#</cfoutput>", variables);
    EXPECT_EQ(out.equals("8"), true);

    out = runJitTemplate("<cfoutput>#2^53#</cfoutput>", variables);
    EXPECT_EQ(out.equals("9.00719925474E+015"), true);

    out = runJitTemplate("<cfoutput>#2^3^2#|#-2^2#|#2^-3#|#2^0.5#</cfoutput>", variables);
    EXPECT_EQ(out.equals("64|4|0.125|1.41421356237"), true);

    out = runJitTemplate("<cfoutput>#2^(-1)#|#10^-2#|#2^1024#</cfoutput>", variables);
    EXPECT_EQ(out.equals("0.5|0.01|1.#INF"), true);
}

// CF 2021 stringifies a NaN double as the single U+FFFD replacement character
// (UTF-8 bytes EF BF BD; Len() == 1, Asc() == 65533) in every output path —
// cfoutput, ToString(), concatenation, WriteOutput, cfdump (HTML &#xfffd;).
// SerializeJSON keeps the non-JSON "NaN" token. Verified against the CF server.
TEST_F(JitExpressionTest, NanOutputRendersReplacementChar) {
    // cfoutput of a NaN expression and of a NaN stored in a variable
    string out = runJitTemplate("<cfoutput>[#(-2)^0.5#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[\xEF\xBF\xBD]"), true);

    runJitTemplate("<cfset x = (-2)^0.5>", variables);
    out = runJitTemplate("<cfoutput>[#x#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[\xEF\xBF\xBD]"), true);

    // unary minus keeps the NaN sign bit but still renders as U+FFFD
    runJitTemplate("<cfset n = -x>", variables);
    out = runJitTemplate("<cfoutput>[#n#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[\xEF\xBF\xBD]"), true);

    // ToString() of a NaN double yields a single U+FFFD character
    runJitTemplate("<cfset s = ToString(x)>", variables);
    out = runJitTemplate("<cfoutput>[#s#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[\xEF\xBF\xBD]"), true);

    // concatenation stringifies NaN via the same U+FFFD path
    runJitTemplate("<cfset c = x & \"\">", variables);
    out = runJitTemplate("<cfoutput>[#c#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[\xEF\xBF\xBD]"), true);

    // WriteOutput in cfscript
    out = runJitTemplate("<cfscript>writeOutput(\"[\" & x & \"]\");</cfscript>", variables);
    EXPECT_EQ(out.equals("[\xEF\xBF\xBD]"), true);

    // SerializeJSON keeps the non-JSON NaN token like CF
    out = runJitTemplate("<cfoutput>#SerializeJSON(x)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("NaN"), true);

    // Infinity is unaffected: 1.#INF / -1.#INF
    out = runJitTemplate("<cfoutput>#2^1024#|#-2^1025#</cfoutput>", variables);
    EXPECT_EQ(out.equals("1.#INF|-1.#INF"), true);
}

TEST_F(JitExpressionTest, NanOutputCfdump) {
    string out = runJitTemplate("<cfset x = (-2)^0.5><cfdump var=\"#x#\">", variables);
    // HTML cfdump emits &#xfffd; for a NaN value cell
    EXPECT_EQ(out.contains("&#xfffd;"), true);

    out = runJitTemplate("<cfset x = (-2)^0.5><cfdump var=\"#x#\" format=\"text\">", variables);
    // text cfdump emits the raw U+FFFD bytes inside the <pre> block
    EXPECT_EQ(out.contains("\xEF\xBF\xBD"), true);
}

TEST_F(WriteOutputTest, PowViaCfevaluate) {
    cfvariant result = cfml::cfevaluate(out, "WriteOutput(2^3)", nullptr);
    EXPECT_EQ(out.equals("8"), true);
    EXPECT_EQ(result.m_bool, true);

    webstrada::string out2;
    cfml::cfevaluate(out2, "WriteOutput(2^53)", nullptr);
    EXPECT_EQ(out2.equals("9.00719925474E+015"), true);

    webstrada::string out3;
    cfml::cfevaluate(out3, "WriteOutput(2^3^2)", nullptr);
    EXPECT_EQ(out3.equals("64"), true);

    webstrada::string out4;
    cfml::cfevaluate(out4, "WriteOutput(-2^2)", nullptr);
    EXPECT_EQ(out4.equals("4"), true);
}

// Integer literals above the signed 32-bit range must not crash the JIT
// parser (BUG #5, "stoi"). Values within int32 stay Integer; larger values
// are promoted to Float (double) and, when unsigned, keep their literal text.
TEST_F(JitExpressionTest, IntLiteralJustBelowInt32Boundary) {
    runJitTemplate("<cfset x = 2147483647>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["x"].m_int, 2147483647);

    runJitTemplate("<cfset x = -2147483648>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["x"].m_int, -2147483648);
}

TEST_F(JitExpressionTest, IntLiteralAboveInt32PromotedToLong) {
    runJitTemplate("<cfset x = 2147483648>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Long, true);
    EXPECT_EQ(variables["x"].m_long, 2147483648LL);

    runJitTemplate("<cfset x = 9007199254740992>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Long, true);
    EXPECT_EQ(variables["x"].m_long, 9007199254740992LL);

    // beyond int64 still becomes Float (CFBigInteger mimic)
    runJitTemplate("<cfset x = 9223372036854775808>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 9223372036854775808.0);
}

TEST_F(JitExpressionTest, IntLiteralBelowInt32PromotedToFloat) {
    runJitTemplate("<cfset x = -2147483649>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, -2147483649.0);

    runJitTemplate("<cfset x = -9223372036854775808>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, -9.2233720368547758e18);
}

TEST_F(JitExpressionTest, IntLiteralBeyondInt64PromotedToFloat) {
    runJitTemplate("<cfset x = 9223372036854775808>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 9223372036854775808.0);

    runJitTemplate("<cfset x = 123456789012345678901234567890>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
}

TEST_F(JitExpressionTest, IntLiteralPromotionPreservesLiteralText) {
    string out = runJitTemplate("<cfoutput>#2147483648#</cfoutput>", variables);
    EXPECT_EQ(out.equals("2147483648"), true);

    out = runJitTemplate("<cfoutput>#9007199254740992#</cfoutput>", variables);
    EXPECT_EQ(out.equals("9007199254740992"), true);

    out = runJitTemplate("<cfoutput>#9223372036854775808#</cfoutput>", variables);
    EXPECT_EQ(out.equals("9223372036854775808"), true);
}

TEST_F(JitExpressionTest, ArithmeticOverflowPromotesToFloat) {
    runJitTemplate("<cfset x = 2147483647 + 1>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 2147483648.0);

    runJitTemplate("<cfset x = -2147483648 - 1>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, -2147483649.0);

    runJitTemplate("<cfset x = 2147483647 * 3>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 6442450941.0);

    runJitTemplate("<cfset x = 1000000000 * 1000000000>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Float, true);
    EXPECT_DOUBLE_EQ(variables["x"].m_double, 1e18);
}

TEST_F(JitExpressionTest, ArithmeticWithinInt32StaysInt) {
    runJitTemplate("<cfset x = 2147483646 + 1>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["x"].m_int, 2147483647);

    runJitTemplate("<cfset x = -2147483647 - 1>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["x"].m_int, -2147483648);

    runJitTemplate("<cfset x = 46340 * 46340>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["x"].m_int, 2147395600);
}

TEST_F(JitExpressionTest, LargeIntComparisons) {
    // Verified against CF 2021: 2147483649 EQ 2147483648 -> NO (both promoted
    // to Float, 2147483649.0 != 2147483648.0), 2^53 EQ 9007199254740993 -> YES
    // (9007199254740993 rounds to 9007199254740992 as a double),
    // 2147483648 LT 2147483648 -> NO.
    string cfml =
        "<cfif 2147483648 GT 2147483647>Y<cfelse>N</cfif>"
        "<cfif 2147483648 EQ 2147483648>Y<cfelse>N</cfif>"
        "<cfif 2147483649 EQ 2147483648>Y<cfelse>N</cfif>"
        "<cfif -2147483649 LT -2147483648>Y<cfelse>N</cfif>"
        "<cfif 2^53 EQ 9007199254740992>Y<cfelse>N</cfif>";
    string out = runJitTemplate(cfml, variables);
    EXPECT_EQ(out.equals("YYNYY"), true);

    cfml =
        "<cfif 2^53 EQ 9007199254740993>Y<cfelse>N</cfif>"
        "<cfif 2147483648 LT 2147483648>Y<cfelse>N</cfif>"
        "<cfif 9007199254740992 GT 1000000>Y<cfelse>N</cfif>";
    out = runJitTemplate(cfml, variables);
    EXPECT_EQ(out.equals("YNY"), true);
}

TEST_F(JitExpressionTest, LargeIntModMatchesColdFusion) {
    // CF computes % on the int32-truncated value (2147483648 -> -2147483648,
    // so 2147483648 % 1000 == -648; verified against CF 2021).
    runJitTemplate("<cfset x = 2147483648 % 1000>", variables);
    EXPECT_EQ(variables["x"].m_type == cfvariant::Number, true);
    EXPECT_EQ(variables["x"].m_int, -648);

    runJitTemplate("<cfset x = -2147483648 % 1000>", variables);
    EXPECT_EQ(variables["x"].m_int, -648);
}

TEST_F(WriteOutputTest, IntRangeViaCfevaluate) {
    cfml::cfevaluate(out, "WriteOutput(2147483648)", nullptr);
    EXPECT_EQ(out.equals("2147483648"), true);

    webstrada::string out2;
    cfml::cfevaluate(out2, "WriteOutput(9007199254740992)", nullptr);
    EXPECT_EQ(out2.equals("9007199254740992"), true);

    webstrada::string out3;
    cfml::cfevaluate(out3, "WriteOutput(-2147483649)", nullptr);
    EXPECT_EQ(out3.equals("-2147483649"), true);
}

// Bare literals inside a <cfoutput>#...#</cfoutput> expression (previously
// output nothing). The SharpExpression's Expression group is deleted when it
// wraps a single child, so a bare string/number/boolean literal or a
// parenthesized expression
// is a direct child and must still be evaluated and rendered.
class SharpOutputTest : public testing::Test {
protected:
    webstrada::string out;
    cfvariant variables;
    cfml::VariantCleanupGuard guard;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    // Runs the tag-based output path directly (the cfoutputexpr runtime
    // function the JIT compiler emits for <cfoutput>#...#</cfoutput>).
    void outputExpr(const char *varName) {
        cfml::cfoutputexpr(out, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, &variables, varName);
    }
};

TEST_F(SharpOutputTest, JitBareStringLiteral) {
    out = runJitTemplate("<cfoutput>[#\"plain\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[plain]"), true);

    out = runJitTemplate("<cfoutput>[# 'single' #]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[single]"), true);

    out = runJitTemplate("<cfoutput>[# \" spaced \" #]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[ spaced ]"), true);
}

TEST_F(SharpOutputTest, JitStringEscapes) {
    // ## -> #, "" -> " and '' -> ' inside a bare string literal
    out = runJitTemplate("<cfoutput>[#\"a ## b\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[a # b]"), true);

    out = runJitTemplate("<cfoutput>[#\"d \"\"q\"\" x\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[d \"q\" x]"), true);

    out = runJitTemplate("<cfoutput>[#'d ''q'' x'#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[d 'q' x]"), true);
}

TEST_F(SharpOutputTest, JitStringInterpolation) {
    variables.set("X");
    variables["X"] = cfvariant(5);

    out = runJitTemplate("<cfoutput>[#\"a #x# b\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[a 5 b]"), true);

    out = runJitTemplate("<cfoutput>[#\"a #x# b #x# c\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[a 5 b 5 c]"), true);

    out = runJitTemplate("<cfoutput>[#\"#x#\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[5]"), true);
}

TEST_F(SharpOutputTest, JitBareNumberLiteral) {
    out = runJitTemplate("<cfoutput>[#8.0#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[8.0]"), true);

    out = runJitTemplate("<cfoutput>[# 8.10 #]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[8.10]"), true);

    out = runJitTemplate("<cfoutput>[#42#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[42]"), true);

    // leading minus makes the float computed: -8.0 renders as -8
    out = runJitTemplate("<cfoutput>[#-8.0#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[-8]"), true);

    out = runJitTemplate("<cfoutput>[# 3.5E2 #]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[3.5E2]"), true);
}

TEST_F(SharpOutputTest, JitBareBooleanLiteral) {
    // CF renders literal booleans as true/false, computed ones as YES/NO
    out = runJitTemplate("<cfoutput>[#true#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[true]"), true);

    out = runJitTemplate("<cfoutput>[#false#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[false]"), true);

    out = runJitTemplate("<cfoutput>[#IsNumeric(\"5\")#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[YES]"), true);
}

TEST_F(SharpOutputTest, JitParenthesizedLiteral) {
    // single-child parenthesized expressions are also direct children
    out = runJitTemplate("<cfoutput>[#(\"plain\")#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[plain]"), true);

    out = runJitTemplate("<cfoutput>[#(8.0)#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[8.0]"), true);

    out = runJitTemplate("<cfoutput>[#(true)#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[true]"), true);
}

TEST_F(SharpOutputTest, JitInterpolatedBoolean) {
    // interpolation keeps the literal vs computed boolean distinction
    out = runJitTemplate("<cfoutput>[#\"x=#true#\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[x=true]"), true);

    out = runJitTemplate("<cfoutput>[#\"x=#IsNumeric(\"5\")#\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[x=YES]"), true);
}

TEST_F(SharpOutputTest, JitVariableAndFunctionStillWork) {
    variables.set("X");
    variables["X"] = cfvariant(5);

    out = runJitTemplate("<cfoutput>[#x#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[5]"), true);

    out = runJitTemplate("<cfoutput>[#Len(\"abc\")#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[3]"), true);
}

TEST_F(SharpOutputTest, InterpreterBareStringLiteral) {
    outputExpr("\"plain\"");
    EXPECT_EQ(out.equals("plain"), true);
}

TEST_F(SharpOutputTest, InterpreterStringEscapes) {
    outputExpr("\"a ## b\"");
    EXPECT_EQ(out.equals("a # b"), true);

    out.clear();
    outputExpr("\"d \"\"q\"\" x\"");
    EXPECT_EQ(out.equals("d \"q\" x"), true);
}

TEST_F(SharpOutputTest, InterpreterStringInterpolation) {
    variables.set("X");
    variables["X"] = cfvariant(5);

    outputExpr("\"a #x# b\"");
    EXPECT_EQ(out.equals("a 5 b"), true);
}

TEST_F(SharpOutputTest, InterpreterBareNumberAndBoolean) {
    outputExpr("8.0");
    EXPECT_EQ(out.equals("8.0"), true);

    out.clear();
    outputExpr("true");
    EXPECT_EQ(out.equals("true"), true);

    out.clear();
    outputExpr("IsNumeric(\"5\")");
    EXPECT_EQ(out.equals("YES"), true);
}

// ---- Binary/unary operator support in tag-based #...# expressions (BUGS.md
// #3): evaluateExpr now evaluates the full CFML operator set instead of
// emitting binary operators as literal text. Verified byte-for-byte against
// CF 2021 in tests/cfm/sharp_operator_test.cfm.

TEST_F(SharpOutputTest, InterpreterArithmeticOperators) {
    outputExpr("(2 + 3)");
    EXPECT_EQ(out.equals("5"), true);

    out.clear();
    outputExpr("(7 - 2)");
    EXPECT_EQ(out.equals("5"), true);

    out.clear();
    outputExpr("(2 * 3)");
    EXPECT_EQ(out.equals("6"), true);

    out.clear();
    outputExpr("(10 / 2)");
    EXPECT_EQ(out.equals("5"), true);

    out.clear();
    outputExpr("(5 \\ 2)");
    EXPECT_EQ(out.equals("2"), true);

    out.clear();
    outputExpr("(5.9 \\ 2)");
    EXPECT_EQ(out.equals("2"), true);

    out.clear();
    outputExpr("(-5 \\ 2)");
    EXPECT_EQ(out.equals("-2"), true);

    out.clear();
    outputExpr("(5 MOD 3)");
    EXPECT_EQ(out.equals("2"), true);

    out.clear();
    outputExpr("(10 % 4)");
    EXPECT_EQ(out.equals("2"), true);

    out.clear();
    outputExpr("(2 ^ 3)");
    EXPECT_EQ(out.equals("8"), true);
}

TEST_F(SharpOutputTest, InterpreterOperatorPrecedence) {
    outputExpr("(2 + 3 * 4)");
    EXPECT_EQ(out.equals("14"), true);

    out.clear();
    outputExpr("(\"A\" & 2 + 3)");
    EXPECT_EQ(out.equals("A5"), true); // '+' binds tighter than '&'

    out.clear();
    outputExpr("(2^3^2)");
    EXPECT_EQ(out.equals("64"), true); // '^' is left-associative

    out.clear();
    outputExpr("(-2^2)");
    EXPECT_EQ(out.equals("4"), true); // unary '-' binds tighter than '^'

    out.clear();
    outputExpr("(1 + 2 + 3)");
    EXPECT_EQ(out.equals("6"), true);

    out.clear();
    outputExpr("(10 - 4 - 3)");
    EXPECT_EQ(out.equals("3"), true); // left-associative

    out.clear();
    outputExpr("(20 / 4 / 2)");
    EXPECT_EQ(out.equals("2.5"), true);
}

TEST_F(SharpOutputTest, InterpreterConcatenation) {
    variables.set("X");
    variables["X"] = cfvariant("hi");

    outputExpr("(3 & x)");
    EXPECT_EQ(out.equals("3hi"), true);

    out.clear();
    outputExpr("(x & 3)");
    EXPECT_EQ(out.equals("hi3"), true);

    out.clear();
    outputExpr("(1 & 2 & 3)");
    EXPECT_EQ(out.equals("123"), true);

    out.clear();
    outputExpr("(\"a\" & true)");
    EXPECT_EQ(out.equals("atrue"), true);
}

TEST_F(SharpOutputTest, InterpreterComparisonOperators) {
    // Word forms: EQ NEQ IS GT GTE LT LTE (symbolic < > <= >= are rejected by
    // CF's tag parser and would close <cfoutput>, so they are not tested here).
    outputExpr("(5 EQ 5)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 EQ 4)");
    EXPECT_EQ(out.equals("NO"), true);

    out.clear();
    outputExpr("(5 NEQ 4)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 IS 5)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 IS NOT 4)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 GT 3)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 GTE 5)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 LT 6)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 LTE 5)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 == 5)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 != 3)");
    EXPECT_EQ(out.equals("YES"), true);
}

TEST_F(SharpOutputTest, InterpreterContainsOperators) {
    outputExpr("(\"hello\" CONTAINS \"ell\")");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(\"hello\" CONTAINS \"xyz\")");
    EXPECT_EQ(out.equals("NO"), true);

    out.clear();
    outputExpr("(\"hello\" DOES NOT CONTAIN \"xyz\")");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(\"hello\" DOES NOT CONTAIN \"ell\")");
    EXPECT_EQ(out.equals("NO"), true);
}

TEST_F(SharpOutputTest, InterpreterLogicalOperators) {
    outputExpr("((5 EQ 5) AND (4 EQ 4))");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("((5 EQ 4) OR (4 EQ 4))");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(NOT (5 EQ 4))");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(NOT (5 EQ 5))");
    EXPECT_EQ(out.equals("NO"), true);

    out.clear();
    outputExpr("((5 EQ 5) XOR (4 EQ 4))");
    EXPECT_EQ(out.equals("NO"), true); // true XOR true -> false

    out.clear();
    outputExpr("((5 EQ 4) XOR (4 EQ 4))");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("((5 EQ 5) EQV (4 EQ 4))");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("((5 EQ 5) EQV (4 EQ 5))");
    EXPECT_EQ(out.equals("NO"), true);

    out.clear();
    outputExpr("((5 EQ 4) IMP (4 EQ 4))");
    EXPECT_EQ(out.equals("YES"), true); // false IMP true -> true

    out.clear();
    outputExpr("((5 EQ 5) IMP (4 EQ 5))");
    EXPECT_EQ(out.equals("NO"), true); // true IMP false -> false
}

TEST_F(SharpOutputTest, InterpreterAndOrReturnOperands) {
    // AND/OR return one of their operands, preserving the boolean flavor.
    outputExpr("(2 AND 3)");
    EXPECT_EQ(out.equals("3"), true);

    out.clear();
    outputExpr("(0 AND 3)");
    EXPECT_EQ(out.equals("0"), true);

    out.clear();
    outputExpr("(2 OR 3)");
    EXPECT_EQ(out.equals("2"), true);

    out.clear();
    outputExpr("(0 OR 3)");
    EXPECT_EQ(out.equals("3"), true);

    out.clear();
    outputExpr("(2 && 3)");
    EXPECT_EQ(out.equals("3"), true);

    out.clear();
    outputExpr("(0 || 3)");
    EXPECT_EQ(out.equals("3"), true);
}

TEST_F(SharpOutputTest, JitSymbolicLogicalOperators) {
    // Symbolic && / || must tokenize as a single operator (previously the
    // grammar only produced bare & and |, so these threw "Binary operator
    // missing operand" or silently dropped the right operand).
    out = runJitTemplate("<cfscript>writeOutput(1 && 3);</cfscript>", variables);
    EXPECT_EQ(out.equals("3"), true);

    out = runJitTemplate("<cfscript>writeOutput(0 || 3);</cfscript>", variables);
    EXPECT_EQ(out.equals("3"), true);

    // Bare form inside a cfoutput body (previously failed to parse).
    out = runJitTemplate("<cfoutput>#0 || 3#</cfoutput>", variables);
    EXPECT_EQ(out.equals("3"), true);

    out = runJitTemplate("<cfoutput>#2 && 3#</cfoutput>", variables);
    EXPECT_EQ(out.equals("3"), true);

    // Left operand wins for && when the right is falsy; right for ||.
    out = runJitTemplate("<cfoutput>#2 && 0#</cfoutput>", variables);
    EXPECT_EQ(out.equals("0"), true);

    out = runJitTemplate("<cfoutput>#0 || 0#</cfoutput>", variables);
    EXPECT_EQ(out.equals("0"), true);

    // Mixed with word forms and variables.
    variables.set("A");
    variables["A"] = cfvariant(2);
    variables.set("B");
    variables["B"] = cfvariant(3);
    out = runJitTemplate("<cfoutput>#a && b#</cfoutput>", variables);
    EXPECT_EQ(out.equals("3"), true);

    out = runJitTemplate("<cfoutput>#a || 0#</cfoutput>", variables);
    EXPECT_EQ(out.equals("2"), true);

    // cfif conditions with symbolic operators.
    out = runJitTemplate("<cfif 1 && 1>Y<cfelse>N</cfif>", variables);
    EXPECT_EQ(out.equals("Y"), true);

    out = runJitTemplate("<cfif 1 && 0>Y<cfelse>N</cfif>", variables);
    EXPECT_EQ(out.equals("N"), true);

    out = runJitTemplate("<cfif 0 || 1>Y<cfelse>N</cfif>", variables);
    EXPECT_EQ(out.equals("Y"), true);

    out = runJitTemplate("<cfif 0 || 0>Y<cfelse>N</cfif>", variables);
    EXPECT_EQ(out.equals("N"), true);
}

TEST_F(SharpOutputTest, InterpreterUnaryNotPrecedence) {
    // NOT binds looser than comparisons: NOT 0 GT 3 == NOT(0 GT 3) == true.
    outputExpr("(NOT 0 GT 3)");
    EXPECT_EQ(out.equals("YES"), true);

    // NOT binds tighter than AND: NOT 0 AND 1 == (NOT 0) AND 1 == 1.
    out.clear();
    outputExpr("(NOT 0 AND 1)");
    EXPECT_EQ(out.equals("1"), true);
}

TEST_F(SharpOutputTest, InterpreterUnaryMinus) {
    outputExpr("(-5)");
    EXPECT_EQ(out.equals("-5"), true);

    out.clear();
    outputExpr("(+5)");
    EXPECT_EQ(out.equals("5"), true);

    out.clear();
    outputExpr("(-(2 + 3))");
    EXPECT_EQ(out.equals("-5"), true);
}

TEST_F(SharpOutputTest, InterpreterOperatorsWithFunctionsAndIndexing) {
    outputExpr("(Len(\"abc\") + 2)");
    EXPECT_EQ(out.equals("5"), true);

    out.clear();
    outputExpr("(Max(2, 3) * 2)");
    EXPECT_EQ(out.equals("6"), true);

    out.clear();
    outputExpr("(Len(\"abc\") + Len(\"de\"))");
    EXPECT_EQ(out.equals("5"), true);

    // Array indexing on the left of an operator.
    cfvariant arr(cfvariant::Array);
    arr.insert(cfvariant(10));
    arr.insert(cfvariant(20));
    variables.set("ARR");
    variables["ARR"] = arr;
    out.clear();
    outputExpr("(arr[1] + arr[2])");
    EXPECT_EQ(out.equals("30"), true);

    out.clear();
    outputExpr("(arr[1] & arr[2])");
    EXPECT_EQ(out.equals("1020"), true);

    out.clear();
    outputExpr("(arr[1] + arr[2] * 2)");
    EXPECT_EQ(out.equals("50"), true);
}

TEST_F(SharpOutputTest, InterpreterOperatorStringInterpolation) {
    variables.set("A");
    variables["A"] = cfvariant(3);
    variables.set("B");
    variables["B"] = cfvariant(4);

    // Interpolation inside a string literal is itself a full expression.
    out = runJitTemplate("<cfoutput>[#\"x #a + b# y\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[x 7 y]"), true);

    out = runJitTemplate("<cfoutput>[#\"#a + b# z\"#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("[7 z]"), true);
}

TEST_F(SharpOutputTest, JitIntegerDivEqvImpOperators) {
    // '\', EQV and IMP previously compiled to cfvariant_compare and returned
    // NO/0; they now route to cfvariant_idiv / compareVariants.
    out = runJitTemplate("<cfset a = 5 \\ 2><cfoutput>#a#</cfoutput>", variables);
    EXPECT_EQ(out.equals("2"), true);

    out = runJitTemplate("<cfset b = true EQV true><cfoutput>#b#</cfoutput>", variables);
    EXPECT_EQ(out.equals("YES"), true);

    out = runJitTemplate("<cfset c = false IMP true><cfoutput>#c#</cfoutput>", variables);
    EXPECT_EQ(out.equals("YES"), true);

    out = runJitTemplate("<cfset d = true IMP false><cfoutput>#d#</cfoutput>", variables);
    EXPECT_EQ(out.equals("NO"), true);

    out = runJitTemplate("<cfset e = \"hello\" CONTAINS \"ell\"><cfoutput>#e#</cfoutput>", variables);
    EXPECT_EQ(out.equals("YES"), true);
}

TEST_F(SharpOutputTest, InterpreterUndefinedVarStillLiteral) {
    // BUGS.md #4: an undefined #...# name now throws instead of rendering its
    // literal text.
    bool caught = false;
    try {
        outputExpr("undefinedVar");
    } catch (const webstrada::exception &ex) {
        caught = true;
        EXPECT_EQ(string(ex.what()).equals("Variable UNDEFINEDVAR is undefined."), true);
    }
    EXPECT_EQ(caught, true);
}

TEST_F(SharpOutputTest, InterpreterDefinedVarRenders) {
    // A defined variable keeps rendering normally.
    variables.set("DEFINEDVAR");
    variables["DEFINEDVAR"] = cfvariant(42);
    out = runJitTemplate("<cfoutput>#definedVar#</cfoutput>", variables);
    EXPECT_EQ(out.equals("42"), true);
}

TEST_F(SharpOutputTest, NotequalIsNotAnOperator) {
    // BUGS.md #8: NOTEQUAL (single word) is not a valid CF operator (CF 2021
    // rejects it in every context). It must not be treated as NEQ; like any
    // other unrecognized word it falls through the generic unknown-expression
    // path, where the unknown name now throws (BUGS.md #4) exactly as CF 2021
    // rejects the template.
    bool caught = false;
    try {
        outputExpr("(5 NOTEQUAL 4)");
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    caught = false;
    try {
        outputExpr("(5 FOO 4)");
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    // The valid CF inequality operators must keep working.
    out.clear();
    outputExpr("(5 NEQ 4)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 NOT EQUAL 4)");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("(5 IS NOT 4)");
    EXPECT_EQ(out.equals("YES"), true);
}

TEST_F(SharpOutputTest, SymbolicAngleComparisonRejected) {
    // BUGS.md #8: CF rejects the symbolic < > <= >= comparison operators inside
    // #...# (its tag parser consumes < and > as tag delimiters), so the engine
    // must not evaluate them leniently — it throws, mirroring CF's template abort.
    variables.set("a");
    variables["a"] = cfvariant(5);
    variables.set("b");
    variables["b"] = cfvariant(3);

    bool caught = false;
    std::string msg;
    try {
        outputExpr("a < b");
    } catch (const webstrada::exception &ex) {
        caught = true;
        msg = ex.m_message.constData();
    }
    EXPECT_EQ(caught, true);
    EXPECT_EQ(msg.find("Illegal symbolic comparison") != std::string::npos, true);

    caught = false;
    try {
        outputExpr("a > b");
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    caught = false;
    try {
        outputExpr("a <= b");
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    caught = false;
    try {
        outputExpr("a >= b");
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    // Parenthesized symbolic comparisons are rejected too.
    caught = false;
    try {
        outputExpr("(a < b)");
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    // The word forms and ==/!= remain valid.
    out.clear();
    outputExpr("a LT b");
    EXPECT_EQ(out.equals("NO"), true);

    out.clear();
    outputExpr("a GT b");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("a LTE a");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("a GTE b");
    EXPECT_EQ(out.equals("YES"), true);

    out.clear();
    outputExpr("a != b");
    EXPECT_EQ(out.equals("YES"), true);

    // A symbolic angle inside a quoted string literal is NOT an operator, so it
    // must keep working (CF accepts it).
    out.clear();
    variables.set("x");
    variables["x"] = cfvariant("a < b");
    outputExpr("x EQ \"a < b\"");
    EXPECT_EQ(out.equals("YES"), true);
}

TEST_F(SharpOutputTest, JitSymbolicAngleComparisonRejected) {
    variables.set("a");
    variables["a"] = cfvariant(5);
    variables.set("b");
    variables["b"] = cfvariant(3);

    // cfoutput body: engine must reject, mirroring CF's template abort.
    bool caught = false;
    try {
        runJitTemplate("<cfoutput>#a < b#</cfoutput>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    caught = false;
    try {
        runJitTemplate("<cfoutput>#a <= b#</cfoutput>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    // String-literal interpolation in cfscript is rejected too (CF 2021 rejects it).
    caught = false;
    try {
        runJitTemplate("<cfscript>writeOutput(\"#a < b#\");</cfscript>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    // Direct cfscript expressions keep the symbolic operators (CF accepts them).
    out = runJitTemplate("<cfscript>writeOutput(1 < 2);</cfscript>", variables);
    EXPECT_EQ(out.equals("YES"), true);

    out = runJitTemplate("<cfscript>writeOutput(3 >= 3);</cfscript>", variables);
    EXPECT_EQ(out.equals("YES"), true);

    // A symbolic angle inside a quoted string within interpolation still works.
    out = runJitTemplate("<cfoutput>#\"a < b\" EQ \"a < b\"#</cfoutput>", variables);
    EXPECT_EQ(out.equals("YES"), true);

    variables.set("x");
    variables["x"] = cfvariant("a < b");
    out = runJitTemplate("<cfscript>writeOutput(\"#x EQ 'a < b'#\");</cfscript>", variables);
    EXPECT_EQ(out.equals("YES"), true);
}

TEST_F(SharpOutputTest, LeadingSharpQuoteRejected) {
    // BUGS.md #2: a leading # that cannot close as a #...# expression in a
    // <cfoutput> body is tokenized as literal text by textparser 1.0.6. CF 2021
    // rejects such templates outright (server-error, empty body), so the engine
    // must throw at compile time instead of rendering the stray '#' leniently.
    bool caught = false;
    try {
        runJitTemplate("<cfoutput>#\"x #a#\"</cfoutput>", variables);
    } catch (const webstrada::exception &ex) {
        caught = true;
        EXPECT_EQ(ex.m_message.equals("Parsing error!"), true);
    }
    EXPECT_EQ(caught, true);
}

TEST_F(SharpOutputTest, LoneSharpInBodyRejected) {
    // The same class of divergence: any '#' in a <cfoutput> body that is not a
    // complete #...# expression or an escaped ## is a parse error in CF 2021.
    std::vector<const char*> rejected = {
        "<cfoutput>a#b</cfoutput>",
        "<cfoutput>#a</cfoutput>",
        "<cfoutput>text #a# more #b</cfoutput>",
        "<cfoutput>#</cfoutput>",
        "<cfoutput>##a#</cfoutput>",
        "<cfoutput><cfif true>#</cfif></cfoutput>",
    };
    for (auto code : rejected) {
        bool caught = false;
        try {
            runJitTemplate(code, variables);
        } catch (const webstrada::exception &ex) {
            caught = true;
            EXPECT_EQ(ex.m_message.equals("Parsing error!"), true);
        }
        EXPECT_EQ(caught, true) << code;
    }
}

TEST_F(SharpOutputTest, SharpEscapesAndLiteralTextAccepted) {
    // Verified against CF 2021: these <cfoutput> bodies still compile and render
    // byte-for-byte, including the closed leading-#" form and ## escapes.
    variables.set("a");
    variables["a"] = cfvariant(5);

    out = runJitTemplate("<cfoutput>#\"x #a#\"#</cfoutput>", variables);
    EXPECT_EQ(out.equals("x 5"), true);

    out = runJitTemplate("<cfoutput>\"x #a#\"</cfoutput>", variables);
    EXPECT_EQ(out.equals("\"x 5\""), true);

    out = runJitTemplate("<cfoutput>##</cfoutput>", variables);
    EXPECT_EQ(out.equals("#"), true);

    out = runJitTemplate("<cfoutput>#a#</cfoutput>", variables);
    EXPECT_EQ(out.equals("5"), true);

    // Trailing literal text with no '#' is fine.
    out = runJitTemplate("<cfoutput>#a# x</cfoutput>", variables);
    EXPECT_EQ(out.equals("5 x"), true);

    // ## escapes surrounded by literal text are fine.
    out = runJitTemplate("<cfoutput>a ## b</cfoutput>", variables);
    EXPECT_EQ(out.equals("a # b"), true);

    // A complete #...# pair inside otherwise-literal text is fine.
    out = runJitTemplate("<cfoutput>ab#a#cd</cfoutput>", variables);
    EXPECT_EQ(out.equals("ab5cd"), true);
}

TEST_F(SharpOutputTest, BareFunctionNameIsMethodHandle) {
    // A bare reference to a built-in function name (e.g. #pi#, #abs#) is a
    // method handle, not an undefined variable (previously BUGS.md #3). The
    // handle stringifies as coldfusion.runtime.CFPageMethod@<hash>; the hash is
    // ColdFusion's per-JVM object identity hash, so only the deterministic
    // prefix is asserted here. Verified byte-for-byte against CF 2021 in
    // tests/cfm/cfloop_function_handle_test.cfm.
    out = runJitTemplate("<cfoutput>#Left(ToString(pi), 32)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("coldfusion.runtime.CFPageMethod@"), true);

    out = runJitTemplate("<cfoutput>#Left(ToString(abs), 32)#|#Left(ToString(len), 32)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("coldfusion.runtime.CFPageMethod@|coldfusion.runtime.CFPageMethod@"), true);

    // The full string matches the CFPageMethod pattern.
    out = runJitTemplate("<cfoutput>#pi#</cfoutput>", variables);
    EXPECT_EQ(out.startWith("coldfusion.runtime.CFPageMethod@"), true);
    EXPECT_EQ(out.length() > 32, true);

    // Predicates on the handle match CF 2021.
    out = runJitTemplate("<cfoutput>#IsObject(pi)#|#IsSimpleValue(pi)#|#IsCustomFunction(pi)#|#IsClosure(pi)#|#IsStruct(pi)#|#IsArray(pi)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("YES|NO|NO|NO|NO|NO"), true);

    // A variable with the same name shadows the built-in function.
    variables.set("pi");
    variables["pi"] = cfvariant(99);
    out = runJitTemplate("<cfoutput>#pi#</cfoutput>", variables);
    EXPECT_EQ(out.equals("99"), true);

    // A name that is not a built-in function still throws as undefined.
    bool caught = false;
    try {
        runJitTemplate("<cfoutput>#notafunction#</cfoutput>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);
}

TEST_F(SharpOutputTest, JitScriptMethodHandle) {
    // BUGS.md #2: the JIT cfscript expression path previously compiled a bare
    // identifier to a variable lookup, so <cfscript>writeOutput(IsObject(pi));</cfscript>
    // threw "Variable 'pi' is undefined." while CF 2021 renders YES. The bare
    // identifier now resolves to a method handle like the interpreter path.
    out = runJitTemplate("<cfscript>writeOutput(IsObject(pi));</cfscript>", variables);
    EXPECT_EQ(out.equals("YES"), true);

    out = runJitTemplate("<cfscript>writeOutput(IsObject(abs));writeOutput(IsObject(len));</cfscript>", variables);
    EXPECT_EQ(out.equals("YESYES"), true);

    // Parenthesized form resolves the same way.
    out = runJitTemplate("<cfscript>writeOutput(IsObject((pi)));</cfscript>", variables);
    EXPECT_EQ(out.equals("YES"), true);

    // A bare reference renders the handle text (writeOutput(pi) and the
    // interpolated writeOutput("#pi#") — CF renders coldfusion.runtime.CFPageMethod@<hash>).
    out = runJitTemplate("<cfscript>writeOutput(pi);</cfscript>", variables);
    EXPECT_EQ(out.startWith("coldfusion.runtime.CFPageMethod@"), true);

    out = runJitTemplate("<cfscript>writeOutput(\"#pi#\");</cfscript>", variables);
    EXPECT_EQ(out.startWith("coldfusion.runtime.CFPageMethod@"), true);

    // The handle is deterministic and identical to the #...# interpreter path.
    out = runJitTemplate("<cfscript>writeOutput(\"#pi#\");</cfscript><cfoutput>[#pi#]</cfoutput>", variables);
    EXPECT_EQ(out.equals("coldfusion.runtime.CFPageMethod@9f9[coldfusion.runtime.CFPageMethod@9f9]"), true);

    // Predicates on the JIT handle match CF 2021.
    out = runJitTemplate("<cfscript>writeOutput(IsObject(pi));writeOutput(IsSimpleValue(pi));writeOutput(IsCustomFunction(pi));writeOutput(IsClosure(pi));writeOutput(IsStruct(pi));writeOutput(IsArray(pi));</cfscript>", variables);
    EXPECT_EQ(out.equals("YESNONONONONO"), true);

    // A variable shadows the built-in function.
    variables.set("pi");
    variables["pi"] = cfvariant(99);
    out = runJitTemplate("<cfscript>writeOutput(pi);</cfscript>", variables);
    EXPECT_EQ(out.equals("99"), true);
}

TEST_F(SharpOutputTest, JitScriptMethodHandleChainBaseRejected) {
    // A chain base (s.x / arr[1]) never falls back to a method handle: CF 2021
    // rejects IsObject(pi.foo) with a server error, and a plain undefined name
    // that is not a built-in still throws Variable X is undefined.
    bool caught = false;
    try {
        runJitTemplate("<cfscript>writeOutput(IsObject(pi.foo));</cfscript>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    caught = false;
    try {
        runJitTemplate("<cfscript>writeOutput(IsObject(pi[1]));</cfscript>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);

    caught = false;
    try {
        runJitTemplate("<cfscript>writeOutput(IsObject(notafunction));</cfscript>", variables);
    } catch (const webstrada::exception &) { caught = true; }
    EXPECT_EQ(caught, true);
}

// ---- User-defined functions and closures ----

class UdfTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }
};

TEST_F(UdfTest, RegisterAndCall) {
    string out = runJitTemplate("<cfscript>function add(a, b) { return a + b; } writeOutput(add(2, 3));</cfscript>", variables);
    EXPECT_EQ(out.equals("5"), true);
}

TEST_F(UdfTest, DeclaredInsideCfoutputScriptIsHoisted) {
    // A UDF whose declaration lives in a <cfscript> block nested inside
    // <cfoutput> is still a page-level function (CF hoists it and it is callable
    // at the call site). Previously the page-level UDF registration pass only
    // scanned top-level <cfscript> tokens, so a <cfoutput>-nested declaration
    // threw "Variable F is undefined." (was BUGS.md "User-defined functions
    // declared inside <cfoutput><cfscript> are not registered"). Verified
    // against CF 2025 on the RDS host.
    string out = runJitTemplate(
        "<cfoutput><cfscript>function f() { return \"x\"; } writeOutput(f());</cfscript></cfoutput>",
        variables
    );
    EXPECT_EQ(out.equals("x"), true);

    // The same UDF is also callable from a later, separate top-level script.
    variables = cfvariant::Struct;
    out = runJitTemplate(
        "<cfoutput><cfscript>function g() { return 42; }</cfscript></cfoutput>"
        "<cfscript>writeOutput(g());</cfscript>",
        variables
    );
    EXPECT_EQ(out.equals("42"), true);
}

TEST_F(UdfTest, HoistedAcrossTemplate) {
    // Trailing newline matches real .cfm files (CF emits a trailing space after
    // the <cfscript> when the file ends with a newline).
    string out = runJitTemplate("<cfoutput>#earlyCall(5)#</cfoutput><cfscript>function earlyCall(n) { return \"E\" & n; }</cfscript>\n", variables);
    EXPECT_EQ(out.equals("E5 "), true);
}

TEST_F(UdfTest, Recursion) {
    string out = runJitTemplate("<cfscript>function fact(n) { if (n <= 1) return 1; return n * fact(n - 1); } writeOutput(fact(5));</cfscript>", variables);
    EXPECT_EQ(out.equals("120"), true);
}

TEST_F(UdfTest, DefaultParams) {
    string out = runJitTemplate("<cfscript>function greet(name, p = \"!\") { return \"Hi \" & name & p; } writeOutput(greet(\"A\") & \"|\" & greet(\"B\", \"?\"));</cfscript>", variables);
    EXPECT_EQ(out.equals("Hi A!|Hi B?"), true);
}

TEST_F(UdfTest, NamedArguments) {
    // Named arguments bind by parameter name; missing params use their defaults
    // (was BUGS.md "Named arguments in function calls are not supported").
    // Verified against CF 2025 on the RDS host.
    string out = runJitTemplate(
        "<cfscript>function f(a=\"DA\", b=\"DB\", c=\"DC\") { return \"a=\" & a & \"|b=\" & b & \"|c=\" & c; }"
        "writeOutput(f(c=\"z\"));"
        "writeOutput(\"|\" & f(b=\"y\", a=\"x\"));"
        "writeOutput(\"|\" & f(\"p\", \"q\", \"r\"));"
        "</cfscript>",
        variables
    );
    EXPECT_EQ(out.equals("a=DA|b=DB|c=z|a=x|b=y|c=DC|a=p|b=q|c=r"), true);
}

TEST_F(UdfTest, NamedArgumentsInterpreter) {
    // The cfoutput interpreter path dispatches named args too.
    string out = runJitTemplate(
        "<cfscript>function g(a=\"D\", b=\"E\") { return a & b; }</cfscript>"
        "<cfoutput>#g(b=\"B\")#|#g(a=\"A\")#</cfoutput>",
        variables
    );
    EXPECT_EQ(out.equals("DB|AE"), true);
}

TEST_F(UdfTest, NamedArgumentsUnknownNameThrows) {
    // An unknown named-argument name must NOT throw: CF silently accepts it
    // into the `arguments` scope and only binds the matching declared params
    // (verified on CF 2025: `f(zzz="x")` where f declares `a` -> "Variable A
    // is undefined.", not an argument-name error; `f(a="DA")` called
    // `f(zzz="x")` -> arguments keys `A,zzz`). Was BUGS.md "named args to a
    // no-param function throw" — `cf_named_args_reorder` rejected any name
    // that matched no declared parameter, so MangoBlog's paragraphFormatter
    // `initSettings(paragraphComments=true, ...)` (which declares no
    // parameters) threw on every call.
    string out = runJitTemplate(
        "<cfscript>function g(a=\"DA\") { return structKeyList(arguments) & \"=\" & arguments.a; }"
        "writeOutput(g(zzz=\"x\"));"
        "writeOutput(\"|\" & g(a=\"ok\"));"
        "writeOutput(\"|\" & g(y=\"1\", a=\"2\"));"
        "writeOutput(\"|\" & g());"
        "</cfscript>",
        variables
    );
    EXPECT_EQ(out.equals("A,zzz=DA|A=ok|A,y=2|A=DA"), true);
}

TEST_F(UdfTest, NamedArgumentsNoParamsFunction) {
    // A function that declares NO parameters accepts named arguments straight
    // into its `arguments` scope under their original casing (verified on CF
    // 2025: `f(a=1, b=2)` returns `a,b`). This is MangoBlog's
    // paragraphFormatter BasePlugin.initSettings pattern.
    string out = runJitTemplate(
        "<cfscript>function f() { return structKeyList(arguments); }"
        "writeOutput(f(a=1, b=2));"
        "writeOutput(\"|\" & f(x=1));"
        "</cfscript>",
        variables
    );
    EXPECT_EQ(out.equals("a,b|x"), true);
}

TEST_F(UdfTest, NamedArgumentLiterallyNamedVar) {
    // `var` is tokenized as a Keyword by the textparser, but CF 2025 accepts
    // it as a named-argument name (trace(var="x"), two(var="hello")). Was
    // BUGS.md "var cannot be used as a named function argument".
    string out = runJitTemplate(
        "<cfscript>function two(var=\"D\", other=\"O\") { return arguments.var & \"|\" & arguments.other; }"
        "writeOutput(two(var=\"hello\"));"
        "writeOutput(\"|\" & two(var=\"a\", other=\"b\"));"
        "writeOutput(\"|\" & two());"
        "writeOutput(\"|\" & two(\"pos\"));"
        "</cfscript>",
        variables
    );
    EXPECT_EQ(out.equals("hello|O|a|b|D|O|pos|O"), true);
}

TEST_F(UdfTest, NamedArgumentLiterallyNamedName) {
    // A named argument whose name is `name` (`c.two(name="x", value="2")`)
    // is a bare variable in the codegen, not a declaration. Was BUGS.md "A
    // script named argument whose argument name is `name` is misparsed".
    string out = runJitTemplate(
        "<cfscript>c = {two: function(name=\"\", value=\"\") { return arguments.name & \"=\" & arguments.value; }};"
        "writeOutput(c.two(name=\"x\", value=\"2\"));"
        "</cfscript>",
        variables
    );
    EXPECT_EQ(out.equals("x=2"), true);
}

TEST_F(UdfTest, MemberAccessOnVarNamedParam) {
    // `arguments.var` — `var` as a member name after '.' — is also a Keyword
    // in the textparser; CF accepts it. Was part of BUGS.md "var cannot be
    // used as a named function argument" (the keyword was dropped and the
    // member op lost its right operand).
    string out = runJitTemplate(
        "<cfscript>function two(var=\"hello\") { return arguments.var; } writeOutput(two());</cfscript>",
        variables
    );
    EXPECT_EQ(out.equals("hello"), true);
}

TEST_F(UdfTest, NamedArgumentsMissingRequiredThrows) {
    // A missing required parameter (no default, not supplied) is undefined.
    bool caught = false;
    try {
        runJitTemplate("<cfscript>function f(a, b) { return a & b; } writeOutput(f(b=\"x\"));</cfscript>", variables);
    } catch (const webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(UdfTest, ArgumentsScope) {
    string out = runJitTemplate("<cfscript>function sumAll() { t = 0; for (i = 1; i <= arrayLen(arguments); i++) { t = t + arguments[i]; } return t; } writeOutput(sumAll(1,2,3,4));</cfscript>", variables);
    EXPECT_EQ(out.equals("10"), true);
}

TEST_F(UdfTest, ArgumentsVisibleKeysMatchCf) {
    string out = runJitTemplate("<cfscript>function t(a, b) { return structKeyList(arguments) & \"|\" & structCount(arguments); } writeOutput(t(\"one\") & \"|\" & t(\"one\",\"two\",\"three\"));</cfscript>", variables);
    EXPECT_EQ(out.equals("A,B|2|A,B,3|3"), true);
}

TEST_F(UdfTest, LocalScopeExcludesArguments) {
    // CF's `local` scope holds only var-declared names + ARGUMENTS; the
    // arguments are NOT keys of `local` (was BUGS.md "Function arguments are
    // exposed in the local scope").
    string out = runJitTemplate(
        "<cfscript>function f(a, b) { var v = \"X\"; "
        "var r = (listFindNoCase(structKeyList(local),\"A\") EQ 0) & \",\" & "
        "(listFindNoCase(structKeyList(local),\"V\") GT 0) & \",\" & "
        "(listFindNoCase(structKeyList(local),\"ARGUMENTS\") GT 0) & \",\" & "
        "isDefined(\"local.a\") & \",\" & isDefined(\"local.v\") & \",\" & a & \",\" & b; "
        "return r; } "
        "writeOutput(f(\"A\",\"B\"));</cfscript>", variables);
    EXPECT_EQ(out.equals("YES,YES,YES,NO,YES,A,B"), true) << out.constData();

    // Unqualified writes to a parameter go to the `arguments` scope, not local.
    out = runJitTemplate(
        "<cfscript>function f(a) { a = \"M\"; return arguments.a & \",\" & isDefined(\"local.a\"); } "
        "writeOutput(f(\"A\"));</cfscript>", variables);
    EXPECT_EQ(out.equals("M,NO"), true) << out.constData();
}

TEST_F(UdfTest, LocalShadowingAndArgumentWrites) {
    // `local.arg1 = L` creates a local that shadows the argument for reads;
    // `arguments.arg1 = Y` / unqualified `arg1 = Y` write only `arguments`.
    string out = runJitTemplate(
        "<cfscript>function g(a) { local.a = \"L\"; arguments.a = \"Y\"; "
        "return local.a & \",\" & arguments.a & \",\" & a; } "
        "writeOutput(g(\"A\"));</cfscript>", variables);
    EXPECT_EQ(out.equals("L,Y,L"), true) << out.constData();

    out = runJitTemplate(
        "<cfscript>function h(a) { local.a = \"L\"; a = \"Y\"; "
        "return local.a & \",\" & arguments.a & \",\" & a; } "
        "writeOutput(h(\"A\"));</cfscript>", variables);
    EXPECT_EQ(out.equals("L,Y,L"), true) << out.constData();
}

TEST_F(UdfTest, VarCannotShadowParameter) {
    // CF rejects a var-declared name that collides with a parameter at compile
    // time: "A is already defined in argument scope."
    bool caught = false;
    try {
        runJitTemplate("<cfscript>function f(a) { var a = \"V\"; return a; } writeOutput(f(\"A\"));</cfscript>", variables);
    } catch (const webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
    caught = false;
    try {
        runJitTemplate("<cffunction name=\"g\" output=\"false\"><cfargument name=\"a\"><cfset var a = \"V\"></cffunction><cfoutput>x</cfoutput>", variables);
    } catch (const webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(UdfTest, ClosureCapturesParameter) {
    // A closure captures the enclosing function's parameters (which live in the
    // enclosing `arguments` scope, not its `local`).
    string out = runJitTemplate(
        "<cfscript>function makeFactory(b) { return function(x) { return x * b; }; } "
        "f5 = makeFactory(5); f7 = makeFactory(7); writeOutput(f5(3) & \",\" & f7(3));</cfscript>", variables);
    EXPECT_EQ(out.equals("15,21"), true) << out.constData();
}

TEST_F(UdfTest, VarScopeAndUnqualifiedLeak) {
    // var-declared names stay function-local; unqualified writes leak to the
    // calling (page) variables scope — the classic CF UDF gotcha.
    string out = runJitTemplate("<cfscript>outer = 100; function usesOuter() { localVar = 5; return outer + localVar; } writeOutput(usesOuter() & \"|\" & localVar);</cfscript>", variables);
    EXPECT_EQ(out.equals("105|5"), true);

    out = runJitTemplate("<cfscript>x = 100; function shadowTest() { var x = 1; return x; } writeOutput(shadowTest() & \"|\" & x);</cfscript>", variables);
    EXPECT_EQ(out.equals("1|100"), true);
}

TEST_F(UdfTest, UdfVariablesWritesPageScope) {
    // Inside a plain script UDF in a .cfm, `variables` is the CALLING page's
    // variables scope (was BUGS.md "UDF: variables.foo"): `variables.foo = 1`
    // sets a page variable visible after the call, and `var`/local shadowing
    // still isolates the function's own scope.
    string out = runJitTemplate(
        "<cfscript>function setPageVar() { variables.foo = 1; }"
        "setPageVar();"
        "writeOutput(isDefined(\"foo\") & \"|\" & variables.foo);</cfscript>",
        variables);
    EXPECT_EQ(out.equals("YES|1"), true);
}

