TEST_F(UdfTest, TagFunctionWriteOutputInBody) {
    // writeOutput inside a tag-form function follows the output attribute.
    string out = runJitTemplate(
        "<cffunction name=\"w\" output=\"true\"><cfset writeOutput(\"W1 \")><cfreturn \"R\"></cffunction>"
        "<cfoutput>#w()#</cfoutput>\n", variables);
    EXPECT_EQ(out.equals("W1 R "), true);
}

// ---------------------------------------------------------------------------
// QueryNew / Query value tests.
// ---------------------------------------------------------------------------

class QueryNewTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    // Runs CFML via the JIT and returns the output string.
    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }

    // Runs CFML that assigns a query to a variable and returns the query payload.
    const QueryData *queryData(const string &cfml_code) {
        run(cfml_code);
        cfvariant *q = &variables["q"];
        if (!q || q->m_type != cfvariant::Query || !q->m_query) {
            throw std::runtime_error("Expected a query variable named q");
        }
        return q->m_query;
    }

    // Returns the string form of a cell (toString is non-const).
    static string cellStr(const cfvariant &cell) {
        cfvariant copy(cell);
        return copy.toString();
    }
};

TEST_F(QueryNewTest, BasicColumnListAndRecordCount) {
    run("<cfset q = QueryNew(\"a,b,c\")>");
    EXPECT_EQ(variables["q"].m_type, cfvariant::Query);
    EXPECT_EQ(queryData("<cfset q = QueryNew(\"a,b,c\")>")->columns.size(), 3u);
    EXPECT_EQ(queryData("<cfset q = QueryNew(\"a,b,c\")>")->rowCount(), 0);
}

TEST_F(QueryNewTest, ColumnListSortedAndUppercased) {
    // CF sorts and uppercases query.columnlist (verified against CF 2021).
    run("<cfset q = QueryNew(\"c,a,b\")>");
    const QueryData *qd = queryData("<cfset q = QueryNew(\"c,a,b\")>");
    EXPECT_EQ(qd->columns[0].name.equals("c"), true);   // insertion order kept
    EXPECT_EQ(qd->columns[1].name.equals("a"), true);
    EXPECT_EQ(qd->columns[2].name.equals("b"), true);
    EXPECT_EQ(qd->rowCount(), 0);
}

TEST_F(QueryNewTest, RowDataStructArray) {
    run("<cfset q = QueryNew(\"name,age\", \"varchar,integer\", [{name:\"bob\",age:30},{name:\"alice\",age:25}])>");
    const QueryData *qd = queryData("<cfset q = QueryNew(\"name,age\", \"varchar,integer\", [{name:\"bob\",age:30},{name:\"alice\",age:25}])>");
    EXPECT_EQ(qd->rowCount(), 2);
    // varchar cells keep their string form; integer cells are parsed to int.
    EXPECT_EQ(cellStr(qd->columns[0].values[0]).equals("bob"), true);
    EXPECT_EQ(qd->columns[1].values[0].m_type, cfvariant::Number);
    EXPECT_EQ(qd->columns[1].values[0].m_int, 30);
    EXPECT_EQ(qd->columns[1].values[1].m_int, 25);
}

TEST_F(QueryNewTest, SingleStructRow) {
    run("<cfset q = QueryNew(\"a,b\", \"varchar,varchar\", {a:\"x\",b:\"y\"})>");
    const QueryData *qd = queryData("<cfset q = QueryNew(\"a,b\", \"varchar,varchar\", {a:\"x\",b:\"y\"})>");
    EXPECT_EQ(qd->rowCount(), 1);
    EXPECT_EQ(cellStr(qd->columns[0].values[0]).equals("x"), true);
    EXPECT_EQ(cellStr(qd->columns[1].values[0]).equals("y"), true);
}

TEST_F(QueryNewTest, PositionalArrayRows) {
    run("<cfset q = QueryNew(\"a,b\", \"varchar,varchar\", [[1,\"two\"],[4,\"five\"]])>");
    const QueryData *qd = queryData("<cfset q = QueryNew(\"a,b\", \"varchar,varchar\", [[1,\"two\"],[4,\"five\"]])>");
    EXPECT_EQ(qd->rowCount(), 2);
    EXPECT_EQ(cellStr(qd->columns[0].values[0]).equals("1"), true);
    EXPECT_EQ(cellStr(qd->columns[1].values[0]).equals("two"), true);
    EXPECT_EQ(cellStr(qd->columns[0].values[1]).equals("4"), true);
    EXPECT_EQ(cellStr(qd->columns[1].values[1]).equals("five"), true);
}

TEST_F(QueryNewTest, StructColumnListIsRowData) {
    // CF treats a struct first argument as row data: QueryNew({a:"integer",
    // b:"varchar"}) yields columns A,B with one row whose cells are the
    // struct's values, all varchar (verified against CF 2021).
    run("<cfset q = QueryNew({a:\"integer\", b:\"varchar\"})>");
    const QueryData *qd = queryData("<cfset q = QueryNew({a:\"integer\", b:\"varchar\"})>");
    EXPECT_EQ(qd->columns.size(), 2u);
    EXPECT_EQ(qd->rowCount(), 1);
    EXPECT_EQ(cellStr(qd->columns[0].values[0]).equals("integer"), true);
    EXPECT_EQ(cellStr(qd->columns[1].values[0]).equals("varchar"), true);
}

TEST_F(QueryNewTest, EmptyColumnList) {
    run("<cfset q = QueryNew(\"\")>");
    const QueryData *qd = queryData("<cfset q = QueryNew(\"\")>");
    EXPECT_EQ(qd->columns.size(), 0u);
    EXPECT_EQ(qd->rowCount(), 0);
}

TEST_F(QueryNewTest, TypeCoercionInteger) {
    // "30.9" -> 30 (truncated), "5" -> 5 (verified against CF 2021).
    run("<cfset q = QueryNew(\"a\", \"integer\", [{a:\"30.9\"},{a:\"5\"}])>");
    const QueryData *qd = queryData("<cfset q = QueryNew(\"a\", \"integer\", [{a:\"30.9\"},{a:\"5\"}])>");
    EXPECT_EQ(qd->columns[0].values[0].m_type, cfvariant::Number);
    EXPECT_EQ(qd->columns[0].values[0].m_int, 30);
    EXPECT_EQ(qd->columns[0].values[1].m_int, 5);
}

TEST_F(QueryNewTest, MissingRowDataStaysNull) {
    // A row missing a typed column keeps its cell null (serializes as null).
    run("<cfset q = QueryNew(\"name,age\", \"varchar,integer\", [{name:\"bob\",age:30},{name:\"x\"}])>");
    const QueryData *qd = queryData("<cfset q = QueryNew(\"name,age\", \"varchar,integer\", [{name:\"bob\",age:30},{name:\"x\"}])>");
    EXPECT_EQ(qd->columns[1].values[1].m_type, cfvariant::Null);
}

TEST_F(QueryNewTest, ExtraStructKeyThrows) {
    // A struct row with a key that is not a declared column throws (CF: Expression).
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"a,b\", \"varchar,varchar\", [{a:\"x\",b:\"y\",c:\"z\"}])>");
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryNewTest, MissingArgThrows) {
    bool caught = false;
    try {
        run("<cfset q = QueryNew()>");
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryNewTest, MemberAccessDotAndBracket) {
    string out = run("<cfset q = QueryNew(\"name,age\", \"varchar,integer\", [{name:\"bob\",age:30}])><cfoutput>#q.recordcount#|#q.columnlist#|#q.name[1]#|#q.age[1]#|#q[\"name\"][1]#|#q.currentrow#</cfoutput>");
    EXPECT_EQ(out.equals("1|AGE,NAME|bob|30|bob|1"), true);
}

TEST_F(QueryNewTest, MemberAccessUnknownColumnThrows) {
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"a\")><cfoutput>#q.nope[1]#</cfoutput>");
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryNewTest, SerializeJSONQuery) {
    // Byte-matched against CF 2021.
    string out = run("<cfset q = QueryNew(\"name,age\", \"varchar,integer\", [{name:\"bob\",age:30},{name:\"x\"}])><cfoutput>#serializeJSON(q)#</cfoutput>");
    EXPECT_EQ(out.equals("{\"COLUMNS\":[\"NAME\",\"AGE\"],\"DATA\":[[\"bob\",30],[\"x\",null]]}"), true);
}

TEST_F(QueryNewTest, SerializeJSONQueryDoubleCell) {
    string out = run("<cfset q = QueryNew(\"score\", \"double\", [{score:1.5}])><cfoutput>#serializeJSON(q)#</cfoutput>");
    EXPECT_EQ(out.equals("{\"COLUMNS\":[\"SCORE\"],\"DATA\":[[1.5]]}"), true);
}

TEST_F(QueryNewTest, SerializeJSONQueryBigintCell) {
    string out = run("<cfset q = QueryNew(\"big\", \"bigint\", [{big:2147483648}])><cfoutput>#serializeJSON(q)#</cfoutput>");
    EXPECT_EQ(out.equals("{\"COLUMNS\":[\"BIG\"],\"DATA\":[[2147483648]]}"), true);
}

TEST_F(QueryNewTest, SerializeJSONQueryDateCell) {
    // CF serializes date cells as "January, 01 2020 00:00:00".
    string out = run("<cfset q = QueryNew(\"dob\", \"date\", [{dob:createDate(2020,1,1)}])><cfoutput>#serializeJSON(q)#</cfoutput>");
    EXPECT_EQ(out.equals("{\"COLUMNS\":[\"DOB\"],\"DATA\":[[\"January, 01 2020 00:00:00\"]]}"), true);
}

TEST_F(QueryNewTest, CfdumpHtmlQuery) {
    // Byte-matched against CF 2021 (2 rows, 2 columns).
    string out = run("<cfset q = QueryNew(\"a,b\", \"varchar,varchar\", [{a:\"x\",b:\"y\"},{a:\"p\",b:\"q\"}])><cfdump var=\"#q#\">");
    EXPECT_EQ(out.contains("<table class=\"cfdump_query\">"), true);
    EXPECT_EQ(out.contains(">a</td>"), true);
    EXPECT_EQ(out.contains(">b</td>"), true);
    EXPECT_EQ(out.contains("x \r\n"), true);
    EXPECT_EQ(out.contains("y \r\n"), true);
    EXPECT_EQ(out.contains(">2</td>"), true);
}

TEST_F(QueryNewTest, CfdumpTextQuery) {
    // Byte-matched against CF 2021 text format.
    string out = run("<cfset q = QueryNew(\"a,b\", \"varchar,varchar\", [{a:\"x\",b:\"y\"},{a:\"p\",b:\"q\"}])><cfdump var=\"#q#\" format=\"text\">");
    EXPECT_EQ(out.equals("<pre>query\r\n\r\n \r\n[Record # 1] \r\na: x \r\nb: y\r\n \r\n[Record # 2] \r\na: p \r\nb: q\r\n</pre>"), true);
}

TEST_F(QueryNewTest, CfdumpMixedCaseColumnOrder) {
    // Unsorted/mixed-case input: cfdump sorts columns case-insensitively and
    // keeps the cell values aligned (regression: cells were indexed by the
    // sorted position instead of the original column index).
    string out = run("<cfset q = QueryNew(\"Name,AGE\", \"varchar,integer\", [{Name:\"x\",AGE:5}])><cfdump var=\"#q#\">");
    int agePos = out.indexOf(">AGE</td>");
    int namePos = out.indexOf(">Name</td>");
    EXPECT_EQ(agePos >= 0 && namePos >= 0 && agePos < namePos, true);   // AGE sorts before Name
    int fivePos = out.indexOf("5 \r\n");
    int xPos = out.indexOf("x \r\n");
    EXPECT_EQ(fivePos >= 0 && xPos >= 0 && fivePos < xPos, true);       // AGE cell (5) before Name cell (x)
}

TEST_F(QueryNewTest, IsQuery) {
    string out = run("<cfset q = QueryNew(\"a\")><cfoutput>#isQuery(q)#</cfoutput>");
    EXPECT_EQ(out.equals("YES"), true);
    out = run("<cfoutput>#isQuery(5)#</cfoutput>");
    EXPECT_EQ(out.equals("NO"), true);
}

// ---------------------------------------------------------------------------
// QueryAddColumn / QueryAddRow / QueryGetRow / QueryKeyExists / QuerySetCell /
// ValueList tests.
// ---------------------------------------------------------------------------

class QueryMutationTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }

    const QueryData *queryData() {
        cfvariant *q = &variables["q"];
        if (!q || q->m_type != cfvariant::Query || !q->m_query) {
            throw std::runtime_error("Expected a query variable named q");
        }
        return q->m_query;
    }

    static string cellStr(const cfvariant &cell) {
        cfvariant copy(cell);
        return copy.toString();
    }
};

TEST_F(QueryMutationTest, AddRowReturnsCount) {
    string out = run("<cfset q = QueryNew(\"a,b\")><cfset r1 = QueryAddRow(q)><cfset r2 = QueryAddRow(q)><cfset r3 = QueryAddRow(q, 2)><cfoutput>#q.recordcount#|#r1#|#r2#|#r3#</cfoutput>");
    EXPECT_EQ(out.equals("4|1|2|4"), true);
    EXPECT_EQ(queryData()->rowCount(), 4);
}

TEST_F(QueryMutationTest, AddRowStructAndArray) {
    run("<cfset q = QueryNew(\"a,b\")><cfset QueryAddRow(q, {a:\"x\", b:1})><cfset QueryAddRow(q, [{a:\"p\", b:2},{a:\"q\", b:3}])>");
    const QueryData *qd = queryData();
    EXPECT_EQ(qd->rowCount(), 3);
    EXPECT_EQ(cellStr(qd->columns[0].values[0]).equals("x"), true);
    EXPECT_EQ(qd->columns[1].values[1].m_int, 2);
    EXPECT_EQ(cellStr(qd->columns[0].values[2]).equals("q"), true);
}

TEST_F(QueryMutationTest, AddRowExtraKeyThrows) {
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"a,b\")><cfset QueryAddRow(q, {a:\"x\", b:1, c:9})>");
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryMutationTest, SetCellLastRowAndExplicit) {
    string out = run("<cfset q = QueryNew(\"a,b\", \"varchar,integer\")><cfset QueryAddRow(q)><cfset s1 = QuerySetCell(q, \"a\", \"x\")><cfset s2 = QuerySetCell(q, \"b\", 5)><cfset QueryAddRow(q)><cfset s3 = QuerySetCell(q, \"a\", \"y\", 2)><cfoutput>#q.a[1]#|#q.b[1]#|#q.a[2]#|#s1#|#s2#|#s3#</cfoutput>");
    EXPECT_EQ(out.equals("x|5|y|YES|YES|YES"), true);
}

TEST_F(QueryMutationTest, SetCellCoercesType) {
    // "30.9" coerces to integer 30 (verified against CF 2021).
    run("<cfset q = QueryNew(\"n\", \"integer\")><cfset QueryAddRow(q)><cfset QuerySetCell(q, \"n\", \"30.9\")>");
    EXPECT_EQ(queryData()->columns[0].values[0].m_type, cfvariant::Number);
    EXPECT_EQ(queryData()->columns[0].values[0].m_int, 30);
}

TEST_F(QueryMutationTest, SetCellNoRowsThrows) {
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"a\")><cfset QuerySetCell(q, \"a\", \"x\")>");
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryMutationTest, SetCellUnknownColumnThrows) {
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"a\")><cfset QueryAddRow(q)><cfset QuerySetCell(q, \"zzz\", \"x\")>");
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryMutationTest, AddColumnWithDatatype) {
    run("<cfset q = QueryNew(\"a\")><cfset QueryAddRow(q)><cfset QueryAddRow(q)><cfset r = QueryAddColumn(q, \"n\", \"integer\", [\"1\",\"2\"])><cfoutput>#r#</cfoutput>");
    const QueryData *qd = queryData();
    EXPECT_EQ(qd->columns.size(), 2u);
    EXPECT_EQ(qd->columns[1].values[0].m_type, cfvariant::Number);
    EXPECT_EQ(qd->columns[1].values[0].m_int, 1);
    EXPECT_EQ(qd->columns[1].values[1].m_int, 2);
}

TEST_F(QueryMutationTest, AddColumnPadsLonger) {
    // A longer new column pads existing columns (verified against CF 2021).
    run("<cfset q = QueryNew(\"a\")><cfset QueryAddRow(q)><cfset QueryAddRow(q)><cfset r = QueryAddColumn(q, \"long\", [\"1\",\"2\",\"3\",\"4\"])>");
    const QueryData *qd = queryData();
    EXPECT_EQ(qd->rowCount(), 4);
    EXPECT_EQ(qd->columns[0].values[0].m_type, cfvariant::Null);  // a[1] untouched
    EXPECT_EQ(cellStr(qd->columns[1].values[3]).equals("4"), true);
}

TEST_F(QueryMutationTest, AddColumnPadsShorter) {
    // A shorter new column is padded with nulls to the query's row count.
    run("<cfset q = QueryNew(\"a\")><cfset QueryAddRow(q)><cfset QueryAddRow(q)><cfset QueryAddRow(q)><cfset r = QueryAddColumn(q, \"short\", [\"only1\"])>");
    const QueryData *qd = queryData();
    EXPECT_EQ(qd->rowCount(), 3);
    EXPECT_EQ(cellStr(qd->columns[1].values[0]).equals("only1"), true);
    EXPECT_EQ(qd->columns[1].values[2].m_type, cfvariant::Null);
}

TEST_F(QueryMutationTest, AddColumnDuplicateThrows) {
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"a\")><cfset QueryAddColumn(q, \"a\", [\"1\"])>");
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryMutationTest, GetRow) {
    string out = run("<cfset q = QueryNew(\"Name,AGE\", \"varchar,integer\", [{Name:\"x\",AGE:5}])><cfset row = QueryGetRow(q, 1)><cfoutput>#row.Name#|#row.AGE#|#row[\"name\"]#</cfoutput>");
    EXPECT_EQ(out.equals("x|5|x"), true);
}

TEST_F(QueryMutationTest, GetRowOutOfBoundsThrows) {
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"a\")><cfset QueryAddRow(q)><cfset QueryGetRow(q, 5)>");
    } catch (webstrada::exception &) {
        caught = true;
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryMutationTest, KeyExists) {
    string out = run("<cfset q = QueryNew(\"a,b\", \"varchar,integer\", [{a:\"x\",b:1}])><cfoutput>#QueryKeyExists(q, \"a\")#|#QueryKeyExists(q, \"B\")#|#QueryKeyExists(q, \"zzz\")#|#QueryKeyExists(q, \"\")#</cfoutput>");
    EXPECT_EQ(out.equals("YES|YES|NO|NO"), true);
}

TEST_F(QueryMutationTest, ValueList) {
    string out = run("<cfset q = QueryNew(\"a,b\", \"varchar,integer\", [{a:\"x\",b:1},{a:\"y\",b:2},{a:\"z\",b:3}])><cfoutput>#ValueList(q.a)#|#ValueList(q.b, \";\")#</cfoutput>");
    EXPECT_EQ(out.equals("x,y,z|1;2;3"), true);
}

TEST_F(QueryMutationTest, ValueListNullCellEmpty) {
    // A null cell contributes an empty item, keeping the delimiter
    // (verified against CF 2021: [ ,z]).
    string out = run("<cfset q = QueryNew(\"a,b\", \"varchar,varchar\", [{a:\"x\"},{a:\"y\",b:\"z\"}])><cfoutput>#ValueList(q.b)#</cfoutput>");
    EXPECT_EQ(out.equals(",z"), true);
}

TEST_F(QueryMutationTest, ValueListEmptyQuery) {
    string out = run("<cfset q = QueryNew(\"a\")><cfoutput>[#ValueList(q.a)#]</cfoutput>");
    EXPECT_EQ(out.equals("[]"), true);
}

TEST_F(QueryMutationTest, CellAssignBracketWritesThrough) {
    // q["a"][1] = "z" persists (was BUGS.md: cell assignment was lost because
    // the column array was a temp copy).
    string out = run("<cfset q = QueryNew(\"a,b\", \"varchar,integer\", [{a:\"x\",b:1},{a:\"y\",b:2}])><cfset q[\"a\"][2] = \"new\"><cfset q.b[1] = 42><cfoutput>#q.a[1]#|#q.a[2]#|#q.b[1]#|#q.b[2]#</cfoutput>");
    EXPECT_EQ(out.equals("x|new|42|2"), true);
    const QueryData *qd = queryData();
    EXPECT_EQ(cellStr(qd->columns[0].values[1]).equals("new"), true);
    EXPECT_EQ(qd->columns[1].values[0].m_int, 42);
}

TEST_F(QueryMutationTest, CellAssignDotWritesThrough) {
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"}])><cfset q.a[1] = \"z\"><cfoutput>#q.a[1]#</cfoutput>");
    EXPECT_EQ(out.equals("z"), true);
}

TEST_F(QueryMutationTest, CellAssignCoercesType) {
    // Assigning "42" to an integer column coerces to 42 (matches QuerySetCell).
    run("<cfset q = QueryNew(\"n\", \"integer\", [{n:1}])><cfset q[\"n\"][1] = \"42\">");
    const QueryData *qd = queryData();
    EXPECT_EQ(qd->columns[0].values[0].m_type, cfvariant::Number);
    EXPECT_EQ(qd->columns[0].values[0].m_int, 42);
}

TEST_F(QueryMutationTest, CellAssignCompound) {
    string out = run("<cfset q = QueryNew(\"n\", \"integer\", [{n:1}])><cfset q[\"n\"][1] += 10><cfoutput>#q.n[1]#</cfoutput>");
    EXPECT_EQ(out.equals("11"), true);
}

TEST_F(QueryMutationTest, CellAssignInCfscript) {
    string out = run("<cfscript>q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"}]);q[\"a\"][1] = \"new\";WriteOutput(q[\"a\"][1] & q[\"a\"][2]);</cfscript>");
    EXPECT_EQ(out.equals("newy"), true);
}

TEST_F(QueryMutationTest, CopiedColumnWritesThrough) {
    // x = q["a"] keeps a writable query-column reference (CF: mutating the
    // copy writes through to the query).
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"}])><cfset x = q[\"a\"]><cfset x[1] = \"MUT\"><cfoutput>#q.a[1]#|#x[1]#</cfoutput>");
    EXPECT_EQ(out.equals("MUT|MUT"), true);
}

TEST_F(QueryMutationTest, SecondCopyOfBracketColumnThrows) {
    // A second copy of a bracket column degrades to the scalar first cell
    // (CF 2021), so writing an element throws the dereference Expression error
    // instead of writing through to the query.
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cftry><cfset x = q[\"a\"]><cfset y = x><cfset y[1] = \"CPY\"><cfoutput>ok</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals("Expression|You have attempted to dereference a scalar variable of type class java.lang.String as a structure with members."), true);
    // The original reference keeps working (the write through it persists).
    string out2 = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cftry><cfset x = q[\"a\"]><cfset y = x><cfset y[1] = \"CPY\"><cfcatch></cfcatch></cftry><cfset x[2] = \"X2\"><cfoutput>#q.a[2]#|#x[2]#</cfoutput>");
    EXPECT_EQ(out2.equals("X2|X2"), true);
}

TEST_F(QueryMutationTest, SecondCopyOfDotColumnThrows) {
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"}])><cftry><cfset d = q.a><cfset e = d><cfset e[1] = \"CPY\"><cfoutput>ok</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals("Expression|You have attempted to dereference a scalar variable of type class java.lang.String as a structure with members."), true);
}

TEST_F(QueryMutationTest, StoredColumnRefIsNotAnArray) {
    // ArrayLen/ArrayAppend reject a stored column reference with CF's
    // "cannot be used as an array" error, and IsArray is NO; the direct
    // bracket temp q["a"] still counts as an array.
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cfset x = q[\"a\"]><cftry><cfoutput>#ArrayLen(x)#</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals("class java.lang.String|Object of type class java.lang.String cannot be used as an array|"), true);
    string out2 = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cfset x = q[\"a\"]><cftry><cfset ArrayAppend(x, \"W\")><cfoutput>ok</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out2.equals("class java.lang.String|Object of type class java.lang.String cannot be used as an array|"), true);
    string out3 = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cfset x = q[\"a\"]><cfoutput>#IsArray(x)#|#IsArray(q[\"a\"])#|#ArrayLen(q[\"a\"])#</cfoutput>");
    EXPECT_EQ(out3.equals("NO|YES|3"), true);
}

TEST_F(QueryMutationTest, CopiedColumnReadsLive) {
    // Reads through a stored bracket reference reflect later query mutations
    // (CF: x = q["a"]; q["a"][2] = "YY" shows YY via x[2]).
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cfset x = q[\"a\"]><cfset q[\"a\"][2] = \"YY\"><cfoutput>#x[1]#|#x[2]#|#x[3]#</cfoutput>");
    EXPECT_EQ(out.equals("x|YY|z"), true);
}

TEST_F(QueryMutationTest, PhantomRowWriteInvisible) {
    // Writing past the last row through a stored reference is invisible: the
    // value reads back empty and recordcount is unchanged (CF 2021).
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cfset x = q[\"a\"]><cfset x[4] = \"w\"><cfoutput>#q.recordcount#|#x[4]#|#q.a[4]#</cfoutput>");
    EXPECT_EQ(out.equals("3||"), true);
}

TEST_F(QueryMutationTest, DegradedColumnCopyIsScalar) {
    // A re-copied bracket column stringifies as the scalar first cell and
    // indexes like a string (character access; out-of-range throws CF's
    // "Cannot access array element at position N." error).
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cfset x = q[\"a\"]><cfset y = x><cfoutput>#y#|#Len(y)#|#y[1]#</cfoutput>");
    EXPECT_EQ(out.equals("x|1|x"), true);
    string out2 = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cftry><cfset x = q[\"a\"]><cfset y = x><cfoutput>#y[3]#</cfoutput><cfcatch><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out2.equals("Cannot access array element at position 3."), true);
    // The len() member method on a stored reference behaves like Len (first
    // cell length), matching CF.
    string out3 = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cfset x = q[\"a\"]><cfoutput>#x.len()#</cfoutput>");
    EXPECT_EQ(out3.equals("1"), true);
}

TEST_F(QueryMutationTest, DegradedIntegerColumnCopyIsScalar) {
    // A re-copied integer column degrades to an Integer scalar: indexing it
    // throws the java.lang.Integer dereference error, and it stringifies as
    // the first cell.
    string out = run("<cfset q = QueryNew(\"n\", \"integer\", [{n:1},{n:2},{n:3}])><cftry><cfset x = q[\"n\"]><cfset y = x><cfset y[1] = 9><cfoutput>ok</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals("Expression|You have attempted to dereference a scalar variable of type class java.lang.Integer as a structure with members.|"), true);
    string out2 = run("<cfset q = QueryNew(\"n\", \"integer\", [{n:1},{n:2},{n:3}])><cftry><cfset x = q[\"n\"]><cfset y = x><cfoutput>#y[1]#</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out2.equals("Expression|You have attempted to dereference a scalar variable of type class java.lang.Integer as a structure with members.|"), true);
    string out3 = run("<cfset q = QueryNew(\"n\", \"integer\", [{n:1},{n:2},{n:3}])><cfset x = q[\"n\"]><cfset y = x><cfoutput>#y#</cfoutput>");
    EXPECT_EQ(out3.equals("1"), true);
}

TEST_F(QueryMutationTest, DotColumnFirstCopyIsScalar) {
    // A dot-access column stored into a variable is the scalar first cell
    // (CF 2021), so reading a second index throws CF's array-position error
    // and writing an element throws the dereference error.
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cftry><cfset d = q.a><cfoutput>#d[2]#</cfoutput><cfcatch><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals("Cannot access array element at position 2."), true);
    string out2 = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"},{a:\"z\"}])><cfset d = q.a><cfoutput>#d#|#Len(d)#</cfoutput>");
    EXPECT_EQ(out2.equals("x|1"), true);
}


TEST_F(QueryMutationTest, CopiedDotColumnIsReadOnly) {
    // x = q.a (dot access) is a read-only column copy: writing an element
    // throws an Expression error (CF), while the direct q.a[1] = "z" form
    // still writes through.
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"}])><cftry><cfset x = q.a><cfset x[1] = \"MUT\"><cfoutput>ok</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals("Expression|You have attempted to dereference a scalar variable of type class java.lang.String as a structure with members."), true);
    string out2 = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"},{a:\"y\"}])><cfset q.a[1] = \"z\"><cfoutput>#q.a[1]#</cfoutput>");
    EXPECT_EQ(out2.equals("z"), true);
}

TEST_F(QueryMutationTest, WholeColumnAssignWritesCurrentRow) {
    // q.a = v (dot whole-column assignment) writes the current row's cell
    // (row 1 here), coercing to the column type like a cell write (CF).
    string out = run("<cfset q = QueryNew(\"a,b\", \"varchar,integer\", [{a:\"x\",b:1},{a:\"y\",b:2},{a:\"z\",b:3}])><cfset q.a = \"W\"><cfset q.b = 42><cfoutput>#q.a[1]#|#q.a[2]#|#q.a[3]#|#q.b[1]#|#q.b[2]#|#q.b[3]#</cfoutput>");
    EXPECT_EQ(out.equals("W|y|z|42|2|3"), true);
}

TEST_F(QueryMutationTest, WholeColumnAssignUnknownColumnThrows) {
    // A non-column name throws CF's columnMap Application error.
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"}])><cftry><cfset q.zzz = \"v\"><cfoutput>ok</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals("Application|There is a problem in the column mappings specified in the columnMap structure.|The query attribute input does not contain any column by the name of zzz."), true);
}

TEST_F(QueryMutationTest, BracketWholeColumnAssignThrows) {
    // Bracket whole-column assignment q["a"] = v is rejected by CF with the
    // "trying to modify the query" Expression error.
    string out = run("<cfset q = QueryNew(\"a\", \"varchar\", [{a:\"x\"}])><cftry><cfset q[\"a\"] = \"W\"><cfoutput>ok</cfoutput><cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals("Expression|An error occurred while trying to modify the query named class coldfusion.sql.QueryTable."), true);
}

TEST_F(QueryMutationTest, CfscriptDottedIndexAccess) {
    // s.k[2] was miscompiled to s[k[2]] in cfscript function args
    // (was BUGS.md: cfscript dotted member + index access is miscompiled).
    string out = run("<cfscript>s = {k:[\"a\",\"b\",\"c\"]};writeOutput(s.k[2] & s.k[3]);</cfscript>");
    EXPECT_EQ(out.equals("bc"), true);
}

TEST_F(QueryMutationTest, CfscriptDottedIndexNested) {
    string out = run("<cfscript>t = {a:{b:[10,20,30]}};writeOutput(t.a.b[2]);</cfscript>");
    EXPECT_EQ(out.equals("20"), true);
}

TEST_F(QueryMutationTest, CfscriptIndexThenDot) {
    string out = run("<cfscript>arr = [[1,2],[3,4]];writeOutput(arr[2][1]);</cfscript>");
    EXPECT_EQ(out.equals("3"), true);
}

// QueryEach / QueryFilter / QueryMap / QueryReduce / QueryConvertForGrid /
// QueryGetResult / QuotedValueList, verified byte-for-byte against CF 2021 in
// tests/cfm/query_functions_test.cfm + query_functions_test2.cfm.
class QueryFunctionsTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }
};

TEST_F(QueryFunctionsTest, QuotedValueList) {
    EXPECT_EQ(run("<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"b\"}])><cfoutput>#QuotedValueList(q.id)#</cfoutput>").equals("'1','2'"), true);
    EXPECT_EQ(run("<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"b\"}])><cfoutput>#QuotedValueList(q.name, \"|\")#</cfoutput>").equals("'a'|'b'"), true);
    EXPECT_EQ(run("<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"\"}])><cfoutput>[#QuotedValueList(q.name)#]</cfoutput>").equals("['a','']"), true);
    // Empty query column -> empty string (no quotes).
    EXPECT_EQ(run("<cfset q = QueryNew(\"x\", \"varchar\", [])><cfoutput>[#QuotedValueList(q.x)#]</cfoutput>").equals("[]"), true);
    // Embedded quotes are not escaped (CF behavior).
    EXPECT_EQ(run("<cfset q = QueryNew(\"n\", \"varchar\", [{n:\"x'y\"}])><cfoutput>#QuotedValueList(q.n)#</cfoutput>").equals("'x'y'"), true);
}

TEST_F(QueryFunctionsTest, QueryEachCallbacks) {
    string out = run(
        "<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"b\"},{id:3,name:\"c\"}])>"
        "<cfset out = \"\">"
        "<cfset QueryEach(q, function(row, rn, qq) { out = out & rn & \":\" & row.id & row.name & \"|\"; })>"
        "<cfoutput>#out#</cfoutput>");
    EXPECT_EQ(out.equals("1:1a|2:2b|3:3c|"), true);
}

TEST_F(QueryFunctionsTest, QueryEachUsesQueryArgument) {
    string out = run(
        "<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"b\"}])>"
        "<cfset out = \"\">"
        "<cfset QueryEach(q, function(row, rn, qq) { out = out & qq.name[rn] & \"|\"; })>"
        "<cfoutput>#out#</cfoutput>");
    EXPECT_EQ(out.equals("a|b|"), true);
}

TEST_F(QueryFunctionsTest, QueryFilterKeepsOriginal) {
    string out = run(
        "<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"b\"},{id:3,name:\"c\"}])>"
        "<cfset fq = QueryFilter(q, function(row, rn, qq) { return row.id MOD 2 EQ 1; })>"
        "<cfoutput>#fq.recordcount#|#ValueList(fq.id)#|#fq.columnlist#|#q.recordcount#|#ValueList(q.id)#</cfoutput>");
    EXPECT_EQ(out.equals("2|1,3|ID,NAME|3|1,2,3"), true);
}

TEST_F(QueryFunctionsTest, QueryMapMutatesRow) {
    string out = run(
        "<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"b\"},{id:3,name:\"c\"}])>"
        "<cfset mq = QueryMap(q, function(row, rn, qq) { row.name = row.name & rn; return row; })>"
        "<cfoutput>#mq.recordcount#|#ValueList(mq.name)#|#mq.columnlist#</cfoutput>");
    EXPECT_EQ(out.equals("3|a1,b2,c3|ID,NAME"), true);
}

TEST_F(QueryFunctionsTest, QueryMapReturnsNewStruct) {
    string out = run(
        "<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"b\"}])>"
        "<cfset mq = QueryMap(q, function(row, rn, qq) { return {id: rn, name: \"z\"}; })>"
        "<cfoutput>#ValueList(mq.id)#|#ValueList(mq.name)#</cfoutput>");
    EXPECT_EQ(out.equals("1,2|z,z"), true);
}

TEST_F(QueryFunctionsTest, QueryMapMissingColumnThrows) {
    // CF throws a fatal error when the mapped struct lacks a query column.
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"}])>"
            "<cfset mq = QueryMap(q, function(row, rn, qq) { return {id: rn}; })>"
            "<cfoutput>#mq.recordcount#</cfoutput>");
    } catch (const webstrada::exception &e) {
        caught = (std::string(e.what()).find("missing the column 'name'") != std::string::npos);
    }
    EXPECT_EQ(caught, true);
}

TEST_F(QueryFunctionsTest, QueryReduceSum) {
    EXPECT_EQ(run("<cfset q = QueryNew(\"id\", \"integer\", [{id:1},{id:2},{id:3}])><cfset s = QueryReduce(q, function(acc, row, rn, qq) { return acc + row.id; }, 0)><cfoutput>#s#</cfoutput>").equals("6"), true);
}

TEST_F(QueryFunctionsTest, QueryReduceStringConcat) {
    EXPECT_EQ(run("<cfset q = QueryNew(\"id,name\", \"integer,varchar\", [{id:1,name:\"a\"},{id:2,name:\"b\"},{id:3,name:\"c\"}])><cfset s = QueryReduce(q, function(acc, row, rn, qq) { return acc & row.name; }, \">\")><cfoutput>#s#</cfoutput>").equals(">abc"), true);
}

TEST_F(QueryFunctionsTest, QueryReduceEmptyQuery) {
    EXPECT_EQ(run("<cfset q = QueryNew(\"id\", \"integer\", [])><cfset s = QueryReduce(q, function(acc, row, rn, qq) { return acc + row.id; }, 100)><cfoutput>#s#</cfoutput>").equals("100"), true);
}

TEST_F(QueryFunctionsTest, QueryGetResultIsNull) {
    // CF returns null for a QueryNew-built query (verified vs CF 2021).
    EXPECT_EQ(run("<cfset q = QueryNew(\"id\", \"integer\", [{id:1}])><cfoutput>#IsNull(QueryGetResult(q))#</cfoutput>").equals("YES"), true);
}

TEST_F(QueryFunctionsTest, QueryConvertForGridPaging) {
    string out = run(
        "<cfset q = QueryNew(\"id\", \"integer\", [{id:1},{id:2},{id:3},{id:4},{id:5}])>"
        "<cfset g1 = QueryConvertForGrid(q, 1, 2)>"
        "<cfset g2 = QueryConvertForGrid(q, 2, 2)>"
        "<cfset g3 = QueryConvertForGrid(q, 3, 2)>"
        "<cfoutput>#ValueList(g1.QUERY.id)#:#g1.TOTALROWCOUNT#</cfoutput>"
        "<cfoutput>#ValueList(g2.QUERY.id)#:#g2.TOTALROWCOUNT#</cfoutput>"
        "<cfoutput>#ValueList(g3.QUERY.id)#:#g3.TOTALROWCOUNT#</cfoutput>");
    EXPECT_EQ(out.equals("1,2:53,4:55:5"), true);
}

TEST_F(QueryFunctionsTest, QueryConvertForGridOutOfRange) {
    string out = run(
        "<cfset q = QueryNew(\"id\", \"integer\", [{id:1},{id:2},{id:3}])>"
        "<cfset g = QueryConvertForGrid(q, 10, 2)>"
        "<cfoutput>[#ValueList(g.QUERY.id)#]:#g.TOTALROWCOUNT#</cfoutput>");
    EXPECT_EQ(out.equals("[]:3"), true);
}

TEST_F(QueryFunctionsTest, QueryConvertForGridZeroPageSize) {
    string out = run(
        "<cfset q = QueryNew(\"id\", \"integer\", [{id:1},{id:2},{id:3}])>"
        "<cfset g = QueryConvertForGrid(q, 1, 0)>"
        "<cfoutput>[#ValueList(g.QUERY.id)#]:#g.TOTALROWCOUNT#</cfoutput>");
    EXPECT_EQ(out.equals("[]:3"), true);
}

TEST_F(QueryFunctionsTest, QueryConvertForGridNegativePageThrows) {
    // A start index below zero throws like CF's Java IndexOutOfBounds.
    bool caught = false;
    try {
        run("<cfset q = QueryNew(\"id\", \"integer\", [{id:1},{id:2},{id:3}])>"
            "<cfset g = QueryConvertForGrid(q, 0, 2)>"
            "<cfoutput>X</cfoutput>");
    } catch (const webstrada::exception &e) {
        caught = (std::string(e.what()).find("out of bounds for length 3") != std::string::npos);
    }
    EXPECT_EQ(caught, true);
}

// ArrayEach / ArrayFilter / ArrayReduce / List* / Struct* higher-order
// functions, verified byte-for-byte against CF 2021 in
// tests/cfm/higher_order_functions_test.cfm + higher_order_functions_struct_test.cfm.
class HigherOrderFunctionsTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }
};

TEST_F(HigherOrderFunctionsTest, ArrayEachFilterReduce) {
    string out = run(
        "<cfscript>"
        "arr = [1,2,3,4];"
        "eachOut = \"\";"
        "ArrayEach(arr, function(item, idx, a){ eachOut = eachOut & idx & \":\" & item & \"|\"; });"
        "f = ArrayFilter(arr, function(item, idx, a){ return item MOD 2 EQ 0; });"
        "s = ArrayReduce(arr, function(acc, item, idx, a){ return acc + item; }, 0);"
        "writeOutput(eachOut & \";\" & f[1] & \",\" & f[2] & \";\" & s);"
        "</cfscript>");
    EXPECT_EQ(out.equals("1:1|2:2|3:3|4:4|;2,4;10"), true);
}

TEST_F(HigherOrderFunctionsTest, ArrayReduceStringAndEmpty) {
    EXPECT_EQ(run("<cfscript>arr = [1,2,3];writeOutput(ArrayReduce(arr, function(acc, item, idx, a){ return acc & item; }, \">\"));</cfscript>").equals(">123"), true);
    EXPECT_EQ(run("<cfscript>writeOutput(ArrayReduce(ArrayNew(1), function(acc, item, idx, a){ return acc + item; }, 7));</cfscript>").equals("7"), true);
}

TEST_F(HigherOrderFunctionsTest, ListEachFilterMapReduce) {
    string out = run(
        "<cfscript>"
        "l = \"a,b,c,b,a\";"
        "leach = \"\";"
        "ListEach(l, function(item, idx, ll){ leach = leach & idx & \":\" & item & \"|\"; });"
        "writeOutput(leach & \";\" & ListFilter(l, function(item, idx, ll){ return item NEQ \"b\"; }) & \";\" &"
        " ListMap(l, function(item, idx, ll){ return item & \"!\"; }) & \";\" & ListReduce(l, function(acc, item, idx, ll){ return acc & item; }, \">\"));"
        "</cfscript>");
    EXPECT_EQ(out.equals("1:a|2:b|3:c|4:b|5:a|;a,c,a;a!,b!,c!,b!,a!;>abcba"), true);
}

TEST_F(HigherOrderFunctionsTest, ListGetDuplicatesAndRemove) {
    EXPECT_EQ(run("<cfoutput>#ListGetDuplicates(\"a,b,a,c,b,a\")#</cfoutput>").equals("a,b"), true);
    EXPECT_EQ(run("<cfoutput>#ListGetDuplicates(\"x,y,z\")#</cfoutput>").equals(""), true);
    EXPECT_EQ(run("<cfoutput>#ListRemoveDuplicates(\"a,b,a,c,b,a\")#</cfoutput>").equals("a,b,c"), true);
    EXPECT_EQ(run("<cfoutput>#ListRemoveDuplicates(\"a,A,b\", \",\", true)#</cfoutput>").equals("a,b"), true);
    EXPECT_EQ(run("<cfoutput>#ListRemoveDuplicates(\"a,A,b\", \",\", false)#</cfoutput>").equals("a,A,b"), true);
}

TEST_F(HigherOrderFunctionsTest, ListQualifyAndCounts) {
    EXPECT_EQ(run("<cfoutput>#ListQualify(\"a,b,c\", \"'\")#</cfoutput>").equals("'a','b','c'"), true);
    EXPECT_EQ(run("<cfoutput>#ListValueCount(\"a,b,a,c\", \"a\")#</cfoutput>").equals("2"), true);
    EXPECT_EQ(run("<cfoutput>#ListValueCountNoCase(\"a,b,A,c\", \"a\")#</cfoutput>").equals("2"), true);
}

TEST_F(HigherOrderFunctionsTest, ListSortVariants) {
    EXPECT_EQ(run("<cfoutput>#ListSort(\"3,1,2\", \"numeric\")#</cfoutput>").equals("1,2,3"), true);
    EXPECT_EQ(run("<cfoutput>#ListSort(\"c,a,b\", \"text\", \"desc\")#</cfoutput>").equals("c,b,a"), true);
    EXPECT_EQ(run("<cfoutput>#ListSort(\"B,a,C\", \"textnocase\")#</cfoutput>").equals("a,B,C"), true);
    EXPECT_EQ(run("<cfscript>writeOutput(ListSort(\"a,c,b\", function(a, b){ return compare(a, b); }));</cfscript>").equals("a,b,c"), true);
}

TEST_F(HigherOrderFunctionsTest, StructAppendAndCopy) {
    string out = run(
        "<cfscript>"
        "a = {x: 1, y: 2};"
        "b = {y: 20, z: 30};"
        "r = StructAppend(a, b);"
        "StructAppend(a, {y: 99}, false);"
        "copy = StructCopy(b);"
        "copy.z = 300;"
        "writeOutput(r & \";\" & a.x & \",\" & a.y & \",\" & a.z & \";\" & copy.z & \";\" & b.z);"
        "</cfscript>");
    EXPECT_EQ(out.equals("YES;1,20,30;300;30"), true);
}

TEST_F(HigherOrderFunctionsTest, StructEachFilterMapReduce) {
    string out = run(
        "<cfscript>"
        "s = {m: 20, n: 30};"
        "seach = \"\";"
        "StructEach(s, function(k, v, ss){ seach = seach & k & \"=\" & v & \"|\"; });"
        "ms = StructMap(s, function(k, v, ss){ return v * 10; });"
        "writeOutput(seach & \";\" & StructReduce(s, function(acc, k, v, ss){ return acc + v; }, 0) & \";\" & ms.m & \":\" & ms.n);"
        "</cfscript>");
    EXPECT_EQ(out.equals("M=20|N=30|;50;200:300"), true);
}

TEST_F(HigherOrderFunctionsTest, StructFindKeyAndValue) {
    string out = run(
        "<cfscript>"
        "data = {a: 1, b: {c: 2, d: {e: 3}}, f: 1};"
        "fk = StructFindKey(data, \"e\");"
        "fv = StructFindValue(data, 3);"
        "writeOutput(ArrayLen(fk) & \":\" & fk[1].path & \":\" & fk[1].value & \";\" & ArrayLen(fv) & \":\" & fv[1].key & \":\" & fv[1].path);"
        "</cfscript>");
    EXPECT_EQ(out.equals("1:.B.D.e:3;1:E:.B.D.E"), true);
}

TEST_F(HigherOrderFunctionsTest, StructGetCreatesPath) {
    string out = run(
        "<cfscript>"
        "sg = StructGet(\"newroot.x.y\");"
        "writeOutput(IsStruct(sg) & \";\" & IsStruct(variables.newroot) & \";\" & IsStruct(variables.newroot.x));"
        "</cfscript>");
    EXPECT_EQ(out.equals("YES;YES;YES"), true);
}

TEST_F(HigherOrderFunctionsTest, StructGetAndSetMetadata) {
    string out = run(
        "<cfscript>"
        "meta = StructGetMetadata({p: 1});"
        "sm = {q: 1};"
        "StructSetMetadata(sm, {foo: \"bar\"});"
        "meta2 = StructGetMetadata(sm);"
        "writeOutput(meta.ordered & \":\" & meta.casesensistive & \";\" & meta2.keys.foo);"
        "</cfscript>");
    EXPECT_EQ(out.equals("unordered:NO;bar"), true);
}

TEST_F(HigherOrderFunctionsTest, StructSortAndToSorted) {
    string out = run(
        "<cfscript>"
        "ss = {b: 30, a: 10, c: 20};"
        "ts = StructToSorted(ss, \"text\");"
        "tks = \"\";"
        "StructEach(ts, function(k, v, s){ tks = tks & k & \",\"; });"
        "writeOutput(ArrayToList(StructSort(ss, \"text\")) & \";\" & ArrayToList(StructSort(ss, \"text\", \"desc\")) & \";\" & tks);"
        "</cfscript>");
    // StructSort sorts by VALUE (a=10,c=20,b=30); StructToSorted "text" sorts keys.
    EXPECT_EQ(out.equals("A,C,B;B,C,A;A,B,C,"), true);
}

// ---- HTTP response output encoding (<cfcontent> / <cfflush>) ----

// Compile-and-run a template with the response state bound like the CLI does
// (no web engine: flushes mark the response committed and park bytes in the
// CLI sink). `runRaw` returns the internal UTF-8 buffer; `runEncoded` returns
// the bytes as they would be sent to a browser with the active response charset.
class ResponseEncodingTest : public testing::Test {
protected:
    cfvariant variables;
    cfml::VariantCleanupGuard guard;

    void SetUp() override {
        variables = cfvariant::Struct;
        cfml::response_begin();
    }

    string run(const string &cfml_code, string *rawOut = nullptr) {
        char temp_path[] = "tmp/webstrada_response_test_XXXXXX";
        int fd = mkstemp(temp_path);
        if (fd == -1) throw std::runtime_error("Failed to create temporary file");
        string code = cfml_code;
        if (write(fd, code.constData(), code.length()) != (ssize_t)code.length()) {
            close(fd);
            unlink(temp_path);
            throw std::runtime_error("Failed to write to temporary file");
        }
        close(fd);

        string out;
        try {
            cfml::response_begin();
            llvm_codegen comp;
            auto compiled = comp.compile(temp_path, false);
            unlink(temp_path);

            if (!compiled) throw std::runtime_error("Failed to compile CFML template via JIT");

            cfvariant cgi = cfvariant::Struct;
            cfvariant server = cfvariant::Struct;
            cfvariant cookie = cfvariant::Struct;
            cfvariant application = cfvariant::Struct;
            cfvariant session = cfvariant::Struct;
            cfvariant url = cfvariant::Struct;
            cfvariant form = cfvariant::Struct;

            cfml::VariantCleanupGuard guard;
            compiled(&out, &cgi, &server, &cookie, &application, &session, &url, &form, &variables);
        } catch (...) {
            unlink(temp_path);
            throw;
        }
        if (rawOut) *rawOut = out;
        return out;
    }

    // Encoded output (what the CLI/web engine would send).
    std::vector<char> encoded(const string &cfml_code) {
        string raw;
        run(cfml_code, &raw);
        return cfml::response_encode_all(raw);
    }

    static std::string toStr(const std::vector<char> &bytes) {
        return std::string(bytes.data(), bytes.size());
    }
};

TEST_F(ResponseEncodingTest, DefaultStateIsUtf8TextHtml) {
    cfml::response_begin();
    EXPECT_EQ(std::string(cfml::response_charset_name()), "UTF-8");
    EXPECT_EQ(std::string(cfml::response_content_type_name()), "text/html");
    EXPECT_EQ(cfml::response_committed(), 0);
    EXPECT_EQ(cfml::response_is_binary(), 0);
}

TEST_F(ResponseEncodingTest, Latin1EncodesChr233AsSingleByte) {
    auto bytes = encoded("<cfcontent type=\"text/html; charset=ISO-8859-1\"><cfoutput>#Chr(233)#</cfoutput>");
    EXPECT_EQ(toStr(bytes), std::string("\xE9", 1));
    EXPECT_EQ(std::string(cfml::response_charset_name()), "ISO-8859-1");
}
TEST_F(ResponseEncodingTest, Latin1AliasesAccepted) {
    EXPECT_EQ(toStr(encoded("<cfcontent type=\"text/html; charset=latin1\"><cfoutput>#Chr(233)#</cfoutput>")), std::string("\xE9", 1));
    EXPECT_EQ(toStr(encoded("<cfcontent type=\"text/html; charset=latin-1\"><cfoutput>#Chr(233)#</cfoutput>")), std::string("\xE9", 1));
    EXPECT_EQ(toStr(encoded("<cfcontent type=\"text/html; charset=8859_1\"><cfoutput>#Chr(233)#</cfoutput>")), std::string("\xE9", 1));
}

TEST_F(ResponseEncodingTest, Utf8PassesThrough) {
    auto bytes = encoded("<cfcontent type=\"text/html; charset=UTF-8\"><cfoutput>#Chr(233)#</cfoutput>");
    EXPECT_EQ(toStr(bytes), std::string("\xC3\xA9", 2));
}

TEST_F(ResponseEncodingTest, UnicodeIsUtf16WithBom) {
    auto bytes = encoded("<cfcontent type=\"text/html; charset=Unicode\"><cfoutput>Hi</cfoutput>");
    EXPECT_EQ(toStr(bytes), std::string("\xFE\xFF\x00H\x00i", 6));
}

TEST_F(ResponseEncodingTest, TypeWithoutCharsetKeepsDefault) {
    cfml::response_begin();
    auto bytes = encoded("<cfcontent type=\"text/plain\"><cfoutput>x</cfoutput>");
    EXPECT_EQ(toStr(bytes), std::string("x", 1));
    EXPECT_EQ(std::string(cfml::response_content_type_name()), "text/plain");
    EXPECT_EQ(std::string(cfml::response_charset_name()), "UTF-8");
}

TEST_F(ResponseEncodingTest, UnknownCharsetThrows) {
    EXPECT_THROW(encoded("<cfcontent type=\"text/html; charset=BOGUS\"><cfoutput>x</cfoutput>"), webstrada::exception);
}

TEST_F(ResponseEncodingTest, ResetDefaultDiscardsPriorOutput) {
    EXPECT_EQ(toStr(encoded("<cfoutput>Pre</cfoutput><cfcontent type=\"text/plain\"><cfoutput>Post</cfoutput>")), "Post");
}

TEST_F(ResponseEncodingTest, ResetNoPreservesPriorOutput) {
    EXPECT_EQ(toStr(encoded("<cfoutput>Pre</cfoutput><cfcontent type=\"text/plain\" reset=\"no\"><cfoutput>Post</cfoutput>")), "PrePost");
}

TEST_F(ResponseEncodingTest, LastCharsetWinsBeforeCommit) {
    // Two charset changes before any flush: the last one applies.
    auto bytes = encoded("<cfcontent type=\"text/html; charset=ISO-8859-1\" reset=\"no\">"
                         "<cfoutput>a#Chr(233)#</cfoutput>"
                         "<cfcontent type=\"text/html; charset=UTF-8\" reset=\"no\">"
                         "<cfoutput>b#Chr(233)#</cfoutput>");
    EXPECT_EQ(toStr(bytes), std::string("a\xC3\xA9" "b\xC3\xA9", 6));
}

TEST_F(ResponseEncodingTest, SilentBlockUnwindDoesNotPoisonNextRequest) {
    // A <cfsilent> (or <cffunction output="false">) block that unwinds past
    // cf_silent_end on an exception leaves a stale real-out pointer in
    // g_silentRealBufs (was BUGS.md "g_silentRealBufs can hold a dangling
    // pointer"): the recorded string* outlives the request's output buffer.
    // response_begin() now clears the silent buffers, so a later <cfcontent
    // reset> (which reads silent_real_out()) never touches the stale pointer.
    // Simulated here by throwing inside <cfsilent>, then running a plain
    // <cfcontent reset> under AddressSanitizer would have been a
    // stack-buffer-overflow.
    try {
        run("<cfsilent><cfthrow message=\"boom\"></cfsilent>");
    } catch (const webstrada::exception &) {
        // expected
    }
    // Fresh request state; <cfcontent reset> must not crash and still clears
    // the page buffer normally.
    EXPECT_EQ(toStr(encoded("<cfoutput>Pre</cfoutput><cfcontent type=\"text/plain\"><cfoutput>Post</cfoutput>")), "Post");
}

TEST_F(ResponseEncodingTest, EmptyFlushCommitsCharset) {
    // The first <cfflush> commits the response even when the buffer is empty,
    // so the earlier charset is locked (was BUGS.md "<cfflush> with an empty
    // buffer"): CF keeps ISO-8859-1 here and encodes the byte as latin-1.
    auto bytes = encoded("<cfcontent type=\"text/html; charset=ISO-8859-1\">"
                         "<cfflush>"
                         "<cfcontent type=\"text/html; charset=UTF-8\">"
                         "<cfoutput>#Chr(233)#</cfoutput>");
    EXPECT_EQ(toStr(bytes), std::string("\xE9", 1));
}

TEST_F(ResponseEncodingTest, CfcontentResetInsideCfsilentClearsWholePage) {
    // A <cfcontent> reset inside <cfsilent> clears the WHOLE page output (the
    // real buffer, not just the discard), matching CF 2025 (was BUGS.md #10).
    auto bytes = encoded("<cfoutput>A|</cfoutput>"
                         "<cfsilent><cfcontent type=\"text/plain\"></cfsilent>"
                         "<cfoutput>|B</cfoutput>");
    EXPECT_EQ(toStr(bytes), std::string("|B", 2));
}

TEST_F(ResponseEncodingTest, FlushCommitsCharset) {
    // The first flush with data locks the charset; the later change is ignored
    // (reset="no" so the post-flush bytes survive to prove the latin-1 encoding).
    auto bytes = encoded("<cfcontent type=\"text/html; charset=ISO-8859-1\" reset=\"no\">"
                         "<cfoutput>a#Chr(233)#</cfoutput>"
                         "<cfflush>"
                         "<cfcontent type=\"text/html; charset=UTF-8\" reset=\"no\">"
                         "<cfoutput>b#Chr(233)#</cfoutput>");
    EXPECT_EQ(toStr(bytes), std::string("a\xE9" "b\xE9", 4));
}

TEST_F(ResponseEncodingTest, ResetAfterFlushKeepsFlushedBytes) {
    // A reset after a flush cannot remove bytes already written to the engine.
    auto bytes = encoded("<cfcontent type=\"text/html; charset=ISO-8859-1\">"
                         "<cfoutput>Pre #Chr(233)#</cfoutput>"
                         "<cfflush>"
                         "<cfoutput>Post</cfoutput>"
                         "<cfcontent type=\"text/html; charset=UTF-8\">");
    EXPECT_EQ(toStr(bytes), std::string("Pre \xE9", 5));
}

TEST_F(ResponseEncodingTest, FlushPreservesWithResetNo) {
    auto bytes = encoded("<cfoutput>Pre</cfoutput><cfflush><cfcontent type=\"text/html\" reset=\"no\"><cfoutput>Post</cfoutput>");
    EXPECT_EQ(toStr(bytes), "PrePost");
}

TEST_F(ResponseEncodingTest, FileContentReplacesOutputAndIsBinary) {
    string path = "tmp/response_test_bin.dat";
    {
        FILE *f = fopen(path.constData(), "wb");
        ASSERT_TRUE(f != nullptr);
        fwrite("abc\x00" "def\xff", 1, 7, f);
        fclose(f);
    }
    cfml::response_begin();
    string raw;
    run("<cfcontent file=\"" + path + "\" type=\"application/octet-stream\">"
        "<cfoutput>ignored</cfoutput>", &raw);
    // Raw internal buffer holds the exact file bytes; binary mode bypasses encoding.
    EXPECT_EQ(std::string(raw.constData(), raw.length()), std::string("abc\x00" "def\xff", 7));
    EXPECT_EQ(cfml::response_is_binary(), 1);
    EXPECT_EQ(std::string(cfml::response_content_type_name()), "application/octet-stream");
    EXPECT_EQ(cfml::response_encode(raw), (std::vector<char>(raw.constData(), raw.constData() + raw.length())));
    unlink(path.constData());
}

TEST_F(ResponseEncodingTest, DeletefileRemovesFile) {
    string path = "tmp/response_test_del.dat";
    {
        FILE *f = fopen(path.constData(), "wb");
        ASSERT_TRUE(f != nullptr);
        fwrite("data", 1, 4, f);
        fclose(f);
    }
    cfml::response_begin();
    run("<cfcontent file=\"" + path + "\" type=\"text/plain\" deletefile=\"yes\">");
    EXPECT_EQ(access(path.constData(), F_OK), -1); // file was deleted
}

TEST_F(ResponseEncodingTest, VariableBinaryPassesThrough) {
    cfvariant bin(cfvariant::Binary);
    bin.m_binary->assign({std::byte(0x41), std::byte(0x00), std::byte(0x42)});
    cfml::response_begin();
    string out;
    cfml::response_apply_cfcontent(&out, nullptr, nullptr, nullptr, &bin, nullptr);
    EXPECT_EQ(std::string(out.constData(), out.length()), std::string("A\x00" "B", 3));
    EXPECT_EQ(cfml::response_is_binary(), 1);
}

TEST_F(ResponseEncodingTest, CommittedTypeAndCharsetChangeIgnored) {
    cfml::response_begin();
    string out;
    cfml::response_apply_cfcontent(&out, cfml::cfvariant_create_string("text/html; charset=ISO-8859-1"), nullptr, nullptr, nullptr, nullptr);
    EXPECT_EQ(std::string(cfml::response_charset_name()), "ISO-8859-1");
    out = "abc";
    cfml::response_flush(&out); // non-empty flush commits the response
    EXPECT_EQ(cfml::response_committed(), 1);
    // Once committed, changing the type/charset is silently ignored.
    cfml::response_apply_cfcontent(&out, cfml::cfvariant_create_string("text/html; charset=UTF-8"), nullptr, nullptr, nullptr, nullptr);
    EXPECT_EQ(std::string(cfml::response_charset_name()), "ISO-8859-1");
    EXPECT_EQ(std::string(cfml::response_content_type_name()), "text/html");
}

TEST_F(ResponseEncodingTest, ContentTypeWithSpacesAndQuotesParsed) {
    cfml::response_begin();
    string out;
    cfml::response_apply_cfcontent(&out, cfml::cfvariant_create_string("text/html ; charset = \"ISO-8859-1\""), nullptr, nullptr, nullptr, nullptr);
    EXPECT_EQ(std::string(cfml::response_content_type_name()), "text/html");
    EXPECT_EQ(std::string(cfml::response_charset_name()), "ISO-8859-1");
}

// ---------------------------------------------------------------------------
// <cfheader> / <cflocation> unit tests.
//
// These run CFML through the JIT and inspect both the response state (custom
// headers, status code, committed flag) and the output buffer. The normal
// paths are additionally verified against ColdFusion 2025 in tests/cfm/
// (cfheader_*_test.cfm, cflocation_*_test.cfm); the error paths (invalid
// attribute combinations, status-code range, response already committed,
// unsupported charset) are exceptions covered here.
// ---------------------------------------------------------------------------

class ResponseHeaderTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
        cfml::response_begin();
    }

    // Runs CFML through the JIT and returns the output buffer. A <cflocation>
    // abort is swallowed (like the request harness does), so the output
    // written before the abort is returned; any other exception propagates.
    string run(const string &cfml_code) {
        char temp_path[] = "/tmp/webstrada_jit_test_XXXXXX";
        int fd = mkstemp(temp_path);
        if (fd == -1) throw std::runtime_error("Failed to create temporary file");
        string code = cfml_code;
        if (write(fd, code.constData(), code.length()) != (ssize_t)code.length()) {
            close(fd);
            unlink(temp_path);
            throw std::runtime_error("Failed to write to temporary file");
        }
        close(fd);

        string out;
        try {
            llvm_codegen comp;
            auto compiled = comp.compile(temp_path, false);
            unlink(temp_path);
            if (!compiled) throw std::runtime_error("Failed to compile CFML template via JIT");
            cfvariant cgi = cfvariant::Struct;
            cfvariant server = cfvariant::Struct;
            cfvariant cookie = cfvariant::Struct;
            cfvariant application = cfvariant::Struct;
            cfvariant session = cfvariant::Struct;
            cfvariant url = cfvariant::Struct;
            cfvariant form = cfvariant::Struct;
            cfml::VariantCleanupGuard guard;
            try {
                compiled(&out, &cgi, &server, &cookie, &application, &session, &url, &form, &variables);
            } catch (const webstrada::abort_exception &) {
                // <cflocation> aborts the page; prior output is preserved.
            }
        } catch (...) {
            unlink(temp_path);
            throw;
        }
        return out;
    }

    // Asserts that running `cfml_code` throws a webstrada::exception whose
    // message equals `msg`.
    void expectThrows(const string &cfml_code, const char *msg) {
        bool threw = false;
        try {
            runJitTemplate(cfml_code, variables);
        } catch (const webstrada::exception &e) {
            threw = true;
            EXPECT_EQ(string(e.m_message).equals(msg), true)
                << "CFML: " << cfml_code.constData() << " -> " << e.m_message.constData();
        }
        EXPECT_EQ(threw, true) << "CFML: " << cfml_code.constData();
    }

    // Value of a queued response header (case-insensitive name), "" when absent.
    std::string headerValue(const std::string &name) const {
        for (const auto &h : cfml::response().headers) {
            if (webstrada::string(h.first.c_str()).compareCaseInsensitive(name.c_str()) == 0) {
                return h.second;
            }
        }
        return "";
    }
};

TEST_F(ResponseHeaderTest, CfHeaderSetsCustomHeader) {
    run("<cfheader name=\"X-Custom\" value=\"hello world\"><cfoutput>OK</cfoutput>");
    EXPECT_EQ(headerValue("X-Custom"), "hello world");
}

TEST_F(ResponseHeaderTest, CfHeaderMultipleHeadersAndCasePreserved) {
    run("<cfheader name=\"X-One\" value=\"1\"><cfheader name=\"x-Two\" value=\"2\">");
    EXPECT_EQ(headerValue("X-One"), "1");
    EXPECT_EQ(headerValue("x-Two"), "2");
    // The names are emitted with the original casing.
    EXPECT_EQ(cfml::response().headers.size(), (size_t)2);
    EXPECT_EQ(cfml::response().headers[0].first, "X-One");
    EXPECT_EQ(cfml::response().headers[1].first, "x-Two");
}

TEST_F(ResponseHeaderTest, CfHeaderDynamicNameAndValue) {
    run("<cfset hn=\"X-Dyn\"><cfset hv=\"dyn-val\"><cfheader name=\"#hn#\" value=\"#hv#\"><cfoutput>OK</cfoutput>");
    EXPECT_EQ(headerValue("X-Dyn"), "dyn-val");
}

TEST_F(ResponseHeaderTest, CfHeaderEmptyValueIsEmitted) {
    run("<cfheader name=\"X-Empty\" value=\"\"><cfoutput>OK</cfoutput>");
    EXPECT_EQ(headerValue("X-Empty"), "");
}

TEST_F(ResponseHeaderTest, CfHeaderValueStripsCrlf) {
    run("<cfheader name=\"X-Safe\" value=\"a#Chr(13)#b#Chr(10)#c\"><cfoutput>OK</cfoutput>");
    EXPECT_EQ(headerValue("X-Safe"), "abc");
}

TEST_F(ResponseHeaderTest, CfHeaderContentTypeRoutesThroughResponse) {
    run("<cfheader name=\"Content-Type\" value=\"text/plain; charset=ISO-8859-1\"><cfoutput>OK</cfoutput>");
    EXPECT_EQ(std::string(cfml::response_content_type_name()), "text/plain");
    EXPECT_EQ(std::string(cfml::response_charset_name()), "ISO-8859-1");
    EXPECT_EQ(cfml::response().headers.size(), (size_t)0); // not a custom header
}

TEST_F(ResponseHeaderTest, CfHeaderContentTypeIsCaseInsensitive) {
    run("<cfheader name=\"content-type\" value=\"text/plain\"><cfoutput>OK</cfoutput>");
    EXPECT_EQ(std::string(cfml::response_content_type_name()), "text/plain");
}

TEST_F(ResponseHeaderTest, CfHeaderStatuscodeSetsStatus) {
    run("<cfheader statuscode=\"404\"><cfoutput>NOTFOUND</cfoutput>");
    EXPECT_EQ(cfml::response().statusCode, 404);
    EXPECT_EQ(cfml::response().headers.size(), (size_t)0);
}

TEST_F(ResponseHeaderTest, CfHeaderContentDispositionDefaultCharsetIsUtf8) {
    // CF re-encodes the value with the default file charset (UTF-8) and ships
    // the raw bytes, so Chr(233) becomes the two UTF-8 bytes C3 A9.
    run("<cfheader name=\"Content-Disposition\" value=\"attachment; filename=#Chr(233)#.txt\">");
    EXPECT_EQ(headerValue("Content-Disposition"), std::string("attachment; filename=\xC3\xA9.txt"));
}

TEST_F(ResponseHeaderTest, CfHeaderCharsetAttributeReencodesValue) {
    // charset=ISO-8859-1: Chr(233) becomes a single 0xE9 byte.
    run("<cfheader name=\"X-Enc\" value=\"#Chr(233)#\" charset=\"ISO-8859-1\">");
    EXPECT_EQ(headerValue("X-Enc"), std::string("\xE9", 1));
}

TEST_F(ResponseHeaderTest, CfHeaderUnsupportedCharsetThrows) {
    expectThrows("<cfheader name=\"X\" value=\"v\" charset=\"BOGUS\"><cfoutput>OK</cfoutput>",
                 "Attribute validation error for tag cfheader. BOGUS is not a supported character encoding.");
}

TEST_F(ResponseHeaderTest, CfHeaderAfterFlushThrows) {
    // The flush commits the response; the later cfheader throws CF's error.
    bool threw = false;
    try {
        run("<cfoutput>FLUSH</cfoutput><cfflush><cfheader name=\"X-Late\" value=\"y\"><cfoutput>AFTER</cfoutput>");
    } catch (const webstrada::exception &e) {
        threw = true;
        EXPECT_EQ(string(e.m_message).equals("Failed to add HTML header. ColdFusion was unable to add the header you specified to the output stream. This is probably because you have already used a cfflush tag in your template or buffered output is turned off."), true);
    }
    EXPECT_EQ(threw, true);
    EXPECT_EQ(cfml::response_committed(), 1);
    EXPECT_EQ(cfml::response().headers.size(), (size_t)0);
}

TEST_F(ResponseHeaderTest, CfHeaderNoAttributesIsCompileError) {
    expectThrows("<cfheader><cfoutput>X</cfoutput>",
                 "Attribute validation error for tag CFHEADER. It has an invalid attribute combination: ''. Possible combinations are: Required attributes: 'name'. Optional attributes: 'charset,value'. Required attributes: 'statuscode'. Optional attributes: None.");
}

TEST_F(ResponseHeaderTest, CfHeaderValueWithoutNameIsCompileError) {
    expectThrows("<cfheader value=\"y\"><cfoutput>X</cfoutput>",
                 "Attribute validation error for tag CFHEADER. It has an invalid attribute combination: 'value'. Possible combinations are: Required attributes: 'name'. Optional attributes: 'charset,value'. Required attributes: 'statuscode'. Optional attributes: None.");
}

TEST_F(ResponseHeaderTest, CfHeaderNameAndStatuscodeIsCompileError) {
    // Both present (any order): invalid combination, attribute list sorted.
    expectThrows("<cfheader name=\"x\" statuscode=\"404\"><cfoutput>X</cfoutput>",
                 "Attribute validation error for tag CFHEADER. It has an invalid attribute combination: 'name,statuscode'. Possible combinations are: Required attributes: 'name'. Optional attributes: 'charset,value'. Required attributes: 'statuscode'. Optional attributes: None.");
    expectThrows("<cfheader statuscode=\"404\" name=\"x\"><cfoutput>X</cfoutput>",
                 "Attribute validation error for tag CFHEADER. It has an invalid attribute combination: 'name,statuscode'. Possible combinations are: Required attributes: 'name'. Optional attributes: 'charset,value'. Required attributes: 'statuscode'. Optional attributes: None.");
}

TEST_F(ResponseHeaderTest, CfHeaderStatusCodeWithStatusTextIgnored) {
    run("<cfheader statuscode=\"404\" statustext=\"Not Found\"><cfoutput>NOTFOUND</cfoutput>");
    EXPECT_EQ(cfml::response().statusCode, 404);
    EXPECT_EQ(cfml::response().headers.size(), (size_t)0);
}

TEST_F(ResponseHeaderTest, CfHeaderUnknownAttributeIsCompileError) {
    expectThrows("<cfheader foo=\"bar\"><cfoutput>X</cfoutput>",
                 "Attribute validation error for tag CFHEADER. It does not allow the attribute(s) FOO. The valid attribute(s) are CHARSET,NAME,STATUSCODE,VALUE.");
}

TEST_F(ResponseHeaderTest, CfLocationAbortsPageAndSetsRedirectState) {
    string out = run("<cfoutput>BEFORE</cfoutput>\n<cflocation url=\"http://example.com/target\">\n<cfoutput>AFTER</cfoutput>");
    EXPECT_EQ(out.equals("BEFORE "), true); // page aborted: AFTER not rendered
    auto &r = cfml::response();
    EXPECT_EQ(r.statusCode, 302);
    EXPECT_EQ(headerValue("location"), "http://example.com/target");
    EXPECT_EQ(headerValue("Cache-Control"), "no-cache");
    EXPECT_EQ(headerValue("Pragma"), "no-cache");
    EXPECT_EQ(cfml::response_committed(), 0); // nothing flushed
}

TEST_F(ResponseHeaderTest, CfLocationStatus301) {
    run("<cflocation url=\"http://example.com/t\" statusCode=\"301\">");
    EXPECT_EQ(cfml::response().statusCode, 301);
    EXPECT_EQ(headerValue("location"), "http://example.com/t");
}

TEST_F(ResponseHeaderTest, CfLocationDynamicStatusCodeAndUrl) {
    run("<cfset u=\"http://example.com/dyn\"><cfset code=302><cflocation url=\"#u#\" statusCode=\"#code#\">");
    EXPECT_EQ(cfml::response().statusCode, 302);
    EXPECT_EQ(headerValue("location"), "http://example.com/dyn");
}

TEST_F(ResponseHeaderTest, CfLocationUrlControlCharsEncoded) {
    // Control characters in the URL are percent-encoded (CF's encodeControlChars).
    run("<cflocation url=\"http://example.com/a#Chr(9)#b\">");
    EXPECT_EQ(headerValue("location"), "http://example.com/a%09b");
}

TEST_F(ResponseHeaderTest, CfLocationStatusRangeValidated) {
    // CF only allows 300-307; 200/308/400 throw at runtime.
    expectThrows("<cfset code=200><cflocation url=\"x\" statusCode=\"#code#\">",
                 "Attribute validation error in the cflocation tag. Value of statuscode must be between 300 and 307.");
    expectThrows("<cflocation url=\"x\" statusCode=\"308\">",
                 "Attribute validation error in the cflocation tag. Value of statuscode must be between 300 and 307.");
}

TEST_F(ResponseHeaderTest, CfLocationMissingUrlIsCompileError) {
    expectThrows("<cflocation statusCode=\"302\">",
                 "Attribute validation error for tag CFLOCATION. It requires the attribute(s): URL.");
}

TEST_F(ResponseHeaderTest, CfLocationUnknownAttributeIsCompileError) {
    expectThrows("<cflocation url=\"x\" foo=\"bar\">",
                 "Attribute validation error for tag CFLOCATION. It does not allow the attribute(s) FOO. The valid attribute(s) are ADDTOKEN,STATUSCODE,URL.");
}

TEST_F(ResponseHeaderTest, CfLocationAfterFlushAbortsWithoutHeaders) {
    string out = run("<cfoutput>FLUSH</cfoutput><cfflush><cflocation url=\"http://example.com/after\">");
    // The response was committed by the flush, so CF silently drops the
    // redirect headers/status but still aborts the page.
    EXPECT_EQ(cfml::response_committed(), 1);
    EXPECT_EQ(cfml::response().statusCode, 200);
    EXPECT_EQ(cfml::response().headers.size(), (size_t)0);
    // The pre-abort output is preserved (the flush parked it for the CLI).
    EXPECT_EQ(cfml::response_encode_all(out).empty(), false);
}

TEST_F(ResponseHeaderTest, CfLocationInLoopAborts) {
    string out = run("<cfloop from=\"1\" to=\"3\" index=\"i\"><cflocation url=\"http://example.com/loop\"></cfloop><cfoutput>AFTER</cfoutput>");
    EXPECT_EQ(out.isEmpty(), true);
    EXPECT_EQ(cfml::response().statusCode, 302);
}

// ---------------------------------------------------------------------------
// Web/HTTP/Output tag unit tests: <cfcookie>, <cfhtmlhead>, <cfsavecontent>,
// <cfsetting> and <cfprocessingdirective>.
//
// These run CFML through the JIT and inspect the response state (Set-Cookie
// bodies, head content, output-only mode) and the output buffer. The normal
// paths are byte-verified against ColdFusion 2025 in tests/cfm/
// (cfcookie_test.cfm, cfhtmlhead_test.cfm, cfsavecontent_test.cfm,
// cfsetting_test.cfm, cfprocessingdirective_test.cfm); the header/error paths
// that the byte-verifier cannot see (Set-Cookie bytes, committed-response
// cookie drop, compile-time validation errors) are covered here.
// ---------------------------------------------------------------------------

class WebOutputTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
        cfml::response_begin();
        cfml::cf_cfoutputonly_set(false);
        // scope_begin normally resets per-request state; the JIT tests run
        // without it, so clear the shared per-thread buffers directly.
        cfml::scope_begin(nullptr, nullptr, nullptr);
    }

    // Runs CFML through the JIT and returns the output buffer.
    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }

    void expectOutput(const string &cfml_code, const char *expected) {
        string out = run(cfml_code);
        EXPECT_EQ(out.equals(expected), true) << "CFML: " << cfml_code.constData() << " -> " << out.constData();
    }

    // Asserts that compiling+running `cfml_code` throws a webstrada::exception
    // whose message equals `msg` (exact match).
    void expectThrows(const string &cfml_code, const char *msg) {
        bool threw = false;
        try {
            run(cfml_code);
        } catch (const webstrada::exception &e) {
            threw = true;
            EXPECT_EQ(string(e.m_message).equals(msg), true)
                << "CFML: " << cfml_code.constData() << " -> " << e.m_message.constData();
        }
        EXPECT_EQ(threw, true) << "CFML: " << cfml_code.constData();
    }

    // The queued Set-Cookie header bodies, in order.
    std::vector<std::string> cookieHeaders() const {
        return cfml::response().cookies;
    }
};

TEST_F(WebOutputTest, CookieBasicUppercasesNameAndEncodesValue) {
    run("<cfcookie name=\"myCookie\" value=\"hello world\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    EXPECT_EQ(cs[0], "MYCOOKIE=hello%20world; Path=/");
}

TEST_F(WebOutputTest, CookieEncodesNonAsciiUtf8) {
    run("<cfcookie name=\"u\" value=\"#Chr(233)#x\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    EXPECT_EQ(cs[0], "U=%C3%A9x; Path=/");
}

TEST_F(WebOutputTest, CookieEncodeValueNoQuotesTokenValues) {
    // URL encoding only ever yields token chars (letters/digits/%); a raw
    // non-encoded value with token chars is written bare.
    run("<cfcookie name=\"q0\" value=\"a+b\" encodevalue=\"no\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    EXPECT_EQ(cs[0], "Q0=a+b; Path=/");
}

TEST_F(WebOutputTest, CookieEncodeValueNoQuotesNonToken) {
    // A space makes the value a non-token: Tomcat quotes it and adds
    // Version=1 (matching CF 2025).
    run("<cfcookie name=\"q1\" value=\"a b\" encodevalue=\"no\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    EXPECT_EQ(cs[0], "Q1=\"a b\"; Version=1; Path=/");
}

TEST_F(WebOutputTest, CookieExpiresNumericDays) {
    run("<cfcookie name=\"exp\" value=\"x\" expires=\"10\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    // maxAge = 86400 * 10; the Expires date is `now + 10 days` in RFC1123 GMT.
    time_t t = time(nullptr) + 10LL * 86400;
    struct tm tmVal;
    gmtime_r(&t, &tmVal);
    static const char *wday[] = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};
    static const char *mon[] = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
    char buf[96];
    snprintf(buf, sizeof(buf), "EXP=x; Expires=%s, %02d %s %04d %02d:%02d:%02d GMT; Path=/",
             wday[tmVal.tm_wday], tmVal.tm_mday, mon[tmVal.tm_mon], tmVal.tm_year + 1900,
             tmVal.tm_hour, tmVal.tm_min, tmVal.tm_sec);
    EXPECT_EQ(cs[0], buf);
}

TEST_F(WebOutputTest, CookieExpiresNeverThirtyYears) {
    run("<cfcookie name=\"nev\" value=\"x\" expires=\"never\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    time_t t = time(nullptr) + 946080000LL;
    struct tm tmVal;
    gmtime_r(&t, &tmVal);
    static const char *wday[] = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};
    static const char *mon[] = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
    char buf[96];
    snprintf(buf, sizeof(buf), "NEV=x; Expires=%s, %02d %s %04d %02d:%02d:%02d GMT; Path=/",
             wday[tmVal.tm_wday], tmVal.tm_mday, mon[tmVal.tm_mon], tmVal.tm_year + 1900,
             tmVal.tm_hour, tmVal.tm_min, tmVal.tm_sec);
    EXPECT_EQ(cs[0], buf);
}

TEST_F(WebOutputTest, CookieExpiresNowIsEpochPlusTen) {
    run("<cfcookie name=\"now\" value=\"x\" expires=\"now\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    EXPECT_EQ(cs[0], "NOW=x; Expires=Thu, 01 Jan 1970 00:00:10 GMT; Path=/");
}

TEST_F(WebOutputTest, CookieSessionCookieHasNoExpires) {
    run("<cfcookie name=\"s\" value=\"x\" expires=\"session\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    EXPECT_EQ(cs[0], "S=x; Path=/");
}

TEST_F(WebOutputTest, CookiePastSlashDateIsEpochPlusTen) {
    run("<cfcookie name=\"d1\" value=\"x\" expires=\"10/09/97\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    EXPECT_EQ(cs[0], "D1=x; Expires=Thu, 01 Jan 1970 00:00:10 GMT; Path=/");
}

TEST_F(WebOutputTest, CookieFutureSlashDateUsesDiff) {
    run("<cfcookie name=\"d3\" value=\"x\" expires=\"08/11/2099\"><cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    // 2099-08-11 is a real (future) date: maxAge is a positive diff, so the
    // header carries an Expires date plus the Path.
    EXPECT_EQ(cs[0].compare(0, 5, "D3=x;"), 0);
    EXPECT_NE(cs[0].find("Expires="), std::string::npos);
    EXPECT_EQ(cs[0].size() >= 8 && cs[0].compare(cs[0].size() - 8, 8, "; Path=/") == 0, true);
}

