TEST_F(WebOutputTest, CookieSecureHttpOnlyAndSamesiteOrder) {
    run("<cfcookie name=\"qed\" value=\"a b\" encodevalue=\"no\" expires=\"never\" "
        "domain=\".x.com\" secure=\"yes\" httpOnly=\"yes\" samesite=\"lax\" path=\"/p\">"
        "<cfoutput>OK</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    // SameSite forces CF's own header builder: raw value, RFC850 12-hour date.
    EXPECT_EQ(cs[0].compare(0, 8, "QED=a b;"), 0);
    EXPECT_NE(cs[0].find("; Domain=.x.com; Max-Age=946080000; Expires="), std::string::npos);
    EXPECT_NE(cs[0].find("; Path=/p; Secure; HttpOnly; SameSite=lax"), std::string::npos);
}

