// ---------------------------------------------------------------------------
// <cflogin> / <cfloginuser> / <cflogout> + the auth functions.
//
// The body-output paths are byte-verified against CF 2025 in tests/cfm/
// (cflogin_basic_test.cfm, cflogin_user_outside_test.cfm, cflogout_test.cfm,
// cflogin_roles_test.cfm, cflogin_timing_test.cfm, cflogin_session_storage_test.cfm).
// The Set-Cookie bytes and the cookie/session round-trip (which the byte
// verifier cannot see) are covered here.
// ---------------------------------------------------------------------------

class LoginTagTest : public testing::Test {
protected:
    cfvariant variables;
    cfvariant cgi, server, cookie, application, session, url, form;
    ScopeStore m_store;
    std::string m_dbPath;

    void SetUp() override {
        variables = cfvariant::Struct;
        cfml::response_begin();
        cfml::cf_cfoutputonly_set(false);
        // A real SQLite store so the auth pool (cf_security) works.
        char db[] = "/tmp/webstrada_login_test_XXXXXX";
        int fd = mkstemp(db);
        if (fd == -1) throw std::runtime_error("mkstemp failed");
        close(fd);
        unlink(db);
        m_dbPath = db;
        if (!m_store.open(m_dbPath)) throw std::runtime_error("scope store open failed");
        cfml::scope_begin(&m_store, &application, &session);
    }

    void TearDown() override {
        cfml::scope_end();
        m_store.close();
        unlink(m_dbPath.c_str());
        unlink((m_dbPath + "-wal").c_str());
        unlink((m_dbPath + "-shm").c_str());
    }

    // Runs CFML through the JIT with the test scopes (cookie/url/form/session
    // seeded from the member variants) and returns the output buffer.
    string run(const string &cfml_code) {
        char temp_path[] = "/tmp/webstrada_login_jit_XXXXXX";
        int fd = mkstemp(temp_path);
        if (fd == -1) throw std::runtime_error("mkstemp failed");
        string code = cfml_code;
        if (write(fd, code.constData(), code.length()) != (ssize_t)code.length()) {
            close(fd);
            unlink(temp_path);
            throw std::runtime_error("write failed");
        }
        close(fd);

        string out;
        try {
            llvm_codegen comp;
            auto compiled = comp.compile(temp_path, false);
            unlink(temp_path);
            if (!compiled) throw std::runtime_error("compile failed");
            cfml::VariantCleanupGuard guard;
            compiled(&out, &cgi, &server, &cookie, &application, &session, &url, &form, &variables);
        } catch (...) {
            unlink(temp_path);
            throw;
        }
        return out;
    }

    // The queued Set-Cookie header bodies, in order.
    std::vector<std::string> cookieHeaders() const {
        return cfml::response().cookies;
    }
};

TEST_F(LoginTagTest, LoginSetsAuthCookieWithTokenAndHttpOnly) {
    run("<cflogin><cfloginuser name=\"bob\" password=\"secret\" roles=\"admin\"></cflogin>"
        "<cfoutput>#IsUserLoggedIn()#|#GetAuthUser()#|#GetUserRoles()#</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    // CFAUTHORIZATION_<apptoken>="<b64>"; Version=1; Path=/; HttpOnly (the
    // base64 token has '=' padding so it is a non-token value -> quoted).
    EXPECT_EQ(cs[0].compare(0, std::string("CFAUTHORIZATION_=").size(), "CFAUTHORIZATION_="), 0);
    EXPECT_EQ(cs[0].find("; Version=1; Path=/; HttpOnly") != std::string::npos, true);
    // The cookie value is base64(username\r appToken\r time\r nonce).
    std::string value = cs[0].substr(std::string("CFAUTHORIZATION_=").size());
    // value is "\"<b64>\"; Version=1; ..." — strip the surrounding quotes.
    ASSERT_EQ(value[0], '"');
    size_t quote = value.find('"', 1);
    ASSERT_NE(quote, std::string::npos);
    value = value.substr(1, quote - 1);
    std::vector<std::byte> bytes;
    cfml::binaryDecodeBase64(webstrada::string(value.c_str()), bytes, false);
    std::string dec(bytes.begin(), bytes.end());
    // username \r empty-appToken \r time \r 16-hex nonce
    size_t r1 = dec.find('\r');
    ASSERT_NE(r1, std::string::npos);
    size_t r2 = dec.find('\r', r1 + 1);
    ASSERT_NE(r2, std::string::npos);
    size_t r3 = dec.find('\r', r2 + 1);
    ASSERT_NE(r3, std::string::npos);
    EXPECT_EQ(dec.substr(0, r1), "bob");
    EXPECT_EQ(dec.substr(r1 + 1, r2 - r1 - 1), "");  // no <cfapplication> -> empty token
    EXPECT_EQ(dec.substr(r3 + 1).size(), (size_t)16);
}

TEST_F(LoginTagTest, LoginNoBodyUserLogsOutEmitsEmptyCookie) {
    // <cflogin> body runs but no <cfloginuser>: doEndTag logs out -> the empty
    // (maxAge 0) CFAUTHORIZATION cookie, exactly like CF 2025.
    run("<cflogin><cfset x = 1></cflogin><cfoutput>#IsUserLoggedIn()#</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    EXPECT_EQ(cs[0], "CFAUTHORIZATION_=\"\"; Max-Age=0; Expires=Thu, 01-Jan-1970 12:00:00 GMT; Path=/; HttpOnly");
}

TEST_F(LoginTagTest, LoginCookieRoundTripSkipsBody) {
    // Request 1: not logged in -> body runs, cfloginuser sets the login, and a
    // CFAUTHORIZATION cookie is issued.
    string out1 = run("<cflogin><cfset bodyran = \"yes\"><cfloginuser name=\"frank\" password=\"pw\" roles=\"z\"></cflogin>"
                      "<cfoutput>#IsUserLoggedIn()#|#GetAuthUser()#</cfoutput>");
    EXPECT_EQ(out1.equals("YES|frank"), true);
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)1);
    std::string prefix = "CFAUTHORIZATION_=\"";
    ASSERT_EQ(cs[0].compare(0, prefix.size(), prefix), 0);
    size_t q = cs[0].find('"', prefix.size());
    ASSERT_NE(q, std::string::npos);
    std::string token = cs[0].substr(prefix.size(), q - prefix.size());

    // Request 2: feed the cookie back -> the login resolves, body is skipped.
    // The cookie scope is a fresh empty struct per request (the worker fills it
    // from the Cookie header); seed it the same way. Reset the variables scope
    // too (request 1 left `bodyran` in it).
    variables = cfvariant::Struct;
    cookie.set_type(cfvariant::Struct);
    cookie.structSet("CFAUTHORIZATION_", webstrada::string(token.c_str()));
    string out2 = run("<cflogin><cfset bodyran = \"yes\"><cfloginuser name=\"frank\" password=\"pw\" roles=\"z\"></cflogin>"
                      "<cfoutput>#IsUserLoggedIn()#|#GetAuthUser()#|#isDefined(\"bodyran\")#</cfoutput>");
    // BODYRAN stays undefined because the body was skipped.
    EXPECT_EQ(out2.equals("YES|frank|NO"), true);
}

TEST_F(LoginTagTest, LogoutClearsCookie) {
    run("<cflogin><cfloginuser name=\"carol\" password=\"pw\" roles=\"r1\"></cflogin>"
        "<cflogout><cfoutput>#IsUserLoggedIn()#</cfoutput>");
    auto cs = cookieHeaders();
    ASSERT_EQ(cs.size(), (size_t)2);
    // login cookie then logout cookie (empty, maxAge 0).
    EXPECT_EQ(cs[0].find("CFAUTHORIZATION_=") == 0, true);
    EXPECT_EQ(cs[1], "CFAUTHORIZATION_=\"\"; Max-Age=0; Expires=Thu, 01-Jan-1970 12:00:00 GMT; Path=/; HttpOnly");
}

TEST_F(LoginTagTest, LoginUserOutsideCfloginSetsNoCookie) {
    // <cfloginuser> outside <cflogin> logs the request in directly with no
    // cookie (CF's UserTag with no AuthenticateTag ancestor).
    run("<cfloginuser name=\"jack\" password=\"pw\" roles=\"solo\">"
        "<cfoutput>#IsUserLoggedIn()#|#GetAuthUser()#|#GetUserRoles()#</cfoutput>");
    EXPECT_EQ(cfml::response().cookies.size(), (size_t)0);
}

TEST_F(LoginTagTest, SessionStorageStoresKeyInSession) {
    // <cfapplication loginstorage="session">: the token lives in the session
    // scope, no CFAUTHORIZATION cookie is emitted (CFID/CFTOKEN session
    // cookies may appear from <cfapplication sessionmanagement>).
    run("<cfapplication name=\"sessapp\" sessionmanagement=\"true\" loginstorage=\"session\">"
        "<cflogin><cfloginuser name=\"dave\" password=\"pw\" roles=\"a,b\"></cflogin>"
        "<cfoutput>#IsUserLoggedIn()#|#GetUserRoles()#</cfoutput>");
    for (const auto &c : cfml::response().cookies) {
        EXPECT_NE(c.compare(0, std::string("CFAUTHORIZATION_").size(), "CFAUTHORIZATION_"), 0) << "unexpected auth cookie: " << c;
    }
    auto it = session.m_struct->find(webstrada::string("CFAUTHORIZATION_sessapp"));
    ASSERT_NE(it, session.m_struct->end());
    std::vector<std::byte> bytes;
    cfml::binaryDecodeBase64(const_cast<cfvariant&>(it->second).toString(), bytes, false);
    std::string dec(bytes.begin(), bytes.end());
    size_t r1 = dec.find('\r');
    ASSERT_NE(r1, std::string::npos);
    EXPECT_EQ(dec.substr(0, r1), "dave");
}

TEST_F(LoginTagTest, AuthFunctionsWhenNotLoggedIn) {
    // No login: GetAuthUser() is "", IsUserLoggedIn() NO, roles/role checks
    // empty/false.
    string out = run("<cfoutput>#GetAuthUser()#|#IsUserLoggedIn()#|#GetUserRoles()#|"
                     "#IsUserInRole(\"admin\")#|#IsUserInAnyRole(\"admin,user\")#</cfoutput>");
    EXPECT_EQ(out.equals("|NO||NO|NO"), true);
}

TEST_F(LoginTagTest, JUsernamePopulatesCfloginStructInBody) {
    // j_username/j_password in the URL scope populate the `cflogin` struct
    // {NAME, PASSWORD} inside the body; it is removed after the tag.
    url.set_type(cfvariant::Struct);
    url.structSet("J_USERNAME", webstrada::string("alice"));
    url.structSet("J_PASSWORD", webstrada::string("secretpw"));
    string out = run("<cflogin><cfoutput>#cflogin.name#|#cflogin.password#|#IsUserLoggedIn()#</cfoutput></cflogin>"
                     "<cfoutput>|#isDefined(\"cflogin\")#</cfoutput>");
    // The struct is visible in the body; IsUserLoggedIn stays NO until the end
    // tag; after </cflogin> the struct is gone.
    EXPECT_EQ(out.equals("alice|secretpw|NO|NO"), true);
}

TEST_F(LoginTagTest, SessionStorageRoundTripResolvesLogin) {
    // loginstorage="session" with a follow-up request: the session key resolves
    // the login and skips the body.
    run("<cfapplication name=\"sessapp\" sessionmanagement=\"true\" loginstorage=\"session\">"
        "<cflogin><cfset bodyran = \"yes\"><cfloginuser name=\"dave\" password=\"pw\" roles=\"a,b\"></cflogin>"
        "<cfoutput>#IsUserLoggedIn()#|#GetAuthUser()#</cfoutput>");
    // Persist the session (request boundary, like the worker's scope_end) then
    // reload it as request 2, feeding the CFID/CFTOKEN cookies back so the
    // same session is resumed.
    std::string cfid, cftoken;
    for (const auto &c : cfml::response().cookies) {
        if (c.compare(0, 4, "CFID") == 0) cfid = c.substr(5, c.find(';', 5) - 5);
        else if (c.compare(0, 7, "CFTOKEN") == 0) cftoken = c.substr(8, c.find(';', 8) - 8);
    }
    cfml::scope_end();
    variables = cfvariant::Struct;
    cookie.set_type(cfvariant::Struct);
    if (!cfid.empty()) cookie.structSet("CFID", webstrada::string(cfid.c_str()));
    if (!cftoken.empty()) cookie.structSet("CFTOKEN", webstrada::string(cftoken.c_str()));
    cfml::response_begin();
    cfml::scope_begin(&m_store, &application, &session);
    string out2 = run("<cfapplication name=\"sessapp\" sessionmanagement=\"true\" loginstorage=\"session\">"
        "<cflogin><cfset bodyran = \"yes\"><cfloginuser name=\"dave\" password=\"pw\" roles=\"a,b\"></cflogin>"
        "<cfoutput>#IsUserLoggedIn()#|#GetAuthUser()#|#isDefined(\"bodyran\")#</cfoutput>");
    // BODYRAN stays undefined because the body was skipped on request 2.
    EXPECT_EQ(out2.equals("YES|dave|NO"), true);
}

