// ---------------------------------------------------------------------------
// Input-encoding pipeline (BOM / pageEncoding / ICU detection / default).
//
// These feed raw source bytes (UTF BOMs, Latin-1, windows-1252, UTF-16) to the
// compiler and verify ColdFusion's input-encoding order. The behavior is
// byte-verified against CF 2025 on the RDS host in
// tests/cfm/input_encoding_*_test.cfm (see PROGRESS.md).
// ---------------------------------------------------------------------------

namespace {

// Writes `bytes` to a fresh temp file, compiles it as a template and returns
// the page output.
static string runTemplateBytes(const std::vector<char> &bytes) {
    char temp_path[] = "/tmp/webstrada_enc_test_XXXXXX";
    int fd = mkstemp(temp_path);
    if (fd == -1) throw std::runtime_error("Failed to create temporary file");
    if (!bytes.empty() && write(fd, bytes.data(), bytes.size()) != (ssize_t)bytes.size()) {
        close(fd); unlink(temp_path); throw std::runtime_error("Failed to write file");
    }
    close(fd);
    string out;
    try {
        llvm_codegen comp;
        auto compiled = comp.compile(temp_path, false);
        unlink(temp_path);
        if (!compiled) throw std::runtime_error("Failed to compile");
        cfvariant cgi = cfvariant::Struct, server = cfvariant::Struct, cookie = cfvariant::Struct;
        cfvariant application = cfvariant::Struct, session = cfvariant::Struct, url = cfvariant::Struct;
        cfvariant form = cfvariant::Struct, variables = cfvariant::Struct;
        cfml::VariantCleanupGuard guard;
        compiled(&out, &cgi, &server, &cookie, &application, &session, &url, &form, &variables);
    } catch (...) {
        unlink(temp_path);
        throw;
    }
    return out;
}

// Returns the compile-time error message (or "" on success).
static std::string compileBytesError(const std::vector<char> &bytes) {
    try {
        runTemplateBytes(bytes);
        return "";
    } catch (const webstrada::exception &ex) {
        return ex.m_message.isEmpty() ? "" : std::string(ex.m_message.constData());
    }
}

static std::vector<char> vecOf(const char *s, size_t len) {
    return std::vector<char>(s, s + len);
}

// Encodes UTF-8 `text` to UTF-16 (LE/BE) bytes without a BOM.
static std::vector<char> utf16FromUtf8(const std::string &text, bool bigEndian) {
    std::vector<char> out;
    size_t i = 0;
    while (i < text.size()) {
        unsigned char c = static_cast<unsigned char>(text[i]);
        uint32_t cp;
        size_t extra;
        if (c < 0x80) { cp = c; extra = 0; }
        else if ((c & 0xE0) == 0xC0) { cp = c & 0x1F; extra = 1; }
        else if ((c & 0xF0) == 0xE0) { cp = c & 0x0F; extra = 2; }
        else if ((c & 0xF8) == 0xF0) { cp = c & 0x07; extra = 3; }
        else { cp = 0xFFFD; extra = 0; }
        for (size_t k = 1; k <= extra && i + k < text.size(); k++) {
            cp = (cp << 6) | (static_cast<unsigned char>(text[i + k]) & 0x3F);
        }
        i += extra + 1;
        if (cp < 0x10000) {
            out.push_back(bigEndian ? (char)(cp >> 8) : (char)(cp & 0xFF));
            out.push_back(bigEndian ? (char)(cp & 0xFF) : (char)(cp >> 8));
        } else {
            uint32_t v = cp - 0x10000;
            uint32_t hi = 0xD800 + (v >> 10);
            uint32_t lo = 0xDC00 + (v & 0x3FF);
            out.push_back(bigEndian ? (char)(hi >> 8) : (char)(hi & 0xFF));
            out.push_back(bigEndian ? (char)(hi & 0xFF) : (char)(hi >> 8));
            out.push_back(bigEndian ? (char)(lo >> 8) : (char)(lo & 0xFF));
            out.push_back(bigEndian ? (char)(lo & 0xFF) : (char)(lo >> 8));
        }
    }
    return out;
}

} // namespace

class TemplateEncodingTest : public testing::Test {
protected:
    static webstrada::string runBytes(const std::vector<char> &bytes) { return runTemplateBytes(bytes); }
};

TEST_F(TemplateEncodingTest, Utf8BomStrippedAndDecoded) {
    // A UTF-8 BOM is stripped and the source decoded as UTF-8.
    std::string src = "\xEF\xBB\xBF<cfoutput>caf\xC3\xA9 \xE4\xB8\x96\xE7\x95\x8C</cfoutput>";
    EXPECT_EQ(runBytes(vecOf(src.data(), src.size())).equals("caf\xC3\xA9 \xE4\xB8\x96\xE7\x95\x8C"), true);
}

TEST_F(TemplateEncodingTest, Utf8NoBomDecodedViaDefault) {
    // UTF-8 without BOM/directive: ICU rejects short samples below the 100
    // threshold, so the default input charset (UTF-8) decodes it.
    std::string src = "<cfoutput>caf\xC3\xA9</cfoutput>";
    EXPECT_EQ(runBytes(vecOf(src.data(), src.size())).equals("caf\xC3\xA9"), true);
}

TEST_F(TemplateEncodingTest, Utf16LeBomDecoded) {
    // UTF-16LE BOM is stripped and the source decoded as UTF-16LE.
    std::vector<char> bytes;
    bytes.push_back('\xFF'); bytes.push_back('\xFE');
    std::vector<char> u16 = utf16FromUtf8("<cfoutput>caf\xC3\xA9</cfoutput>", false);
    bytes.insert(bytes.end(), u16.begin(), u16.end());
    EXPECT_EQ(runBytes(bytes).equals("caf\xC3\xA9"), true);
}

TEST_F(TemplateEncodingTest, Utf16BeBomDecoded) {
    std::vector<char> bytes;
    bytes.push_back('\xFE'); bytes.push_back('\xFF');
    std::vector<char> u16 = utf16FromUtf8("<cfoutput>caf\xC3\xA9</cfoutput>", true);
    bytes.insert(bytes.end(), u16.begin(), u16.end());
    EXPECT_EQ(runBytes(bytes).equals("caf\xC3\xA9"), true);
}

TEST_F(TemplateEncodingTest, PageEncodingRereadsLatin1) {
    // No BOM: pageEncoding="ISO-8859-1" re-reads the file with Latin-1, so the
    // 0xE9 byte becomes U+00E9 (é) and the page outputs UTF-8.
    std::string src = "<cfprocessingdirective pageEncoding=\"ISO-8859-1\">\r\n<cfoutput>caf\xE9</cfoutput>";
    EXPECT_EQ(runBytes(vecOf(src.data(), src.size())).equals("caf\xC3\xA9"), true);
}

TEST_F(TemplateEncodingTest, PageEncodingRereadsWindows1252) {
    // 0x93 in windows-1252 is U+201C (left double quotation mark).
    std::string src = "<cfprocessingdirective pageEncoding=\"windows-1252\">\r\n<cfoutput>smart\x93</cfoutput>";
    EXPECT_EQ(runBytes(vecOf(src.data(), src.size())).equals("smart\xE2\x80\x9C"), true);
}

TEST_F(TemplateEncodingTest, Utf8BomConflictingPageEncodingIsCompileError) {
    std::string src = "\xEF\xBB\xBF<cfprocessingdirective pageEncoding=\"ISO-8859-1\">\r\nx";
    std::string err = compileBytesError(vecOf(src.data(), src.size()));
    EXPECT_EQ(err, "Cannot use the charset ISO-8859-1 because the file has a Byte Order Mark indicating it uses the charset UTF8.");
}

TEST_F(TemplateEncodingTest, Utf16LeBomConflictingPageEncodingIsCompileError) {
    std::string text = "<cfprocessingdirective pageEncoding=\"ISO-8859-1\">\r\nx";
    std::vector<char> bytes;
    bytes.push_back('\xFF'); bytes.push_back('\xFE');
    for (char c : text) { bytes.push_back(c); bytes.push_back('\0'); }
    std::string err = compileBytesError(bytes);
    EXPECT_EQ(err, "Cannot use the charset ISO-8859-1 because the file has a Byte Order Mark indicating it uses the charset UnicodeLittleUnmarked.");
}

TEST_F(TemplateEncodingTest, Utf16LeBomWithUtf16PageEncodingAccepted) {
    // isEncodingMatch: pageEncoding="UTF-16" matches either Unicode endianness.
    std::vector<char> bytes;
    bytes.push_back('\xFF'); bytes.push_back('\xFE');
    std::vector<char> u16 = utf16FromUtf8("<cfprocessingdirective pageEncoding=\"UTF-16\">\r\n<cfoutput>OK16</cfoutput>", false);
    bytes.insert(bytes.end(), u16.begin(), u16.end());
    EXPECT_EQ(runBytes(bytes).equals("OK16"), true);
}

TEST_F(TemplateEncodingTest, Utf16LeBomWithUtf16LePageEncodingAccepted) {
    std::vector<char> bytes;
    bytes.push_back('\xFF'); bytes.push_back('\xFE');
    std::vector<char> u16 = utf16FromUtf8("<cfprocessingdirective pageEncoding=\"UTF-16LE\">\r\n<cfoutput>OK16LE</cfoutput>", false);
    bytes.insert(bytes.end(), u16.begin(), u16.end());
    EXPECT_EQ(runBytes(bytes).equals("OK16LE"), true);
}

TEST_F(TemplateEncodingTest, UnsupportedPageEncodingIsCompileError) {
    std::string src = "<cfprocessingdirective pageEncoding=\"BOGUS\">x</cfprocessingdirective>";
    EXPECT_EQ(compileBytesError(vecOf(src.data(), src.size())),
              "The specified page encoding, BOGUS, is not supported.");
}

TEST_F(TemplateEncodingTest, EmptyPageEncodingIsCompileError) {
    // CF renders the empty value as '' in the message.
    std::string src = "<cfprocessingdirective pageEncoding=\"\">x</cfprocessingdirective>";
    EXPECT_EQ(compileBytesError(vecOf(src.data(), src.size())),
              "The specified page encoding, '', is not supported.");
}

TEST_F(TemplateEncodingTest, NonLiteralPageEncodingIsCompileError) {
    std::string src = "<cfset enc=\"UTF-8\">\r\n<cfprocessingdirective pageEncoding=\"#enc#\">x</cfprocessingdirective>";
    EXPECT_EQ(compileBytesError(vecOf(src.data(), src.size())),
              "Expression at line 2 has to be constant value.");
}

TEST_F(TemplateEncodingTest, UnquotedPageEncodingAccepted) {
    std::string src = "<cfprocessingdirective pageEncoding=UTF-8>\r\n<cfoutput>UNQ</cfoutput>";
    EXPECT_EQ(runBytes(vecOf(src.data(), src.size())).equals("UNQ"), true);
}

TEST_F(TemplateEncodingTest, Utf16WithoutBomDetectedByIcu) {
    // UTF-16LE content without a BOM: ICU reports 100% confidence (>= the
    // default threshold), so the file is read as UTF-16LE even without a
    // directive.
    std::vector<char> bytes = utf16FromUtf8("<cfoutput>UTF16DETECT</cfoutput>", false);
    EXPECT_EQ(runBytes(bytes).equals("UTF16DETECT"), true);
}

TEST_F(TemplateEncodingTest, PageEncodingInCommentedDirectiveIgnored) {
    // A commented-out <cfprocessingdirective> must not re-decode the page.
    std::string src = "<!--- <cfprocessingdirective pageEncoding=\"ISO-8859-1\"> --->\r\n<cfoutput>caf\xC3\xA9</cfoutput>";
    EXPECT_EQ(runBytes(vecOf(src.data(), src.size())).equals("caf\xC3\xA9"), true);
}

// ---------------------------------------------------------------------------
// Drawing-axis transform and ImageDrawText (best-effort) unit tests.
//
// These run CFML through the JIT, write the resulting image to a PNG in the
// repo tmp/ directory and sample the decoded pixels with cairo. The exact
// drawing-axis semantics (post-multiplied transform, clockwise-positive
// rotation, clearrect honoring the axis) were verified against ColdFusion
// 2025; ImageDrawText output cannot be pixel-verified against CF (the server
// crashes on all text rendering), so its test only checks the coarse
// placement.
// ---------------------------------------------------------------------------

namespace {

// Returns (r, g, b) straight values of a pixel in an ARGB32 PNG, or false if
// the file cannot be decoded.
static bool samplePngPixel(const std::string &path, int x, int y, uint8_t *r, uint8_t *g, uint8_t *b)
{
    cairo_surface_t *sf = cairo_image_surface_create_from_png(path.c_str());
    if (!sf || cairo_surface_status(sf) != CAIRO_STATUS_SUCCESS) {
        if (sf) cairo_surface_destroy(sf);
        return false;
    }
    int w = cairo_image_surface_get_width(sf);
    int h = cairo_image_surface_get_height(sf);
    if (x < 0 || y < 0 || x >= w || y >= h) {
        cairo_surface_destroy(sf);
        return false;
    }
    int stride = cairo_image_surface_get_stride(sf);
    const uint32_t *d = (const uint32_t*)cairo_image_surface_get_data(sf);
    uint32_t p = d[y * stride / 4 + x];
    uint8_t a = (uint8_t)((p >> 24) & 0xFF);
    uint8_t pr = (uint8_t)((p >> 16) & 0xFF);
    uint8_t pg = (uint8_t)((p >> 8) & 0xFF);
    uint8_t pb = (uint8_t)(p & 0xFF);
    if (a && a != 255) { pr = (uint8_t)((pr * 255) / a); pg = (uint8_t)((pg * 255) / a); pb = (uint8_t)((pb * 255) / a); }
    *r = pr; *g = pg; *b = pb;
    cairo_surface_destroy(sf);
    return true;
}

static bool pngPixelIs(const std::string &path, int x, int y, uint8_t er, uint8_t eg, uint8_t eb)
{
    uint8_t r, g, b;
    if (!samplePngPixel(path, x, y, &r, &g, &b)) return false;
    return r == er && g == eg && b == eb;
}

static int pngNonBlackCount(const std::string &path)
{
    cairo_surface_t *sf = cairo_image_surface_create_from_png(path.c_str());
    if (!sf || cairo_surface_status(sf) != CAIRO_STATUS_SUCCESS) {
        if (sf) cairo_surface_destroy(sf);
        return -1;
    }
    int w = cairo_image_surface_get_width(sf);
    int h = cairo_image_surface_get_height(sf);
    int stride = cairo_image_surface_get_stride(sf);
    const uint32_t *d = (const uint32_t*)cairo_image_surface_get_data(sf);
    int count = 0;
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            uint32_t p = d[y * stride / 4 + x];
            uint8_t a = (uint8_t)((p >> 24) & 0xFF);
            uint8_t pr = (uint8_t)((p >> 16) & 0xFF);
            uint8_t pg = (uint8_t)((p >> 8) & 0xFF);
            uint8_t pb = (uint8_t)(p & 0xFF);
            if (a && a != 255) { pr = (uint8_t)((pr * 255) / a); pg = (uint8_t)((pg * 255) / a); pb = (uint8_t)((pb * 255) / a); }
            if (pr != 0 || pg != 0 || pb != 0) count++;
        }
    }
    cairo_surface_destroy(sf);
    return count;
}

} // namespace

TEST_F(JitExpressionTest, ImageTranslateDrawingAxisFillsRectAtOffset) {
    std::filesystem::create_directories("tmp");
    runJitTemplate(
        "<cfset im = ImageNew(\"\", 30, 30, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"red\")>"
        "<cfset ImageTranslateDrawingAxis(im, 5, 5)>"
        "<cfset ImageDrawRect(im, 0, 0, 10, 10, true)>"
        "<cfset ImageWrite(im, \"tmp/ut_ax_translate.png\", true)>", variables);
    // Filled rect (0,0,10,10) shifted by (5,5) covers [5,14]x[5,14].
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_translate.png", 5, 5, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_translate.png", 14, 14, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_translate.png", 4, 4, 0, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_translate.png", 15, 15, 0, 0, 0), true);
}

TEST_F(JitExpressionTest, ImageTranslateDrawingAxisCumulative) {
    runJitTemplate(
        "<cfset im = ImageNew(\"\", 30, 30, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"red\")>"
        "<cfset ImageTranslateDrawingAxis(im, 3, 4)>"
        "<cfset ImageTranslateDrawingAxis(im, 2, 1)>"
        "<cfset ImageDrawLine(im, 0, 0, 5, 0)>"
        "<cfset ImageWrite(im, \"tmp/ut_ax_cumul.png\", true)>", variables);
    // Two translates sum to (5,5): the horizontal line lands on row 5,
    // columns 5..10.
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_cumul.png", 5, 5, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_cumul.png", 10, 5, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_cumul.png", 11, 5, 0, 0, 0), true);
}

TEST_F(JitExpressionTest, ImageRotateDrawingAxis90AboutCenter) {
    runJitTemplate(
        "<cfset im = ImageNew(\"\", 30, 30, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"red\")>"
        "<cfset ImageRotateDrawingAxis(im, 90, 15, 15)>"
        "<cfset ImageDrawLine(im, 0, 15, 30, 15)>"
        "<cfset ImageWrite(im, \"tmp/ut_ax_rotate.png\", true)>", variables);
    // Rotating the horizontal line (0..30, 15) by +90 deg about (15,15)
    // yields a vertical line on column 15. cairo may land one pixel off the
    // Java2D column, so accept columns 14..16.
    bool found = false;
    for (int col = 14; col <= 16; col++) {
        if (pngPixelIs("tmp/ut_ax_rotate.png", col, 15, 255, 0, 0)) found = true;
    }
    EXPECT_EQ(found, true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_rotate.png", 14, 29, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_rotate.png", 0, 0, 0, 0, 0), true);
}

TEST_F(JitExpressionTest, ImageShearDrawingAxisLinesSlope) {
    runJitTemplate(
        "<cfset im = ImageNew(\"\", 30, 30, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"red\")>"
        "<cfset ImageShearDrawingAxis(im, 0.5, 0)>"
        "<cfset ImageDrawLine(im, 0, 0, 0, 10)>"
        "<cfset ImageWrite(im, \"tmp/ut_ax_shear.png\", true)>", variables);
    // Shear x as a function of y: x' = x + 0.5*y. The vertical line (0,0..10)
    // becomes (0,0)..(5,10).
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_shear.png", 0, 0, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_shear.png", 5, 10, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_shear.png", 10, 5, 0, 0, 0), true);
}

TEST_F(JitExpressionTest, ImageClearRectHonorsAxisTransform) {
    runJitTemplate(
        "<cfset im = ImageNew(\"\", 30, 30, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"red\")>"
        "<cfset ImageDrawRect(im, 0, 0, 29, 29, true)>"
        "<cfset ImageSetBackgroundColor(im, \"white\")>"
        "<cfset ImageTranslateDrawingAxis(im, 5, 5)>"
        "<cfset ImageClearRect(im, 0, 0, 10, 10)>"
        "<cfset ImageWrite(im, \"tmp/ut_ax_clear.png\", true)>", variables);
    // The cleared rect is translated to [5,14]x[5,14] (verified vs CF 2025).
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_clear.png", 5, 5, 255, 255, 255), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_clear.png", 14, 14, 255, 255, 255), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_clear.png", 0, 0, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_ax_clear.png", 20, 20, 255, 0, 0), true);
}

TEST_F(JitExpressionTest, ImageDrawTextRendersAtBaseline) {
    runJitTemplate(
        "<cfset im = ImageNew(\"\", 60, 30, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"white\")>"
        "<cfset attrs = {font: \"SansSerif\", size: 14}>"
        "<cfset ImageDrawText(im, \"Ag\", 2, 20, attrs)>"
        "<cfset ImageWrite(im, \"tmp/ut_text_base.png\", true)>", variables);
    // Text glyphs appear below the top of the image, starting near x=2.
    EXPECT_EQ(pngPixelIs("tmp/ut_text_base.png", 2, 20, 0, 0, 0), true); // baseline itself is not ink
    int count = pngNonBlackCount("tmp/ut_text_base.png");
    EXPECT_GT(count, 20);
    // Ink must sit in the expected region (y between baseline-ascent and the
    // descender) rather than at the image origin.
    EXPECT_EQ(pngPixelIs("tmp/ut_text_base.png", 0, 0, 0, 0, 0), true);
    uint8_t r, g, b;
    bool anyNearBaseline = false;
    for (int x = 2; x < 20; x++) {
        for (int y = 8; y <= 22; y++) {
            if (samplePngPixel("tmp/ut_text_base.png", x, y, &r, &g, &b) && r == 255 && g == 255 && b == 255)
                anyNearBaseline = true;
        }
    }
    EXPECT_EQ(anyNearBaseline, true);
}

TEST_F(JitExpressionTest, ImageDrawTextRespectsAxisTransform) {
    runJitTemplate(
        "<cfset im = ImageNew(\"\", 60, 30, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"white\")>"
        "<cfset ImageTranslateDrawingAxis(im, 10, 5)>"
        "<cfset ImageDrawText(im, \"Hi\", 2, 20)>"
        "<cfset ImageWrite(im, \"tmp/ut_text_axis.png\", true)>", variables);
    // Translate (10,5) moves the baseline to (12,25); ink appears there, not
    // at the untranslated spot.
    EXPECT_EQ(pngPixelIs("tmp/ut_text_axis.png", 0, 0, 0, 0, 0), true);
    EXPECT_EQ(pngNonBlackCount("tmp/ut_text_axis.png") > 0, true);
    // Untranslated baseline (2,20) region must be empty (region kept clear of
    // the translated glyphs at x>=13).
    bool inkAtUntranslated = false;
    uint8_t r, g, b;
    for (int x = 3; x < 12; x++) {
        for (int y = 12; y <= 19; y++) {
            if (samplePngPixel("tmp/ut_text_axis.png", x, y, &r, &g, &b) && r == 255 && g == 255 && b == 255)
                inkAtUntranslated = true;
        }
    }
    EXPECT_EQ(inkAtUntranslated, false);
}

// ===========================================================================
// Image pixel/geometry operations (ImageFlip, ImageGrayscale, ImageNegative,
// ImageCrop, ImageResize, ImageScaleToFit, ImageRotate, ImageAddBorder,
// ImageBlur, ImageSharpen, ImageCopy, ImagePaste, ImageShear, ImageTranslate,
// ImageMakeColorTransparent, ImageMakeTranslucent, ImageOverlay).
// ===========================================================================

class ImageOpsTest : public testing::Test {
protected:
    cfvariant variables;

    void SetUp() override {
        variables = cfvariant::Struct;
        cfml::response_begin();
    }

    // Runs CFML and returns the output text.
    string run(const string &code) {
        return runJitTemplate(code, variables);
    }

    // Runs CFML and writes the resulting image to a PNG for pixel sampling.
    string runWrite(const string &setup, const char *file) {
        return run(setup + "<cfset ImageWrite(im, \"" + file + "\", true)>");
    }
};

TEST_F(ImageOpsTest, FlipDimensionsAndDims) {
    // 8x5 image; vertical/horizontal/180 keep dims, diagonal/antidiagonal/90/270 swap.
    string out = run(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageFlip(im, \"vertical\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageFlip(im, \"horizontal\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageFlip(im, \"diagonal\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageFlip(im, \"antidiagonal\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageFlip(im, \"90\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageFlip(im, \"180\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageFlip(im, \"270\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>");
    // Cumulative: after diagonal the image is 5x8, so the later ops act on it.
    EXPECT_EQ(out.equals("8x5|8x5|8x5|5x8|8x5|5x8|5x8|8x5"), true);
}

TEST_F(ImageOpsTest, FlipPixels) {
    // Vertical flip reverses rows. Draw a red pixel at (1,1); after flip it is
    // at (1, h-2).
    runWrite(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"red\")><cfset ImageDrawPoint(im, 1, 1)>"
        "<cfset ImageFlip(im, \"vertical\")>", "tmp/ut_flip_v.png");
    EXPECT_EQ(pngPixelIs("tmp/ut_flip_v.png", 1, 3, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_flip_v.png", 1, 1, 0, 0, 0), true);
}

TEST_F(ImageOpsTest, GrayscaleAndNegative) {
    // Grayscale: red (255,0,0) -> luma 76. Negative: 255-76=179.
    runWrite(
        "<cfset im = ImageNew(\"\", 4, 4, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"red\")><cfset ImageDrawPoint(im, 1, 1)>"
        "<cfset ImageGrayscale(im)>", "tmp/ut_gray.png");
    EXPECT_EQ(pngPixelIs("tmp/ut_gray.png", 1, 1, 76, 76, 76), true);

    runWrite(
        "<cfset im = ImageNew(\"\", 4, 4, \"rgb\")>"
        "<cfset ImageSetDrawingColor(im, \"red\")><cfset ImageDrawPoint(im, 1, 1)>"
        "<cfset ImageNegative(im)>", "tmp/ut_neg.png");
    EXPECT_EQ(pngPixelIs("tmp/ut_neg.png", 1, 1, 0, 255, 255), true); // 255-red
    EXPECT_EQ(pngPixelIs("tmp/ut_neg.png", 0, 0, 255, 255, 255), true); // black -> white
}

TEST_F(ImageOpsTest, CropResizeScaleToFit) {
    string out = run(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset ImageCrop(im, 2, 1, 4, 3)><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageResize(im, \"16\", \"12\", \"nearest\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset ImageScaleToFit(im, \"6\", \"6\")><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>");
    EXPECT_EQ(out.equals("4x3|16x12|6x5"), true); // 16:12 = 4:3 scaleToFit 6x6 -> 6 wide
}

TEST_F(ImageOpsTest, ResizePixels) {
    // A solid red image (background) scaled to 8x8 nearest keeps red everywhere.
    runWrite(
        "<cfset im = ImageNew(\"\", 4, 4, \"rgb\")>"
        "<cfset ImageSetBackgroundColor(im, \"red\")><cfset ImageClearRect(im, 0, 0, 4, 4)>"
        "<cfset ImageResize(im, \"8\", \"8\", \"nearest\")>", "tmp/ut_resize.png");
    EXPECT_EQ(pngPixelIs("tmp/ut_resize.png", 3, 3, 255, 0, 0), true);
    EXPECT_EQ(pngPixelIs("tmp/ut_resize.png", 7, 7, 255, 0, 0), true);
}

TEST_F(ImageOpsTest, Rotate90) {
    // Rotating 90 CW: an 8x5 image becomes 5x8.
    string out = run(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset ImageRotate(im, 90)><cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>");
    EXPECT_EQ(out.equals("5x8"), true);
}

TEST_F(ImageOpsTest, AddBorderGrowsImage) {
    string out = run(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset ImageAddBorder(im, 2, \"blue\", \"constant\")>"
        "<cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>");
    EXPECT_EQ(out.equals("12x9"), true);
}

TEST_F(ImageOpsTest, BlurAndSharpen) {
    // Blur smooths a solid red region in a black image: a corner pixel of the
    // image picks up some red from the box filter.
    runWrite(
        "<cfset im = ImageNew(\"\", 6, 6, \"rgb\")>"
        "<cfset ImageSetBackgroundColor(im, \"red\")><cfset ImageClearRect(im, 1, 1, 2, 2)>"
        "<cfset ImageBlur(im, 3)>", "tmp/ut_blur.png");
    uint8_t r, g, b;
    bool hasRed = samplePngPixel("tmp/ut_blur.png", 0, 0, &r, &g, &b);
    EXPECT_EQ(hasRed, true);
    EXPECT_GT(r, 0);

    // Sharpen on an already sharp solid region keeps it solid.
    runWrite(
        "<cfset im = ImageNew(\"\", 6, 6, \"rgb\")>"
        "<cfset ImageSetBackgroundColor(im, \"red\")><cfset ImageClearRect(im, 1, 1, 2, 2)>"
        "<cfset ImageSharpen(im, 1.0)>", "tmp/ut_sharp.png");
    EXPECT_EQ(pngPixelIs("tmp/ut_sharp.png", 1, 1, 255, 0, 0), true);
}

TEST_F(ImageOpsTest, CopyPasteOverlay) {
    string out = run(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset c = ImageCopy(im, 1, 1, 4, 3)>"
        "<cfoutput>#ImageGetWidth(c)#x#ImageGetHeight(c)#</cfoutput>|"
        "<cfset im2 = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset ImagePaste(im2, im, 0, 0)>"
        "<cfoutput>#ImageGetWidth(im2)#x#ImageGetHeight(im2)#</cfoutput>|"
        "<cfset ImageOverlay(im2, im, \"src_over\", \"0.5\")>"
        "<cfoutput>#ImageGetWidth(im2)#x#ImageGetHeight(im2)#</cfoutput>");
    EXPECT_EQ(out.equals("4x3|8x5|8x5"), true);
}

TEST_F(ImageOpsTest, MakeColorTransparentAndTranslucent) {
    string out = run(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset t = ImageMakeColorTransparent(im, \"black\")>"
        "<cfoutput>#ImageGetWidth(t)#x#ImageGetHeight(t)#</cfoutput>|"
        "<cfset tr = ImageMakeTranslucent(im, 50)>"
        "<cfoutput>#ImageGetWidth(tr)#x#ImageGetHeight(tr)#</cfoutput>");
    EXPECT_EQ(out.equals("8x5|8x5"), true);
}

TEST_F(ImageOpsTest, ShearTranslate) {
    string out = run(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset ImageShear(im, 0.5, \"horizontal\")>"
        "<cfoutput>#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>|"
        "<cfset im2 = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset ImageShear(im2, 0.5, \"vertical\")>"
        "<cfoutput>#ImageGetWidth(im2)#x#ImageGetHeight(im2)#</cfoutput>|"
        "<cfset ImageTranslate(im2, 2, 3)>"
        "<cfoutput>#ImageGetWidth(im2)#x#ImageGetHeight(im2)#</cfoutput>");
    // Horizontal shear: floor(8 + 0.5*5) = 10; vertical: floor(5 + 0.5*8) = 9.
    EXPECT_EQ(out.equals("10x5|8x9|8x9"), true);
}

TEST_F(ImageOpsTest, ErrorMessages) {
    string out = run(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cftry><cfset ImageBlur(im, 2)><cfoutput>NOERR</cfoutput>"
        "<cfcatch type=\"any\"><cfoutput>BLUR:#cfcatch.message#</cfoutput></cfcatch></cftry>|"
        "<cftry><cfset ImageFlip(im, \"bogus\")><cfoutput>NOERR</cfoutput>"
        "<cfcatch type=\"any\"><cfoutput>FLIP:#cfcatch.message#</cfoutput></cfcatch></cftry>|"
        "<cftry><cfset ImageSharpen(im, 5)><cfoutput>NOERR</cfoutput>"
        "<cfcatch type=\"any\"><cfoutput>SHARP:#cfcatch.message#</cfoutput></cfcatch></cftry>");
    EXPECT_EQ(out.equals(
        "BLUR:The blurRadius must be between 3 and 10 (3 <= radius <= 10).|"
        "FLIP:The transpose argument must be  vertical, horizontal, diagonal, antidiagonal, 90, 180, or 270.|"
        "SHARP:Gain value is out of range. Its range is between -1 and 2, including fractional values."), true);
}

// ===========================================================================
// Built-in member-method calls (`value.method(args)`).
// ===========================================================================

class MemberMethodTest : public testing::Test {
protected:
    cfvariant variables;
    cfml::VariantCleanupGuard guard;

    void SetUp() override {
        variables = cfvariant::Struct;
    }

    // Runs a cfscript snippet via the JIT path and returns the writeOutput text.
    string jit(const string &scriptBody) {
        return runJitTemplate("<cfscript>" + scriptBody + "</cfscript>", variables);
    }

    // Runs an expression via the interpreter path (cfoutput #...#) and returns
    // the rendered text.
    string interp(const string &expr) {
        return runJitTemplate("<cfoutput>#" + expr + "#</cfoutput>", variables);
    }
};

TEST_F(MemberMethodTest, StringMethods) {
    EXPECT_EQ(jit("writeOutput(\"hello\".toUpperCase());").equals("HELLO"), true);
    EXPECT_EQ(jit("writeOutput(\"HELLO\".toLowerCase());").equals("hello"), true);
    EXPECT_EQ(jit("writeOutput(\"hello\".mid(2, 3));").equals("ell"), true);
    EXPECT_EQ(jit("writeOutput(\"  x  \".trim());").equals("x"), true);
    EXPECT_EQ(jit("writeOutput(\"hello\".len());").equals("5"), true);
    EXPECT_EQ(jit("writeOutput(\"hello\".reverse());").equals("olleh"), true);
    EXPECT_EQ(jit("writeOutput(\"hello\".replace(\"l\", \"L\", \"all\"));").equals("heLLo"), true);
    EXPECT_EQ(jit("writeOutput(\"a,b,c\".listLen());").equals("3"), true);
    EXPECT_EQ(jit("writeOutput(\"a,b,c\".listGetAt(2));").equals("b"), true);
    EXPECT_EQ(jit("writeOutput(\"a,b,c\".listToArray()[1]);").equals("a"), true);
    EXPECT_EQ(jit("writeOutput(\"hello world\".find(\"world\"));").equals("7"), true);
    EXPECT_EQ(jit("writeOutput(\"HELLO\".findNoCase(\"ell\"));").equals("2"), true);
}

TEST_F(MemberMethodTest, StringMethodsInterpreter) {
    EXPECT_EQ(interp("'hello'.toUpperCase()").equals("HELLO"), true);
    EXPECT_EQ(interp("'hello'.mid(2,3)").equals("ell"), true);
    EXPECT_EQ(interp("'hello'.len()").equals("5"), true);
    EXPECT_EQ(interp("'a,b,c'.listLen()").equals("3"), true);
}

TEST_F(MemberMethodTest, ArrayMethods) {
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.len());").equals("3"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.max());").equals("3"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.min());").equals("1"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.sum());").equals("6"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.toList());").equals("3,1,2"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.contains(2));").equals("YES"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.contains(9));").equals("NO"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.find(2));").equals("3"), true);
}

TEST_F(MemberMethodTest, ArrayMethodsMutate) {
    EXPECT_EQ(jit("arr = [3, 1, 2]; arr.append(4); writeOutput(arr[4] & \":\" & arr.len());").equals("4:4"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; arr.prepend(0); writeOutput(arr[1] & \":\" & arr.len());").equals("0:4"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; arr.push(5); writeOutput(arr[4]);").equals("5"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; arr.delete(2); writeOutput(arr[1] & \":\" & arr[2]);").equals("3:1"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; arr.deleteAt(2); writeOutput(arr[1] & \":\" & arr[2]);").equals("3:2"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; arr.clear(); writeOutput(arr.len());").equals("0"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; arr.resize(5); writeOutput(arr.len());").equals("5"), true);
}

TEST_F(MemberMethodTest, ArrayPushReturnsNewLength) {
    // CF's arr.push(x) returns the array's NEW LENGTH, while ArrayAppend/append
    // return YES (verified on the RDS host). Previously push mapped to
    // ARRAYAPPEND and rendered YES (was BUGS.md "Array push() member method
    // returns YES instead of the new length").
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.push(5));").equals("4"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; writeOutput(arr.append(5));").equals("YES"), true);
    EXPECT_EQ(jit("arr = [3, 1, 2]; arr.push(5); writeOutput(arr.len());").equals("4"), true);
    // Interpreter (cfoutput member-method) path.
    EXPECT_EQ(runJitTemplate("<cfset arr = [3, 1, 2]><cfoutput>#arr.push(5)#|#arr.len()#</cfoutput>", variables).equals("4|4"), true);
    // push returns the new length even for an empty array / multiple pushes.
    EXPECT_EQ(jit("arr = []; writeOutput(arr.push(1) & \":\" & arr.push(2));").equals("1:2"), true);
}

TEST_F(MemberMethodTest, StructMethods) {
    EXPECT_EQ(jit("st = {x: 10, y: 20}; writeOutput(st.keyExists(\"x\"));").equals("YES"), true);
    EXPECT_EQ(jit("st = {x: 10, y: 20}; writeOutput(st.count());").equals("2"), true);
    EXPECT_EQ(jit("st = {x: 10, y: 20}; writeOutput(st.isEmpty());").equals("NO"), true);
    EXPECT_EQ(jit("st = {x: 10, y: 20}; writeOutput(st.keyList());").equals("X,Y"), true);
    EXPECT_EQ(jit("st = {x: 10, y: 20}; writeOutput(st.find(\"y\"));").equals("20"), true);
    EXPECT_EQ(jit("st = {x: 10, y: 20}; writeOutput(st.keyArray()[1]);").equals("X"), true);
    EXPECT_EQ(jit("st = {x: 10, y: 20}; writeOutput(st.valueArray()[2]);").equals("20"), true);
    EXPECT_EQ(jit("st = {x: 10, y: 20}; st.delete(\"x\"); writeOutput(st.keyExists(\"x\"));").equals("NO"), true);
    EXPECT_EQ(jit("st = {x: 10, y: 20}; st.clear(); writeOutput(st.count());").equals("0"), true);
}

TEST_F(MemberMethodTest, QueryMethods) {
    EXPECT_EQ(jit("q = queryNew(\"a,b\"); q.addRow(); querySetCell(q, \"a\", 1, 1); querySetCell(q, \"b\", 2, 1); writeOutput(q.recordCount);").equals("1"), true);
    EXPECT_EQ(jit("q = queryNew(\"a,b\"); q.addRow(); querySetCell(q, \"a\", 1, 1); writeOutput(q.len());").equals("1"), true);
}

TEST_F(MemberMethodTest, DateMethods) {
    EXPECT_EQ(jit("dt = createDateTime(2024,5,6,7,8,9); writeOutput(dt.year());").equals("2024"), true);
    EXPECT_EQ(jit("dt = createDateTime(2024,5,6,7,8,9); writeOutput(dt.month());").equals("5"), true);
    EXPECT_EQ(jit("dt = createDateTime(2024,5,6,7,8,9); writeOutput(dt.day());").equals("6"), true);
    EXPECT_EQ(jit("dt = createDateTime(2024,5,6,7,8,9); writeOutput(dt.dateFormat(\"yyyy-mm-dd\"));").equals("2024-05-06"), true);
    EXPECT_EQ(jit("dt = createDateTime(2024,5,6,7,8,9); writeOutput(dt.datePart(\"m\"));").equals("5"), true);
    EXPECT_EQ(jit("dt = createDateTime(2024,5,6,7,8,9); writeOutput(dt.add(\"d\", 2).dateFormat(\"yyyy-mm-dd\"));").equals("2024-05-08"), true);
}

TEST_F(MemberMethodTest, IndexedScalarMemberMethod) {
    EXPECT_EQ(jit("s = {k: [\"hello\", \"world\"]}; writeOutput(s.k[2].toUpperCase());").equals("WORLD"), true);
    EXPECT_EQ(jit("s = {k: [\"hello\", \"world\"]}; writeOutput(s.k[2].len());").equals("5"), true);
    EXPECT_EQ(jit("s = {k: [\"hello\", \"world\"]}; writeOutput(s.k[2].mid(1, 3));").equals("wor"), true);
    EXPECT_EQ(jit("s = {k: [\"hello\", \"world\"]}; writeOutput(s.k[1].toUpperCase());").equals("HELLO"), true);
}

TEST_F(MemberMethodTest, IndexedScalarMemberMethodInterpreter) {
    EXPECT_EQ(runJitTemplate("<cfset s = {k: [\"hello\", \"world\"]}><cfoutput>#s.k[2].toUpperCase()#</cfoutput>", variables).equals("WORLD"), true);
    EXPECT_EQ(runJitTemplate("<cfset s = {k: [\"hello\", \"world\"]}><cfoutput>#s.k[2].mid(1,3)#</cfoutput>", variables).equals("wor"), true);
}

TEST_F(MemberMethodTest, InterpreterMutatingMethodsWriteThrough) {
    // In the cfoutput interpreter path, a mutating member method must write
    // through to the caller's variable, matching the JIT path (previously the
    // receiver was a by-value snapshot so #arr.append(4)# mutated a copy —
    // BUGS.md "Interpreter-path member methods mutate a copy").
    EXPECT_EQ(runJitTemplate("<cfset arr = [3, 1, 2]><cfoutput>#arr.append(4)#|#arr.toList()#</cfoutput>", variables).equals("YES|3,1,2,4"), true);
    EXPECT_EQ(runJitTemplate("<cfset arr = [3, 1, 2]><cfoutput>#arr.prepend(0)#|#arr.toList()#</cfoutput>", variables).equals("YES|0,3,1,2"), true);
    EXPECT_EQ(runJitTemplate("<cfset arr = [3, 1, 2]><cfoutput>#arr.delete(2)#|#arr.toList()#</cfoutput>", variables).equals("YES|3,1"), true);
    EXPECT_EQ(runJitTemplate("<cfset arr = [3, 1, 2]><cfoutput>#arr.deleteAt(2)#|#arr.toList()#</cfoutput>", variables).equals("YES|3,2"), true);
    EXPECT_EQ(runJitTemplate("<cfset arr = [3, 1, 2]><cfoutput>#arr.clear()#|#arr.len()#</cfoutput>", variables).equals("YES|0"), true);
    EXPECT_EQ(runJitTemplate("<cfset st = {x: 10, y: 20}><cfoutput>#st.delete(\"x\")#|#st.keyList()#</cfoutput>", variables).equals("YES|Y"), true);
    EXPECT_EQ(runJitTemplate("<cfset st = {x: 10, y: 20}><cfoutput>#st.clear()#|#st.count()#</cfoutput>", variables).equals("YES|0"), true);
    // A nested member array writes through too (s.k is a live slot).
    EXPECT_EQ(runJitTemplate("<cfset s = {k: [1, 2]}><cfoutput>#s.k.append(9)#|#s.k.toList()#</cfoutput>", variables).equals("YES|1,2,9"), true);
    EXPECT_EQ(runJitTemplate("<cfset s = {k: [1, 2]}><cfoutput>#s.k.deleteAt(1)#|#s.k.toList()#</cfoutput>", variables).equals("YES|2"), true);
    // Bracket-chained bases are live lvalues as well.
    EXPECT_EQ(runJitTemplate("<cfset a = [[5, 6], [7]]><cfoutput>#a[1].append(8)#|#a[1].toList()#</cfoutput>", variables).equals("YES|5,6,8"), true);
    EXPECT_EQ(runJitTemplate("<cfset a = [[5, 6], [7]]><cfoutput>#a[2].prepend(0)#|#a[2].toList()#</cfoutput>", variables).equals("YES|0,7"), true);
    // Scope-qualified and bracket-keyed bases write through.
    EXPECT_EQ(runJitTemplate("<cfset variables.mut = [7, 8]><cfoutput>#variables.mut.append(9)#|#variables.mut.toList()#</cfoutput>", variables).equals("YES|7,8,9"), true);
    EXPECT_EQ(runJitTemplate("<cfset st = {k: [1, 2]}><cfoutput>#st[\"k\"].append(5)#|#st[\"k\"].toList()#</cfoutput>", variables).equals("YES|1,2,5"), true);
    // A method result is a fresh value, not a live slot: chaining a mutator on
    // it does not reach back into the variable (matches the JIT path).
    EXPECT_EQ(runJitTemplate("<cfset arr = [1, 2, 3]><cfoutput>#arr.slice(1, 2).clear()#|#arr.toList()#</cfoutput>", variables).equals("YES|1,2,3"), true);
}

TEST_F(MemberMethodTest, InterpreterStoredUdfShadowingBuiltin) {
    // A stored UDF invoked through the cfoutput interpreter path still shadows
    // the built-in member-method table.
    EXPECT_EQ(runJitTemplate("<cfset s = {}><cfset s.say = function(v) { return \"Hi \" & arguments.v; }><cfoutput>#s.say(\"x\")#</cfoutput>", variables).equals("Hi x"), true);
    EXPECT_EQ(runJitTemplate("<cfset s = {}><cfset s.len = function() { return 99; }><cfoutput>#s.len()#</cfoutput>", variables).equals("99"), true);
}

TEST_F(MemberMethodTest, StoredUdfShadowingBuiltin) {
    EXPECT_EQ(jit("s = {}; s.say = function(v) { return \"Hi \" & arguments.v; }; writeOutput(s.say(\"x\"));").equals("Hi x"), true);
    // A stored UDF shadows a built-in member method of the same name; other
    // member methods still resolve to the built-in table (s holds 1 key here).
    EXPECT_EQ(jit("s = {}; s.len = function() { return 99; }; writeOutput(s.len());").equals("99"), true);
    EXPECT_EQ(jit("s = {}; s.len = function() { return 99; }; writeOutput(s.count());").equals("1"), true);
}

TEST_F(MemberMethodTest, ChainedMethods) {
    EXPECT_EQ(jit("arr = [1, 2, 3]; writeOutput(arr.toList().listLen());").equals("3"), true);
    EXPECT_EQ(jit("st = {k: [\"hi\", \"there\"]}; writeOutput(st.keyArray()[1]);").equals("K"), true);
}

TEST_F(MemberMethodTest, MissingMemberMethodThrows) {
    EXPECT_THROW(jit("s = \"hi\"; writeOutput(s.foo());"), webstrada::exception);
    EXPECT_THROW(jit("st = {}; writeOutput(st.foo());"), webstrada::exception);
    EXPECT_THROW(jit("arr = [1]; writeOutput(arr.nosuch());"), webstrada::exception);
    EXPECT_THROW(interp("'hi'.foo()"), webstrada::exception);
}

TEST_F(MemberMethodTest, UnimplementedMemberMethodThrows) {
    // Mapped member methods whose target function is not implemented throw the
    // standard not-implemented error instead of silently misbehaving. pop /
    // first / last / shift are now implemented (BUGS.md #4); a method with no
    // array-member mapping (reverse) throws the member-not-found error.
    EXPECT_THROW(jit("arr = [1, 2]; writeOutput(arr.reverse());"), webstrada::exception);
    EXPECT_THROW(jit("arr = [1, 2]; writeOutput(arr.nosuch());"), webstrada::exception);
    EXPECT_EQ(jit("arr = [1, 2]; writeOutput(arr.pop() & \"|\" & arr.toList());").equals("2|1"), true);
    EXPECT_EQ(jit("arr = [1, 2]; writeOutput(arr.first());").equals("1"), true);
    EXPECT_EQ(jit("arr = [1, 2]; writeOutput(arr.last());").equals("2"), true);
    EXPECT_EQ(jit("arr = [1, 2]; writeOutput(arr.shift() & \"|\" & arr.toList());").equals("1|2"), true);
}



