static void writeBytesFile(const char *path, const unsigned char *data, size_t len)
{
    std::ofstream f(path, std::ios::binary | std::ios::trunc);
    f.write((const char*)data, (std::streamsize)len);
    f.close();
}

// webstrada::string lacks std::string::find; convert for substring checks.
static bool strContains(const string &s, const char *needle)
{
    return s.indexOf(needle) >= 0;
}

TEST_F(JitExpressionTest, ImageExifMetadataStruct) {
    std::filesystem::create_directories("tmp");
    writeBytesFile("tmp/ut_exif_full.jpg", kEXIFFULL, sizeof(kEXIFFULL));
    string out = runJitTemplate(
        "<cfset im = ImageRead(\"tmp/ut_exif_full.jpg\")>"
        "<cfoutput>#SerializeJSON(ImageGetEXIFMetadata(im))#</cfoutput>", variables);
    // Spot-check a few tags; the full struct order is CF-verified in the cfm suite.
    EXPECT_EQ(strContains(out, "\"Make\":\"ProbeMake\""), true);
    EXPECT_EQ(strContains(out, "\"Model\":\"ProbeModel\""), true);
    EXPECT_EQ(strContains(out, "\"F-Number\":\"f/2.8\""), true);
    EXPECT_EQ(strContains(out, "\"Exposure Time\":\"1/125 sec\""), true);
    EXPECT_EQ(strContains(out, "\"Orientation\":\"Bottom, right side (Rotate 180)\""), true);
    EXPECT_EQ(strContains(out, "\"Aperture Value\":\"f/2.6\""), true);
    EXPECT_EQ(strContains(out, "\"Focal Length\":\"50.0 mm\""), true);
    EXPECT_EQ(strContains(out, "\"Exposure Bias Value\":\"1/3 EV\""), true);
    EXPECT_EQ(strContains(out, "\"Shutter Speed Value\":\"5.7 sec\""), true);
    EXPECT_EQ(strContains(out, "\"Focal Length 35\":\"75mm\""), true);
}

TEST_F(JitExpressionTest, ImageExifTagLookup) {
    writeBytesFile("tmp/ut_exif_full.jpg", kEXIFFULL, sizeof(kEXIFFULL));
    string out = runJitTemplate(
        "<cfset im = ImageRead(\"tmp/ut_exif_full.jpg\")>"
        "<cfoutput>#ImageGetEXIFTag(im, \"Make\")#|#ImageGetEXIFTag(im, \"make\")#|"
        "#ImageGetEXIFTag(im, \"NoSuchTag\")#|#ImageGetEXIFTag(im, \"Date/Time\")#</cfoutput>", variables);
    EXPECT_EQ(out.equals("ProbeMake|ProbeMake||2024:01:15 10:30:00"), true);
}

TEST_F(JitExpressionTest, ImageExifPILQuirks) {
    // A PIL-style flattened IFD (SHORT array ExposureTime, DOUBLE FNumber)
    // reproduces CF's quirks: "500 1000 sec" and empty F-Number.
    writeBytesFile("tmp/ut_exif_probe.jpg", kEXIFPROBE, sizeof(kEXIFPROBE));
    string out = runJitTemplate(
        "<cfset im = ImageRead(\"tmp/ut_exif_probe.jpg\")>"
        "<cfoutput>#ImageGetEXIFTag(im, \"Exposure Time\")#|#ImageGetEXIFTag(im, \"F-Number\")#|"
        "#ImageGetEXIFTag(im, \"ISO Speed Ratings\")#|#ImageGetEXIFTag(im, \"Focal Length\")#</cfoutput>", variables);
    // PIL wrote 0x920a as a string; com.drew reads it as Focal Length and its
    // rational description is null -> "" (matches CF's "Focal Length":"").
    EXPECT_EQ(out.equals("500 1000 sec||400|"), true);
}

TEST_F(JitExpressionTest, ImageIptcMetadataAndTags) {
    writeBytesFile("tmp/ut_iptc_probe.jpg", kIPTCPROBE, sizeof(kIPTCPROBE));
    string out = runJitTemplate(
        "<cfset im = ImageRead(\"tmp/ut_iptc_probe.jpg\")>"
        "<cfoutput>#SerializeJSON(ImageGetIPTCMetadata(im))#</cfoutput>"
        "<cfoutput>|#ImageGetIPTCTag(im, \"By-line\")#|#ImageGetIPTCTag(im, \"Object Name\")#|"
        "#ImageGetIPTCTag(im, \"Urgency\")#|#ImageGetIPTCTag(im, \"NoSuch\")#</cfoutput>", variables);
    EXPECT_EQ(out.equals("{\"Urgency\":\"80\",\"By-line\":\"ProbeByline\",\"Object Name\":\"ProbeCaption\","
                   "\"Application Record Version\":\"20594\",\"Keywords\":\"ProbeKeywords\","
                   "\"Copyright Notice\":\"Copyright Probe\"}|ProbeByline|ProbeCaption|80|"), true);
}

TEST_F(JitExpressionTest, ImageExifGpsTags) {
    // GPS tag values/descriptions (the struct key ORDER for images with GPS
    // plus IFD0/SubIFD follows CF's internal directory/tag iteration and is
    // not byte-verified — see BUGS_CF.md; the tag getters are deterministic).
    writeBytesFile("tmp/ut_gps_probe.jpg", kGPSPROBE, sizeof(kGPSPROBE));
    string out = runJitTemplate(
        "<cfset im = ImageRead(\"tmp/ut_gps_probe.jpg\")>"
        "<cfoutput>#ImageGetEXIFTag(im, \"GPS Latitude\")#|#ImageGetEXIFTag(im, \"GPS Version ID\")#|"
        "#ImageGetEXIFTag(im, \"GPS Status\")#|#ImageGetEXIFTag(im, \"GPS Time-Stamp\")#|"
        "#ImageGetEXIFTag(im, \"GPS Img Direction\")#|#ImageGetEXIFTag(im, \"GPS Map Datum\")#</cfoutput>", variables);
    EXPECT_EQ(out.equals("51\xC2\xB0 30' 45\"|2.300|Active (Measurement in progress)|12:34:56.78 UTC|90 degrees|WGS-84"), true);
}

TEST_F(JitExpressionTest, ImageMetaMissingSourceThrows) {
    // Blank and base64-created images have no source file; CF throws the
    // "BLOBS or Base64" error for all four metadata functions.
    string out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cftry><cfoutput>X:#ImageGetEXIFMetadata(im)#</cfoutput>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("X:The ImageMetadata feature is not supported for BLOBS or Base64 strings.|"
                   "The ImageMetadata feature is not supported for BLOBS or Base64 strings."), true);
    out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cftry><cfoutput>X:#ImageGetEXIFTag(im, \"Make\")#</cfoutput>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.type#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("X:Application"), true);
}

TEST_F(JitExpressionTest, ImageMetaOnNonJpegIsEmpty) {
    string out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset p = ExpandPath(\"tmp/ut_meta_plain.png\")>"
        "<cfset ImageWrite(im, p, true)>"
        "<cfset ip = ImageRead(p)>"
        "<cfoutput>#SerializeJSON(ImageGetEXIFMetadata(ip))#|#SerializeJSON(ImageGetIPTCMetadata(ip))#|"
        "#ImageGetEXIFTag(ip, \"Make\")#|#ImageGetIPTCTag(ip, \"By-line\")#</cfoutput>", variables);
    EXPECT_EQ(out.equals("{}|{}||"), true);
}

TEST_F(JitExpressionTest, ImageCreateCaptchaDimensions) {
    // Default width/height are computed like CF's ImageHelper.createCaptcha.
    string out = runJitTemplate(
        "<cfset cap = ImageCreateCaptcha(0, 0, \"AB\")>"
        "<cfoutput>#ImageGetWidth(cap)#x#ImageGetHeight(cap)#|#IsImage(cap)#</cfoutput>", variables);
    // width = round(1.5*2*24*0.72 + 1) = 53; height = round(2*24*0.72 + 1) = 36.
    EXPECT_EQ(out.equals("53x36|YES"), true);
    out = runJitTemplate(
        "<cfset cap = ImageCreateCaptcha(120, 200, \"ABCDEF\", \"high\", \"\", 30)>"
        "<cfoutput>#ImageGetWidth(cap)#x#ImageGetHeight(cap)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("200x120"), true);
}

TEST_F(JitExpressionTest, ImageCreateCaptchaErrors) {
    // Empty text and oversized-relative-to-dimensions text throw CF's
    // InvalidCaptchaArgumentException message/detail.
    string out = runJitTemplate(
        "<cftry><cfset c = ImageCreateCaptcha(100, 100, \"\")>"
        "<cfoutput>NOERR</cfoutput>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("An invalid argument has caused this error.|"
                   "Verify your inputs. The CAPTCHA text cannot be blank or undefined."), true);
    out = runJitTemplate(
        "<cftry><cfset c = ImageCreateCaptcha(100, 100, \"AB\", \"bogus\")>"
        "<cfoutput>NOERR</cfoutput>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("The value of the difficulty attribute can be low, medium, or high."), true);
    out = runJitTemplate(
        "<cftry><cfset c = ImageCreateCaptcha(20, 20, \"ABCDEF\")>"
        "<cfoutput>NOERR</cfoutput>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.detail#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(strContains(out, "not big enough to fit the text"), true);
}

TEST_F(JitExpressionTest, ImageGetBufferedImage) {
    // CF returns a java.awt.image.BufferedImage; this engine has no Java
    // object interop, so the image itself is returned (BUGS.md). The width
    // flows through both representations.
    string out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 9, 4, \"rgb\")>"
        "<cfset bi = ImageGetBufferedImage(im)>"
        "<cfoutput>#ImageGetWidth(bi)#x#ImageGetHeight(bi)#|#IsImage(bi)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("9x4|YES"), true);
}


TEST_F(JitExpressionTest, ImageCfimageTagActions) {
    std::filesystem::create_directories("tmp");
    string out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfset ImageWrite(im, \"tmp/cfimg_src.png\", true)>"
        "<cfimage action=\"read\" source=\"tmp/cfimg_src.png\" name=\"r1\">"
        "<cfimage action=\"read\" source=\"#r1#\" name=\"r2\">"
        "<cfimage action=\"write\" source=\"#r1#\" destination=\"tmp/cfimg_o1.png\" overwrite=\"true\">"
        "<cfimage action=\"resize\" source=\"#r1#\" width=\"16\" height=\"10\" destination=\"tmp/cfimg_o2.png\" name=\"r3\" overwrite=\"true\">"
        "<cfimage action=\"resize\" source=\"#r1#\" width=\"200%\" height=\"100%\" name=\"r6\">"
        "<cfimage action=\"border\" source=\"#r1#\" thickness=\"2\" color=\"blue\" destination=\"tmp/cfimg_o3.png\" name=\"r4\" overwrite=\"true\">"
        "<cfimage action=\"rotate\" source=\"#r1#\" angle=\"90\" destination=\"tmp/cfimg_o4.png\" name=\"r5\" overwrite=\"true\">"
        "<cfimage action=\"info\" source=\"#r1#\" structname=\"info1\">"
        "<cfimage action=\"convert\" source=\"#r1#\" destination=\"tmp/cfimg_o5.png\" name=\"r8\" overwrite=\"true\">"
        "<cfoutput>#ImageGetWidth(r1)#x#ImageGetHeight(r1)#|#ImageGetWidth(r2)#x#ImageGetHeight(r2)#|"
        "#ImageGetWidth(r3)#x#ImageGetHeight(r3)#|#ImageGetWidth(r6)#x#ImageGetHeight(r6)#|"
        "#ImageGetWidth(r4)#x#ImageGetHeight(r4)#|#ImageGetWidth(r5)#x#ImageGetHeight(r5)#|"
        "#info1.width#x#info1.height#|#ImageGetWidth(r8)#x#ImageGetHeight(r8)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("8x5|8x5|16x10|16x5|12x9|5x8|8x5|8x5"), true);
}

TEST_F(JitExpressionTest, ImageCfimageTagWritetobrowser) {
    string out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfimage action=\"writetobrowser\" source=\"#im#\" height=\"20\" width=\"30\">"
        "<cfoutput>AFTER</cfoutput>", variables);
    // The temp image name is random; the tag structure is deterministic.
    EXPECT_EQ(strContains(out, "<img src=\"/CFFileServlet/_cf_image/_cfimg"), true);
    EXPECT_EQ(strContains(out, "height=\"20\" width=\"30\" alt=\"\" />\nAFTER"), true);
}

TEST_F(JitExpressionTest, ImageCfimageTagCaptcha) {
    string out = runJitTemplate(
        "<cfimage action=\"captcha\" width=\"120\" height=\"60\" text=\"AB\" name=\"cap1\">"
        "<cfoutput>#ImageGetWidth(cap1)#x#ImageGetHeight(cap1)#|#IsImage(cap1)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("120x60|YES"), true);
    // Inline output emits the img tag with alt before height/width.
    out = runJitTemplate(
        "<cfimage action=\"captcha\" text=\"XY\">"
        "<cfoutput>AFTER</cfoutput>", variables);
    EXPECT_EQ(strContains(out, "<img src=\"/CFFileServlet/_cf_captcha/_captcha_img"), true);
    EXPECT_EQ(strContains(out, "alt=\"\" height=\"36\" width=\"53\" />\nAFTER"), true);
}

TEST_F(JitExpressionTest, ImageCfimageTagErrors) {
    string out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 4, 4, \"rgb\")>"
        "<cftry><cfimage action=\"write\" source=\"#im#\" destination=\"\">NOERR</cfimage>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("The destination attribute in the cfimage tag is either blank or undefined."), true);
    out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 4, 4, \"rgb\")>"
        "<cftry><cfimage action=\"read\" source=\"#im#\" name=\"\">NOERR</cfimage>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("The name attribute in the cfimage tag is either blank or undefined."), true);
    out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 4, 4, \"rgb\")>"
        "<cftry><cfimage action=\"bogus\" source=\"#im#\" destination=\"tmp/cfimg_b.png\" overwrite=\"true\">NOERR</cfimage>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("The action bogus is not supported by the cfimage tag.|Ensure that you have specified the correct action. "
                   "Valid values are read, write, writetobrowser, convert, resize, info, rotate, and border."), true);
    out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 4, 4, \"rgb\")>"
        "<cftry><cfimage action=\"border\" source=\"#im#\" thickness=\"-1\">NOERR</cfimage>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("The thickness attribute of a border cannot be negative."), true);
    out = runJitTemplate(
        "<cftry><cfimage action=\"read\" name=\"x\">NOERR</cfimage>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("The cfimage tag accepts only those ColdFusion variables that contain "
                   "Base64 strings, BLOBs, Byte arrays  or other images as inputs."), true);
    out = runJitTemplate(
        "<cftry><cfimage action=\"captcha\" width=\"120\" height=\"60\" text=\"AB\" difficulty=\"bogus\">NOERR</cfimage>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(out.equals("The value of the difficulty attribute can be low, medium, or high."), true);
}

TEST_F(JitExpressionTest, ImageCfimageTagReadCopies) {
    // action="read" from an image variable copies; mutating the copy does not
    // touch the source (matches CF's `new Image(source)`).
    string out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 8, 5, \"rgb\")>"
        "<cfimage action=\"read\" source=\"#im#\" name=\"c1\">"
        "<cfset ImageResize(c1, 16, 10)>"
        "<cfoutput>#ImageGetWidth(c1)#x#ImageGetHeight(c1)#|#ImageGetWidth(im)#x#ImageGetHeight(im)#</cfoutput>", variables);
    EXPECT_EQ(out.equals("16x10|8x5"), true);
}

TEST_F(JitExpressionTest, ImageCfimageTagOverwriteError) {
    // Writing to an existing file without overwrite throws CF's FileOverwrite
    // message; the absolute path is environment-dependent so only the shape is
    // asserted here (the CFM suite cannot byte-verify the path either).
    string out = runJitTemplate(
        "<cfset im = ImageNew(\"\", 4, 4, \"rgb\")>"
        "<cfimage action=\"write\" source=\"#im#\" destination=\"tmp/cfimg_ow.png\" overwrite=\"true\">"
        "<cftry><cfimage action=\"write\" source=\"#im#\" destination=\"tmp/cfimg_ow.png\">NOERR</cfimage>"
        "<cfcatch type=\"any\"><cfoutput>#cfcatch.message#</cfoutput></cfcatch></cftry>", variables);
    EXPECT_EQ(strContains(out, "The file "), true);
    EXPECT_EQ(strContains(out, "already exists."), true);
}

TEST_F(JitExpressionTest, WorkerProcessCliRequestApplicationCfm) {
    std::filesystem::create_directories("tmp/test_cli_app");
    {
        std::ofstream appFile("tmp/test_cli_app/Application.cfm");
        appFile << "<cfapplication name=\"TestApp\"><cfset Application.TestAppVar = \"AppVal42\">";
    }
    {
        std::ofstream pageFile("tmp/test_cli_app/page.cfm");
        pageFile << "<cfoutput>#Application.TestAppVar#</cfoutput>";
    }

    worker w;
    std::filesystem::path pagePath = std::filesystem::absolute("tmp/test_cli_app/page.cfm");
    std::filesystem::path dirPath = std::filesystem::absolute("tmp/test_cli_app");
    w.process_cli_request(pagePath.string().c_str(), dirPath.string().c_str());

    EXPECT_EQ(w.out().equals("AppVal42"), true);

    std::filesystem::remove_all("tmp/test_cli_app");
}

TEST_F(JitExpressionTest, WorkerProcessCliRequestTopLevelExitHaltsPage) {
    // A top-level <cfexit> halts the page via process_cli_request without an
    // error; the output written before it is preserved.
    std::filesystem::create_directories("tmp/test_cli_exit");
    {
        std::ofstream pageFile("tmp/test_cli_exit/page.cfm");
        pageFile << "<cfoutput>BEFORE|</cfoutput><cfexit><cfoutput>AFTER</cfoutput>";
    }

    worker w;
    std::filesystem::path pagePath = std::filesystem::absolute("tmp/test_cli_exit/page.cfm");
    std::filesystem::path dirPath = std::filesystem::absolute("tmp/test_cli_exit");
    w.process_cli_request(pagePath.string().c_str(), dirPath.string().c_str());

    EXPECT_EQ(w.out().equals("BEFORE|"), true);

    std::filesystem::remove_all("tmp/test_cli_exit");
}

TEST_F(JitExpressionTest, LlvmCodegenCompileString) {
    std::string snippet = "<cfoutput>#100 + 200#</cfoutput>";
    llvm_codegen compiler;
    auto fn = compiler.compile_string(snippet.data(), snippet.size(), false, "test_stdin");
    EXPECT_NE(fn, nullptr);

    string out;
    cfvariant cgi = cfvariant::Struct;
    cfvariant server = cfvariant::Struct;
    cfvariant cookie = cfvariant::Struct;
    cfvariant application = cfvariant::Struct;
    cfvariant session = cfvariant::Struct;
    cfvariant url = cfvariant::Struct;
    cfvariant form = cfvariant::Struct;
    cfvariant variables = cfvariant::Struct;

    fn(&out, &cgi, &server, &cookie, &application, &session, &url, &form, &variables);
    EXPECT_EQ(out.equals("300"), true);
}

// ---- <cferror> (CFML_TAG_CFERROR.md) ----

// Runs a page through worker::process_cli_request (the same path that
// dispatches <cferror>) in a fresh temp tree; returns the output buffer.
static std::string runCliRequestTree(const std::vector<std::pair<std::string, std::string>> &files,
                                     const char *page = "page.cfm")
{
    std::string root = makeAppCfmTree(files);
    worker w;
    std::filesystem::path pagePath = std::filesystem::absolute(root + "/" + page);
    std::filesystem::path dirPath = std::filesystem::absolute(root);
    w.process_cli_request(pagePath.string().c_str(), dirPath.string().c_str());
    return std::string(w.out().constData(), w.out().length());
}

class CferrorTest : public testing::Test {
protected:
    void SetUp() override {}
    void TearDown() override {}
};

TEST_F(CferrorTest, CustomHandlerMatchesNamedThrow) {
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>ERR|MSG=#error.message#|MLTO=#error.mailto#|RC=#error.rootcause.type#:#error.rootcause.message#:#error.rootcause.detail#</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"myboom\" template=\"err_page.cfm\"><cfthrow type=\"myboom\" message=\"boom\" detail=\"bdtl\">"},
    });
    EXPECT_EQ(out, "ERR|MSG=boom|MLTO=|RC=myboom:boom:bdtl");
}

TEST_F(CferrorTest, AnyHandlerFallsBackForBareThrow) {
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>ERR|MSG=#error.message#|RC=#error.rootcause.type#:#error.rootcause.message#</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"any\" template=\"err_page.cfm\"><cfthrow message=\"bare\">"},
    });
    EXPECT_EQ(out, "ERR|MSG=bare|RC=Application:bare");
}

TEST_F(CferrorTest, ExceptionAttrDefaultsToAny) {
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>ERR|RC=#error.rootcause.type#:#error.rootcause.message#</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" template=\"err_page.cfm\"><cfthrow type=\"whatever\" message=\"def\">"},
    });
    EXPECT_EQ(out, "ERR|RC=whatever:def");
}

TEST_F(CferrorTest, FirstRegisteredMatchingHandlerWins) {
    std::string out = runCliRequestTree({
        {"first_page.cfm", "<cfoutput>FIRST|#error.message#</cfoutput>"},
        {"second_page.cfm", "<cfoutput>SECOND|#error.message#</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"myboom\" template=\"first_page.cfm\"><cferror type=\"exception\" exception=\"ktype\" template=\"second_page.cfm\"><cfthrow type=\"myboom\" message=\"win\">"},
    });
    EXPECT_EQ(out, "FIRST|win");
}

TEST_F(CferrorTest, CustomNameMatchIsCaseInsensitive) {
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>ERR|#error.message#</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"MyBoom\" template=\"err_page.cfm\"><cfthrow type=\"myboom\" message=\"c\">"},
    });
    EXPECT_EQ(out, "ERR|c");
}

TEST_F(CferrorTest, MailtoAttrFlowsIntoErrorStruct) {
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>ERR|MLTO=#error.mailto#</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"any\" template=\"err_page.cfm\" mailto=\"a@b.c\"><cfthrow message=\"m\">"},
    });
    EXPECT_EQ(out, "ERR|MLTO=a@b.c");
}

TEST_F(CferrorTest, GeneratedContentKeepsPreThrowOutput) {
    // The pre-throw output is discarded from the body but kept in
    // error.generatedcontent (verified against CF 2025).
    std::string out = runCliRequestTree({
        {"gc_page.cfm", "<cfoutput>PAGE|GC=#error.generatedcontent#</cfoutput>"},
        {"page.cfm", "<cfoutput>PRE|</cfoutput><cferror type=\"exception\" exception=\"any\" template=\"gc_page.cfm\"><cfthrow message=\"g\">"},
    });
    EXPECT_EQ(out, "PAGE|GC=PRE|");
}

TEST_F(CferrorTest, ErrorStructKeysAndWrapperSemantics) {
    // The wrapper has the ExceptionScope pseudo-keys as empty values (CF:
    // structKeyExists(error,'detail') is YES and #error.detail# is empty); the
    // rootcause carries the real throw values. The type-dependent pseudo-keys
    // (nativeerrorcode) stay undefined.
    std::string out = runCliRequestTree({
        {"keys_page.cfm", "<cfoutput>ED=#structKeyExists(error,'detail')#|EC=#structKeyExists(error,'errorcode')#|DTL=[#error.detail#]|ECD=[#error.errorcode#]|RCD=#error.rootcause.detail#|RCE=#error.rootcause.errorcode#|NE=[#structKeyExists(error,'nativeerrorcode')#]</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"any\" template=\"keys_page.cfm\"><cfthrow message=\"k\" detail=\"kd\" errorcode=\"ke\">"},
    });
    EXPECT_EQ(out, "ED=YES|EC=YES|DTL=[]|ECD=[]|RCD=kd|RCE=ke|NE=[NO]");
}

TEST_F(CferrorTest, BadTypeValueIsCatchableWithCfsMessage) {
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>P</cfoutput>"},
        {"page.cfm", "<cftry><cferror type=\"bogustype\" template=\"err_page.cfm\"><cfcatch type=\"any\"><cfoutput>MSG=[#cfcatch.message#]|DTL=[#cfcatch.detail#]|TYPE=[#cfcatch.type#]</cfoutput></cfcatch></cftry>"},
    });
    EXPECT_EQ(out, "MSG=[Attribute validation error for tag CFERROR.]|DTL=[The value of the attribute type, which is currently bogustype, is invalid.]|TYPE=[Application]");
}

TEST_F(CferrorTest, EmptyTypeValueRendersQuotedEmpty) {
    // CF renders the empty value as '' in the detail.
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>P</cfoutput>"},
        {"page.cfm", "<cftry><cferror type=\"\" template=\"err_page.cfm\"><cfcatch type=\"any\"><cfoutput>DTL=[#cfcatch.detail#]</cfoutput></cfcatch></cftry>"},
    });
    EXPECT_EQ(out, "DTL=[The value of the attribute type, which is currently '', is invalid.]");
}

TEST_F(CferrorTest, UnresolvableTemplateIsCatchableMissingInclude) {
    std::string out = runCliRequestTree({
        {"page.cfm", "<cftry><cferror type=\"exception\" template=\"no_such_tpl_xyz.cfm\"><cfcatch type=\"any\"><cfoutput>MSG=[#cfcatch.message#]|DTL=[#cfcatch.detail#]|TYPE=[#cfcatch.type#]</cfoutput></cfcatch></cftry>"},
    });
    EXPECT_EQ(out, "MSG=[Error attempting to resolve the template no_such_tpl_xyz.cfm.]|DTL=[The template could not be found.]|TYPE=[MissingInclude]");
}

TEST_F(CferrorTest, AbsoluteTemplateValueResolvesAgainstWebRoot) {
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>ROOTERR|#error.message#</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"any\" template=\"/err_page.cfm\"><cfthrow message=\"abs\">"},
    });
    EXPECT_EQ(out, "ROOTERR|abs");
}

TEST_F(CferrorTest, RequestHandlerReplacesPlaceholdersAndLeavesUnknown) {
    std::string out = runCliRequestTree({
        {"req_page.txt", "RP|GC=<#ERROR.GENERATEDCONTENT#>|MLTO=<#ERROR.MAILTO#>|RCT=<#ERROR.ROOTCAUSE.TYPE#>|RCM=<#ERROR.ROOTCAUSE.MESSAGE#>|RCD=<#ERROR.ROOTCAUSE.DETAIL#>|UNK=<#ERROR.NOSUCH#>|END"},
        {"page.cfm", "<cferror type=\"request\" template=\"req_page.txt\"><cfthrow type=\"ktype\" message=\"rboot\" detail=\"rdtl\">"},
    });
    EXPECT_EQ(out, "RP|GC=<>|MLTO=<>|RCT=<ktype>|RCM=<rboot>|RCD=<rdtl>|UNK=<#ERROR.NOSUCH#>|END");
}

TEST_F(CferrorTest, RequestHandlerEmitsPageAndStatus500) {
    std::string out = runCliRequestTree({
        {"req_page.txt", "REQPAGE"},
        {"page.cfm", "<cferror type=\"request\" template=\"req_page.txt\"><cfthrow message=\"x\">"},
    });
    EXPECT_EQ(out, "REQPAGE");
    EXPECT_EQ(cfml::response().statusCode, 500);
}

TEST_F(CferrorTest, HandlerThrowsFallsThroughToRequestHandlerWithNewException) {
    std::string out = runCliRequestTree({
        {"throwing_page.cfm", "<cfoutput>THREW|</cfoutput><cfthrow message=\"handlerthrew\">"},
        {"req_page.txt", "RP|GC=<#ERROR.GENERATEDCONTENT#>|RCT=<#ERROR.ROOTCAUSE.TYPE#>|RCM=<#ERROR.ROOTCAUSE.MESSAGE#>|END"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"ktype\" template=\"throwing_page.cfm\"><cferror type=\"request\" template=\"req_page.txt\"><cfthrow type=\"ktype\" message=\"originalboom\">"},
    });
    EXPECT_EQ(out, "RP|GC=<THREW|>|RCT=<Application>|RCM=<handlerthrew>|END");
}

TEST_F(CferrorTest, CfexitInHandlerEndsOnlyTheHandlerPage) {
    std::string out = runCliRequestTree({
        {"err_page.cfm", "<cfoutput>HANDLER|</cfoutput><cfexit><cfoutput>NEVER</cfoutput>"},
        {"after_page.cfm", "<cfoutput>AFTERHANDLER</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"any\" template=\"err_page.cfm\"><cfthrow message=\"x\">"},
    });
    EXPECT_EQ(out, "HANDLER|");
}

TEST_F(CferrorTest, MissingRequestPageIsTemplateNotFoundNotHandled) {
    // CF: a missing request page is a TemplateNotFoundException which never
    // reaches cferror (built-in 404). The worker must throw it.
    std::string root = makeAppCfmTree({
        {"err_page.cfm", "<cfoutput>ERRPAGE</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"any\" template=\"err_page.cfm\">"},
    });
    worker w;
    std::filesystem::path pagePath = std::filesystem::absolute(root + "/no_such_page_xyz.cfm");
    std::filesystem::path dirPath = std::filesystem::absolute(root);
    bool thrown = false;
    try {
        w.process_cli_request(pagePath.string().c_str(), dirPath.string().c_str());
    } catch (const webstrada::exception &ex) {
        thrown = true;
        EXPECT_EQ(ex.m_message.equals("Template not found!"), true);
        EXPECT_EQ(ex.m_missingTemplate, true);
    }
    EXPECT_EQ(thrown, true);
}

TEST_F(CferrorTest, UnmatchedCustomThrowPropagatesToBuiltin) {
    // No handler matches (named handler for a different type, no "any"), so
    // the exception is re-thrown and the built-in error page handles it.
    std::string root = makeAppCfmTree({
        {"err_page.cfm", "<cfoutput>ERRPAGE</cfoutput>"},
        {"page.cfm", "<cferror type=\"exception\" exception=\"ktype\" template=\"err_page.cfm\"><cfthrow type=\"other\" message=\"nomatch\">"},
    });
    worker w;
    std::filesystem::path pagePath = std::filesystem::absolute(root + "/page.cfm");
    std::filesystem::path dirPath = std::filesystem::absolute(root);
    bool thrown = false;
    try {
        w.process_cli_request(pagePath.string().c_str(), dirPath.string().c_str());
    } catch (const webstrada::exception &ex) {
        thrown = true;
        EXPECT_EQ(ex.m_message.equals("nomatch"), true);
    }
    EXPECT_EQ(thrown, true);
}

// ---- Stacktrace / CFML call stack (TAGCONTEXT) ----

class StackTraceTest : public testing::Test {
protected:
    void SetUp() override { cfml::g_callStack.clear(); }
    void TearDown() override { cfml::g_callStack.clear(); }
};

TEST_F(StackTraceTest, PushSetLinePopBalance) {
    EXPECT_EQ(cfml::g_callStack.size(), 0u);
    cfml::cf_stack_push("/a/outer.cfm", "");
    cfml::cf_stack_push("/a/inner.cfm", "doWork");
    cfml::cf_stack_set_line(42);
    EXPECT_EQ(cfml::g_callStack.size(), 2u);
    EXPECT_EQ(cfml::g_callStack[0].path, "/a/outer.cfm");
    EXPECT_EQ(cfml::g_callStack[0].line, 0);      // untouched outer frame
    EXPECT_EQ(cfml::g_callStack[0].function.empty(), true);
    EXPECT_EQ(cfml::g_callStack[1].path, "/a/inner.cfm");
    EXPECT_EQ(cfml::g_callStack[1].line, 42);
    EXPECT_EQ(cfml::g_callStack[1].function, "DOWORK");  // uppercased
    cfml::cf_stack_set_line(7);                   // updates the top only
    EXPECT_EQ(cfml::g_callStack[0].line, 0);
    EXPECT_EQ(cfml::g_callStack[1].line, 7);
    cfml::cf_stack_pop();
    EXPECT_EQ(cfml::g_callStack.size(), 1u);
    cfml::cf_stack_pop();
    EXPECT_EQ(cfml::g_callStack.size(), 0u);
    // Popping / setting on an empty stack must not crash.
    cfml::cf_stack_pop();
    cfml::cf_stack_set_line(99);
    EXPECT_EQ(cfml::g_callStack.size(), 0u);
}

TEST_F(StackTraceTest, TagContextArrayBuildingRoundTrip) {
    std::vector<webstrada::StackLevel> st;
    st.push_back({"C:/webroot/outer.cfm", 12});
    st.push_back({"C:/webroot/inner.cfm", 5});
    cfvariant *tags = cfml::cf_stack_tagcontext(st);
    ASSERT_TRUE(tags->m_type == cfvariant::Array);
    ASSERT_EQ(tags->m_array->size(), 2u);
    // Element [1] (index 0) is the innermost frame, like CF.
    const int innerIdx = 0, outerIdx = 1;
    EXPECT_EQ((*tags)[innerIdx]["TEMPLATE"].toString().equals("C:/webroot/inner.cfm"), true);
    EXPECT_EQ((*tags)[innerIdx]["LINE"].m_int, 5);
    EXPECT_EQ((*tags)[outerIdx]["TEMPLATE"].toString().equals("C:/webroot/outer.cfm"), true);
    EXPECT_EQ((*tags)[outerIdx]["LINE"].m_int, 12);
    // Round trip back to an outermost-first stack (rethrow preservation).
    std::vector<webstrada::StackLevel> back = cfml::cf_stack_tagcontext_to_levels(tags);
    ASSERT_EQ(back.size(), 2u);
    EXPECT_EQ(back[0].path, "C:/webroot/outer.cfm");
    EXPECT_EQ(back[0].line, 12);
    EXPECT_EQ(back[1].path, "C:/webroot/inner.cfm");
    EXPECT_EQ(back[1].line, 5);
    delete tags;
}

TEST_F(StackTraceTest, ExceptionCapturesFramesThroughCli) {
    // Nested UDF call chain: the caught exception's tagContext carries the
    // throw-site line, the caller line and the call-site line, and the live
    // stack is balanced (empty) once the request completes.
    std::string out = runCliRequestTree({
        {"page.cfm",
         "<cfscript>\n"
         "function inner() {\n"
         "    throw(type = \"boom\", message = \"x\");\n"
         "}\n"
         "function outer() {\n"
         "    return inner();\n"
         "}\n"
         "</cfscript>\n"
         "<cftry>\n"
         "    <cfset outer()>\n"
         "    <cfcatch type=\"boom\">\n"
         "        <cfoutput>#arrayLen(cfcatch.tagContext)#:#cfcatch.tagContext[1].line#:#GetFileFromPath(cfcatch.tagContext[1].template)#:#cfcatch.tagContext[2].line#:#cfcatch.tagContext[3].line#</cfoutput>\n"
         "    </cfcatch>\n"
         "</cftry>"},
    });
    EXPECT_EQ(webstrada::string(out.c_str()).trimmed().equals("3:3:page.cfm:6:10"), true);
    EXPECT_EQ(cfml::g_callStack.empty(), true);
}

TEST_F(StackTraceTest, LineNumbersAreEncodingIndependent) {
    // Line numbers come from the textparser line map
    // (textparser_get_line_number_at_position), not a raw byte scan, so
    // multibyte UTF-8 content before the throw site must not shift the reported
    // line. Line 1 carries é, è, € and ü (2-3 bytes each) inside a string.
    std::string out = runCliRequestTree({
        {"page.cfm",
         "<cfset s = \"\xc3\xa9\xc3\xa8\xe2\x82\xac z\xc3\xbcrich\">\n"   // line 1 (multibyte)
         "<!--- another multibyte comment line --->\n"                     // line 2
         "<cfset x = 1>\n"                                                // line 3
         "<cftry>\n"                                                      // line 4
         "    <cfthrow type=\"boom\" message=\"x\">\n"                    // line 5
         "    <cfcatch type=\"boom\">\n"                                  // line 6
         "        <cfoutput>#cfcatch.tagContext[1].line#:#GetFileFromPath(cfcatch.tagContext[1].template)#</cfoutput>\n"
         "    </cfcatch>\n"
         "</cftry>"},
    });
    EXPECT_EQ(webstrada::string(out.c_str()).trimmed().equals("5:page.cfm"), true);
    EXPECT_EQ(cfml::g_callStack.empty(), true);
}

TEST_F(StackTraceTest, RethrowPreservesOriginalFrames) {
    // A `rethrow` re-raises the same exception: the tagContext keeps the
    // original throw site (line 4), not the rethrow line (line 7).
    std::string out = runCliRequestTree({
        {"page.cfm",
         "<cfscript>\n"
         "function rt() {\n"
         "    try {\n"
         "        throw(type = \"e1\", message = \"x\");\n"
         "    } catch (e1 ex) {\n"
         "        rethrow;\n"
         "    }\n"
         "}\n"
         "</cfscript>\n"
         "<cftry>\n"
         "    <cfset rt()>\n"
         "    <cfcatch type=\"e1\">\n"
         "        <cfoutput>#cfcatch.tagContext[1].line#:#cfcatch.tagContext[2].line#</cfoutput>\n"
         "    </cfcatch>\n"
         "</cftry>"},
    });
    EXPECT_EQ(webstrada::string(out.c_str()).trimmed().equals("4:11"), true);
}

TEST_F(StackTraceTest, IncludeChainAddsIncludedTemplateFrame) {
    // An error inside an included template reports the included file's line as
    // the innermost frame and the <cfinclude> line as the caller frame.
    std::string out = runCliRequestTree({
        {"sub.cfm",
         "<cfset a = 1>\n"
         "<cfthrow type=\"incErr\" message=\"x\">"},
        {"page.cfm",
         "<cftry>\n"
         "    <cfinclude template=\"sub.cfm\">\n"
         "    <cfcatch type=\"incErr\">\n"
         "        <cfoutput>#cfcatch.tagContext[1].line#:#GetFileFromPath(cfcatch.tagContext[1].template)#:#cfcatch.tagContext[2].line#</cfoutput>\n"
         "    </cfcatch>\n"
         "</cftry>"},
    });
    EXPECT_EQ(webstrada::string(out.c_str()).trimmed().equals("2:sub.cfm:2"), true);
    EXPECT_EQ(cfml::g_callStack.empty(), true);
}

TEST_F(StackTraceTest, CallStackGetReturnsInnermostFirstArray) {
    cfml::cf_stack_push("/web/page.cfm", "");
    cfml::cf_stack_push("/web/outer.cfm", "outer");
    cfml::cf_stack_push("/web/inner.cfm", "doWork");
    cfml::cf_stack_set_line(42);

    cfvariant *arr = cfml::cf_callstackget();
    ASSERT_TRUE(arr->m_type == cfvariant::Array);
    ASSERT_EQ(arr->m_array->size(), 3u);
    // Element [1] (index 0) is the innermost frame; function names are
    // uppercased, keys use CF's casing.
    const int innerIdx = 0, outerIdx = 1, pageIdx = 2;
    EXPECT_EQ((*arr)[innerIdx]["Template"].toString().equals("/web/inner.cfm"), true);
    EXPECT_EQ((*arr)[innerIdx]["LineNumber"].m_int, 42);
    EXPECT_EQ((*arr)[innerIdx]["Function"].toString().equals("DOWORK"), true);
    EXPECT_EQ((*arr)[outerIdx]["Function"].toString().equals("OUTER"), true);
    EXPECT_EQ((*arr)[pageIdx]["Function"].toString().isEmpty(), true);
    EXPECT_EQ((*arr)[pageIdx]["LineNumber"].m_int, 0);
    delete arr;
}

TEST_F(StackTraceTest, CallStackDumpBrowserOutput) {
    cfml::cf_stack_push("/web/page.cfm", "");
    cfml::cf_stack_push("/web/inner.cfm", "doWork");
    cfml::cf_stack_set_line(7);

    string out;
    cfvariant *ret = cfml::cf_callstackdump(&out, nullptr);
    EXPECT_EQ(ret, nullptr);
    EXPECT_EQ(out.equals("/web/inner.cfm:DOWORK:7\n/web/page.cfm:0\n"), true);
}

TEST_F(StackTraceTest, CallStackDumpFileOutput) {
    cfml::cf_stack_push("/web/page.cfm", "");
    cfml::cf_stack_set_line(3);

    std::string path = "/tmp/webstrada_csd_" + std::to_string(getpid()) + ".txt";
    cfvariant pathVal(path.c_str());
    cfvariant *ret = cfml::cf_callstackdump(nullptr, &pathVal);
    EXPECT_EQ(ret, nullptr);

    std::ifstream f(path, std::ios::binary);
    std::string content((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
    EXPECT_EQ(content, "/web/page.cfm:3\n");
    std::remove(path.c_str());
}

// ---- Tier-1 built-in functions (CFFUNCTION_IMPLEMENTATION_ACTION_PLAN.md) ----

TEST_F(JitExpressionTest, Tier1GetToken) {
    // Default delimiters are whitespace (space/tab/CR/LF), not comma.
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetToken(\"a,b,c,d\",2)#</cfoutput>", variables).equals(""), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetToken(\"a,b,c,d\",1,\";\")#</cfoutput>", variables).equals("a,b,c,d"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetToken(\"a b c\",3,\" \")#</cfoutput>", variables).equals("c"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetToken(\"a.b.c.d\",4,\".\")#</cfoutput>", variables).equals("d"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetToken(\"a,b,c,d\",9)#</cfoutput>", variables).equals(""), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetToken(\"a,,b\",2,\",\")#</cfoutput>", variables).equals("b"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetToken(\"\",1)#</cfoutput>", variables).equals(""), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetToken(\"a b\",2)#</cfoutput>", variables).equals("b"), true);
}

TEST_F(JitExpressionTest, Tier1GetTokenIndexError) {
    // CF: "The value of parameter 2 of the function GetToken, which is now 0,
    // must be a positive integer".
    EXPECT_THROW(runJitTemplate("<cfoutput>#GetToken(\"a,b\",0)#</cfoutput>", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cfoutput>#GetToken(\"a,b\",-3)#</cfoutput>", variables), webstrada::exception);
}

TEST_F(JitExpressionTest, Tier1SetVariable) {
    EXPECT_EQ(runJitTemplate("<cfset r = SetVariable(\"x\", \"v\")><cfoutput>#r#:#x#</cfoutput>", variables).equals("v:v"), true);
    EXPECT_EQ(runJitTemplate("<cfset r = SetVariable(\"a.b.c\", \"deep\")><cfoutput>#r#:#a.b.c#</cfoutput>", variables).equals("deep:deep"), true);
}

// Compile-time variable binding (ColdFusion's "fast path"): the JIT routes
// page-level simple-identifier reads through cfvariant_get_var_fast /
// cfvariant_bare_identifier_fast, which memoize the resolved variables-scope
// pointer (generation-guarded against StructDelete/StructClear). These tests
// pin the observable behavior — the fast path must be indistinguishable from
// the full scope search.
TEST_F(JitExpressionTest, VarFastPathBasicReads) {
    EXPECT_EQ(runJitTemplate("<cfset a=1><cfset b=2><cfoutput>#a#|#b#|#a+b#</cfoutput>", variables).equals("1|2|3"), true);
    // Case-insensitive reads.
    EXPECT_EQ(runJitTemplate("<cfset a=5><cfoutput>#A#</cfoutput>", variables).equals("5"), true);
}

TEST_F(JitExpressionTest, VarFastPathUndefinedThrows) {
    // A read of an undefined page variable still throws CF's message.
    EXPECT_THROW(runJitTemplate("<cfoutput>#zz_undefined_zz#</cfoutput>", variables), webstrada::exception);
    // ... and the error text matches.
    try {
        runJitTemplate("<cfoutput>#zz_undefined_zz#</cfoutput>", variables);
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.m_message).equals("Variable ZZ_UNDEFINED_ZZ is undefined."), true);
    }
}

TEST_F(JitExpressionTest, VarFastPathFunctionNameFallback) {
    // A bare identifier that is a built-in function name still resolves to a
    // method handle (not a variable).
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsObject(abs)#</cfoutput>", variables).equals("YES"), true);
}

TEST_F(JitExpressionTest, VarFastPathStructDeleteInvalidates) {
    // The memoized pointer must be invalidated when the key is erased: a read
    // after StructDelete throws, matching CF (no stale value returned).
    try {
        runJitTemplate("<cfset x = 5><cfoutput>#x#|</cfoutput><cfset StructDelete(variables, \"x\")><cfoutput>#x#</cfoutput>", variables);
        EXPECT_TRUE(false) << "expected Variable X undefined after StructDelete";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.m_message).equals("Variable X is undefined."), true);
    }
    // Re-inserting the key after a delete re-memoizes.
    EXPECT_EQ(runJitTemplate("<cfset x = 5><cfoutput>#x#|</cfoutput><cfset StructDelete(variables, \"x\")><cfset x = 9><cfoutput>#x#</cfoutput>", variables).equals("5|9"), true);
}

TEST_F(JitExpressionTest, VarFastPathStructClearInvalidates) {
    // StructClear invalidates every memoized slot.
    try {
        runJitTemplate("<cfset x = 5><cfset y = 7><cfoutput>#x#|#y#</cfoutput><cfset StructClear(variables)><cfoutput>#x#</cfoutput>", variables);
        EXPECT_TRUE(false) << "expected Variable X undefined after StructClear";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.m_message).equals("Variable X is undefined."), true);
    }
}

TEST_F(JitExpressionTest, VarFastPathReassignmentReflects) {
    // Reassignment keeps the map node, so the memoized pointer sees the new
    // value immediately (no stale reads).
    EXPECT_EQ(runJitTemplate("<cfset x = 5><cfoutput>#x#|</cfoutput><cfset x = 6><cfoutput>#x#|</cfoutput><cfloop index=\"i\" from=\"1\" to=\"3\"><cfset x = i><cfoutput>#x#;</cfoutput></cfloop>", variables).equals("5|6|1;2;3;"), true);
}

TEST_F(JitExpressionTest, VarFastPathQueryScopeShadows) {
    // Inside a <cfloop query>, an unqualified name matching a column resolves
    // to the column (query scope precedes variables); the fast path bypasses
    // the memoized page variable there.
    EXPECT_EQ(runJitTemplate(
        "<cfset q = QueryNew(\"name\")>"
        "<cfset QueryAddRow(q)><cfset QuerySetCell(q, \"name\", \"col1\")>"
        "<cfset QueryAddRow(q)><cfset QuerySetCell(q, \"name\", \"col2\")>"
        "<cfset name = \"pagevar\">"
        "<cfloop query=\"q\"><cfoutput>#name#;</cfoutput></cfloop>"
        "<cfoutput>#name#</cfoutput>",
        variables).equals("col1;col2;pagevar"), true);
}

TEST_F(JitExpressionTest, VarFastPathUdfLocalShadows) {
    // Inside a UDF body the fast path is not used (function-local reads bind
    // their own scope), so a `var` local shadows the page variable.
    EXPECT_EQ(runJitTemplate(
        "<cfset x = 5>"
        "<cfscript>function f() { var x = 100; return x; } writeOutput(f());</cfscript>"
        "<cfoutput>#x#</cfoutput>",
        variables).equals("1005"), true);
}

TEST_F(JitExpressionTest, VarFastPathMemberAccessChainBase) {
    // A chain-base read (s.x) uses cfvariant_get_var_fast; the memoized base
    // struct is stable and its members mutate through normally.
    EXPECT_EQ(runJitTemplate("<cfset s={a:1}><cfoutput>#s.a#|</cfoutput><cfset s.a=99><cfoutput>#s.a#</cfoutput>", variables).equals("1|99"), true);
}

TEST_F(JitExpressionTest, VarFastPathScopeNamesSkipped) {
    // Built-in scope names are excluded from the fast path and still resolve
    // to the scope object.
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsStruct(URL)#</cfoutput>", variables).equals("YES"), true);
}

TEST_F(JitExpressionTest, VarFastPathInsideTagExpression) {
    // The fast path also applies to expressions in tag attributes and cfif.
    EXPECT_EQ(runJitTemplate("<cfset x=3><cfif x GT 2><cfoutput>GT</cfoutput></cfif>", variables).equals("GT"), true);
    EXPECT_EQ(runJitTemplate("<cfset n=7><cfset r = RepeatString(\"a\", n)><cfoutput>#r#</cfoutput>", variables).equals("aaaaaaa"), true);
}

TEST_F(JitExpressionTest, MemberChainAfterBracketIndex) {
    // Regression (was BUGS.md "JIT <cfset> assignment of a two-level member
    // chain"): mergeObjectMembers glues the dotted tail into ONE Variable token,
    // which used to be emitted as a single literal-key lookup on the indexed
    // base ("k2.k3" instead of .k2 then .k3), yielding NotSet/auto-created
    // slots. Every hop after a [ ] hop must be its own cfvariant_index.
    EXPECT_EQ(runJitTemplate(
        "<cfset s1={k1={k2={k3=\"deep\"}}}>"
        "<cfset key=\"k1\">"
        "<cfoutput>#s1[key].k2.k3#</cfoutput>", variables).equals("deep"), true);

    // Literal base + bracket + two hops.
    EXPECT_EQ(runJitTemplate(
        "<cfset s={a={b={c=\"v\"}}}>"
        "<cfoutput>#s[\"a\"].b.c#|</cfoutput>"
        "<cfset k=\"a\"><cfoutput>#s[k].b.c#</cfoutput>", variables).equals("v|v"), true);

    // Writes through the chained path mutate the original struct.
    EXPECT_EQ(runJitTemplate(
        "<cfset s={a={b={c=\"x\"}}}>"
        "<cfset k=\"a\">"
        "<cfset s[k].b.c=\"mut\">"
        "<cfoutput>#s.a.b.c#|#StructKeyList(s.a.b)#</cfoutput>", variables).equals("mut|C"), true);

    // Compound assignment walks the same chain.
    EXPECT_EQ(runJitTemplate(
        "<cfset s={a={b={c=41}}}>"
        "<cfset k=\"a\">"
        "<cfset s[k].b.c+=1>"
        "<cfoutput>#s.a.b.c#</cfoutput>", variables).equals("42"), true);

    // Chain rooted at an array element.
    EXPECT_EQ(runJitTemplate(
        "<cfset arr=[{name=\"i1\"}]>"
        "<cfset i=1>"
        "<cfset arr[i].name=\"mut\">"
        "<cfoutput>#arr[1].name#</cfoutput>", variables).equals("mut"), true);
}


TEST_F(CfincludeTest, VarFastPathIncludeSharesScope) {
    // An included template has its own slots but shares the caller's variables
    // scope; reads of a variable set by the caller work.
    auto dir = makeTempDir({
        {"inc.cfm", "<cfoutput>INC:#shared#</cfoutput>"},
        {"main.cfm", "<cfset shared = 5><cfinclude template=\"inc.cfm\">"},
    });
    EXPECT_EQ(runFile(dir, "main.cfm").equals("INC:5"), true);
    removeTempDir(dir);
}

TEST_F(JitExpressionTest, Tier1ObjectEquals) {
    EXPECT_EQ(runJitTemplate("<cfoutput>#ObjectEquals(\"abc\",\"abc\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#ObjectEquals(\"abc\",\"abd\")#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#ObjectEquals(1,1)#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#ObjectEquals(1,\"1\")#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#ObjectEquals(1,1.0)#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#ObjectEquals([1,2],[1,2])#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#ObjectEquals({a:1},{a:2})#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#ObjectEquals(structnew(),structnew())#</cfoutput>", variables).equals("YES"), true);
}

TEST_F(JitExpressionTest, Tier1CreateOdbcDateAndTime) {
    // Renders CF's ODBC {d '...'} / {t '...'} forms.
    EXPECT_EQ(runJitTemplate("<cfoutput>#CreateODBCDate(CreateDate(2026,8,8))#</cfoutput>", variables).equals("{d '2026-08-08'}"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#CreateODBCTime(CreateTime(5,30,45))#</cfoutput>", variables).equals("{t '05:30:45'}"), true);
    // Still usable in date functions.
    EXPECT_EQ(runJitTemplate("<cfoutput>#DateFormat(CreateODBCDate(CreateDate(2026,8,8)),\"yyyy-mm-dd\")#</cfoutput>", variables).equals("2026-08-08"), true);
    // Invalid input throws CF's message (shared with CreateODBCDateTime).
    EXPECT_THROW(runJitTemplate("<cfoutput>#CreateODBCDate(\"bad\")#</cfoutput>", variables), webstrada::exception);
}

TEST_F(JitExpressionTest, Tier1SimpleFunctions) {
    EXPECT_EQ(runJitTemplate("<cfoutput>[#GetContextRoot()#]</cfoutput>", variables).equals("[]"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsDebugMode()#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>[#GetClientVariablesList()#]</cfoutput>", variables).equals("[]"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#DeleteClientVariable(\"x\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>[#Len(GetCSPNonce())#]</cfoutput>", variables).equals("[0]"), true);
    EXPECT_EQ(runJitTemplate("<cfset q=\"a'b\"><cfoutput>#PreserveSingleQuotes(q)#</cfoutput>", variables).equals("a'b"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetLocalHostIP()#</cfoutput>", variables).equals("127.0.0.1"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetEncoding(\"form\")#</cfoutput>", variables).equals("UTF-8"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#GetEncoding(\"url\")#</cfoutput>", variables).equals("UTF-8"), true);
    // GetEncoding rejects a non FORM/URL scope (CF message).
    EXPECT_THROW(runJitTemplate("<cfoutput>#GetEncoding(\"foo\")#</cfoutput>", variables), webstrada::exception);
}

TEST_F(JitExpressionTest, Tier1IpFunctions) {
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsIPv6(\"::1\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsIPv6(\"127.0.0.1\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsIPv6(\"192.168.1.1\")#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsIPv6(\"foo\")#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsIPv6(\"::ffff:127.0.0.1\")#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsLocalHost(\"127.0.0.1\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsLocalHost(\"localhost\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsLocalHost(\"::1\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsLocalHost(\"8.8.8.8\")#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsLocalHost(\"  localhost  \")#</cfoutput>", variables).equals("NO"), true);
}

TEST_F(JitExpressionTest, Tier1GetFunctionList) {
    // Values are empty strings; keys cover the engine's registry.
    EXPECT_EQ(runJitTemplate("<cfset fl=GetFunctionList()><cfoutput>#StructKeyExists(fl,\"GETTOKEN\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfset fl=GetFunctionList()><cfoutput>#StructKeyExists(fl,\"GETTEMPLATEPATH\")#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfset fl=GetFunctionList()><cfoutput>#StructKeyExists(fl,\"PARAMETEREXISTS\")#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfset fl=GetFunctionList()><cfoutput>#fl[\"GETTOKEN\"] eq \"\"#</cfoutput>", variables).equals("YES"), true);
}

TEST_F(JitExpressionTest, Tier1GetMetricData) {
    // simple_load returns an integer; perf_monitor returns a struct with CF's
    // key set.
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsNumeric(GetMetricData(\"simple_load\"))#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfset m=GetMetricData(\"perf_monitor\")><cfoutput>#IsStruct(m)#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfset m=GetMetricData(\"perf_monitor\")><cfoutput>#StructKeyExists(m,\"pagehits\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfset m=GetMetricData(\"perf_monitor\")><cfoutput>#StructKeyExists(m,\"instancename\")#</cfoutput>", variables).equals("YES"), true);
}

TEST_F(JitExpressionTest, Tier1SystemMemory) {
    // Cannot be byte-verified against CF (the RDS host lacks pmtagent), so the
    // unit test only checks that a positive byte count is returned.
    cfvariant *freeMem = cfml::cf_getsystemfreememory();
    EXPECT_EQ(freeMem->m_type, cfvariant::Long);
    EXPECT_GT(freeMem->m_long, 0);
    delete freeMem;
    cfvariant *totalMem = cfml::cf_getsystemtotalmemory();
    EXPECT_EQ(totalMem->m_type, cfvariant::Long);
    EXPECT_GT(totalMem->m_long, 0);
    delete totalMem;
}

TEST_F(JitExpressionTest, Tier1DiskSpace) {
    // GetFreeSpace/GetTotalSpace on a valid path return bytes; a bare "/" is
    // invalid on CF 2025 (path-length > 1 requirement).
    cfvariant p("/tmp");
    cfvariant *free = cfml::cf_getfreespace(&p);
    EXPECT_EQ(free->m_type, cfvariant::Long);
    EXPECT_GT(free->m_long, 0);
    delete free;
    cfvariant *total = cfml::cf_gettotalspace(&p);
    EXPECT_EQ(total->m_type, cfvariant::Long);
    EXPECT_GT(total->m_long, 0);
    delete total;

    cfvariant root("/");
    EXPECT_THROW(cfml::cf_getfreespace(&root), webstrada::exception);
    EXPECT_THROW(cfml::cf_gettotalspace(&root), webstrada::exception);
}

TEST_F(JitExpressionTest, Tier1IsDdxAndWddx) {
    // The RDS host has no PDF service, so CF always reports NO for IsDDX there
    // (see BUGS_CF.md); the engine sniffs the <DDX> root element per the plan.
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsDDX('<DDX xmlns=\"http://ns.adobe.com/DDX/1.0/\"><PDF result=\"out.pdf\"><Pages/></PDF></DDX>')#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsDDX('<root></root>')#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsDDX('hello')#</cfoutput>", variables).equals("NO"), true);

    // IsWDDX requires the case-sensitive <wddxPacket> root with a version
    // attribute, a <header/> and a non-empty <data> (byte-verified vs CF 2025).
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsWDDX('<wddxPacket version=\"1.0\"><header/><data><string>hi</string></data></wddxPacket>')#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsWDDX('<wddxPacket><header/><data><string>hi</string></data></wddxPacket>')#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsWDDX('<wddxPacket version=\"1.0\"><data><string>hi</string></data></wddxPacket>')#</cfoutput>", variables).equals("NO"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IsWDDX('hello')#</cfoutput>", variables).equals("NO"), true);
}

TEST_F(JitExpressionTest, Tier1LocationThrowsLikeCf2025) {
    // CF 2025 removed the script Location() function; it throws CF's
    // method-not-found error with the argument count.
    try {
        runJitTemplate("<cfoutput>#Location(\"http://example.com\")#</cfoutput>", variables);
        FAIL() << "Location() should throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.what()).contains("Method Location with 1 arguments is not in class coldfusion.runtime.CFPage."), true);
    }
}

TEST_F(JitExpressionTest, Tier1TransactionFunctions) {
    // Outside a transaction both throw CF's active-transaction error.
    try {
        runJitTemplate("<cfscript>TransactionCommit();</cfscript>", variables);
        FAIL() << "TransactionCommit() should throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.what()).contains("An active transaction is required before calling any transaction method."), true);
    }
    try {
        runJitTemplate("<cfscript>TransactionRollback();</cfscript>", variables);
        FAIL() << "TransactionRollback() should throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.what()).contains("An active transaction is required before calling any transaction method."), true);
    }
    // Inside a transaction the commit/rollback succeed.
    EXPECT_EQ(runJitTemplate("<cftransaction action=\"begin\"><cfscript>TransactionCommit();</cfscript></cftransaction><cfoutput>ok</cfoutput>", variables).equals("ok"), true);
    EXPECT_EQ(runJitTemplate("<cftransaction action=\"begin\"><cfscript>TransactionRollback();</cfscript></cftransaction><cfoutput>ok</cfoutput>", variables).equals("ok"), true);
}

TEST_F(JitExpressionTest, Tier1RemovedFunctionsMatchCf2025) {
    // GetTemplatePath and ParameterExists were removed from CF 2025; calling
    // them reports "Variable X is undefined." like any unknown name.
    try {
        runJitTemplate("<cfoutput>#GetTemplatePath()#</cfoutput>", variables);
        FAIL() << "GetTemplatePath() should throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.what()).contains("Variable GETTEMPLATEPATH is undefined."), true);
    }
    try {
        runJitTemplate("<cfoutput>#ParameterExists(\"x\")#</cfoutput>", variables);
        FAIL() << "ParameterExists() should throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.what()).contains("Variable PARAMETEREXISTS is undefined."), true);
    }
}

TEST_F(JitExpressionTest, Tier1IsThreadInterrupted) {
    // No thread can exist (cfthread is unimplemented), so CF's "thread was not
    // created" error is reproduced.
    try {
        runJitTemplate("<cfoutput>#isThreadInterrupted(\"t1\")#</cfoutput>", variables);
        FAIL() << "isThreadInterrupted() should throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.what()).contains("Thread t1 cannot be used in action isInterrupted because the thread t1 was not created."), true);
    }
}

// ---- Tier-2 built-in functions (CFFUNCTION_IMPLEMENTATION_ACTION_PLAN.md) ----

TEST_F(JitExpressionTest, Tier2EncodeForFamily) {
    // Byte-verified against CF 2025 (tests/cfm/tier2_encoder_test.cfm).
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForHTML('a&b<c>d\"e')#</cfoutput>", variables).equals("a&amp;b&lt;c&gt;d&quot;e"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForHTMLAttribute('a&b<c>d\"e')#</cfoutput>", variables).equals("a&amp;b&lt;c&gt;d&quot;e"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForJavaScript('a&b<c>d\"e')#</cfoutput>", variables).equals("a\\x26b\\x3Cc\\x3Ed\\x22e"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForCSS('a\"b<c>d&e')#</cfoutput>", variables).equals("a\\22 b\\3c c\\3e d\\26 e"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForXML('a&b<c>d\"e')#</cfoutput>", variables).equals("a&#x26;b&#x3c;c&#x3e;d&#x22;e"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForXMLAttribute('a&b<c>d\"e')#</cfoutput>", variables).equals("a&#x26;b&#x3c;c&#x3e;d&#x22;e"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForDN('&')#</cfoutput>", variables).equals("&"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForLDAP('*')#</cfoutput>", variables).equals("\\2a"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForXPath('<script>')#</cfoutput>", variables).equals("&lt;script&gt;"), true);
    // DN escapes < > / and leading/trailing space; LDAP escapes ( ) * / \\.
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForDN(' a ')#</cfoutput>", variables).equals("\\ a\\ "), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#EncodeForLDAP('(')#</cfoutput>", variables).equals("\\28"), true);
    // Non-ASCII uses named HTML entities / hex escapes.
    EXPECT_EQ(runJitTemplate("<cfset u = Chr(233)><cfoutput>#EncodeForHTML(u)#</cfoutput>", variables).equals("&eacute;"), true);
    EXPECT_EQ(runJitTemplate("<cfset u = Chr(233)><cfoutput>#EncodeForJavaScript(u)#</cfoutput>", variables).equals("\\xE9"), true);
    EXPECT_EQ(runJitTemplate("<cfset u = Chr(937)><cfoutput>#EncodeForXML(u)#</cfoutput>", variables).equals("&#x3a9;"), true);
    EXPECT_EQ(runJitTemplate("<cfset u = Chr(937)><cfoutput>#EncodeForCSS(u)#</cfoutput>", variables).equals("\\3a9 "), true);
}

TEST_F(JitExpressionTest, Tier2DecodeForHtmlAndCanonicalize) {
    EXPECT_EQ(runJitTemplate("<cfoutput>#DecodeForHTML('a&amp;b&lt;c&gt;d&quot;e')#</cfoutput>", variables).equals("a&b<c>d\"e"), true);
    EXPECT_EQ(runJitTemplate("<cfset A = Chr(38)><cfset s = \"a\" & A & \"amp;\" & A & \"amp;b\"><cfoutput>#DecodeForHTML(s)#</cfoutput>", variables).equals("a&&b"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#DecodeForHTML('&amp;lt;')#</cfoutput>", variables).equals("&lt;"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#DecodeForHTML('plain')#</cfoutput>", variables).equals("plain"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#Canonicalize('a&amp;b', false, false)#</cfoutput>", variables).equals("a&b"), true);
    EXPECT_EQ(runJitTemplate("<cfset A = Chr(38)><cfset c2 = \"a\" & A & \"amp;\" & A & \"amp;b\"><cfoutput>#Canonicalize(c2, false, false)#</cfoutput>", variables).equals("a&&b"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#Canonicalize('a&amp;lt;b', false, false)#</cfoutput>", variables).equals("a<b"), true);
    // Restriction trips -> empty string (throwOnError defaults to false).
    EXPECT_EQ(runJitTemplate("<cfoutput>#Canonicalize('a&amp;lt;b', true, true)#</cfoutput>", variables).equals(""), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#Canonicalize('%26', false, false)#</cfoutput>", variables).equals("&"), true);
    // throwOnError=true throws CF's IntrusionException.
    EXPECT_THROW(runJitTemplate("<cfoutput>#Canonicalize('a&amp;lt;b', true, true, true)#</cfoutput>", variables), webstrada::exception);
}

TEST_F(JitExpressionTest, Tier2NumberFormat) {
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(1234)#</cfoutput>", variables).equals("1,234"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(1234.5)#</cfoutput>", variables).equals("1,235"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(1234567.89)#</cfoutput>", variables).equals("1,234,568"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(1234, \"9,999.99\")#</cfoutput>", variables).equals("1,234.00"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(-1234, \"(9,999)\")#</cfoutput>", variables).equals("(1,234)"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(1234, \"+9,999\")#</cfoutput>", variables).equals("+1,234"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(1234, \"-9,999\")#</cfoutput>", variables).equals(" 1,234"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(1234, \"$9,999\")#</cfoutput>", variables).equals("$1,234"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(-1234, \"$9,999\")#</cfoutput>", variables).equals("-$1,234"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(12, \"L9999\")#</cfoutput>", variables).equals("12  "), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(12, \"C9999\")#</cfoutput>", variables).equals(" 12 "), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(12.34, \"999.999\")#</cfoutput>", variables).equals(" 12.340"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#NumberFormat(1.2345E7)#</cfoutput>", variables).equals("12,345,000"), true);
    // Invalid mask throws CF's IllegalNumberFormatArgumentException.
    EXPECT_THROW(runJitTemplate("<cfoutput>#NumberFormat(12, \"abc\")#</cfoutput>", variables), webstrada::exception);
}

TEST_F(JitExpressionTest, Tier2Duplicate) {
    EXPECT_EQ(runJitTemplate("<cfset s={a:1}><cfset d=Duplicate(s)><cfset d.a=99><cfoutput>#s.a#:#d.a#</cfoutput>", variables).equals("1:99"), true);
    EXPECT_EQ(runJitTemplate("<cfset a=[1,2]><cfset d=Duplicate(a)><cfset d[1]=99><cfoutput>#a[1]#:#d[1]#</cfoutput>", variables).equals("1:99"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#Duplicate(5)#</cfoutput>", variables).equals("5"), true);
}

// PrecisionEvaluate: BigDecimal-arithmetic expression evaluation with CF 2025's
// exact semantics (verified byte-for-byte against the RDS host in
// tests/cfm/tier2_precisionevaluate_test.cfm).
TEST_F(JitExpressionTest, Tier2PrecisionEvaluateArithmetic) {
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1/3\")#</cfoutput>", variables).equals("0.33333333333333333333"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"10/4\")#</cfoutput>", variables).equals("2.50000000000000000000"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"0.1+0.2\")#</cfoutput>", variables).equals("0.3"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1.5*2\")#</cfoutput>", variables).equals("3.0"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"2.50+1\")#</cfoutput>", variables).equals("3.50"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1+2*3\")#</cfoutput>", variables).equals("7"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1/10000000\")#</cfoutput>", variables).equals("1.0000000000000E-7"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"123456789123456789123456789 + 1\")#</cfoutput>", variables).equals("123456789123456789123456790"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"0.0000001 * 0.0000001\")#</cfoutput>", variables).equals("1E-14"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1.5e3\")#</cfoutput>", variables).equals("1.5E+3"), true);
}

TEST_F(JitExpressionTest, Tier2PrecisionEvaluateDivideExactAndFallback) {
    // Exact at the dividend scale (a.divide(b, UNNECESSARY) succeeds).
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"5.00/2\")#</cfoutput>", variables).equals("2.50"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"0.1/0.2\")#</cfoutput>", variables).equals("0.5"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1.000/8\")#</cfoutput>", variables).equals("0.125"), true);
    // Falls back to scale 20 half-even.
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1/3\")#</cfoutput>", variables).equals("0.33333333333333333333"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"22/7\")#</cfoutput>", variables).equals("3.14285714285714285714"), true);
}

TEST_F(JitExpressionTest, Tier2PrecisionEvaluatePowModInt) {
    // ^ is double math converted to BigDecimal's exact double expansion.
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"2^10\")#</cfoutput>", variables).equals("1024"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"2^100\")#</cfoutput>", variables).equals("1267650600228229401496703205376"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"2^0.5\")#</cfoutput>", variables).equals("1.4142135623730951454746218587388284504413604736328125"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"-2^2\")#</cfoutput>", variables).equals("4"), true);
    // MOD/% and \ are integer ops.
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"10 MOD 3\")#</cfoutput>", variables).equals("1"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"10\\3\")#</cfoutput>", variables).equals("3"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"7.5 % 2\")#</cfoutput>", variables).equals("1"), true);
}

TEST_F(JitExpressionTest, Tier2PrecisionEvaluateCompareAndVars) {
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"0.1+0.2 == 0.3\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1 LT 2\")#</cfoutput>", variables).equals("YES"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"NOT 0 GT 3\")#</cfoutput>", variables).equals("YES"), true);
    // Variables resolve inside the expression; a comma splits into expressions.
    EXPECT_EQ(runJitTemplate("<cfset x=3><cfoutput>#PrecisionEvaluate(\"x * 2\")#</cfoutput>", variables).equals("6"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1+1, 2+2\")#</cfoutput>", variables).equals("4"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"true\")#</cfoutput>", variables).equals("true"), true);
    // Dotted scope names resolve too (form.y), like CF.
    EXPECT_EQ(runJitTemplate("<cfset form.y=7><cfoutput>#PrecisionEvaluate(\"form.y * 2\")#</cfoutput>", variables).equals("14"), true);
    // A numeric string variable coerces to a number (Cast._BigDecimal).
    EXPECT_EQ(runJitTemplate("<cfset p=\"3.14159\"><cfoutput>#PrecisionEvaluate(\"p * 2\")#</cfoutput>", variables).equals("6.28318"), true);
}

TEST_F(JitExpressionTest, Tier2PrecisionEvaluateDivisionByZeroThrows) {
    EXPECT_THROW(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1/0\")#</cfoutput>", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1 MOD 0\")#</cfoutput>", variables), webstrada::exception);
    EXPECT_THROW(runJitTemplate("<cfoutput>#PrecisionEvaluate(\"1\\0\")#</cfoutput>", variables), webstrada::exception);
}


TEST_F(JitExpressionTest, Tier2IIf) {
    EXPECT_EQ(runJitTemplate("<cfset x=5><cfoutput>#IIf(x GT 3, \"x\", \"0\")#</cfoutput>", variables).equals("5"), true);
    EXPECT_EQ(runJitTemplate("<cfset x=5><cfoutput>#IIf(x GT 9, \"x\", \"0\")#</cfoutput>", variables).equals("0"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IIf(0, \"1\", \"2\")#</cfoutput>", variables).equals("2"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IIf(true, \"'s'\", \"'o'\")#</cfoutput>", variables).equals("s"), true);
    EXPECT_EQ(runJitTemplate("<cfoutput>#IIf(false, \"'s'\", \"'o'\")#</cfoutput>", variables).equals("o"), true);
}

