TEST_F(CfcacheTagTest, StripWhitespaceFragment) {
    // A run of two+ newlines/tabs collapses to a single \r (CF's
    // SecurityManager.tokenSeparator) in the stored and displayed fragment
    // body (CF's addToTemplateCache re-prints the stripped body). Both tags are
    // on the same physical line, so they share the template key and the second
    // is a hit serving the stripped copy.
    expectOutput("<cfcache id=\"sw\" stripwhitespace=\"true\">A\t\tB</cfcache>|<cfcache id=\"sw\">IGNORED</cfcache>",
                 "A\rB|A\rB");
}

// ---------------------------------------------------------------------------
// <cfzip> / <cfzipparam>
//
// The RDS host lacks the CF `zip` package (see BUGS_CF.md), so cfzip cannot be
// byte-verified against ColdFusion; these unit tests pin the engine's behavior
// (zip/unzip/list/read/readBinary/delete, cfzipparam content, error paths).
// ---------------------------------------------------------------------------
class CfzipTagTest : public testing::Test {
protected:
    cfvariant variables;
    std::string workDir;
    std::string zipPath;
    std::string outDir;

    void SetUp() override {
        variables = cfvariant::Struct;
        char tmpl[] = "/tmp/webstrada_cfzip_XXXXXX";
        int fd = mkstemp(tmpl);
        EXPECT_NE(fd, -1);
        close(fd);
        unlink(tmpl);   // the directory is created by the template
        workDir = tmpl;
        zipPath = workDir + ".zip";
        outDir = workDir + "_out";
        std::filesystem::create_directories(workDir);
        std::filesystem::create_directories(workDir + "/subdir");
        std::filesystem::create_directories(outDir);
        writeFile(workDir + "/aa.txt", "hello aa");
        writeFile(workDir + "/sub.bin", "BINARYDATA");
        writeFile(workDir + "/subdir/deep.txt", "deep");
    }

    void TearDown() override {
        std::filesystem::remove_all(workDir);
        std::filesystem::remove(zipPath);
        std::filesystem::remove_all(outDir);
        std::filesystem::remove(zipPath + "_content.zip");
    }

    static void writeFile(const std::string &path, const std::string &content) {
        std::ofstream out(path, std::ios::binary | std::ios::trunc);
        out << content;
    }

    // Runs a CFML template and returns the output.
    string run(const std::string &cfml_code) {
        return runJitTemplate(cfml_code.c_str(), variables);
    }

    void expectOutput(const std::string &cfml_code, const char *expected) {
        string out = run(cfml_code);
        EXPECT_EQ(out.equals(expected), true)
            << "CFML: " << cfml_code.c_str() << " -> " << out.constData();
    }

    bool fileExists(const std::string &path) {
        return std::filesystem::exists(path);
    }
};

TEST_F(CfzipTagTest, ZipAndListDirectory) {
    run(("<cfzip action=\"zip\" file=\"" + zipPath +
         "\" source=\"" + workDir + "\"></cfzip>").c_str());
    EXPECT_EQ(fileExists(zipPath), true);
    // The entry iteration order is filesystem-dependent, so sort the names.
    string out = run(("<cfzip action=\"list\" file=\"" + zipPath + "\" name=\"q\"></cfzip>"
                      "<cfset names = \"\"><cfloop query=\"q\"><cfset names = ListAppend(names, q.name)></cfloop>"
                      "<cfoutput>#q.recordCount#|#q.columnList#|#ListSort(names,'text')#</cfoutput>").c_str());
    EXPECT_EQ(out.equals("3|COMMENT,COMPRESSEDSIZE,CRC,DATELASTMODIFIED,DIRECTORY,ENCRYPTIONALGORITHM,"
                         "NAME,SIZE,TYPE|aa.txt,sub.bin,subdir/deep.txt"), true)
        << "actual: " << out.constData();
}

TEST_F(CfzipTagTest, ZipListShowDirectory) {
    // showDirectory=no (default) hides directory entries; yes lists them.
    run(("<cfzip action=\"zip\" file=\"" + zipPath +
         "\" source=\"" + workDir + "\"></cfzip>").c_str());
    string no = run(("<cfzip action=\"list\" file=\"" + zipPath + "\" name=\"q\" showDirectory=\"no\"></cfzip>"
                     "<cfoutput>#q.recordCount#</cfoutput>").c_str());
    EXPECT_EQ(no.equals("3"), true) << "actual: " << no.constData();
    string yes = run(("<cfzip action=\"list\" file=\"" + zipPath + "\" name=\"q\" showDirectory=\"yes\"></cfzip>"
                      "<cfoutput>#q.recordCount#</cfoutput>").c_str());
    EXPECT_EQ(yes.equals("4"), true) << "actual: " << yes.constData();   // 3 files + the subdir entry
}

TEST_F(CfzipTagTest, ZipReadAndReadBinary) {
    run(("<cfzip action=\"zip\" file=\"" + zipPath +
         "\" source=\"" + workDir + "\"></cfzip>").c_str());
    expectOutput(("<cfzip action=\"read\" file=\"" + zipPath + "\" entrypath=\"subdir/deep.txt\" variable=\"v\"></cfzip>"
                  "<cfoutput>#Trim(v)#</cfoutput>").c_str(), "deep");
    string bin = run(("<cfzip action=\"readBinary\" file=\"" + zipPath + "\" entrypath=\"sub.bin\" variable=\"v\"></cfzip>"
                      "<cfoutput>#IsBinary(v)#:#Len(v)#</cfoutput>").c_str());
    EXPECT_EQ(bin.equals("YES:10"), true);
}

TEST_F(CfzipTagTest, ZipUnzip) {
    run(("<cfzip action=\"zip\" file=\"" + zipPath +
         "\" source=\"" + workDir + "\"></cfzip>").c_str());
    run(("<cfzip action=\"unzip\" file=\"" + zipPath + "\" destination=\"" + outDir + "\"></cfzip>").c_str());
    EXPECT_EQ(fileExists(outDir + "/aa.txt"), true);
    EXPECT_EQ(fileExists(outDir + "/subdir/deep.txt"), true);
    // The unzipped file content round-trips.
    std::ifstream in(outDir + "/aa.txt", std::ios::binary);
    std::stringstream ss;
    ss << in.rdbuf();
    EXPECT_EQ(ss.str(), "hello aa");
}

TEST_F(CfzipTagTest, ZipDeleteEntry) {
    run(("<cfzip action=\"zip\" file=\"" + zipPath +
         "\" source=\"" + workDir + "\"></cfzip>").c_str());
    run(("<cfzip action=\"delete\" file=\"" + zipPath + "\" entrypath=\"sub.bin\"></cfzip>").c_str());
    string out = run(("<cfzip action=\"list\" file=\"" + zipPath + "\" name=\"q\"></cfzip>"
                      "<cfoutput>#q.recordCount#</cfoutput>").c_str());
    EXPECT_EQ(out.equals("2"), true) << "actual: " << out.constData();
}

TEST_F(CfzipTagTest, ZipParamContent) {
    std::string z2 = zipPath + "_content.zip";
    run(("<cfzip action=\"zip\" file=\"" + z2 + "\">"
         "<cfzipparam content=\"hello content\" entrypath=\"hello.txt\">"
         "</cfzip>").c_str());
    string out = run(("<cfzip action=\"read\" file=\"" + z2 + "\" entrypath=\"hello.txt\" variable=\"v1\"></cfzip>"
                      "<cfoutput>#Trim(v1)#</cfoutput>").c_str());
    EXPECT_EQ(out.equals("hello content"), true);
}

TEST_F(CfzipTagTest, ZipParamSourceWithEntrypath) {
    std::string z2 = zipPath + "_content.zip";
    run(("<cfzip action=\"zip\" file=\"" + z2 + "\">"
         "<cfzipparam source=\"" + workDir + "/aa.txt\" entrypath=\"pfx/aa.txt\">"
         "</cfzip>").c_str());
    string out = run(("<cfzip action=\"read\" file=\"" + z2 + "\" entrypath=\"pfx/aa.txt\" variable=\"v1\"></cfzip>"
                      "<cfoutput>#Trim(v1)#</cfoutput>").c_str());
    EXPECT_EQ(out.equals("hello aa"), true);
}

