// ---- <cfobjectcache> ----

class CfobjectcacheTagTest : public testing::Test {
protected:
    cfvariant variables;
    std::string dsnDir;
    std::string savedDsnDir;
    std::string savedScopeDbPath;
    std::string cacheDb;
    std::string savedCacheDbPath;

    void SetUp() override {
        variables = cfvariant::Struct;
        char dir[] = "/tmp/webstrada_oc_test_XXXXXX";
        char *d = mkdtemp(dir);
        EXPECT_NE(d, nullptr);
        dsnDir = d;
        savedDsnDir = webstrada::config::dsnDbDir;
        savedScopeDbPath = webstrada::config::scopeDbPath;
        webstrada::config::dsnDbDir = dsnDir;

        char db[] = "/tmp/webstrada_oc_cache_XXXXXX";
        int fd = mkstemp(db);
        EXPECT_NE(fd, -1);
        close(fd);
        unlink(db);
        cacheDb = db;
        savedCacheDbPath = webstrada::config::cacheDbPath;
        webstrada::config::cacheDbPath = cacheDb;
        webstrada::open_cache_store();
        cfml::response_begin();
    }

    void TearDown() override {
        webstrada::config::dsnDbDir = savedDsnDir;
        webstrada::config::scopeDbPath = savedScopeDbPath;
        webstrada::config::cacheDbPath = savedCacheDbPath;
        webstrada::cache_store().close();
        unlink((dsnDir + "/DNS_test.sqlite").c_str());
        unlink((dsnDir + "/DNS_test.sqlite-wal").c_str());
        unlink((dsnDir + "/DNS_test.sqlite-shm").c_str());
        rmdir(dsnDir.c_str());
        unlink(cacheDb.c_str());
        unlink((cacheDb + "-wal").c_str());
        unlink((cacheDb + "-shm").c_str());
    }

    string run(const string &cfml_code) {
        return runJitTemplate(cfml_code, variables);
    }

    void expectOutput(const string &cfml_code, const char *expected) {
        string out = run(cfml_code);
        EXPECT_EQ(out.equals(expected), true) << "CFML: " << cfml_code.constData() << " -> " << out.constData();
    }
};

TEST_F(CfobjectcacheTagTest, ClearFlushesQueryCache) {
    // A cachedwithin query is served from the QUERY region until
    // <cfobjectcache action="clear"> flushes it, then re-runs (verified
    // byte-for-byte against CF 2025).
    expectOutput(
        "<cfquery datasource=\"test\">DROP TABLE IF EXISTS ocq_t</cfquery>"
        "<cfquery datasource=\"test\">CREATE TABLE ocq_t (id INTEGER PRIMARY KEY, name TEXT)</cfquery>"
        "<cfquery datasource=\"test\">INSERT INTO ocq_t VALUES (1, 'one')</cfquery>"
        "<cfquery name=\"q1\" datasource=\"test\" cachedwithin=\"#CreateTimeSpan(1,0,0,0)#\">SELECT name FROM ocq_t WHERE id = 1</cfquery>"
        "<cfoutput>#q1.name#|</cfoutput>"
        "<cfquery datasource=\"test\">UPDATE ocq_t SET name = 'two' WHERE id = 1</cfquery>"
        "<cfquery name=\"q2\" datasource=\"test\" cachedwithin=\"#CreateTimeSpan(1,0,0,0)#\">SELECT name FROM ocq_t WHERE id = 1</cfquery>"
        "<cfoutput>#q2.name#|</cfoutput>"
        "<cfobjectcache action=\"clear\">"
        "<cfquery name=\"q3\" datasource=\"test\" cachedwithin=\"#CreateTimeSpan(1,0,0,0)#\">SELECT name FROM ocq_t WHERE id = 1</cfquery>"
        "<cfoutput>#q3.name#</cfoutput>",
        "one|one|two");
}

TEST_F(CfobjectcacheTagTest, ActionClearAndMissingActionCompileError) {
    expectOutput("<cftry><cfobjectcache action=\"clear\"><cfoutput>O1|</cfoutput>"
                 "<cfcatch><cfoutput>E1|</cfoutput></cfcatch></cftry>"
                 "<cftry><cfobjectcache action=\"CLEAR\"><cfoutput>O2|</cfoutput>"
                 "<cfcatch><cfoutput>E2|</cfoutput></cfcatch></cftry>",
                 "O1|O2|");
    try {
        run("<cfobjectcache>");
        ADD_FAILURE() << "expected a compile-time throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.m_message).equals("Attribute validation error for the CFOBJECTCACHE tag."), true);
        EXPECT_EQ(string(e.m_detail).equals("The tag requires the ACTION attribute."), true);
    }
}

TEST_F(CfobjectcacheTagTest, DynamicBadActionThrowsTemplate) {
    // The runtime error is catchable with type Template.
    expectOutput("<cfset x = \"bogus\">"
                 "<cftry><cfobjectcache action=\"#x#\"><cfoutput>O|</cfoutput>"
                 "<cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>",
                 "Template|Attribute validation error for CFOBJECTCACHE.|The value of the ACTION attribute, which is currently bogus, must be one of the values: CLEAR.");
}

TEST_F(CfobjectcacheTagTest, DynamicEmptyActionThrowsTemplate) {
    expectOutput("<cfset x = \"\">"
                 "<cftry><cfobjectcache action=\"#x#\"><cfoutput>O|</cfoutput>"
                 "<cfcatch><cfoutput>#cfcatch.type#|#cfcatch.message#|#cfcatch.detail#</cfoutput></cfcatch></cftry>",
                 "Template|Attribute validation error for CFOBJECTCACHE.|The value of the ACTION attribute, which is currently '', must be one of the values: CLEAR.");
}

TEST_F(CfobjectcacheTagTest, CompileErrors) {
    try {
        run("<cfobjectcache action=\"foo\">");
        ADD_FAILURE() << "expected a compile-time throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.m_message).equals("Attribute validation error for CFOBJECTCACHE."), true);
        EXPECT_EQ(string(e.m_detail).equals("The value of the ACTION attribute, which is currently foo, must be one of the values: CLEAR."), true);
    }
    try {
        run("<cfobjectcache action=\"\">");
        ADD_FAILURE() << "expected a compile-time throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.m_detail).equals("The value of the ACTION attribute, which is currently '', must be one of the values: CLEAR."), true);
    }
    try {
        run("<cfobjectcache action=\"clear\" bogus=\"1\">");
        ADD_FAILURE() << "expected a compile-time throw";
    } catch (const webstrada::exception &e) {
        EXPECT_EQ(string(e.m_message).equals("Attribute validation error for the objectcache tag. The tag does not have an attribute called bogus. The valid attribute(s) are action."), true);
    }
}

 TEST_F(CfobjectcacheTagTest, BodySkippedLikeCf) {
     // GenericTag doStartTag returns SKIP_BODY: a body <cfset> has no effect
     // (verified on CF 2025).
     expectOutput("<cfobjectcache action=\"clear\"><cfset bodyZ = 55>SKIPPED</cfobjectcache>"
                  "<cfoutput>#IsDefined(\"bodyZ\")#</cfoutput>", "NO");
 }

