// ---- Compiler-extension functions (__ prefix) + config file support ----

// Exercises the config-file loader (webstrada/config.cpp), the __configGet() /
// __configSet() / __datasourceTest() compiler-extension functions and their
// JIT/interpreter dispatch. These functions are engine extensions (reserved
// `__` namespace), so there is no Adobe ColdFusion to byte-verify against.
class ConfigExtensionTest : public testing::Test {
protected:
    std::string configPath;
    std::string dsDir;

    void SetUp() override {
        // Isolate the config file and the SQLite DSN directory into a fresh
        // temp directory, and reset every config global to the built-in
        // defaults so tests are independent of each other.
        char tmpl[] = "/tmp/webstrada_config_test_XXXXXX";
        char *dir = mkdtemp(tmpl);
        ASSERT_NE(dir, nullptr);
        configPath = std::string(dir) + "/webstrada-config.json";
        dsDir = std::string(dir) + "/dsn";
        std::filesystem::create_directories(dsDir);

        webstrada::config::configFilePath.clear();
        webstrada::config::enableWhitespaceManagement = true;
        webstrada::config::defaultOutputCharset = "UTF-8";
        webstrada::config::defaultInputCharset = "UTF-8";
        webstrada::config::charsetDetectionMinConfidence = 80;
        webstrada::config::scopeDbPath.clear();
        webstrada::config::cacheDbPath.clear();
        webstrada::config::dsnDbDir = dsDir;
        webstrada::config::datasources.clear();
        webstrada::config::defaultApplicationTimeoutSeconds = 172800.0;
        webstrada::config::defaultSessionTimeoutSeconds = 1200.0;
        webstrada::config::enableQueryLogging = true;
        webstrada::config::debugEnabled = false;
    }

    void TearDown() override {
        std::filesystem::remove_all(std::filesystem::path(configPath).parent_path());
        webstrada::config::configFilePath.clear();
    }

    const cfvariant *member(const cfvariant &st, const char *key) {
        return cfml::structGet(&st, key);
    }

    // Calls the extension functions with a single argument (their uniform ABI
    // is an argument array + count).
    cfvariant *setConfig(const cfvariant &arg) {
        const cfvariant *args[] = {&arg};
        return cfml::cf___configset(args, 1);
    }

    cfvariant *testDatasource(const cfvariant &arg) {
        const cfvariant *args[] = {&arg};
        return cfml::cf___datasourcetest(args, 1);
    }

    std::string readConfigFile() {
        std::ifstream in(configPath, std::ios::binary);
        return std::string((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    }
};

TEST_F(ConfigExtensionTest, InitializeBootstrapsDefaultsFile) {
    webstrada::config::configFilePath = configPath;
    webstrada::config::initialize();
    EXPECT_TRUE(webstrada::config::hasConfigFile());
    std::string text = readConfigFile();
    EXPECT_NE(text.find("\"settings\""), std::string::npos);
    EXPECT_NE(text.find("\"datasources\""), std::string::npos);
    EXPECT_NE(text.find("\"defaultOutputCharset\""), std::string::npos);
    // No change since bootstrap: reloadIfChanged must not fire.
    EXPECT_FALSE(webstrada::config::reloadIfChanged());
}

TEST_F(ConfigExtensionTest, ReloadPicksUpExternalWrite) {
    webstrada::config::configFilePath = configPath;
    webstrada::config::initialize();
    EXPECT_EQ(webstrada::config::defaultOutputCharset, "UTF-8");

    // Simulate another worker writing the file behind this process's back.
    usleep(1000);
    std::ofstream out(configPath, std::ios::binary | std::ios::trunc);
    out << "{\"settings\": {\"defaultOutputCharset\": \"ISO-8859-1\"}, \"datasources\": {}}";
    out.close();

    EXPECT_TRUE(webstrada::config::reloadIfChanged());
    EXPECT_EQ(webstrada::config::defaultOutputCharset, "ISO-8859-1");
    // Now in sync again.
    EXPECT_FALSE(webstrada::config::reloadIfChanged());
}

TEST_F(ConfigExtensionTest, ConfigGetReturnsEffectiveSettings) {
    webstrada::config::defaultOutputCharset = "ISO-8859-1";
    webstrada::config::enableQueryLogging = false;
    webstrada::config::datasources["APP"] = {"sqlite", "", 0, "db1", "u", "p"};

    cfvariant *res = cfml::cf___configget(nullptr, 0);
    ASSERT_TRUE(res != nullptr);
    ASSERT_EQ(res->m_type, cfvariant::Struct);
    const cfvariant *settings = member(*res, "settings");
    ASSERT_TRUE(settings != nullptr);
    const cfvariant *cs = member(*settings, "defaultOutputCharset");
    ASSERT_TRUE(cs != nullptr);
    EXPECT_EQ(cfml::toStdString(cs), "ISO-8859-1");
    const cfvariant *ql = member(*settings, "enableQueryLogging");
    ASSERT_TRUE(ql != nullptr);
    EXPECT_EQ(ql->m_type, cfvariant::Boolean);
    EXPECT_EQ(ql->m_bool, false);

    const cfvariant *ds = member(*res, "datasources");
    ASSERT_TRUE(ds != nullptr);
    const cfvariant *app = member(*ds, "APP");
    ASSERT_TRUE(app != nullptr);
    EXPECT_EQ(cfml::toStdString(member(*app, "backend")), "sqlite");
    // The real password must be masked.
    EXPECT_EQ(cfml::toStdString(member(*app, "password")), "****");
}

TEST_F(ConfigExtensionTest, ConfigSetAppliesAndPersists) {
    webstrada::config::configFilePath = configPath;
    webstrada::config::initialize();

    cfvariant payload(cfvariant::Struct);
    cfvariant settings(cfvariant::Struct);
    cfvariant enc("ISO-8859-1");
    settings.structSet("defaultOutputCharset", enc);
    settings.structSet("enableQueryLogging", cfvariant(0));
    payload.structSet("settings", settings);

    cfvariant *res = setConfig(payload);
    ASSERT_TRUE(res != nullptr);
    EXPECT_EQ(webstrada::config::defaultOutputCharset, "ISO-8859-1");
    EXPECT_FALSE(webstrada::config::enableQueryLogging);

    std::string text = readConfigFile();
    EXPECT_NE(text.find("ISO-8859-1"), std::string::npos);
    EXPECT_NE(text.find("\"enableQueryLogging\":false"), std::string::npos);
}

TEST_F(ConfigExtensionTest, ConfigSetRejectsUnknownSetting) {
    cfvariant payload(cfvariant::Struct);
    cfvariant settings(cfvariant::Struct);
    settings.structSet("bogus", cfvariant(1));
    payload.structSet("settings", settings);

    EXPECT_THROW(setConfig(payload), webstrada::exception);
    try {
        setConfig(payload);
        FAIL() << "expected throw";
    } catch (const webstrada::exception &ex) {
        std::string msg(ex.m_message.constData() ? ex.m_message.constData() : "");
        EXPECT_NE(msg.find("unknown setting 'bogus'"), std::string::npos);
        EXPECT_NE(msg.find("enablequerylogging"), std::string::npos);  // lists valid keys
    }
}

TEST_F(ConfigExtensionTest, ConfigSetRejectsNonNumeric) {
    cfvariant payload(cfvariant::Struct);
    cfvariant settings(cfvariant::Struct);
    settings.structSet("charsetDetectionMinConfidence", cfvariant("abc"));
    payload.structSet("settings", settings);
    EXPECT_THROW(setConfig(payload), webstrada::exception);
}

TEST_F(ConfigExtensionTest, ConfigSetRejectsWrongArgShape) {
    EXPECT_THROW(cfml::cf___configset(nullptr, 0), webstrada::exception);
    cfvariant notAStruct(42);
    EXPECT_THROW(setConfig(notAStruct), webstrada::exception);
    cfvariant emptyStruct(cfvariant::Struct);
    EXPECT_THROW(setConfig(emptyStruct), webstrada::exception);
}

TEST_F(ConfigExtensionTest, DatasourceUpsertAndPasswordSentinel) {
    webstrada::config::configFilePath = configPath;
    webstrada::config::initialize();

    auto dsPayload = [](const char *password) {
        cfvariant payload(cfvariant::Struct);
        cfvariant dsRoot(cfvariant::Struct);
        cfvariant dsObj(cfvariant::Struct);
        dsObj.structSet("backend", cfvariant("sqlite"));
        dsObj.structSet("password", cfvariant(password));
        dsRoot.structSet("appdb", dsObj);
        payload.structSet("datasources", dsRoot);
        return payload;
    };

    setConfig(dsPayload("secret"));
    ASSERT_EQ(webstrada::config::datasources.size(), 1u);
    EXPECT_EQ(webstrada::config::datasources["APPDB"].backend, "sqlite");
    EXPECT_EQ(webstrada::config::datasources["APPDB"].password, "secret");

    // The __configGet() "****" sentinel must keep the existing secret.
    setConfig(dsPayload("****"));
    EXPECT_EQ(webstrada::config::datasources["APPDB"].password, "secret");

    // A real value replaces it.
    setConfig(dsPayload("new"));
    EXPECT_EQ(webstrada::config::datasources["APPDB"].password, "new");

    // And __configGet() masks it back to the sentinel.
    cfvariant *res = cfml::cf___configget(nullptr, 0);
    const cfvariant *app = member(*member(*res, "datasources"), "APPDB");
    EXPECT_EQ(cfml::toStdString(member(*app, "password")), "****");

    // The file persisted the real secret, never the sentinel.
    std::string text = readConfigFile();
    EXPECT_NE(text.find("\"password\":\"new\""), std::string::npos);
    EXPECT_EQ(text.find("****"), std::string::npos);
}

