TEST_F(ConfigExtensionTest, CfmlJitAndInterpreterDispatch) {
    webstrada::config::configFilePath = configPath;
    webstrada::config::initialize();

    cfvariant variables = cfvariant::Struct;

    // JIT path (<cfset>/<cfif>): direct call to cf___configget.
    EXPECT_EQ(runJitTemplate(
        "<cfset x = __configGet()><cfoutput>#x.settings.defaultOutputCharset#|#x.settings.enableWhitespaceManagement#</cfoutput>",
        variables).equals("UTF-8|YES"), true);

    // Interpreter path (#...# output expression).
    EXPECT_EQ(runJitTemplate(
        "<cfoutput>#__configGet().settings.defaultOutputCharset#</cfoutput>",
        variables).equals("UTF-8"), true);

    // __configSet returns the updated effective config.
    EXPECT_EQ(runJitTemplate(
        "<cfset r = __configSet({settings: {defaultOutputCharset: \"ISO-8859-1\"}})><cfoutput>#r.settings.defaultOutputCharset#</cfoutput>",
        variables).equals("ISO-8859-1"), true);

    // Unknown setting: catchable CF error message.
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfset __configSet({settings: {bogus: 1}})><cfset m = \"no error\"><cfcatch><cfset m = cfcatch.message></cfcatch></cftry>"
        "<cfoutput>#m#</cfoutput>",
        variables).left(30).equals("Compiler extension __configSet"), true);

    // Unknown __name: compile-time error on the JIT path (the codegen rejects
    // it while building IR, before the template can run).
    EXPECT_THROW(runJitTemplate("<cfset __bogus()>", variables), webstrada::exception);

    // Unknown __name: a catchable runtime error on the #...# interpreter path.
    EXPECT_EQ(runJitTemplate(
        "<cftry><cfoutput>#__bogus()#</cfoutput><cfset m = \"no error\"><cfcatch><cfset m = cfcatch.message></cfcatch></cftry>"
        "<cfoutput>#m#</cfoutput>",
        variables).equals("Unknown compiler extension function __BOGUS."), true);

    // __datasourceTest end-to-end (configured + not configured).
    EXPECT_EQ(runJitTemplate(
        "<cfset __configSet({datasources: {testdb: {backend: \"sqlite\"}}})>"
        "<cfoutput>#__datasourceTest(\"testdb\").verified#|#__datasourceTest(\"ghost\").error#</cfoutput>",
        variables).equals("YES|Datasource 'ghost' is not configured."), true);
}

TEST_F(ConfigExtensionTest, ServerInfoReportsRuntimeStats) {
    // Simulate two completed requests through the stats module (what the
    // daemon worker records per request), then read them back via __serverInfo.
    webstrada::stats::request_begin("GET", "/index.cfm");
    webstrada::stats::request_end(200);
    webstrada::stats::request_begin("POST", "/admin/api/config.cfm");
    webstrada::stats::request_end(400);

    cfvariant *res = cfml::cf___serverinfo(nullptr, 0);
    ASSERT_TRUE(res != nullptr);
    EXPECT_EQ(cfml::toStdString(member(*res, "state")), "Running");
    EXPECT_EQ(cfml::toStdString(member(*res, "version")), "WebStrada v0.1.0");
    EXPECT_GE(member(*res, "uptimeSeconds")->m_long, 0);
    EXPECT_EQ(member(*res, "requestsServed")->m_long, 2);

    const cfvariant *recent = member(*res, "recentRequests");
    ASSERT_TRUE(recent != nullptr);
    ASSERT_EQ(recent->m_type, cfvariant::Array);
    ASSERT_EQ(recent->m_array->size(), 2u);
    EXPECT_EQ(cfml::toStdString(member(recent->m_array->at(0), "method")), "GET");
    EXPECT_EQ(cfml::toStdString(member(recent->m_array->at(0), "template")), "/index.cfm");
    EXPECT_EQ(member(recent->m_array->at(0), "status")->m_int, 200);
    EXPECT_EQ(member(recent->m_array->at(1), "status")->m_int, 400);
    EXPECT_GE(member(recent->m_array->at(0), "durationMs")->m_double, 0.0);
}

