TEST_F(ConfigExtensionTest, ServerInfoExcludeAdminFilter) {
    // The stats module is shared across tests (some of which already added
    // /admin rows), so assert relative behavior, not absolute counts.
    webstrada::stats::request_begin("GET", "/index.cfm");
    webstrada::stats::request_end(200);
    webstrada::stats::request_begin("GET", "/admin/api/serverinfo.cfm");
    webstrada::stats::request_end(200);

    cfvariant *all = cfml::cf___serverinfo(nullptr, 0);
    const cfvariant *recentAll = member(*all, "recentRequests");
    ASSERT_GE(recentAll->m_array->size(), 2u);

    // excludeAdmin: the /admin row(s) are dropped, my non-admin row stays
    // last.
    cfvariant truthy(1);
    const cfvariant *args[] = { &truthy };
    cfvariant *filtered = cfml::cf___serverinfo(args, 1);
    const cfvariant *recentFiltered = member(*filtered, "recentRequests");
    ASSERT_LT(recentFiltered->m_array->size(), recentAll->m_array->size());
    const cfvariant &lastRow = recentFiltered->m_array->at(recentFiltered->m_array->size() - 1);
    EXPECT_EQ(cfml::toStdString(member(lastRow, "template")), "/index.cfm");

    // Every remaining row is a non-/admin request.
    for (const auto &row : *recentFiltered->m_array) {
        std::string tpl = cfml::toStdString(member(row, "template"));
        EXPECT_TRUE(tpl.rfind("/admin", 0) != 0) << tpl;
    }
}

TEST_F(ConfigExtensionTest, CacheInfoEvictAndClear) {
    // Point the global cache store at a fresh temp db.
    char db[] = "/tmp/webstrada_cache_ext_test_XXXXXX";
    int fd = mkstemp(db);
    ASSERT_NE(fd, -1);
    close(fd);
    std::string saved = webstrada::config::cacheDbPath;
    webstrada::config::cacheDbPath = db;
    webstrada::open_cache_store();
    int64_t nowMs = static_cast<int64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(
                                             std::chrono::system_clock::now().time_since_epoch())
                                             .count());

    // Populate three entries across two regions (one eternal, one with a TTL).
    ASSERT_TRUE(webstrada::cache_store().put("OBJECT", "obj1", "\"v1\"", 0, 0, nowMs));
    ASSERT_TRUE(webstrada::cache_store().put("OBJECT", "obj2", "\"v2\"", 3600000, 0, nowMs));
    ASSERT_TRUE(webstrada::cache_store().put("myregion", "r1", "\"x\"", 0, 0, nowMs));

    cfvariant *info = cfml::cf___cacheinfo(nullptr, 0);
    ASSERT_TRUE(info != nullptr);
    EXPECT_EQ(member(*info, "totalEntries")->m_long, 3);
    EXPECT_GT(member(*info, "totalSize")->m_long, 0);

    const cfvariant *entries = member(*info, "entries");
    ASSERT_EQ(entries->m_array->size(), 3u);
    bool foundObj1 = false;
    bool foundR1 = false;
    for (const auto &row : *entries->m_array) {
        std::string id = cfml::toStdString(member(row, "id"));
        if (id == "obj1") {
            foundObj1 = true;
            EXPECT_EQ(cfml::toStdString(member(row, "region")), "OBJECT");
            EXPECT_EQ(member(row, "expiresMs")->m_long, 0);  // eternal
        } else if (id == "obj2") {
            EXPECT_GT(member(row, "expiresMs")->m_long, nowMs);  // 1h TTL
        } else if (id == "r1") {
            foundR1 = true;
            EXPECT_EQ(cfml::toStdString(member(row, "region")), "myregion");
        }
    }
    EXPECT_TRUE(foundObj1);
    EXPECT_TRUE(foundR1);

    // Evict obj1.
    cfvariant region("OBJECT");
    cfvariant idObj1("obj1");
    const cfvariant *args[] = { &region, &idObj1 };
    cfvariant *ev = cfml::cf___cacheevict(args, 2);
    EXPECT_EQ(member(*ev, "ok")->m_bool, true);
    EXPECT_FALSE(webstrada::cache_store().idExists("OBJECT", "obj1", nowMs));
    EXPECT_TRUE(webstrada::cache_store().idExists("myregion", "r1", nowMs));

    // Evicting a missing id reports ok=false.
    cfvariant missing("nope");
    const cfvariant *args2[] = { &region, &missing };
    cfvariant *ev2 = cfml::cf___cacheevict(args2, 2);
    EXPECT_EQ(member(*ev2, "ok")->m_bool, false);

    // Clear everything.
    cfvariant *cl = cfml::cf___cacheclear(nullptr, 0);
    EXPECT_EQ(member(*cl, "ok")->m_bool, true);
    EXPECT_EQ(webstrada::cache_store().getAllIds("OBJECT", nowMs, false).size(), 0u);
    EXPECT_EQ(webstrada::cache_store().getAllIds("myregion", nowMs, false).size(), 0u);

    webstrada::config::cacheDbPath = saved;
    webstrada::cache_store().close();
    unlink(db);
    unlink((std::string(db) + "-wal").c_str());
    unlink((std::string(db) + "-shm").c_str());
}

