TEST_F(ConfigExtensionTest, CacheInfoCompiledCounts) {
    // The compiled counts are process-global and shared with other tests, so
    // assert the delta after compiling one template + one component.
    int beforeT = 0, beforeC = 0;
    webstrada::compiled_cache_counts(beforeT, beforeC);

    char tplTmpl[] = "/tmp/webstrada_cc_tpl_XXXXXX";
    int fd = mkstemp(tplTmpl);
    ASSERT_NE(fd, -1);
    std::string tplBody = "<cfoutput>x</cfoutput>";
    ASSERT_EQ(write(fd, tplBody.data(), tplBody.size()), (ssize_t)tplBody.size());
    close(fd);
    std::string tplPath = std::string(tplTmpl) + ".cfm";
    rename(tplTmpl, tplPath.c_str());

    char cfcTmpl[] = "/tmp/webstrada_cc_cfc_XXXXXX";
    int fd2 = mkstemp(cfcTmpl);
    ASSERT_NE(fd2, -1);
    std::string cfcBody = "component { function f() { return 1; } }";
    ASSERT_EQ(write(fd2, cfcBody.data(), cfcBody.size()), (ssize_t)cfcBody.size());
    close(fd2);
    std::string cfcPath = std::string(cfcTmpl) + ".cfc";
    rename(cfcTmpl, cfcPath.c_str());

    {
        webstrada::TemplateCache tc;
        webstrada::template_fn fn = tc.get(webstrada::string(tplPath.c_str()));
        EXPECT_TRUE(fn != nullptr);
        webstrada::ComponentInfo *info = tc.get_component(webstrada::string(cfcPath.c_str()));
        EXPECT_TRUE(info != nullptr);
        if (info) webstrada::component_info_release(info);
    }

    int afterT = 0, afterC = 0;
    webstrada::compiled_cache_counts(afterT, afterC);
    EXPECT_GE(afterT - beforeT, 1);
    EXPECT_GE(afterC - beforeC, 1);

    unlink(tplPath.c_str());
    unlink(cfcPath.c_str());
}

